package com.tricore.dxos.gateway.helpdesk;

import com.tricore.dxos.application.authorization.WorkflowAccessDecision;
import com.tricore.dxos.application.authorization.WorkflowAccessException;
import com.tricore.dxos.core.workflow.WorkflowErrorCode;
import com.tricore.dxos.core.workflow.WorkflowException;
import com.tricore.dxos.core.workflow.WorkflowRuntime;
import com.tricore.dxos.gateway.workflow.controller.WorkflowController;
import com.tricore.dxos.gateway.workflow.controller.WorkflowExceptionHandler;
import com.tricore.dxos.infrastructure.workflow.HelpdeskService;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.EnumSource;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;

import java.util.UUID;

import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

class HelpdeskErrorContractTest {
    @RestController
    static class GenericController extends WorkflowController {
        GenericController(WorkflowRuntime runtime) { super(runtime); }
    }

    private static final UUID ID = UUID.fromString("f3bf54b7-fdab-4b45-85dd-94cbd8587a9d");

    @ParameterizedTest
    @EnumSource(value = WorkflowErrorCode.class, names = {"DEFINITION_NOT_FOUND", "INSTANCE_NOT_FOUND"})
    void genericKeepsItsBaselineContractWhileHelpdeskHidesMissingDetails(WorkflowErrorCode code) throws Exception {
        WorkflowRuntime runtime = mock(WorkflowRuntime.class);
        HelpdeskService service = mock(HelpdeskService.class);
        MockMvc generic = MockMvcBuilders.standaloneSetup(new GenericController(runtime))
                .setControllerAdvice(new WorkflowExceptionHandler()).build();
        MockMvc helpdesk = MockMvcBuilders.standaloneSetup(new HelpdeskController(service))
                .setControllerAdvice(new HelpdeskExceptionHandler()).build();

        when(runtime.loadInstance("instance-1")).thenThrow(new WorkflowException(code));
        when(service.get(ID)).thenThrow(new WorkflowException(code));

        generic.perform(get("/api/v1/workflow-instances/instance-1"))
                .andExpect(status().isNotFound())
                .andExpect(jsonPath("$.code").value(code.name()))
                .andExpect(jsonPath("$.message").value(code == WorkflowErrorCode.DEFINITION_NOT_FOUND
                        ? "Workflow definition version not found" : "Workflow instance not found"));
        helpdesk.perform(get("/api/v1/mvp/requests/{id}", ID))
                .andExpect(status().isNotFound())
                .andExpect(jsonPath("$.status").value(404))
                .andExpect(jsonPath("$.code").value("NOT_FOUND"))
                .andExpect(jsonPath("$.message").value("Workflow resource not found"));

        verify(runtime, times(1)).loadInstance("instance-1");
        verify(service, times(1)).get(ID);
        verifyNoMoreInteractions(runtime, service);
    }

    @Test
    void helpdeskHiddenAndMissingRemainIndistinguishableWithoutWrites() throws Exception {
        HelpdeskService service = mock(HelpdeskService.class);
        MockMvc mvc = MockMvcBuilders.standaloneSetup(new HelpdeskController(service))
                .setControllerAdvice(new HelpdeskExceptionHandler()).build();

        when(service.get(ID)).thenThrow(new WorkflowAccessException(WorkflowAccessDecision.HIDDEN));
        String hidden = mvc.perform(get("/api/v1/mvp/requests/{id}", ID))
                .andExpect(status().isNotFound())
                .andExpect(jsonPath("$.code").value("NOT_FOUND"))
                .andReturn().getResponse().getContentAsString();

        reset(service);
        when(service.get(ID)).thenThrow(new WorkflowException(WorkflowErrorCode.INSTANCE_NOT_FOUND));
        mvc.perform(get("/api/v1/mvp/requests/{id}", ID))
                .andExpect(status().isNotFound())
                .andExpect(content().string(hidden));
        verify(service, times(1)).get(ID);
        verifyNoMoreInteractions(service);
    }

    @Test
    void helpdeskUncertainCommitRemains503AndNotRetried() throws Exception {
        HelpdeskService service = mock(HelpdeskService.class);
        MockMvc mvc = MockMvcBuilders.standaloneSetup(new HelpdeskController(service))
                .setControllerAdvice(new HelpdeskExceptionHandler()).build();
        when(service.get(ID)).thenThrow(new WorkflowException(WorkflowErrorCode.COMMIT_OUTCOME_UNKNOWN));

        mvc.perform(get("/api/v1/mvp/requests/{id}", ID))
                .andExpect(status().isServiceUnavailable())
                .andExpect(jsonPath("$.code").value("COMMIT_OUTCOME_UNKNOWN"))
                .andExpect(jsonPath("$.message").value(org.hamcrest.Matchers.containsString("do not automatically retry")));
        verify(service, times(1)).get(ID);
        verifyNoMoreInteractions(service);
    }
}

@ParameterizedTest
@MethodSource("genericNotFoundContract")
void genericWorkflowRetainsDistinctNotFoundCodesAndMessages(WorkflowErrorCode code, String message) throws Exception {
    when(runtime.createInstance(any(), any(), anyLong(), any())).thenThrow(new WorkflowException(code));

    mvc.perform(post(BASE).contentType(MediaType.APPLICATION_JSON).content(CREATE))
            .andExpect(status().isNotFound())
            .andExpect(jsonPath("$.status").value(404))
            .andExpect(jsonPath("$.code").value(code.name()))
            .andExpect(jsonPath("$.message").value(message));
    verify(runtime, times(1)).createInstance("instance-1", "publication", 7, RESOURCE);
    verifyNoMoreInteractions(runtime);
}

static Stream<Arguments> genericNotFoundContract() {
    return Stream.of(
            Arguments.of(WorkflowErrorCode.DEFINITION_NOT_FOUND, "Workflow definition version not found"),
            Arguments.of(WorkflowErrorCode.INSTANCE_NOT_FOUND, "Workflow instance not found"));
}

@Test
void uncertainCommitUsesServiceUnavailableAndNeverTriggersAutomaticRetry() throws Exception {
    when(runtime.createInstance(any(), any(), anyLong(), any()))
            .thenThrow(new WorkflowException(WorkflowErrorCode.COMMIT_OUTCOME_UNKNOWN));

    mvc.perform(post(BASE).contentType(MediaType.APPLICATION_JSON).content(CREATE))
            .andExpect(status().isServiceUnavailable())
            .andExpect(jsonPath("$.status").value(503))
            .andExpect(jsonPath("$.code").value("COMMIT_OUTCOME_UNKNOWN"))
            .andExpect(jsonPath("$.message").value(containsString("do not automatically retry")))
            .andExpect(jsonPath("$.errors").isEmpty());
    verify(runtime, times(1)).createInstance("instance-1", "publication", 7, RESOURCE);
    verifyNoMoreInteractions(runtime);
}

@ParameterizedTest
@MethodSource("accessDenials")
void mapsAclDecisionsToSafeHttpErrors(WorkflowAccessDecision decision, int expectedStatus,
                                      String expectedCode) throws Exception {
    when(runtime.loadInstance("instance-1")).thenThrow(new WorkflowAccessException(decision));

    mvc.perform(get(BASE + "/instance-1"))
            .andExpect(status().is(expectedStatus))
            .andExpect(jsonPath("$.status").value(expectedStatus))
            .andExpect(jsonPath("$.code").value(expectedCode))
            .andExpect(jsonPath("$.errors").isEmpty())
            .andExpect(jsonPath("$.stackTrace").doesNotExist())
            .andExpect(jsonPath("$.cause").doesNotExist());

    verify(runtime).loadInstance("instance-1");
    verifyNoMoreInteractions(runtime);
}

static Stream<Arguments> accessDenials() {
    return Stream.of(
            Arguments.of(WorkflowAccessDecision.HIDDEN, 404, "NOT_FOUND"),
            Arguments.of(WorkflowAccessDecision.FORBIDDEN, 403, "FORBIDDEN"),
            Arguments.of(WorkflowAccessDecision.UNAVAILABLE, 503, "AUTHORIZATION_UNAVAILABLE"),
            Arguments.of(WorkflowAccessDecision.ALLOWED, 503, "AUTHORIZATION_UNAVAILABLE"));
}

@Test
void genericHiddenAclAndMissingInstanceKeepTheirDistinctPublicCodes() throws Exception {
    when(runtime.loadInstance("instance-1"))
            .thenThrow(new WorkflowAccessException(WorkflowAccessDecision.HIDDEN));
    mvc.perform(get(BASE + "/instance-1"))
            .andExpect(status().isNotFound())
            .andExpect(jsonPath("$.code").value("NOT_FOUND"))
            .andExpect(jsonPath("$.message").value("Workflow resource not found"));

    reset(runtime);
    when(runtime.loadInstance("instance-1"))
            .thenThrow(new WorkflowException(WorkflowErrorCode.INSTANCE_NOT_FOUND));
    mvc.perform(get(BASE + "/instance-1"))
            .andExpect(status().isNotFound())
            .andExpect(jsonPath("$.code").value("INSTANCE_NOT_FOUND"))
            .andExpect(jsonPath("$.message").value("Workflow instance not found"));
    verify(runtime, times(1)).loadInstance("instance-1");
    verifyNoMoreInteractions(runtime);
}

package com.tricore.dxos.infrastructure.workflow;

import org.junit.jupiter.api.Test;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;
import com.tricore.dxos.gateway.helpdesk.HelpdeskController;
import static org.assertj.core.api.Assertions.*;

class HelpdeskConfigurationTest {
    @Test void disabledByDefault() {
        try(var context=new AnnotationConfigApplicationContext(HelpdeskConfiguration.class,HelpdeskController.class)) {
            assertThat(context.getBeansOfType(HelpdeskService.class)).isEmpty();
            assertThat(context.getBeansOfType(HelpdeskController.class)).isEmpty();
        }
    }
    @Test void candidateCannotTargetSharedDatabaseOrPublicListener() {
        HelpdeskConfiguration.requireDisposable("jdbc:postgresql://127.0.0.1:55439/helpdesk_disposable_test","helpdesk_runtime_test","127.0.0.1");
        for(String url:new String[]{"jdbc:postgresql://shared.example:5432/helpdesk_disposable_test","jdbc:postgresql://127.0.0.1:5432/postgres",
                "jdbc:postgresql://127.0.0.1:55439/helpdesk_disposable_test?options=anything"})
            assertThatThrownBy(() -> HelpdeskConfiguration.requireDisposable(url,"helpdesk_runtime_test","127.0.0.1")).isInstanceOf(IllegalArgumentException.class);
        assertThatThrownBy(() -> HelpdeskConfiguration.requireDisposable("jdbc:postgresql://127.0.0.1:55439/helpdesk_disposable_test","postgres","127.0.0.1")).isInstanceOf(IllegalArgumentException.class);
        assertThatThrownBy(() -> HelpdeskConfiguration.requireDisposable("jdbc:postgresql://127.0.0.1:55439/helpdesk_disposable_test","helpdesk_runtime_test","0.0.0.0")).isInstanceOf(IllegalArgumentException.class);
    }
}

