    @ParameterizedTest @ValueSource(strings={"expired","issuer","audience","type","unsigned"})
    void invalidJwtIsRejectedBeforeAnyDatabaseWrite(String fault) throws Exception {
        var before=snapshot();
        var claims=new JWTClaimsSet.Builder(SignedJWT.parse(token("employee",AUTHORITIES,key)).getJWTClaimsSet());
        switch(fault) {
            case "expired" -> claims.issueTime(Date.from(Instant.now().minusSeconds(600)))
                    .expirationTime(Date.from(Instant.now().minusSeconds(300)));
            case "issuer" -> claims.issuer(issuer+"/untrusted");
            case "audience" -> claims.audience("other-api");
            case "type" -> claims.claim("typ","ID");
        }
        var jwt=new SignedJWT(new JWSHeader.Builder(JWSAlgorithm.RS256).keyID(key.getKeyID()).build(),claims.build());
        jwt.sign(new RSASSASigner(key));
        String bearer=fault.equals("unsigned") ? new PlainJWT(claims.build()).serialize() : jwt.serialize();
        mvc.perform(post(API).header("Authorization","Bearer "+bearer).contentType("application/json").content(createBody()))
                .andExpect(status().isUnauthorized());
        assertThat(snapshot()).isEqualTo(before);
    }

