    @Test void mismatchedWorkflowResourceAndDefinitionVersionFailClosed() throws Exception {
        var created=create("employee"); String id=created.path("id").asText();
        String instance=created.path("workflowInstanceId").asText();
        var importer=new PostgresWorkflowPersistence(new DriverManagerDataSource(url+"?currentSchema="+schema+",pg_catalog,pg_temp",
                "helpdesk_test",System.getenv("HELPDESK_DISPOSABLE_PASSWORD")),schema);
        var original=importer.loadDefinition("it-helpdesk",1);
        importer.provisionDefinition(new WorkflowDefinition("it-helpdesk",2,original.initialState(),original.states(),original.transitions()));
        for(String mutation:List.of("resource_id='"+UUID.randomUUID()+"'","definition_version=2")) {
            try(var c=admin()) { sql(c,"UPDATE "+schema+".workflow_instances SET "+mutation+" WHERE instance_id='"+instance+"'"); }
            try {
                var before=snapshot();
