const navItems = [
  { to: "/", label: "Tổng quan", icon: LayoutDashboard, end: true },
  { to: "/requests", label: "Yêu cầu của tôi", icon: FileText },
  { to: "/approvals", label: "Bàn xử lý", icon: Workflow },
  { to: "/history", label: "Lịch sử hoạt động", icon: Activity },
];
function Layout() {
  const { role, helpdeskService } = usePortal();
  const [menu, setMenu] = useState(false);
  const [query, setQuery] = useState("");
  const [mobile, setMobile] = useState(
    () => matchMedia("(max-width: 760px)").matches,
  );
  const location = useLocation();
  const navigate = useNavigate();
  useEffect(() => {
    const media = matchMedia("(max-width: 760px)");
    const update = () => {
      setMobile(media.matches);
      setMenu(false);
    };
    media.addEventListener("change", update);
    return () => media.removeEventListener("change", update);
  }, []);
  useEffect(() => {
    if (!menu || !mobile) return;
    document.querySelector<HTMLAnchorElement>(".sidebar a")?.focus();
    const escape = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        setMenu(false);
        requestAnimationFrame(() =>
          document.querySelector<HTMLButtonElement>(".menu-button")?.focus(),
        );
      }
    };
    document.addEventListener("keydown", escape);
    return () => document.removeEventListener("keydown", escape);
  }, [menu, mobile]);
  useEffect(() => {
    setMenu(false);
    document.getElementById("main-content")?.focus();
  }, [location.pathname]);
  return (
    <div className="app-shell">
      <a href="#main-content" className="skip-link">
        Đến nội dung chính
      </a>
      {menu && (
        <button
          className="sidebar-overlay"
          aria-label="Đóng điều hướng"
          onClick={() => setMenu(false)}
        />
      )}
      <aside
        className={`sidebar ${menu ? "open" : ""}`}
        aria-label="Điều hướng chính"
        inert={mobile && !menu}
      >
        <Link to="/" className="brand">
          <img src="/favicon.svg" alt="" width="35" height="35" />
          <span>
            DX<span className="brand-dash">-</span>OS
            <small>University Service Portal</small>
          </span>
          <span className="brand-version">β</span>
        </Link>
        <div className="workspace">
          <span className="workspace-mark">
            <Building2 size={18} />
          </span>
          <div>
            <strong>University Workspace</strong>
            <small>Cổng dịch vụ đại học · Demo</small>
          </div>
          <ChevronDown size={14} />
        </div>
        <p className="nav-label">Dịch vụ đại học</p>
        <nav>
          {helpdeskService && (
            <NavLink to="/mvp/helpdesk" className="nav-item">
              <Workflow size={19} />
              <span>IT Helpdesk MVP · kiểm thử</span>
            </NavLink>
          )}
          {navItems.map(({ to, label, icon: ItemIcon, end }) => (
            <NavLink
              key={to}
              to={to}
              end={end}
              className={({ isActive }) =>
                isActive ? "nav-item active" : "nav-item"
              }
            >
              <ItemIcon size={19} strokeWidth={1.7} />
              <span>{label}</span>
              {to === "/approvals" && (
                <span className="nav-pill" aria-hidden="true">
                  Demo
                </span>
              )}
            </NavLink>
          ))}
        </nav>
        <p className="nav-label system-label">Hệ thống</p>
        <nav>
          <NavLink to="/integration" className="nav-item">
            <ShieldCheck size={19} />
            <span>Trạng thái tích hợp</span>
            <span className="status-dot" />
          </NavLink>
          <NavLink to="/session" className="nav-item">
            <Command size={19} />
            <span>Trạng thái phiên</span>
          </NavLink>
        </nav>
        <div className="sidebar-bottom">
          <div className="demo-card">
            <span className="demo-card-icon">
              <Workflow size={20} />
            </span>
            <strong>Một nền tảng. Nhiều dịch vụ.</strong>
            <p>Hai quy trình mẫu, cùng trải nghiệm DX-Core.</p>
            <Link to="/integration">
              Khám phá kiến trúc <ArrowUpRight size={14} />
            </Link>
          </div>
          <Link to="/session" className="profile">
            <span className="avatar">{role === "processor" ? "XB" : "NÁ"}</span>
            <span>
              <strong>
                {role === "processor"
                  ? "Lê Xuân Bảo"
                  : role
                    ? "Ngọc Ánh"
                    : "Khách trải nghiệm"}
              </strong>
              <small>
                {role === "processor"
                  ? "Người xử lý · Demo"
                  : role
                    ? "Người gửi yêu cầu · Demo"
                    : "Chưa vào phiên demo"}
              </small>
            </span>
            <ChevronDown size={14} />
          </Link>
        </div>
      </aside>
      <div className="main-shell" inert={mobile && menu}>
        <header className="topbar">
          <div className="breadcrumb">
            <button
              className="icon-button menu-button"
              onClick={() => setMenu(!menu)}
              aria-label={menu ? "Đóng menu" : "Mở menu"}
              aria-expanded={menu}
            >
              {menu ? <X size={21} /> : <Menu size={21} />}
            </button>
            <span>Cổng dịch vụ đại học</span>
            <span className="breadcrumb-divider">/</span>
            <strong>
              {location.pathname === "/"
                ? "Tổng quan"
                : location.pathname.includes("new")
                  ? "Tạo yêu cầu"
                  : location.pathname.includes("integration")
                    ? "Tích hợp"
                    : location.pathname.includes("session")
                      ? "Phiên làm việc"
                      : "Không gian làm việc"}
            </strong>
          </div>
          <div className="topbar-right">
            <form
              className="global-search"
              onSubmit={(e) => {
                e.preventDefault();
                navigate(`/requests?q=${encodeURIComponent(query)}`);
              }}
            >
              <Search size={16} />
              <input
                aria-label="Tìm kiếm toàn cục"
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                placeholder="Tìm yêu cầu…"
              />
              <kbd>↵</kbd>
            </form>
            <span className="environment">
              <span />
              MOCK / DEVELOPMENT
            </span>
            <Link
              className="icon-button help-link"
              to="/integration"
              aria-label="Thông tin tích hợp"
            >
              <LifeBuoy size={20} />
            </Link>
          </div>
        </header>
        <main id="main-content" tabIndex={-1}>
          <Outlet />
        </main>
        <footer className="footer">
          <span>
            DX-OS Open-Core <span className="footer-separator">/</span> Internal
            Service Portal
          </span>
          <span>Ứng dụng Tầng 2 · Prototype cho OLP 2026</span>
        </footer>
      </div>
    </div>
  );
}
function Protected() {
  const { role } = usePortal();
  return role ? <Outlet /> : <Navigate to="/session" replace />;
}
export function App({
  helpdeskService,
}: { helpdeskService?: MvpHelpdeskRequestPort } = {}) {
  return (
    <PortalProvider helpdeskService={helpdeskService}>
      <Routes>
        <Route path="/login" element={<AuthPage key="login" mode="login" />} />
        <Route
          path="/register"
          element={<AuthPage key="register" mode="register" />}
        />
        <Route element={<Layout />}>
          <Route path="/session" element={<Session />} />
          <Route path="/integration" element={<Integration />} />
          <Route element={<Protected />}>
            <Route path="/mvp/helpdesk/*" element={<HelpdeskPortal />} />
            <Route index element={<Dashboard />} />
            <Route path="/requests" element={<Requests />} />
            <Route path="/requests/new" element={<NewRequest />} />
            <Route path="/requests/:id" element={<RequestDetail />} />
            <Route path="/approvals" element={<Requests mode="approvals" />} />
            <Route path="/history" element={<Requests mode="history" />} />
          </Route>
          <Route
            path="*"
            element={
              <Empty
                title="Không tìm thấy trang"
                description="Đường dẫn này không tồn tại trong portal."
              >
                <Link className="button primary" to="/">
                  Về tổng quan
                </Link>
              </Empty>
            }
          />
        </Route>
      </Routes>
    </PortalProvider>
  );
}

import { useState } from "react";
import {
  act,
  fireEvent,
  render,
  screen,
  waitFor,
} from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { helpdeskId, helpdeskWire } from "../test/helpdeskFixtures";
import { helpdeskAssignmentFormProps } from "../services/mvp/assignmentBinding";
import { MvpApplicationError } from "../services/mvp/errors";
import {
  HelpdeskRequestService,
  type HelpdeskAssignmentService,
} from "../services/mvp/HelpdeskRequestService";
import {
  mapHelpdeskRequestPresentation,
  type HelpdeskPortalRequestPresentation,
} from "../services/mvp/helpdeskPresentation";
import { HelpdeskApiClient } from "../services/mvp/http/HelpdeskApiClient";
import type { HelpdeskHttpTransport } from "../services/mvp/http/transport";
import { AssignmentForm } from "./AssignmentForm";

function detail(overrides: Partial<HelpdeskPortalRequestPresentation> = {}) {
  return {
    ...mapHelpdeskRequestPresentation(
      helpdeskWire({
        requesterDisplayName: "Người gửi từ Backend",
        assigneeDisplayName: "Người xử lý hiện tại",
        eligibleAssignees: [{ id: "worker-2", displayName: "Người xử lý mới" }],
      }),
    ),
    ...overrides,
  };
}

function fakeService() {
  return {
    assign: vi
      .fn<HelpdeskAssignmentService["assign"]>()
      .mockResolvedValue(detail()),
    detail: vi
      .fn<HelpdeskAssignmentService["detail"]>()
      .mockResolvedValue(detail()),
  } satisfies HelpdeskAssignmentService;
}

// A test-only host. The production Portal remains bound to its MOCK service.
function Host({
  initial,
  service,
}: {
  initial: HelpdeskPortalRequestPresentation;
  service: HelpdeskAssignmentService;
}) {
  const [current, setCurrent] = useState(initial);
  const props = helpdeskAssignmentFormProps(current, service, setCurrent);
  return (
    <>
      <output data-testid="authoritative">
        {current.state}:{current.version}:{current.assignmentVersion}:
        {current.assigneeId}
      </output>
      {props && <AssignmentForm {...props} />}
    </>
  );
}

function deferred<T>() {
  let resolve!: (value: T) => void;
  const promise = new Promise<T>((res) => {
    resolve = res;
  });
  return { promise, resolve };
}

let assertNoLive: () => void;
beforeEach(() => {
  const fetchSpy = vi.spyOn(globalThis, "fetch").mockImplementation(() => {
    throw new Error("Unexpected LIVE fetch");
  });
  const xhrSpy = vi
    .spyOn(XMLHttpRequest.prototype, "send")
    .mockImplementation(() => {
      throw new Error("Unexpected LIVE XHR");
    });
  assertNoLive = () => {
    expect(fetchSpy).not.toHaveBeenCalled();
    expect(xhrSpy).not.toHaveBeenCalled();
  };
});
afterEach(() => {
  try {
    assertNoLive();
  } finally {
    vi.restoreAllMocks();
  }
});

describe("APP-11 standalone Application binding using fake service", () => {
  it.each(
    [[], ["triage"], ["start"], ["start_work"]].map((allowedActions) => ({
      allowedActions,
    })),
  )(
    "does not mount without allowedActions assign: $allowedActions, even with populated eligibility",
    ({ allowedActions }) => {
      const service = fakeService();
      render(<Host initial={detail({ allowedActions })} service={service} />);
      expect(screen.queryByRole("form")).not.toBeInTheDocument();
      expect(service.assign).not.toHaveBeenCalled();
      expect(service.detail).not.toHaveBeenCalled();
    },
  );

  it.each([
    { eligibleAssignees: undefined },
    { eligibleAssignees: null },
    { eligibleAssignees: { items: [], completeness: "unknown" as const } },
    {
      eligibleAssignees: {
        items: [
          {
            id: { scope: "assignee" as const, value: " " },
            displayName: "Name",
          },
        ],
        completeness: "unknown" as const,
      },
    },
    {
      eligibleAssignees: {
        items: [
          { id: { scope: "assignee" as const, value: "a".repeat(1025) } },
        ],
        completeness: "unknown" as const,
      },
    },
    ...[undefined, null, NaN, -1, 0.5, Number.MAX_SAFE_INTEGER + 1].map(
      (assignmentVersion) => ({
        assignmentVersion: assignmentVersion as number,
      }),
    ),
    ...["SUBMITTED", "IN_PROGRESS", "RESOLVED", "CONFIRMED"].map((state) => ({
      state,
    })),
  ])(
    "blocks invalid/missing eligibility, assignment version or policy state: %j",
    (overrides) => {
      const service = fakeService();
      render(<Host initial={detail(overrides)} service={service} />);
      expect(screen.getByRole("button", { name: "Phân công" })).toBeDisabled();
      fireEvent.submit(screen.getByRole("form"));
      expect(service.assign).not.toHaveBeenCalled();
      expect(service.detail).not.toHaveBeenCalled();
    },
  );

  it("uses assignmentVersion zero separately from Workflow 17, awaits authoritative Detail and prevents double submit", async () => {
    const service = fakeService();
    const write = deferred<HelpdeskPortalRequestPresentation>();
    const read = deferred<HelpdeskPortalRequestPresentation>();
    service.assign.mockReturnValue(write.promise);
    service.detail.mockReturnValue(read.promise);
    const initial = detail();
    const user = userEvent.setup();
    render(<Host initial={initial} service={service} />);
    expect(
      screen.getByText("Người xử lý hiện tại", { selector: "span" }),
    ).toBeVisible();
    await user.selectOptions(screen.getByRole("combobox"), "choice-0");
    await user.dblClick(screen.getByRole("button", { name: "Phân công" }));
    expect(service.assign).toHaveBeenCalledExactlyOnceWith(helpdeskId, {
      assigneeId: "worker-2",
      expectedAssignmentVersion: 0,
    });
    expect(service.detail).not.toHaveBeenCalled();
    expect(screen.getByTestId("authoritative")).toHaveTextContent(
      "TRIAGED:17:0:test-worker-subject",
    );
    expect(
      screen.getByRole("button", { name: "Đang phân công…" }),
    ).toBeDisabled();
    await act(async () => {
      // Mutation DTOs do not include eligible list/names. Do not invent either.
      write.resolve(
        mapHelpdeskRequestPresentation(
          helpdeskWire({ assigneeId: "worker-2", assignmentVersion: 1 }),
        ),
      );
      await write.promise;
    });
    expect(service.detail).toHaveBeenCalledExactlyOnceWith(helpdeskId);
    expect(screen.getByTestId("authoritative")).toHaveTextContent(
      "TRIAGED:17:0:test-worker-subject",
    );
    await act(async () => {
      read.resolve(
        detail({
          assigneeId: "worker-2",
          assignmentVersion: 1,
          currentAssignee: {
            id: { scope: "assignee", value: "worker-2" },
            displayName: "Tên sau reload Detail",
          },
        }),
      );
      await read.promise;
    });
    expect(
      await screen.findByText("Tên sau reload Detail", { selector: "span" }),
    ).toBeVisible();
    expect(screen.getByTestId("authoritative")).toHaveTextContent(
      "TRIAGED:17:1:worker-2",
    );
    await user.selectOptions(screen.getByRole("combobox"), "choice-0");
    await user.click(screen.getByRole("button", { name: "Phân công" }));
    await waitFor(() => expect(service.assign).toHaveBeenCalledTimes(2));
    expect(service.assign.mock.calls[1][1]).toEqual({
      assigneeId: "worker-2",
      expectedAssignmentVersion: 1,
    });
  });

  it.each([
    "CONFLICT",
    "COMMIT_OUTCOME_UNKNOWN",
    "UNAUTHENTICATED",
    "FORBIDDEN",
    "NOT_FOUND",
  ] as const)(
    "shows safe %s and locks write without retry, refresh or optimistic changes",
    async (code) => {
      const service = fakeService();
      service.assign.mockRejectedValue(new MvpApplicationError(code));
      const user = userEvent.setup();
      const view = render(<Host initial={detail()} service={service} />);
      await user.selectOptions(screen.getByRole("combobox"), "choice-0");
      await user.dblClick(screen.getByRole("button", { name: "Phân công" }));
      expect(await screen.findByRole("alert")).toHaveTextContent(
        new MvpApplicationError(code).message,
      );
      view.rerender(
        <Host initial={detail({ assignmentVersion: 1 })} service={service} />,
      );
      fireEvent.submit(screen.getByRole("form"));
      expect(screen.getByRole("button", { name: "Phân công" })).toBeDisabled();
      expect(service.assign).toHaveBeenCalledTimes(1);
      expect(service.detail).not.toHaveBeenCalled();
      expect(screen.getByTestId("authoritative")).toHaveTextContent(
        "TRIAGED:17:0:test-worker-subject",
      );
    },
  );

  it("locks after a successful write followed by failed Detail reload without replay", async () => {
    const service = fakeService();
    service.detail.mockRejectedValue(
      new MvpApplicationError("NETWORK_FAILURE"),
    );
    const user = userEvent.setup();
    render(<Host initial={detail()} service={service} />);
    await user.selectOptions(screen.getByRole("combobox"), "choice-0");
    await user.click(screen.getByRole("button", { name: "Phân công" }));
    expect(await screen.findByRole("alert")).toHaveTextContent(
      new MvpApplicationError("COMMIT_OUTCOME_UNKNOWN").message,
    );
    fireEvent.submit(screen.getByRole("form"));
    expect(service.assign).toHaveBeenCalledTimes(1);
    expect(service.detail).toHaveBeenCalledTimes(1);
    expect(
      screen.getByText("Người xử lý hiện tại", { selector: "span" }),
    ).toBeVisible();
  });

  it("keeps redacted names redacted while selecting the real eligible ID", async () => {
    const initial = detail({
      currentAssignee: { id: { scope: "assignee", value: "current" } },
      eligibleAssignees: {
        items: [
          {
            id: { scope: "assignee", value: "worker-redacted" },
            displayName: null,
          },
        ],
        completeness: "unknown",
      },
    });
    const service = fakeService();
    render(<Host initial={initial} service={service} />);
    expect(
      screen.getByText("Tên không được cung cấp", { selector: "span" }),
    ).toBeVisible();
    const user = userEvent.setup();
    await user.selectOptions(screen.getByRole("combobox"), "choice-0");
    await user.click(screen.getByRole("button", { name: "Phân công" }));
    expect(service.assign).toHaveBeenCalledExactlyOnceWith(helpdeskId, {
      assigneeId: "worker-redacted",
      expectedAssignmentVersion: 0,
    });
  });

  it("rejects an ID not supplied by authorized Detail before writing", async () => {
    const service = fakeService();
    const props = helpdeskAssignmentFormProps(detail(), service, vi.fn());
    expect(props?.submission?.status).toBe("ready");
    if (props?.submission?.status !== "ready")
      throw new Error("Expected ready test binding");
    await expect(
      props.submission.submitAssignment({ scope: "assignee", value: "forged" }),
    ).rejects.toThrow(RangeError);
    expect(service.assign).not.toHaveBeenCalled();
  });
});

describe("APP-10/11/13 fake transport integration", () => {
  it.each([
    [401, "UNAUTHENTICATED"],
    [403, "FORBIDDEN"],
    [404, "NOT_FOUND"],
    [409, "CONFLICT"],
    [503, "COMMIT_OUTCOME_UNKNOWN"],
  ] as const)(
    "assignment HTTP %s shows a safe error and locks without replay or optimistic updates",
    async (status, code) => {
      const transport = vi
        .fn<HelpdeskHttpTransport>()
        .mockResolvedValueOnce({
          status: 200,
          body: helpdeskWire({
            eligibleAssignees: [{ id: "worker-2", displayName: null }],
          }),
        })
        .mockResolvedValue({
          status,
          body: {
            code: "COMMIT_OUTCOME_UNKNOWN",
            message: "private diagnostic",
          },
        });
      const onSessionInvalid = vi.fn();
      const service = new HelpdeskRequestService(
        new HelpdeskApiClient(transport, onSessionInvalid),
      );
      render(
        <Host initial={await service.detail(helpdeskId)} service={service} />,
      );
      const user = userEvent.setup();
      await user.selectOptions(screen.getByRole("combobox"), "choice-0");
      await user.dblClick(screen.getByRole("button", { name: "Phân công" }));
      expect(await screen.findByRole("alert")).toHaveTextContent(
        new MvpApplicationError(code).message,
      );
      expect(screen.getByRole("alert")).not.toHaveTextContent("private");
      fireEvent.submit(screen.getByRole("form"));
      expect(screen.getByRole("button", { name: "Phân công" })).toBeDisabled();
      expect(screen.getByTestId("authoritative")).toHaveTextContent(
        "TRIAGED:17:0:test-worker-subject",
      );
      expect(transport).toHaveBeenCalledTimes(2);
      expect(onSessionInvalid).toHaveBeenCalledTimes(status === 401 ? 1 : 0);
      if (status === 401) {
        await expect(service.detail(helpdeskId)).rejects.toMatchObject({
          code: "UNAUTHENTICATED",
        });
        expect(transport).toHaveBeenCalledTimes(2);
      }
    },
  );

  it("maps Detail, posts assignment guard only, then reloads authoritative Detail through Application service", async () => {
    const authorized = helpdeskWire({
      eligibleAssignees: [{ id: "worker-2", displayName: "Tên Backend" }],
    });
    const assigned = helpdeskWire({
      assigneeId: "worker-2",
      assignmentVersion: 1,
    });
    const transport = vi
      .fn<HelpdeskHttpTransport>()
      .mockResolvedValueOnce({ status: 200, body: authorized })
      .mockResolvedValueOnce({ status: 200, body: assigned })
      .mockResolvedValueOnce({
        status: 200,
        body: {
          ...assigned,
          assigneeDisplayName: "Tên từ Detail",
          eligibleAssignees: [],
        },
      });
    const service = new HelpdeskRequestService(
      new HelpdeskApiClient(transport, vi.fn()),
    );
    render(
      <Host initial={await service.detail(helpdeskId)} service={service} />,
    );
    const user = userEvent.setup();
    await user.selectOptions(screen.getByRole("combobox"), "choice-0");
    await user.click(screen.getByRole("button", { name: "Phân công" }));
    expect(
      await screen.findByText("Tên từ Detail", { selector: "span" }),
    ).toBeVisible();
    expect(
      transport.mock.calls.map(([request]) => [
        request.method,
        request.path,
        request.body,
      ]),
    ).toEqual([
      ["GET", `/api/v1/mvp/requests/${helpdeskId}`, undefined],
      [
        "POST",
        `/api/v1/mvp/requests/${helpdeskId}/assign`,
        { assigneeId: "worker-2", expectedAssignmentVersion: 0 },
      ],
      ["GET", `/api/v1/mvp/requests/${helpdeskId}`, undefined],
    ]);
    expect(screen.getByTestId("authoritative")).toHaveTextContent(
      "TRIAGED:17:1:worker-2",
    );
    expect(screen.getByRole("button", { name: "Phân công" })).toBeDisabled();
  });
});

import {
  afterEach,
  beforeEach,
  describe,
  expect,
  expectTypeOf,
  it,
  vi,
} from "vitest";
import {
  act,
  cleanup,
  fireEvent,
  render,
  screen,
  waitFor,
} from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import {
  AssignmentForm,
  type AssignmentFormProps,
  type AssignmentSubmitBinding,
} from "./AssignmentForm";
import { MvpApplicationError, type MvpErrorCode } from "../services/mvp/errors";
import type { Assignee, AssigneeId } from "../services/mvp/types";

const first = {
  id: { scope: "assignee", value: { opaque: "test-person-1" } },
  displayName: "Nguyễn An",
} satisfies Assignee;
const second = {
  id: { scope: "assignee", value: { opaque: "test-person-2" } },
  displayName: "Nguyễn An",
} satisfies Assignee;

/** Test-only ready callback: no production concurrency contract/token implied. */
function fixture(overrides: Partial<AssignmentFormProps> = {}) {
  const submitAssignment = vi
    .fn<(id: AssigneeId) => Promise<void>>()
    .mockResolvedValue(undefined);
  const props: AssignmentFormProps = {
    currentAssignee: null,
    eligibleAssignees: { items: [first, second], completeness: "complete" },
    assignmentPermission: "allowed",
    submission: { status: "ready", submitAssignment },
    ...overrides,
  };
  return { props, submitAssignment };
}

function deferred() {
  let resolve!: () => void;
  const promise = new Promise<void>((resolvePromise) => {
    resolve = resolvePromise;
  });
  return { promise, resolve };
}

let assertNoNetwork: () => void;
beforeEach(() => {
  const fetchSpy = vi.spyOn(globalThis, "fetch").mockImplementation(() => {
    throw new Error("Unexpected LIVE fetch");
  });
  const xhrSpy = vi
    .spyOn(XMLHttpRequest.prototype, "send")
    .mockImplementation(() => {
      throw new Error("Unexpected LIVE XMLHttpRequest");
    });
  assertNoNetwork = () => {
    expect(fetchSpy).not.toHaveBeenCalled();
    expect(xhrSpy).not.toHaveBeenCalled();
  };
});

afterEach(() => {
  cleanup();
  try {
    assertNoNetwork();
  } finally {
    vi.restoreAllMocks();
  }
});

describe("APP-11 standalone assignment capability and data", () => {
  it.each([undefined, "unknown", "denied"] as const)(
    "blocks submit with permission %s despite a populated eligible list and fake ready binding",
    (assignmentPermission) => {
      const { props, submitAssignment } = fixture({ assignmentPermission });
      render(<AssignmentForm {...props} />);
      const form = screen.getByRole("form", { name: "Phân công xử lý" });
      const select = screen.getByRole("combobox", { name: "Người xử lý" });
      expect(select).toBeDisabled();
      expect(screen.getByRole("button", { name: "Phân công" })).toBeDisabled();
      // Even bypassing the disabled controls cannot bypass the callback guard.
      fireEvent.change(select, { target: { value: "choice-0" } });
      fireEvent.submit(form);
      expect(submitAssignment).not.toHaveBeenCalled();
      expect(select).toHaveAccessibleDescription(
        assignmentPermission === "denied"
          ? "Bạn không có quyền phân công yêu cầu này."
          : "Chưa xác nhận quyền phân công.",
      );
    },
  );

  it("defaults to blocked without any props, without requiring Router or PortalProvider", () => {
    render(<AssignmentForm />);
    expect(screen.getByText("Chưa có thông tin được cung cấp")).toBeVisible();
    expect(
      screen.getByRole("heading", { name: "Chưa có danh sách người xử lý" }),
    ).toBeVisible();
    expect(screen.getByRole("button", { name: "Phân công" })).toBeDisabled();
  });

  it.each([
    undefined,
    { status: "blocked" as const, reason: "Chờ xác nhận dữ liệu phân công." },
  ])(
    "requires an explicitly prepared Application callback, not a fabricated version",
    (submission) => {
      const { props, submitAssignment } = fixture({ submission });
      render(<AssignmentForm {...props} />);
      fireEvent.change(screen.getByRole("combobox"), {
        target: { value: "choice-0" },
      });
      fireEvent.submit(screen.getByRole("form"));
      expect(screen.getByRole("button", { name: "Phân công" })).toBeDisabled();
      expect(submitAssignment).not.toHaveBeenCalled();
      expect(
        screen.getByText(submission?.reason ?? "Phân công chưa sẵn sàng."),
      ).toBeVisible();
    },
  );

  it.each(["complete", "partial", "unknown"] as const)(
    "handles an empty %s projection without claiming other people are eligible",
    (completeness) => {
      const { props, submitAssignment } = fixture({
        eligibleAssignees: { items: [], completeness },
      });
      render(<AssignmentForm {...props} />);
      expect(
        screen.getByRole("heading", {
          name: "Danh sách được cung cấp chưa có người xử lý",
        }),
      ).toBeVisible();
      expect(screen.getByRole("combobox")).toBeDisabled();
      expect(screen.getByRole("button", { name: "Phân công" })).toBeDisabled();
      fireEvent.submit(screen.getByRole("form"));
      expect(submitAssignment).not.toHaveBeenCalled();
    },
  );

  it("distinguishes unavailable eligibility from an empty authorized list", () => {
    const { props, submitAssignment } = fixture({
      eligibleAssignees: undefined,
    });
    render(<AssignmentForm {...props} />);
    expect(
      screen.getByRole("heading", { name: "Chưa có danh sách người xử lý" }),
    ).toBeVisible();
    expect(screen.getByRole("button", { name: "Phân công" })).toBeDisabled();
    expect(submitAssignment).not.toHaveBeenCalled();
  });

  it("shows current assignment as supplied and does not preselect it as a new command", () => {
    const { props, submitAssignment } = fixture({ currentAssignee: first });
    render(<AssignmentForm {...props} />);
    expect(screen.getByText("Nguyễn An", { selector: "span" })).toBeVisible();
    expect(screen.getByRole("combobox")).toHaveValue("");
    expect(screen.getByRole("button", { name: "Phân công" })).toBeDisabled();
    expect(submitAssignment).not.toHaveBeenCalled();
  });

  it("shows loading and prevents submit while loading", () => {
    const { props, submitAssignment } = fixture({ loading: true });
    render(<AssignmentForm {...props} />);
    expect(screen.getByRole("status")).toHaveTextContent(
      "Đang tải dữ liệu phân công…",
    );
    expect(screen.getByRole("form")).toHaveAttribute("aria-busy", "true");
    expect(screen.getByRole("combobox")).toBeDisabled();
    fireEvent.submit(screen.getByRole("form"));
    expect(submitAssignment).not.toHaveBeenCalled();
  });

  it("shows the supplied read error without submitting or initiating a reload", () => {
    const { props, submitAssignment } = fixture({
      error: "Không thể tải dữ liệu phân công.",
    });
    render(<AssignmentForm {...props} />);
    expect(screen.getByRole("alert")).toHaveTextContent(
      "Không thể tải dữ liệu phân công.",
    );
    expect(screen.getByRole("button", { name: "Phân công" })).toBeDisabled();
    fireEvent.submit(screen.getByRole("form"));
    expect(submitAssignment).not.toHaveBeenCalled();
  });

  it("keeps Workflow, role and version metadata out of the form contract", () => {
    expectTypeOf<"role">().not.toExtend<keyof AssignmentFormProps>();
    expectTypeOf<"state">().not.toExtend<keyof AssignmentFormProps>();
    expectTypeOf<"workflowVersion">().not.toExtend<keyof AssignmentFormProps>();
    expectTypeOf<"assignmentVersion">().not.toExtend<
      keyof AssignmentFormProps
    >();
    expectTypeOf<
      Parameters<
        Extract<
          AssignmentSubmitBinding,
          { status: "ready" }
        >["submitAssignment"]
      >[0]
    >().toEqualTypeOf<AssigneeId>();
  });
});

describe("APP-11 assignment selection and single write", () => {
  it("displays names but passes the original opaque ID, even with duplicate names", async () => {
    const { props, submitAssignment } = fixture();
    const user = userEvent.setup();
    render(<AssignmentForm {...props} />);
    expect(screen.getAllByRole("option", { name: "Nguyễn An" })).toHaveLength(
      2,
    );
    expect(
      screen
        .getAllByRole("option")
        .map((option) => (option as HTMLOptionElement).value),
    ).toEqual(["", "choice-0", "choice-1"]);
    await user.selectOptions(screen.getByRole("combobox"), "choice-1");
    await user.click(screen.getByRole("button", { name: "Phân công" }));
    await waitFor(() => expect(submitAssignment).toHaveBeenCalledTimes(1));
    expect(submitAssignment.mock.calls[0]).toEqual([second.id]);
    expect(submitAssignment.mock.calls[0][0]).toBe(second.id);
    expect(screen.getByText("Chưa phân công")).toBeVisible();
    expect(screen.queryByText(/Đã phân công/)).not.toBeInTheDocument();
  });

  it("keeps the selected ID when the supplied list is reordered", async () => {
    const { props, submitAssignment } = fixture();
    const user = userEvent.setup();
    const view = render(<AssignmentForm {...props} />);
    await user.selectOptions(screen.getByRole("combobox"), "choice-0");
    view.rerender(
      <AssignmentForm
        {...props}
        eligibleAssignees={{ items: [second, first], completeness: "complete" }}
      />,
    );
    expect(screen.getByRole("combobox")).toHaveValue("choice-1");
    await user.click(screen.getByRole("button", { name: "Phân công" }));
    expect(submitAssignment.mock.calls[0][0]).toBe(first.id);
  });

  it("invalidates a removed or replaced reference instead of submitting another person", async () => {
    const { props, submitAssignment } = fixture();
    const user = userEvent.setup();
    const view = render(<AssignmentForm {...props} />);
    await user.selectOptions(screen.getByRole("combobox"), "choice-0");
    view.rerender(
      <AssignmentForm
        {...props}
        eligibleAssignees={{
          items: [{ ...first, id: { ...first.id } }, second],
          completeness: "complete",
        }}
      />,
    );
    expect(screen.getByRole("combobox")).toHaveValue("");
    expect(screen.getByRole("combobox")).toHaveAccessibleDescription(
      "Danh sách đã thay đổi. Hãy chọn lại người xử lý.",
    );
    expect(screen.getByRole("button", { name: "Phân công" })).toBeDisabled();
    fireEvent.submit(screen.getByRole("form"));
    expect(submitAssignment).not.toHaveBeenCalled();
  });

  it("blocks an existing selection immediately when permission is revoked", async () => {
    const { props, submitAssignment } = fixture();
    const user = userEvent.setup();
    const view = render(<AssignmentForm {...props} />);
    await user.selectOptions(screen.getByRole("combobox"), "choice-0");
    expect(screen.getByRole("button", { name: "Phân công" })).toBeEnabled();
    view.rerender(<AssignmentForm {...props} assignmentPermission="denied" />);
    fireEvent.submit(screen.getByRole("form"));
    expect(screen.getByRole("button", { name: "Phân công" })).toBeDisabled();
    expect(submitAssignment).not.toHaveBeenCalled();
  });

  it("blocks duplicate submit while pending and never replaces authoritative assignee on success", async () => {
    const current = {
      id: { scope: "assignee", value: "current-person" },
      displayName: "Người đang phụ trách",
    } satisfies Assignee;
    const { props, submitAssignment } = fixture({ currentAssignee: current });
    const pending = deferred();
    submitAssignment.mockReturnValue(pending.promise);
    const user = userEvent.setup();
    render(<AssignmentForm {...props} />);
    await user.selectOptions(screen.getByRole("combobox"), "choice-1");
    await user.dblClick(screen.getByRole("button", { name: "Phân công" }));
    fireEvent.submit(screen.getByRole("form"));
    expect(submitAssignment).toHaveBeenCalledTimes(1);
    expect(
      screen.getByRole("button", { name: "Đang phân công…" }),
    ).toBeDisabled();
    expect(screen.getByRole("form")).toHaveAttribute("aria-busy", "true");
    await act(async () => {
      pending.resolve();
      await pending.promise;
    });
    expect(screen.getByRole("form")).toHaveAttribute("aria-busy", "false");
    expect(screen.getByRole("combobox")).toHaveValue("");
    expect(screen.getByText(current.displayName)).toBeVisible();
    expect(props.currentAssignee).toBe(current);
    expect(submitAssignment).toHaveBeenCalledTimes(1);
  });

  it.each<MvpErrorCode>([
    "UNAUTHENTICATED",
    "FORBIDDEN",
    "NOT_FOUND",
    "CONFLICT",
    "NETWORK_FAILURE",
    "COMMIT_OUTCOME_UNKNOWN",
  ])("does not retry %s and keeps the write stopped", async (code) => {
    const { props, submitAssignment } = fixture();
    submitAssignment.mockRejectedValue(new MvpApplicationError(code));
    const user = userEvent.setup();
    render(<AssignmentForm {...props} />);
    await user.selectOptions(screen.getByRole("combobox"), "choice-0");
    await user.dblClick(screen.getByRole("button", { name: "Phân công" }));
    expect(await screen.findByRole("alert")).toBeVisible();
    expect(screen.getByRole("button", { name: "Phân công" })).toBeDisabled();
    fireEvent.submit(screen.getByRole("form"));
    expect(submitAssignment).toHaveBeenCalledTimes(1);
  });

  it("keeps a lost-response write stopped after props and callbacks refresh", async () => {
    const { props, submitAssignment } = fixture();
    let committed = 0;
    submitAssignment.mockImplementation(async () => {
      committed += 1;
      throw new Error("Sensitive diagnostic: reply lost after commit");
    });
    const user = userEvent.setup();
    const view = render(<AssignmentForm {...props} />);
    await user.selectOptions(screen.getByRole("combobox"), "choice-0");
    await user.click(screen.getByRole("button", { name: "Phân công" }));
    expect(await screen.findByRole("alert")).toHaveTextContent(
      "Chưa xác định kết quả ghi",
    );
    expect(screen.getByRole("alert")).not.toHaveTextContent(
      "Sensitive diagnostic",
    );
    const next = fixture();
    view.rerender(<AssignmentForm {...next.props} currentAssignee={first} />);
    fireEvent.submit(screen.getByRole("form"));
    expect(screen.getByRole("button", { name: "Phân công" })).toBeDisabled();
    expect(submitAssignment).toHaveBeenCalledTimes(1);
    expect(next.submitAssignment).not.toHaveBeenCalled();
    expect(committed).toBe(1);
  });
});

import { useId, useRef, useState, type FormEvent } from "react";
import { AlertCircle, LoaderCircle } from "lucide-react";
import {
  executeWriteOnce,
  MvpApplicationError,
  networkFailure,
} from "../services/mvp/errors";
import type {
  Assignee,
  AssigneeId,
  EligibleAssignees,
} from "../services/mvp/types";
import { Empty, Icon } from "./ui";

/** Internal UI capability, populated only from confirmed Backend permission. */
export type AssignmentPermission = "allowed" | "denied" | "unknown";

/**
 * CANDIDATE callback seam, not an HTTP DTO or a concurrency token.
 * A ready callback must be bound by Application to the request and its approved
 * assignment-specific guard. Never use Workflow version as that guard.
 * The Helpdesk Application binding uses the reviewed assignmentVersion contract.
 */
export type AssignmentSubmitBinding =
  | { readonly status: "blocked"; readonly reason?: string }
  | {
      readonly status: "ready";
      readonly submitAssignment: (assigneeId: AssigneeId) => Promise<void>;
    };

export interface AssignmentFormProps {
  readonly currentAssignee?: Assignee | null;
  readonly eligibleAssignees?: EligibleAssignees;
  readonly assignmentPermission?: AssignmentPermission;
  readonly loading?: boolean;
  /** Safe, user-facing Application message, not a raw server diagnostic. */
  readonly error?: string;
  readonly submission?: AssignmentSubmitBinding;
}

/**
 * Reusable form, mounted by APP-14 only with an injected MVP service. No role/state inference,
 * token creation, Workflow transition, optimistic assignee update or HTTP calls.
 * Write errors stop this instance; reopening/reconciliation belongs to Application
 * after its contract is approved. Prop changes do not retry or clear that stop.
 */
export function AssignmentForm({
  currentAssignee,
  eligibleAssignees,
  assignmentPermission = "unknown",
  loading = false,
  error,
  submission,
}: AssignmentFormProps) {
  const formId = useId();
  const [selectedId, setSelectedId] = useState<AssigneeId | null>(null);
  const [busy, setBusy] = useState(false);
  const [writeError, setWriteError] = useState<MvpApplicationError | null>(
    null,
  );
  const lock = useRef(false);
  const choices = eligibleAssignees?.items ?? [];
  // Local option keys are NOT IDs. Preserve the actual opaque ID reference.
  // A refreshed reference requires an explicit new selection; no guessed ID
  // equality/serialization protocol is introduced while the DTO is unconfirmed.
  const selectedIndex = choices.findIndex((item) => item.id === selectedId);
  const selected = choices[selectedIndex];
  const staleSelection = selectedId !== null && selected === undefined;
  const bindingReady = submission?.status === "ready";
  const blocked =
    assignmentPermission !== "allowed" ||
    !bindingReady ||
    loading ||
    Boolean(error) ||
    busy ||
    writeError !== null;
  const canSubmit = !blocked && selected !== undefined;

  const hint =
    assignmentPermission !== "allowed"
      ? assignmentPermission === "denied"
        ? "Bạn không có quyền phân công yêu cầu này."
        : "Chưa xác nhận quyền phân công."
      : !bindingReady
        ? submission?.status === "blocked" && submission.reason
          ? submission.reason
          : "Phân công chưa sẵn sàng."
        : writeError
          ? "Đã dừng gửi. Cần kiểm tra kết quả trước khi tiếp tục."
          : staleSelection
            ? "Danh sách đã thay đổi. Hãy chọn lại người xử lý."
            : "Chọn người xử lý từ danh sách được cung cấp.";

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (lock.current || !canSubmit || submission?.status !== "ready") return;
    lock.current = true;
    setBusy(true);
    try {
      await executeWriteOnce(() => submission.submitAssignment(selected.id));
      // Application owns authoritative data. Never replace currentAssignee or
      // announce an optimistic success; a caller may refresh its supplied props.
      setSelectedId(null);
    } catch (failure) {
      setWriteError(
        failure instanceof MvpApplicationError
          ? failure
          : networkFailure("write", failure),
      );
    } finally {
      lock.current = false;
      setBusy(false);
    }
  }

  return (
    <form
      className="panel request-form"
      aria-labelledby={`${formId}-heading`}
      aria-busy={loading || busy}
      onSubmit={submit}
    >
      <h2 id={`${formId}-heading`}>Phân công xử lý</h2>
      <p>
        Người phụ trách hiện tại:{" "}
        <span>
          {currentAssignee === undefined
            ? "Chưa có thông tin được cung cấp"
            : currentAssignee === null
              ? "Chưa phân công"
              : currentAssignee.displayName || "Tên không được cung cấp"}
        </span>
      </p>
      {loading && (
        <div className="loading-state" role="status">
          <Icon icon={LoaderCircle} />
          <p>Đang tải dữ liệu phân công…</p>
        </div>
      )}
      {error && (
        <div className="inline-notice" role="alert">
          <Icon icon={AlertCircle} />
          <p>{error}</p>
        </div>
      )}
      {writeError && (
        <div className="inline-notice" role="alert">
          <Icon icon={AlertCircle} />
          <p>{writeError.message}</p>
        </div>
      )}
      {!loading && !error && choices.length === 0 && (
        <Empty
          title={
            eligibleAssignees === undefined
              ? "Chưa có danh sách người xử lý"
              : "Danh sách được cung cấp chưa có người xử lý"
          }
          description="Chưa có người xử lý để chọn trong dữ liệu được phép cung cấp."
        />
      )}
      <fieldset disabled={blocked || choices.length === 0}>
        <legend>Chọn người xử lý</legend>
        <label className="field" htmlFor={`${formId}-assignee`}>
          Người xử lý
          <select
            id={`${formId}-assignee`}
            value={selectedIndex < 0 ? "" : `choice-${selectedIndex}`}
            required
            aria-describedby={`${formId}-hint`}
            onChange={(event) => {
              const item = choices.find(
                (_, index) => `choice-${index}` === event.currentTarget.value,
              );
              setSelectedId(item?.id ?? null);
            }}
          >
            <option value="">Chọn người xử lý</option>
            {choices.map((item, index) => (
              <option key={`choice-${index}`} value={`choice-${index}`}>
                {item.displayName || "Tên không được cung cấp"}
              </option>
            ))}
          </select>
        </label>
        <div className="form-actions">
          <button
            type="submit"
            className="button primary"
            disabled={!canSubmit}
          >
            {busy ? "Đang phân công…" : "Phân công"}
          </button>
        </div>
      </fieldset>
      <p id={`${formId}-hint`} className="field-hint">
        {hint}
      </p>
    </form>
  );
}

import { useEffect, useRef, type ReactNode } from "react";
import {
  AlertCircle,
  ArrowRight,
  Check,
  Circle,
  Clock3,
  Inbox,
  LoaderCircle,
  X,
  type LucideIcon,
} from "lucide-react";
import { Link } from "react-router-dom";
import {
  formatDate,
  kindLabels,
  priorityLabels,
  statusLabels,
  type ServiceRequest,
  type TimelineEvent,
} from "../domain/request";

export function Icon({
  icon: Component,
  size = 18,
}: {
  icon: LucideIcon;
  size?: number;
}) {
  return <Component size={size} strokeWidth={1.75} aria-hidden="true" />;
}
export function StatusBadge({ status }: { status: ServiceRequest["status"] }) {
  return (
    <span className={`badge status-${status}`}>
      <Icon
        icon={
          status === "completed"
            ? Check
            : status === "processing"
              ? LoaderCircle
              : status === "pending"
                ? Clock3
                : Circle
        }
        size={13}
      />
      {statusLabels[status]}
    </span>
  );
}
export function Priority({
  priority,
}: {
  priority: ServiceRequest["priority"];
}) {
  return (
    <span className={`priority priority-${priority}`}>
      <span aria-hidden="true" />
      {priorityLabels[priority]}
    </span>
  );
}
export function PageHeading({
  eyebrow,
  title,
  description,
  children,
}: {
  eyebrow?: string;
  title: string;
  description: string;
  children?: ReactNode;
}) {
  return (
    <div className="page-heading">
      <div>
        {eyebrow && <p className="eyebrow">{eyebrow}</p>}
        <h1>{title}</h1>
        <p className="muted">{description}</p>
      </div>
      {children}
    </div>
  );
}
export function Loading() {
  return (
    <div className="loading-state" role="status">
      <LoaderCircle className="spinner" size={26} />
      <p>Đang tải dữ liệu demo…</p>
      <div className="skeleton" />
      <div className="skeleton short" />
    </div>
  );
}
export function Empty({
  title = "Chưa có yêu cầu phù hợp",
  description = "Thử đổi từ khóa hoặc xóa bộ lọc để xem thêm yêu cầu.",
  children,
}: {
  title?: string;
  description?: string;
  children?: ReactNode;
}) {
  return (
    <div className="empty">
      <span className="empty-icon">
        <Inbox size={28} />
      </span>
      <h3>{title}</h3>
      <p>{description}</p>
      {children}
    </div>
  );
}
export function ErrorState({
  message,
  onRetry,
}: {
  message: string;
  onRetry?: () => void;
}) {
  return (
    <div className="error-state" role="alert">
      <AlertCircle size={22} />
      <div>
        <strong>Chưa thể hoàn tất</strong>
        <p>{message}</p>
        {onRetry && (
          <button className="button secondary small" onClick={onRetry}>
            Tải lại dữ liệu
          </button>
        )}
        <Link className="text-link error-link" to="/session">
          Trạng thái phiên
        </Link>
      </div>
    </div>
  );
}
export function RequestTable({
  items,
  compact = false,
}: {
  items: ServiceRequest[];
  compact?: boolean;
}) {
  if (!items.length) return <Empty />;
  return (
    <div className="table-scroll">
      <table>
        <caption className="sr-only">Danh sách yêu cầu dịch vụ nội bộ</caption>
        <thead>
          <tr>
            <th>Yêu cầu</th>
            <th>Trạng thái</th>
            <th>Ưu tiên</th>
            {!compact && <th>Người yêu cầu</th>}
            <th>Cập nhật</th>
            <th>
              <span className="sr-only">Chi tiết</span>
            </th>
          </tr>
        </thead>
        <tbody>
          {items.map((r) => (
            <tr key={r.id}>
              <td>
                <Link className="request-title" to={`/requests/${r.id}`}>
                  <span className="request-id">
                    {r.id} <span>· {kindLabels[r.kind]}</span>
                  </span>
                  <strong>{r.title}</strong>
                </Link>
              </td>
              <td>
                <StatusBadge status={r.status} />
              </td>
              <td>
                <Priority priority={r.priority} />
              </td>
              {!compact && (
                <td>
                  <span className="person">
                    <span className="avatar tiny">
                      {r.requester.split(" ").at(-1)?.slice(0, 1)}
                    </span>
                    {r.requester}
                  </span>
                </td>
              )}
              <td className="date-cell">
                {new Intl.DateTimeFormat("vi-VN", {
                  day: "2-digit",
                  month: "2-digit",
                  year: "numeric",
                }).format(new Date(r.updatedAt))}
              </td>
              <td>
                <Link
                  className="icon-button"
                  to={`/requests/${r.id}`}
                  aria-label={`Xem ${r.id}`}
                >
                  <ArrowRight size={16} />
                </Link>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
export function Timeline({ events }: { events: TimelineEvent[] }) {
  return (
    <ol className="timeline">
      {[...events]
        .sort((a, b) => Date.parse(b.at) - Date.parse(a.at))
        .map((event, i) => (
          <li key={event.id}>
            <span className={`timeline-dot ${i === 0 ? "latest" : ""}`}>
              <Check size={12} />
            </span>
            <div>
              <div className="timeline-title">
                <strong>{event.title}</strong>
                <time dateTime={event.at}>{formatDate(event.at)}</time>
              </div>
              <p>{event.note}</p>
              <span className="timeline-actor">{event.actor}</span>
            </div>
          </li>
        ))}
    </ol>
  );
}
export function Modal({
  title,
  children,
  onClose,
}: {
  title: string;
  children: ReactNode;
  onClose: () => void;
}) {
  const ref = useRef<HTMLDialogElement>(null);
  useEffect(() => {
    const dialog = ref.current!;
    const previousFocus = document.activeElement as HTMLElement | null;
    dialog.showModal();
    dialog.querySelector<HTMLTextAreaElement>("textarea")?.focus();
    return () => {
      dialog.close();
      if (previousFocus?.isConnected) previousFocus.focus();
    };
  }, []);
  return (
    <dialog
      ref={ref}
      aria-labelledby="dialog-title"
      onCancel={(e) => {
        e.preventDefault();
        onClose();
      }}
    >
      <div className="modal-heading">
        <h2 id="dialog-title">{title}</h2>
        <button
          className="icon-button"
          onClick={onClose}
          aria-label="Đóng hộp thoại"
        >
          <X size={20} />
        </button>
      </div>
      {children}
    </dialog>
  );
}

