// Legacy Application view model for injection tests, not a Backend DTO.
const provided: ServiceRequest = {
  id: "SEAM-01",
  kind: "it",
  title: "Yêu cầu do fake service cung cấp",
  description: "Dữ liệu kiểm thử seam Application, không gọi Backend API.",
  status: "resolved",
  priority: "normal",
  requester: "Mai An",
  department: "Phòng phát triển",
  location: "Văn phòng tầng 3",
  assignee: "Bộ phận CNTT",
  createdAt: "2026-10-25T02:00:00Z",
  updatedAt: "2026-10-25T03:00:00Z",
  version: 17,
  timeline: [
    {
      id: "seam-event",
      at: "2026-10-25T03:00:00Z",
      title: "Sự kiện từ fake service",
      actor: "Bộ phận CNTT",
      note: "Lịch sử do fake service cung cấp.",
    },
  ],
};

function fakeService(item: ServiceRequest = provided) {
  return {
    list: vi.fn<RequestService["list"]>().mockResolvedValue([item]),
    get: vi.fn<RequestService["get"]>().mockResolvedValue(item),
    actions: vi.fn<RequestService["actions"]>().mockReturnValue([]),
    create: vi.fn<RequestService["create"]>().mockResolvedValue(item),
    transition: vi.fn<RequestService["transition"]>().mockResolvedValue(item),
  } satisfies RequestService;
}

function deferred<T>() {
  let resolve!: (value: T) => void;
  let reject!: (error: unknown) => void;
  const promise = new Promise<T>((resolvePromise, rejectPromise) => {
    resolve = resolvePromise;
    reject = rejectPromise;
  });
  return { promise, resolve, reject };
}

function SessionProbe() {
  const { role, sessionExpired } = usePortal();
  return (
    <output data-testid="session">
      {role ?? "no-session"}:{sessionExpired ? "expired" : "active"}
    </output>
  );
}

function SessionControls() {
  const { setRole, role, sessionExpired } = usePortal();
  const navigate = useNavigate();
  const location = useLocation();
  return (
    <>
      <output data-testid="session-location">
        {location.pathname}:{role ?? "none"}:
        {sessionExpired ? "expired" : "active"}
      </output>
      <button
        onClick={() => {
          setRole(null);
          navigate("/session");
        }}
      >
        Test logout
      </button>
      <button
        onClick={() => {
          setRole("employee");
          navigate("/requests");
        }}
      >
        Test new session
      </button>
      <button onClick={() => navigate("/requests")}>Test leave form</button>
    </>
  );
}

function mountSessionPortal(service: RequestService, path: string) {
  return render(
    <MemoryRouter initialEntries={[path]}>
      <PortalProvider requestService={service}>
        <SessionControls />
        <Routes>
          <Route path="/requests/new" element={<NewRequest />} />
          <Route path="/requests/:id" element={<RequestDetail />} />
          <Route path="*" element={<p>Test destination</p>} />
        </Routes>
      </PortalProvider>
    </MemoryRouter>,
  );
}

function BindingProbe() {
  const { requestService } = usePortal();
  return (
    <output data-testid="binding">
      {requestService === defaultService ? "MOCK" : "injected"}
    </output>
  );
}

function ReadProbe() {
  const { data, loading, error } = useRequests();
  return (
    <output data-testid="read-result">
      {loading ? "loading" : error || data.map((item) => item.title).join(",")}
    </output>
  );
}

function mountPortal(service: RequestService, path = "/requests") {
  return render(
    <MemoryRouter initialEntries={[path]}>
      <PortalProvider requestService={service}>
        <SessionProbe />
        <Routes>
          <Route path="/requests" element={<Requests />} />
          <Route path="/approvals" element={<Requests mode="approvals" />} />
          <Route path="/history" element={<Requests mode="history" />} />
          <Route path="/requests/new" element={<NewRequest />} />
          <Route path="/requests/:id" element={<RequestDetail />} />
        </Routes>
      </PortalProvider>
    </MemoryRouter>,
  );
}

async function fillCreateForm(user: ReturnType<typeof userEvent.setup>) {
  await user.type(
    screen.getByRole("textbox", { name: /Tiêu đề yêu cầu/ }),
    "Sự cố phần mềm từ seam",
  );
  await user.type(
    screen.getByRole("textbox", { name: /Mô tả chi tiết/ }),
    "Mô tả đủ dài để kiểm tra create qua fake service.",
  );
  await user.type(screen.getByRole("textbox", { name: /Vị trí/ }), "Tầng 3");
}

async function openConfirmation(user: ReturnType<typeof userEvent.setup>) {
  await user.click(
    await screen.findByRole("button", { name: "Xác nhận từ fake service" }),
  );
  const dialog = screen.getByRole("dialog");
  await user.type(
    within(dialog).getByRole("textbox", { name: "Ghi chú xử lý" }),
    "Đã kiểm tra kết quả",
  );
  return {
    dialog,
    submit: within(dialog).getByRole("button", {
      name: "Xác nhận từ fake service",
    }),
  };
}

describe("session boundaries for pending Application writes", () => {
  it.each(["create", "transition"] as const)(
    "expires the same session on a delayed %s 401 even after leaving the form",
    async (operation) => {
      const pending = deferred<ServiceRequest>();
      const service = fakeService();
      service[operation].mockReturnValue(pending.promise);
      service.actions.mockReturnValue([
        { id: "confirm", label: "Xác nhận từ fake service" },
      ]);
      const user = userEvent.setup();
      mountSessionPortal(
        service,
        operation === "create" ? "/requests/new" : `/requests/${provided.id}`,
      );
      if (operation === "create") {
        await fillCreateForm(user);
        await user.click(screen.getByRole("button", { name: "Gửi yêu cầu" }));
      } else {
        const { submit } = await openConfirmation(user);
        await user.click(submit);
      }
      await user.click(screen.getByRole("button", { name: "Test leave form" }));
      await act(async () =>
        pending.reject(new PortalError("401", "same session")),
      );
      expect(screen.getByTestId("session-location")).toHaveTextContent(
        "/requests:none:expired",
      );
      expect(sessionStorage.getItem("dxos-demo-role")).toBeNull();
    },
  );

  it.each(["create", "transition"] as const)(
    "ignores late %s success after logout and a new session",
    async (operation) => {
      const pending = deferred<ServiceRequest>();
      const service = fakeService();
      service[operation].mockReturnValue(pending.promise);
      service.actions.mockReturnValue([
        { id: "confirm", label: "Xác nhận từ fake service" },
      ]);
      const user = userEvent.setup();
      mountSessionPortal(
        service,
        operation === "create" ? "/requests/new" : `/requests/${provided.id}`,
      );
      if (operation === "create") {
        await fillCreateForm(user);
        await user.click(screen.getByRole("button", { name: "Gửi yêu cầu" }));
      } else {
        const { submit } = await openConfirmation(user);
        await user.click(submit);
      }
      await user.click(screen.getByRole("button", { name: "Test logout" }));
      await user.click(
        screen.getByRole("button", { name: "Test new session" }),
      );
      await act(async () => pending.resolve(provided));
      expect(screen.getByTestId("session-location")).toHaveTextContent(
        "/requests:employee:active",
      );
      expect(
        screen.queryByRole("button", { name: "Đóng thông báo" }),
      ).not.toBeInTheDocument();
      expect(service[operation]).toHaveBeenCalledTimes(1);
    },
  );

  it.each(["create", "transition"] as const)(
    "ignores late %s 401 from an old session",
    async (operation) => {
      const pending = deferred<ServiceRequest>();
      const service = fakeService();
      service[operation].mockReturnValue(pending.promise);
      service.actions.mockReturnValue([
        { id: "confirm", label: "Xác nhận từ fake service" },
      ]);
      const user = userEvent.setup();
      mountSessionPortal(
        service,
        operation === "create" ? "/requests/new" : `/requests/${provided.id}`,
      );
      if (operation === "create") {
        await fillCreateForm(user);
        await user.click(screen.getByRole("button", { name: "Gửi yêu cầu" }));
      } else {
        const { submit } = await openConfirmation(user);
        await user.click(submit);
      }
      await user.click(screen.getByRole("button", { name: "Test logout" }));
      await user.click(
        screen.getByRole("button", { name: "Test new session" }),
      );
      await act(async () =>
        pending.reject(new PortalError("401", "old session")),
      );
      expect(screen.getByTestId("session-location")).toHaveTextContent(
        "/requests:employee:active",
      );
      expect(sessionStorage.getItem("dxos-demo-role")).toBe("employee");
    },
  );

  it("does not redirect or notify for a create success after leaving the form", async () => {
    const pending = deferred<ServiceRequest>();
    const service = fakeService();
    service.create.mockReturnValue(pending.promise);
    const user = userEvent.setup();
    mountSessionPortal(service, "/requests/new");
    await fillCreateForm(user);
    await user.click(screen.getByRole("button", { name: "Gửi yêu cầu" }));
    await user.click(screen.getByRole("button", { name: "Test leave form" }));
    await act(async () => pending.resolve(provided));
    expect(screen.getByTestId("session-location")).toHaveTextContent(
      "/requests:employee:active",
    );
    expect(
      screen.queryByRole("button", { name: "Đóng thông báo" }),
    ).not.toBeInTheDocument();
  });
});

let assertNoNetworkOrFallback: () => void;
beforeEach(() => {
  sessionStorage.setItem("dxos-demo-role", "employee");
  const fetchSpy = vi.spyOn(globalThis, "fetch").mockImplementation(() => {
    throw new Error("Unexpected LIVE fetch");
  });
  const xhrSpy = vi
    .spyOn(XMLHttpRequest.prototype, "send")
    .mockImplementation(() => {
      throw new Error("Unexpected LIVE XMLHttpRequest");
    });
  const defaultSpies = [
    vi.spyOn(defaultService, "list"),
    vi.spyOn(defaultService, "get"),
    vi.spyOn(defaultService, "actions"),
    vi.spyOn(defaultService, "create"),
    vi.spyOn(defaultService, "transition"),
  ];
  assertNoNetworkOrFallback = () => {
    expect(fetchSpy).not.toHaveBeenCalled();
    expect(xhrSpy).not.toHaveBeenCalled();
    for (const spy of defaultSpies) expect(spy).not.toHaveBeenCalled();
  };
  Object.defineProperty(HTMLDialogElement.prototype, "showModal", {
    configurable: true,
    value: function (this: HTMLDialogElement) {
      this.setAttribute("open", "");
    },
  });
  Object.defineProperty(HTMLDialogElement.prototype, "close", {
    configurable: true,
    value: function (this: HTMLDialogElement) {
      this.removeAttribute("open");
    },
  });
  Object.defineProperty(HTMLElement.prototype, "scrollIntoView", {
    configurable: true,
    value: vi.fn(),
  });
});

afterEach(() => {
  cleanup();
  try {
    assertNoNetworkOrFallback();
  } finally {
    vi.restoreAllMocks();
    delete (HTMLDialogElement.prototype as { showModal?: unknown }).showModal;
    delete (HTMLDialogElement.prototype as { close?: unknown }).close;
    delete (HTMLElement.prototype as { scrollIntoView?: unknown })
      .scrollIntoView;
  }
});

describe("APP-09 provider injection with MOCK default", () => {
  it("keeps the existing composition-root MockRequestService as default", () => {
    render(
      <PortalProvider>
        <BindingProbe />
      </PortalProvider>,
    );
    expect(screen.getByTestId("binding")).toHaveTextContent("MOCK");
    expect(defaultService).toBeInstanceOf(MockRequestService);
  });

  it("accepts RequestService without pretending MvpRequestPort is compatible", () => {
    expectTypeOf<MvpRequestPort>().not.toExtend<RequestService>();
    expectTypeOf<
      NonNullable<Parameters<typeof PortalProvider>[0]["requestService"]>
    >().toEqualTypeOf<RequestService>();
    render(
      <PortalProvider requestService={fakeService()}>
        <BindingProbe />
      </PortalProvider>,
    );
    expect(screen.getByTestId("binding")).toHaveTextContent("injected");
  });

  it.each(["list", "approvals", "history"] as const)(
    "feeds the %s view through the injected read service",
    async (mode) => {
      const role = mode === "approvals" ? "processor" : "employee";
      sessionStorage.setItem("dxos-demo-role", role);
      const item: ServiceRequest = { ...provided, status: "pending" };
      const service = fakeService(item);
      const path = mode === "list" ? "/requests" : `/${mode}`;
      mountPortal(service, path);
      expect(await screen.findByText(new RegExp(item.title))).toBeVisible();
      expect(service.list).toHaveBeenCalledWith(role);
      expect(service.get).not.toHaveBeenCalled();
      if (mode === "history") {
        expect(screen.getByText(item.timeline[0].note)).toBeVisible();
      }
    },
  );

  it("reads detail and actions from the injected service", async () => {
    const service = fakeService();
    service.actions.mockReturnValue([
      { id: "confirm", label: "Xác nhận từ fake service" },
    ]);
    mountPortal(service, `/requests/${provided.id}`);
    expect(
      await screen.findByRole("button", { name: "Xác nhận từ fake service" }),
    ).toBeVisible();
    expect(service.get).toHaveBeenCalledWith(provided.id, "employee");
    expect(service.actions).toHaveBeenCalledWith(provided, "employee");
    expect(service.list).not.toHaveBeenCalled();
  });

  it("does not invent processor actions when the injected service supplies none", async () => {
    sessionStorage.setItem("dxos-demo-role", "processor");
    const item: ServiceRequest = { ...provided, status: "pending" };
    const service = fakeService(item);
    mountPortal(service, `/requests/${item.id}`);
    await screen.findByRole("heading", { name: item.title });
    expect(service.actions).toHaveBeenCalledWith(item, "processor");
    expect(
      screen.queryByRole("button", { name: "Phê duyệt" }),
    ).not.toBeInTheDocument();
    expect(
      screen.queryByRole("button", { name: "Từ chối" }),
    ).not.toBeInTheDocument();
  });

  it("retries only a requested read using the same injected service", async () => {
    const service = fakeService();
    service.list.mockRejectedValueOnce(
      new PortalError("NETWORK", "Fake read unavailable"),
    );
    mountPortal(service);
    expect(await screen.findByRole("alert")).toHaveTextContent(
      "Fake read unavailable",
    );
    expect(service.list).toHaveBeenCalledTimes(1);
    await userEvent
      .setup()
      .click(screen.getByRole("button", { name: "Tải lại dữ liệu" }));
    expect(await screen.findByText(provided.title)).toBeVisible();
    expect(service.list).toHaveBeenCalledTimes(2);
  });

  it.each(["late data", "late 401"])(
    "reloads on service replacement and ignores %s from the previous service",
    async (outcome) => {
      const pending = deferred<ServiceRequest[]>();
      const previous = fakeService();
      previous.list.mockReturnValue(pending.promise);
      const nextItem = { ...provided, title: "Dữ liệu của service mới" };
      const next = fakeService(nextItem);
      const view = render(
        <PortalProvider requestService={previous}>
          <ReadProbe />
          <SessionProbe />
        </PortalProvider>,
      );
      await waitFor(() => expect(previous.list).toHaveBeenCalledTimes(1));
      view.rerender(
        <PortalProvider requestService={next}>
          <ReadProbe />
          <SessionProbe />
        </PortalProvider>,
      );
      await waitFor(() =>
        expect(screen.getByTestId("read-result")).toHaveTextContent(
          nextItem.title,
        ),
      );
      await act(async () => {
        if (outcome === "late 401")
          pending.reject(new PortalError("401", "Old service expired"));
        else pending.resolve([provided]);
        await pending.promise.catch(() => undefined);
      });
      expect(screen.getByTestId("read-result")).toHaveTextContent(
        nextItem.title,
      );
      expect(screen.getByTestId("session")).toHaveTextContent(
        "employee:active",
      );
      expect(next.list).toHaveBeenCalledTimes(1);
    },
  );

  it("does not read through the injected service without a demo session", () => {
    sessionStorage.clear();
    const service = fakeService();
    mountPortal(service);
    expect(screen.getByTestId("session")).toHaveTextContent(
      "no-session:active",
    );
    expect(service.list).not.toHaveBeenCalled();
    expect(service.get).not.toHaveBeenCalled();
  });

  it.each(["it", "facility"] as const)(
    "sends %s create once through the injected service and reads its returned ID",
    async (kind) => {
      const item: ServiceRequest = {
        ...provided,
        id: "SEAM-created",
        kind,
        status: "pending",
      };
      const service = fakeService(item);
      const pending = deferred<ServiceRequest>();
      service.create.mockReturnValue(pending.promise);
      const user = userEvent.setup();
      mountPortal(service, `/requests/new?kind=${kind}`);
      await fillCreateForm(user);
      await user.dblClick(screen.getByRole("button", { name: "Gửi yêu cầu" }));
      expect(service.create).toHaveBeenCalledTimes(1);
      expect(screen.getByRole("button", { name: "Đang gửi…" })).toBeDisabled();
      expect(service.create).toHaveBeenCalledWith(
        {
          kind,
          title: "Sự cố phần mềm từ seam",
          description: "Mô tả đủ dài để kiểm tra create qua fake service.",
          priority: "normal",
          location: "Tầng 3",
        },
        "employee",
      );
      expect(service.create.mock.calls[0][0]).not.toHaveProperty("role");
      expect(service.create.mock.calls[0][0]).not.toHaveProperty("requester");
      await act(async () => {
        pending.resolve(item);
        await pending.promise;
      });
      expect(
        await screen.findByRole("heading", { name: item.title }),
      ).toBeVisible();
      expect(service.get).toHaveBeenCalledWith(item.id, "employee");
      expect(service.create).toHaveBeenCalledTimes(1);
    },
  );

  it("preserves local validation and focus before calling an injected create", async () => {
    const service = fakeService();
    mountPortal(service, "/requests/new");
    await userEvent
      .setup()
      .click(screen.getByRole("button", { name: "Gửi yêu cầu" }));
    expect(
      screen.getByRole("textbox", { name: /Tiêu đề yêu cầu/ }),
    ).toHaveFocus();
    expect(service.create).not.toHaveBeenCalled();
  });

  it("keeps uncertain injected create locked with no retry or default fallback", async () => {
    const service = fakeService();
    service.create.mockRejectedValue(
      new PortalError("COMMIT_OUTCOME_UNKNOWN", "Fake write outcome unknown"),
    );
    const user = userEvent.setup();
    mountPortal(service, "/requests/new");
    await fillCreateForm(user);
    await user.dblClick(screen.getByRole("button", { name: "Gửi yêu cầu" }));
    expect(await screen.findByRole("alert")).toHaveTextContent(
      "Fake write outcome unknown",
    );
    expect(screen.getByRole("button", { name: "Gửi yêu cầu" })).toBeDisabled();
    expect(service.create).toHaveBeenCalledTimes(1);
  });

  it("sends confirmation once with the supplied version, then reads authoritative detail", async () => {
    const confirmed: ServiceRequest = {
      ...provided,
      status: "confirmed",
      version: 18,
    };
    const service = fakeService();
    service.actions.mockReturnValue([
      { id: "confirm", label: "Xác nhận từ fake service" },
    ]);
    service.get.mockResolvedValueOnce(provided).mockResolvedValue(confirmed);
    const pending = deferred<ServiceRequest>();
    service.transition.mockReturnValue(pending.promise);
    const user = userEvent.setup();
    mountPortal(service, `/requests/${provided.id}`);
    const { submit } = await openConfirmation(user);
    await user.dblClick(submit);
    expect(service.transition).toHaveBeenCalledTimes(1);
    expect(submit).toBeDisabled();
    expect(service.transition).toHaveBeenCalledWith(
      provided.id,
      "confirm",
      "Đã kiểm tra kết quả",
      provided.version,
      "employee",
    );
    await act(async () => {
      pending.resolve(confirmed);
      await pending.promise;
    });
    expect(await screen.findAllByText("Đã xác nhận hoàn thành")).toHaveLength(
      2,
    );
    expect(service.get).toHaveBeenCalledTimes(2);
    expect(service.transition).toHaveBeenCalledTimes(1);
  });

  it("keeps uncertain injected confirmation locked through read reload without retry", async () => {
    const service = fakeService();
    service.actions.mockReturnValue([
      { id: "confirm", label: "Xác nhận từ fake service" },
    ]);
    service.transition.mockRejectedValue(
      new PortalError(
        "COMMIT_OUTCOME_UNKNOWN",
        "Fake confirmation outcome unknown",
      ),
    );
    const user = userEvent.setup();
    mountPortal(service, `/requests/${provided.id}`);
    const { dialog, submit } = await openConfirmation(user);
    await user.dblClick(submit);
    expect(await within(dialog).findByRole("alert")).toHaveTextContent(
      "Fake confirmation outcome unknown",
    );
    expect(submit).toBeDisabled();
    await user.click(within(dialog).getByRole("button", { name: "Đóng" }));
    await user.click(screen.getByRole("button", { name: "Tải lại chi tiết" }));
    expect(
      await screen.findByRole("button", { name: "Xác nhận từ fake service" }),
    ).toBeDisabled();
    expect(service.transition).toHaveBeenCalledTimes(1);
    expect(service.get).toHaveBeenCalledTimes(2);
  });

  it.each(["401", "403", "404"])(
    "keeps injected %s failures in the existing error/session boundary without fallback",
    async (code) => {
      const service = fakeService();
      service.list.mockRejectedValue(
        new PortalError(code, "Fake service read denied"),
      );
      mountPortal(service);
      if (code === "401") {
        await waitFor(() =>
          expect(screen.getByTestId("session")).toHaveTextContent(
            "no-session:expired",
          ),
        );
        expect(sessionStorage.getItem("dxos-demo-role")).toBeNull();
      } else {
        expect(await screen.findByRole("alert")).toHaveTextContent(
          "Fake service read denied",
        );
        expect(screen.getByTestId("session")).toHaveTextContent(
          "employee:active",
        );
      }
      expect(service.list).toHaveBeenCalledTimes(1);
    },
  );
});

import {
  createContext,
  useCallback,
  useContext,
  useState,
  useRef,
  type ReactNode,
} from "react";
import type { DemoRole } from "./domain/request";
import { requestService as defaultRequestService } from "./services/portalService";
import type { RequestService } from "./services/RequestService";
import type { MvpHelpdeskRequestPort } from "./services/mvp/helpdeskPortalPort";
import type { MvpApplicationError } from "./services/mvp/errors";

interface PortalContextValue {
  requestService: RequestService;
  helpdeskService?: MvpHelpdeskRequestPort;
  helpdeskAuthenticated: boolean;
  helpdeskWriteStops: ReadonlyMap<string, MvpApplicationError>;
  stopHelpdeskWrite: (key: string, error: MvpApplicationError) => void;
  releaseHelpdeskReadStop: (key: string) => void;
  helpdeskPending: ReadonlySet<string>;
  beginHelpdeskWrite: (key: string) => boolean;
  endHelpdeskWrite: (key: string) => void;
  role: DemoRole | null;
  setRole: (role: DemoRole | null) => void;
  sessionExpired: boolean;
  expireSession: () => void;
  captureSession: () => () => boolean;
  revision: number;
  refresh: () => void;
  notify: (message: string) => void;
}
const PortalContext = createContext<PortalContextValue | null>(null);
// Default stays MOCK. The optional MVP port has its own presentation model;
// it never masquerades as RequestService or selects a transport from an env flag.
export function PortalProvider({
  children,
  requestService = defaultRequestService,
  helpdeskService,
  helpdeskSession,
}: {
  children: ReactNode;
  requestService?: RequestService;
  helpdeskService?: MvpHelpdeskRequestPort;
  helpdeskSession?: boolean;
}) {
  // Invalidate pending UI work synchronously on logout/expiry/role changes.
  // This is a demo lifecycle boundary, not an authentication credential.
  const [sessionScope, setSessionScope] = useState(() => ({}));
  const currentSessionScope = useRef(sessionScope);
  const currentServices = useRef({ requestService, helpdeskService });
  currentServices.current = { requestService, helpdeskService };
  const captureSession = useCallback(() => {
    return () =>
      currentSessionScope.current === sessionScope &&
      currentServices.current.requestService === requestService &&
      currentServices.current.helpdeskService === helpdeskService;
  }, [sessionScope, requestService, helpdeskService]);
  // In-memory stops survive feature navigation. Unknown writes require an
  // approved reconciliation procedure; a read or role switch cannot release them.
  const [helpdeskWriteStops, setHelpdeskWriteStops] = useState<
    ReadonlyMap<string, MvpApplicationError>
  >(() => new Map());
  const pendingWrites = useRef(new Set<string>());
  const [helpdeskPending, setHelpdeskPending] = useState<ReadonlySet<string>>(
    () => new Set(),
  );
  const beginHelpdeskWrite = useCallback((key: string) => {
    if (pendingWrites.current.has(key)) return false;
    pendingWrites.current.add(key);
    setHelpdeskPending(new Set(pendingWrites.current));
    return true;
  }, []);
  const endHelpdeskWrite = useCallback((key: string) => {
    pendingWrites.current.delete(key);
    setHelpdeskPending(new Set(pendingWrites.current));
  }, []);
  const stopHelpdeskWrite = useCallback(
    (key: string, error: MvpApplicationError) => {
      setHelpdeskWriteStops((previous) => new Map(previous).set(key, error));
    },
    [],
  );
  const releaseHelpdeskReadStop = useCallback((key: string) => {
    setHelpdeskWriteStops((previous) => {
      const code = previous.get(key)?.code;
      if (code !== "CONFLICT" && code !== "FORBIDDEN" && code !== "NOT_FOUND")
        return previous;
      const next = new Map(previous);
      next.delete(key);
      return next;
    });
  }, []);
  const [role, updateRole] = useState<DemoRole | null>(() => {
    if (helpdeskSession !== undefined) return null;
    try {
      const value = sessionStorage.getItem("dxos-demo-role");
      return value === "employee" || value === "processor" ? value : null;
    } catch {
      return null;
    }
  });
  const [revision, setRevision] = useState(0);
  const [notice, setNotice] = useState("");
  const [sessionExpired, setSessionExpired] = useState(false);
  const setRole = useCallback((value: DemoRole | null) => {
    const nextScope = {};
    currentSessionScope.current = nextScope;
    setSessionScope(nextScope);
    try {
      value
        ? sessionStorage.setItem("dxos-demo-role", value)
        : sessionStorage.removeItem("dxos-demo-role");
    } catch {
      // Storage is optional; the current demo session lives in React state.
    }
    updateRole(value);
    setSessionExpired(false);
    setNotice("");
    setRevision((v) => v + 1);
  }, []);
  const expireSession = useCallback(() => {
    const nextScope = {};
    currentSessionScope.current = nextScope;
    setSessionScope(nextScope);
    try {
      sessionStorage.removeItem("dxos-demo-role");
    } catch {
      // Always expire the in-memory session, even when storage is blocked.
    }
    updateRole(null);
    setSessionExpired(true);
    setNotice("");
  }, []);
  return (
    <PortalContext.Provider
      value={{
        requestService,
        helpdeskService,
        helpdeskAuthenticated:
          helpdeskSession !== undefined
            ? helpdeskSession && !sessionExpired
            : Boolean(role),
        helpdeskWriteStops,
        stopHelpdeskWrite,
        releaseHelpdeskReadStop,
        helpdeskPending,
        beginHelpdeskWrite,
        endHelpdeskWrite,
        role,
        setRole,
        sessionExpired,
        expireSession,
        captureSession,
        revision,
        refresh: () => setRevision((v) => v + 1),
        notify: setNotice,
      }}
    >
      {children}
      {notice && (
        <div className="toast" role="status">
          <span>✓</span>
          <div>{notice}</div>
          <button onClick={() => setNotice("")} aria-label="Đóng thông báo">
            ×
          </button>
        </div>
      )}
    </PortalContext.Provider>
  );
}
export function usePortal() {
  const ctx = useContext(PortalContext);
  if (!ctx) throw new Error("PortalProvider required");
  return ctx;
}

import { describe, expect, it } from "vitest";
import {
  filterRequests,
  statusLabels,
  validateRequest,
  type CreateRequestInput,
} from "./request";
import { makeFixtures } from "../fixtures/requests";

const input: CreateRequestInput = {
  kind: "it",
  title: "Cài đặt máy tính mới",
  description: "Cần cài đặt môi trường làm việc cho dự án mới.",
  priority: "normal",
  location: "Tầng 3",
};
describe("shared request model", () => {
  it.each(["it", "facility"] as const)(
    "validates both %s services through one schema",
    (kind) => {
      expect(validateRequest({ ...input, kind })).toEqual({});
    },
  );
  it("rejects blank, short and oversized fields", () => {
    expect(
      validateRequest({
        ...input,
        title: "   ",
        description: "ngắn",
        location: "",
      }),
    ).toHaveProperty("title");
    expect(
      Object.keys(
        validateRequest({
          ...input,
          title: "x".repeat(121),
          description: "x".repeat(2001),
          location: "x".repeat(101),
        }),
      ),
    ).toHaveLength(3);
  });
  it("searches Vietnamese without accents and combines filters", () => {
    expect(
      filterRequests(makeFixtures(), "dieu hoa", "facility", "processing"),
    ).toHaveLength(1);
    expect(filterRequests(makeFixtures(), "DX-1048")).toHaveLength(1);
    expect(filterRequests(makeFixtures(), "khong co ket qua")).toHaveLength(0);
    expect(
      filterRequests(makeFixtures(), "", "it").every((r) => r.kind === "it"),
    ).toBe(true);
  });
  it("keeps resolved IT, confirmed IT and completed Facility distinct", () => {
    expect(statusLabels.resolved).toBe("Chờ nhân viên xác nhận");
    expect(statusLabels.confirmed).toBe("Đã xác nhận hoàn thành");
    expect(statusLabels.completed).toBe("Hoàn thành");
    expect(statusLabels).not.toHaveProperty("closed");
    const fixtures = makeFixtures();
    const resolved = filterRequests(fixtures, "", "it", "resolved");
    expect(resolved.map((item) => item.id)).toEqual(["DX-1044", "DX-1042"]);
    for (const item of resolved) {
      expect(item.timeline.at(-1)?.title).toBe(
        "IT đã xử lý và thông báo kết quả",
      );
      expect(item.updatedAt).toBe(item.timeline.at(-1)?.at);
      expect(item.version).toBe(item.timeline.length - 1);
    }
    const confirmed = { ...resolved[1], status: "confirmed" as const };
    expect(
      filterRequests([...fixtures, confirmed], "", "it", "confirmed"),
    ).toEqual([confirmed]);
    expect(
      filterRequests(fixtures, "", "facility", "completed").map(
        (item) => item.id,
      ),
    ).toEqual(["DX-1039"]);
  });
});

export type RequestKind = "it" | "facility";
// MOCK presentation states; CONFIRMED does not define a Backend terminal state.
export type RequestStatus =
  | "pending"
  | "approved"
  | "processing"
  | "resolved"
  | "confirmed"
  | "completed"
  | "rejected";
export type DemoRole = "employee" | "processor";
export type ActionId = "approve" | "reject" | "start" | "complete" | "confirm";
export type Fault = "" | "network" | "401" | "403" | "404" | "unknown";
export interface TimelineEvent {
  id: string;
  at: string;
  actor: string;
  title: string;
  note: string;
}
export interface ServiceRequest {
  id: string;
  title: string;
  description: string;
  kind: RequestKind;
  status: RequestStatus;
  priority: "normal" | "high" | "urgent";
  requester: string;
  department: string;
  location: string;
  assignee: string;
  createdAt: string;
  updatedAt: string;
  version: number;
  timeline: TimelineEvent[];
}
export interface CreateRequestInput {
  kind: RequestKind;
  title: string;
  description: string;
  priority: ServiceRequest["priority"];
  location: string;
}
export interface RequestAction {
  id: ActionId;
  label: string;
  tone?: "danger";
}
export const kindLabels: Record<RequestKind, string> = {
  it: "Hỗ trợ CNTT",
  facility: "Cơ sở vật chất",
};
export const statusLabels: Record<RequestStatus, string> = {
  pending: "Chờ phê duyệt",
  approved: "Đã phê duyệt",
  processing: "Đang xử lý",
  resolved: "Chờ nhân viên xác nhận",
  confirmed: "Đã xác nhận hoàn thành",
  completed: "Hoàn thành",
  rejected: "Từ chối",
};
export const priorityLabels = {
  normal: "Bình thường",
  high: "Cao",
  urgent: "Khẩn cấp",
};
export function validateRequest(input: CreateRequestInput) {
  const errors: Partial<Record<keyof CreateRequestInput, string>> = {};
  if (!["it", "facility"].includes(input.kind))
    errors.kind = "Chọn một dịch vụ hợp lệ.";
  if (input.title.trim().length < 8 || input.title.trim().length > 120)
    errors.title = "Tiêu đề cần từ 8 đến 120 ký tự.";
  if (
    input.description.trim().length < 20 ||
    input.description.trim().length > 2000
  )
    errors.description = "Mô tả cần từ 20 đến 2.000 ký tự.";
  if (!input.location.trim() || input.location.trim().length > 100)
    errors.location = "Nhập vị trí (tối đa 100 ký tự).";
  if (!["normal", "high", "urgent"].includes(input.priority))
    errors.priority = "Chọn mức ưu tiên hợp lệ.";
  return errors;
}
export function filterRequests(
  items: ServiceRequest[],
  search: string,
  kind = "",
  status = "",
) {
  const normalize = (s: string) =>
    s
      .toLowerCase()
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .replace(/đ/g, "d");
  const query = normalize(search.trim());
  return items.filter(
    (r) =>
      (!kind || r.kind === kind) &&
      (!status || r.status === status) &&
      normalize(`${r.id} ${r.title} ${r.requester}`).includes(query),
  );
}
export const formatDate = (value: string) =>
  new Intl.DateTimeFormat("vi-VN", {
    day: "2-digit",
    month: "2-digit",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  }).format(new Date(value));

