import {
  useCallback,
  useEffect,
  useRef,
  useState,
  type FormEvent,
} from "react";
import {
  Link,
  Route,
  Routes,
  useNavigate,
  useParams,
  useSearchParams,
} from "react-router-dom";
import { AssignmentForm } from "../../components/AssignmentForm";
import { Empty, ErrorState, Loading, PageHeading } from "../../components/ui";
import { usePortal } from "../../context";
import { useSessionOperation } from "../../hooks/useSessionOperation";
import { helpdeskAssignmentFormProps } from "../../services/mvp/assignmentBinding";
import {
  executeWriteOnce,
  MvpApplicationError,
} from "../../services/mvp/errors";
import type { MvpHelpdeskRequestPort } from "../../services/mvp/helpdeskPortalPort";
import { useHelpdeskRead } from "./useHelpdeskRead";

const ROOT = "/mvp/helpdesk";
const CREATE = "helpdesk:create";
const labels = {
  triage: "Tiếp nhận",
  start: "Bắt đầu xử lý",
  resolve: "Ghi kết quả xử lý",
  confirm: "Xác nhận hoàn thành",
} as const;
type WorkflowAction = keyof typeof labels;
const validVersion = (value: number) =>
  Number.isSafeInteger(value) && value >= 0;
const validText = (value: string, max: number) =>
  value.trim().length > 0 && value.length <= max;
const personName = (name: string | null | undefined) =>
  name || "Tên không được cung cấp";

/** Shared write lock is scoped to the provider, so navigation cannot replay a
 * pending/unknown write. Only a user-requested authoritative read releases 409.
 */
function useHelpdeskWrite(key: string) {
  const portal = usePortal();
  const captureOperation = useSessionOperation();
  const currentOperation = captureOperation();
  const invoked = useRef(false);
  const acceptRead = useCallback(() => {
    invoked.current = false;
  }, []);
  const stopped = portal.helpdeskWriteStops.get(key);
  const busy = portal.helpdeskPending.has(key);
  async function run(write: () => Promise<unknown>, after: () => void) {
    if (
      !portal.helpdeskAuthenticated ||
      stopped ||
      invoked.current ||
      !portal.beginHelpdeskWrite(key)
    )
      return;
    invoked.current = true;
    const operation = captureOperation();
    try {
      await executeWriteOnce(write);
      if (operation.canUpdate()) after();
    } catch (error) {
      // executeWriteOnce always normalizes unknown write failures.
      const failure = error as MvpApplicationError;
      // An old session cannot stop its successor. Unknown writes remain stopped
      // across navigation/logout; their outcome still needs approved recovery.
      if (
        failure.code === "COMMIT_OUTCOME_UNKNOWN" ||
        (operation.isCurrent() && failure.code !== "UNAUTHENTICATED")
      )
        portal.stopHelpdeskWrite(key, failure);
      if (failure.code === "UNAUTHENTICATED" && operation.isCurrent())
        portal.expireSession();
    } finally {
      portal.endHelpdeskWrite(key);
    }
  }
  return {
    run,
    busy,
    stopped,
    blocked: busy || Boolean(stopped),
    portal,
    acceptRead,
    isCurrent: currentOperation.canUpdate,
  };
}

export function HelpdeskPortal() {
  const { helpdeskService } = usePortal();
  if (!helpdeskService)
    return (
      <Empty
        title="MVP chưa được gắn service kiểm thử"
        description="MOCK mặc định vẫn hoạt động. Tích hợp LIVE tiếp tục BLOCKED."
      />
    );
  return (
    <>
      <p className="aside-footnote">
        IT Helpdesk MVP · service kiểm thử được inject · LIVE BLOCKED
      </p>
      <Routes>
        <Route index element={<HelpdeskList service={helpdeskService} />} />
        <Route
          path="new"
          element={<HelpdeskCreate service={helpdeskService} />}
        />
        <Route path=":id" element={<DetailRoute service={helpdeskService} />} />
        <Route
          path="*"
          element={
            <Empty
              title="Không tìm thấy trang MVP"
              description="Chọn danh sách yêu cầu để tiếp tục."
            />
          }
        />
      </Routes>
    </>
  );
}

function HelpdeskList({ service }: { service: MvpHelpdeskRequestPort }) {
  const [params, setParams] = useSearchParams();
  const after = params.get("after") ?? undefined;
  const load = useCallback(
    () => service.list({ ...(after ? { after } : {}), limit: 20 }),
    [service, after],
  );
  const read = useHelpdeskRead(load);
  return (
    <>
      <PageHeading
        title="IT Helpdesk MVP"
        description="Yêu cầu IT Support trong phiên kiểm thử."
      >
        <Link className="button primary" to={`${ROOT}/new`}>
          Tạo yêu cầu IT
        </Link>
      </PageHeading>
      <section className="panel">
        <div className="panel-heading">
          <h2>Danh sách yêu cầu</h2>
          <button
            className="text-link"
            disabled={read.loading}
            onClick={read.reload}
          >
            Tải lại danh sách
          </button>
        </div>
        {read.loading ? (
          <Loading />
        ) : read.error ? (
          <ErrorState message={read.error} onRetry={read.reload} />
        ) : !read.data?.items.length ? (
          <Empty
            title="Chưa có yêu cầu IT"
            description="Tạo yêu cầu để bắt đầu phiên kiểm thử."
          />
        ) : (
          <div className="table-scroll">
            <table>
              <caption className="sr-only">Yêu cầu IT Helpdesk MVP</caption>
              <thead>
                <tr>
                  <th>Yêu cầu</th>
                  <th>Trạng thái</th>
                  <th>Người yêu cầu</th>
                  <th>Người xử lý</th>
                </tr>
              </thead>
              <tbody>
                {read.data.items.map((item) => (
                  <tr key={item.id}>
                    <td>
                      <Link
                        className="request-title"
                        to={`${ROOT}/${encodeURIComponent(item.id)}`}
                      >
                        <span className="request-id">{item.id}</span>
                        <strong>{item.title}</strong>
                      </Link>
                    </td>
                    <td>
                      <span className="badge">{item.state}</span>
                    </td>
                    <td>{personName(item.requesterDisplayName)}</td>
                    <td>
                      {item.assigneeId === null
                        ? "Chưa phân công"
                        : personName(item.assigneeDisplayName)}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
        <div className="pagination">
          <button
            className="button secondary small"
            disabled={read.loading || !after}
            onClick={() => setParams({})}
          >
            Trang đầu
          </button>
          <button
            className="button secondary small"
            disabled={read.loading || !read.data?.nextCursor}
            onClick={() => {
              if (read.data?.nextCursor)
                setParams({ after: read.data.nextCursor });
            }}
          >
            Trang tiếp
          </button>
        </div>
      </section>
    </>
  );
}

function HelpdeskCreate({ service }: { service: MvpHelpdeskRequestPort }) {
  const navigate = useNavigate();
  const write = useHelpdeskWrite(CREATE);
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [invalid, setInvalid] = useState(false);
  async function submit(event: FormEvent) {
    event.preventDefault();
    if (write.blocked) return;
    if (!validText(title, 200) || !validText(description, 4000)) {
      setInvalid(true);
      return;
    }
    let id: string | undefined;
    await write.run(
      async () => {
        id = (await service.create({ title, description })).id;
      },
      () => {
        // Return to the authoritative list; the new resource can be opened there.
        if (id) navigate(ROOT);
      },
    );
  }
  return (
    <>
      <Link className="back-link" to={ROOT}>
        Danh sách yêu cầu IT
      </Link>
      <PageHeading
        title="Tạo yêu cầu IT Support"
        description="Chỉ dùng dữ liệu kiểm thử; loại yêu cầu IT_HELPDESK."
      />
      <div className="form-layout">
        <form
          className="panel request-form"
          aria-label="Tạo yêu cầu IT"
          onSubmit={submit}
        >
          <fieldset disabled={write.blocked}>
            <legend>Thông tin yêu cầu</legend>
            <label className="field">
              Tiêu đề yêu cầu
              <input
                required
                maxLength={200}
                value={title}
                onChange={(event) => setTitle(event.target.value)}
              />
            </label>
            <label className="field">
              Mô tả chi tiết
              <textarea
                required
                maxLength={4000}
                rows={5}
                value={description}
                onChange={(event) => setDescription(event.target.value)}
              />
            </label>
          </fieldset>
          {invalid && (
            <p className="field-error" role="alert">
              Tiêu đề và mô tả không được để trống.
            </p>
          )}
          {write.stopped && <ErrorState message={write.stopped.message} />}
          <div className="form-actions">
            <Link to={ROOT} className="button secondary">
              Xem danh sách và đối soát
            </Link>
            <button className="button primary" disabled={write.blocked}>
              {write.busy ? "Đang gửi…" : "Gửi yêu cầu IT"}
            </button>
          </div>
        </form>
      </div>
    </>
  );
}

function DetailRoute({ service }: { service: MvpHelpdeskRequestPort }) {
  const { id = "" } = useParams();
  return <HelpdeskDetail key={id} id={id} service={service} />;
}

function HelpdeskDetail({
  id,
  service,
}: {
  id: string;
  service: MvpHelpdeskRequestPort;
}) {
  const write = useHelpdeskWrite(id);
  const [resolution, setResolution] = useState("");
  const [invalid, setInvalid] = useState(false);
  const [reloadIntent, setReloadIntent] = useState(false);
  const load = useCallback(async () => {
    const [detail, history] = await Promise.all([
      service.detail(id),
      service.history(id),
    ]);
    return { detail, history };
  }, [service, id]);
  const read = useHelpdeskRead(load);
  useEffect(() => {
    if (read.data) write.acceptRead();
  }, [read.data, write.acceptRead]);
  useEffect(() => {
    if (reloadIntent && read.data) {
      write.portal.releaseHelpdeskReadStop(id);
      setReloadIntent(false);
    }
  }, [reloadIntent, read.data, id, write.portal.releaseHelpdeskReadStop]);
  function reload() {
    if (!write.busy) {
      setReloadIntent(true);
      read.reload();
    }
  }
  if (read.loading) return <Loading />;
  if (read.error || !read.data)
    return (
      <ErrorState
        message={
          read.error ?? "Không tìm thấy yêu cầu hoặc yêu cầu không khả dụng."
        }
        onRetry={reload}
      />
    );
  const { detail, history } = read.data;
  if (
    write.stopped?.code === "FORBIDDEN" ||
    write.stopped?.code === "NOT_FOUND"
  ) {
    return <ErrorState message={write.stopped.message} onRetry={reload} />;
  }
  const actions = (Object.keys(labels) as WorkflowAction[]).filter((action) =>
    detail.allowedActions.includes(action),
  );
  const blocked = write.blocked || !validVersion(detail.version);
  const assignment = helpdeskAssignmentFormProps(
    detail,
    service,
    () => {
      if (write.isCurrent()) read.reload();
    },
    write.isCurrent,
  );
  const binding = assignment?.submission;
  // The APP-11 binding owns ID membership, assignment guard and Detail reload.
  // Wrap only its invocation to share the Portal's pending/uncertain write stop.
  const assignmentSubmission =
    binding?.status === "ready"
      ? {
          ...binding,
          submitAssignment: async (
            selected: Parameters<typeof binding.submitAssignment>[0],
          ) => {
            await write.run(
              () => binding.submitAssignment(selected),
              () => {},
            );
          },
        }
      : binding;
  async function transition(action: WorkflowAction) {
    if (blocked || !detail.allowedActions.includes(action)) return;
    if (action === "resolve" && !validText(resolution, 4000)) {
      setInvalid(true);
      return;
    }
    setInvalid(false);
    await write.run(
      () =>
        action === "resolve"
          ? service.resolve(id, { expectedVersion: detail.version, resolution })
          : service[action](id, { expectedVersion: detail.version }),
      () => {
        setResolution("");
        read.reload();
      },
    );
  }
  return (
    <>
      <Link className="back-link" to={ROOT}>
        Danh sách yêu cầu IT
      </Link>
      <PageHeading
        eyebrow={detail.id}
        title={detail.title}
        description="IT Support · dữ liệu từ service kiểm thử"
      >
        <span className="badge">{detail.state}</span>
      </PageHeading>
      <div className="detail-layout">
        <div>
          <section className="panel detail-content">
            <div className="panel-heading">
              <h2>Nội dung yêu cầu</h2>
            </div>
            <p className="request-description">{detail.description}</p>
            {detail.resolution !== null && (
              <>
                <h2>Kết quả xử lý</h2>
                <p>{detail.resolution}</p>
              </>
            )}
          </section>
          <section
            className="panel detail-timeline"
            aria-label="Lịch sử Workflow"
          >
            <div className="panel-heading">
              <h2>Lịch sử xử lý</h2>
            </div>
            {!history.length ? (
              <Empty
                title="Chưa có lịch sử được cung cấp"
                description="Chỉ hiển thị lịch sử được phép đọc từ service."
              />
            ) : (
              <ol className="timeline">
                {history.map((entry, index) => (
                  <li key={index}>
                    <span className="timeline-dot" aria-hidden="true" />
                    <div>
                      <div className="timeline-title">
                        <strong>{entry.transitionId}</strong>
                        <span>{entry.occurredAt}</span>
                      </div>
                      <p>
                        {entry.sourceState} → {entry.targetState}
                      </p>
                      <p>Workflow version: {entry.version}</p>
                    </div>
                  </li>
                ))}
              </ol>
            )}
          </section>
        </div>
        <aside>
          <section className="panel metadata">
            <div className="panel-heading">
              <h2>Thông tin yêu cầu</h2>
            </div>
            <dl>
              <dt>Trạng thái Workflow</dt>
              <dd data-testid="mvp-state">{detail.state}</dd>
              <dt>Workflow version</dt>
              <dd data-testid="mvp-version">{detail.version}</dd>
              <dt>Assignment version</dt>
              <dd data-testid="mvp-assignment-version">
                {detail.assignmentVersion ?? "Chưa được cung cấp"}
              </dd>
              <dt>Người yêu cầu</dt>
              <dd>{personName(detail.requesterDisplayName)}</dd>
              <dt>Requester ID</dt>
              <dd>{detail.requesterId}</dd>
              <dt>Người xử lý</dt>
              <dd>
                {detail.assigneeId === null
                  ? "Chưa phân công"
                  : personName(detail.assigneeDisplayName)}
              </dd>
              {detail.assigneeId !== null && (
                <>
                  <dt>Assignee ID</dt>
                  <dd>{detail.assigneeId}</dd>
                </>
              )}
            </dl>
          </section>
          <section className="panel action-panel">
            <h2>Thao tác xử lý</h2>
            {write.stopped && <ErrorState message={write.stopped.message} />}
            {!actions.length && !assignment && (
              <p>Không có thao tác được service cung cấp.</p>
            )}
            <fieldset disabled={blocked}>
              <legend className="sr-only">Workflow actions</legend>
              {actions.includes("resolve") && (
                <label className="field">
                  Kết quả xử lý
                  <textarea
                    maxLength={4000}
                    rows={4}
                    value={resolution}
                    onChange={(event) => setResolution(event.target.value)}
                  />
                </label>
              )}
              {invalid && (
                <p className="field-error" role="alert">
                  Kết quả xử lý không được để trống.
                </p>
              )}
              {actions.map((action) => (
                <button
                  type="button"
                  className="button primary"
                  key={action}
                  disabled={blocked}
                  onClick={(event) => {
                    if (event.detail <= 1) transition(action);
                  }}
                >
                  {labels[action]}
                </button>
              ))}
            </fieldset>
            <button
              className="text-link"
              disabled={write.busy}
              onClick={reload}
            >
              Tải lại chi tiết và lịch sử
            </button>
          </section>
          {assignment && (
            <fieldset disabled={write.blocked} aria-label="Phân công yêu cầu">
              <legend className="sr-only">Assignment</legend>
              <AssignmentForm
                key={read.revision}
                {...assignment}
                loading={write.busy}
                submission={
                  write.stopped
                    ? { status: "blocked", reason: write.stopped.message }
                    : assignmentSubmission
                }
              />
            </fieldset>
          )}
        </aside>
      </div>
    </>
  );
}

import { render, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { MemoryRouter } from "react-router-dom";
import { afterEach, beforeEach, expect, it, vi } from "vitest";
import { helpdeskId, helpdeskWire } from "../../test/helpdeskFixtures";
import LocalHelpdeskIntegration from "./LocalHelpdeskIntegration";

beforeEach(() => vi.stubGlobal("location", new URL("https://localhost:8443")));
afterEach(() => vi.unstubAllGlobals());
function mount(path = "/mvp/helpdesk") {
  render(
    <MemoryRouter initialEntries={[path]}>
      <LocalHelpdeskIntegration />
    </MemoryRouter>,
  );
}

it("requires the real BFF session even when a demo persona is set", async () => {
  sessionStorage.setItem("dxos-demo-role", "processor");
  const fetcher = vi
    .fn<typeof fetch>()
    .mockResolvedValue(Response.json({ authenticated: false }));
  vi.stubGlobal("fetch", fetcher);
  mount();
  expect(
    await screen.findByRole("link", { name: "Đăng nhập Keycloak" }),
  ).toHaveAttribute("href", "/oauth2/authorization/keycloak");
  expect(fetcher).toHaveBeenCalledTimes(1);
});

it("creates once through BFF without a demo role and renders only the returned request", async () => {
  const fetcher = vi
    .fn<typeof fetch>()
    .mockImplementation(async (url, init) => {
      if (url === "/bff/session")
        return Response.json({ authenticated: true, csrfToken: "csrf-test" });
      if (init?.method === "POST")
        return Response.json(helpdeskWire(), { status: 201 });
      if (String(url).includes("?limit="))
        return Response.json({ items: [helpdeskWire()], nextCursor: null });
      if (String(url).endsWith("/history")) return Response.json([]);
      return Response.json(helpdeskWire());
    });
  vi.stubGlobal("fetch", fetcher);
  mount("/mvp/helpdesk/new");
  const user = userEvent.setup();
  await user.type(
    await screen.findByLabelText(/Tiêu đề/),
    "Disposable integration test",
  );
  await user.type(
    screen.getByLabelText(/Mô tả/),
    "Disposable test description",
  );
  await user.click(screen.getByRole("button", { name: "Gửi yêu cầu IT" }));
  await waitFor(() =>
    expect(
      fetcher.mock.calls.filter(([, init]) => init?.method === "POST"),
    ).toHaveLength(1),
  );
  expect(sessionStorage.getItem("dxos-demo-role")).toBeNull();
  expect(
    fetcher.mock.calls.find(([, init]) => init?.method === "POST"),
  ).toEqual([
    "/bff/api/v1/mvp/requests",
    expect.objectContaining({
      headers: expect.objectContaining({ "X-CSRF-TOKEN": "csrf-test" }),
    }),
  ]);
  expect(await screen.findByText(helpdeskId)).toBeInTheDocument();
});

it("expires the local session on API 401 and removes the request UI", async () => {
  const fetcher = vi
    .fn<typeof fetch>()
    .mockResolvedValueOnce(
      Response.json({ authenticated: true, csrfToken: "csrf-test" }),
    )
    .mockResolvedValueOnce(new Response("", { status: 401 }));
  vi.stubGlobal("fetch", fetcher);
  mount();
  expect(
    await screen.findByRole("link", { name: "Đăng nhập Keycloak" }),
  ).toBeInTheDocument();
  expect(
    screen.queryByRole("link", { name: "Tạo yêu cầu IT" }),
  ).not.toBeInTheDocument();
  expect(fetcher).toHaveBeenCalledTimes(2);
});

it("shows a session network error without falling back to mocks", async () => {
  const fetcher = vi
    .fn<typeof fetch>()
    .mockRejectedValue(new TypeError("offline"));
  vi.stubGlobal("fetch", fetcher);
  mount();
  expect(await screen.findByRole("alert")).toHaveTextContent(
    "Không thể kiểm tra phiên BFF",
  );
  expect(fetcher).toHaveBeenCalledTimes(1);
});

it("keeps an unknown create blocked after navigation without replay", async () => {
  const fetcher = vi
    .fn<typeof fetch>()
    .mockImplementation(async (url, init) => {
      if (url === "/bff/session")
        return Response.json({ authenticated: true, csrfToken: "csrf-test" });
      if (init?.method === "POST")
        return Response.json(
          { code: "COMMIT_OUTCOME_UNKNOWN" },
          { status: 503 },
        );
      return Response.json({ items: [], nextCursor: null });
    });
  vi.stubGlobal("fetch", fetcher);
  mount("/mvp/helpdesk/new");
  const user = userEvent.setup();
  await user.type(
    await screen.findByLabelText(/Tiêu đề/),
    "Disposable unknown write",
  );
  await user.type(
    screen.getByLabelText(/Mô tả/),
    "Connection lost after commit",
  );
  await user.click(screen.getByRole("button", { name: "Gửi yêu cầu IT" }));
  expect(await screen.findByRole("alert")).toHaveTextContent(
    "Chưa xác định kết quả ghi",
  );
  expect(screen.getByRole("button", { name: "Gửi yêu cầu IT" })).toBeDisabled();
  await user.click(screen.getByRole("link", { name: "Danh sách Helpdesk" }));
  await user.click(await screen.findByRole("link", { name: "Tạo yêu cầu IT" }));
  expect(screen.getByRole("button", { name: "Gửi yêu cầu IT" })).toBeDisabled();
  expect(
    fetcher.mock.calls.filter(([, init]) => init?.method === "POST"),
  ).toHaveLength(1);
});

import { useEffect, useState } from "react";
import { Link, Navigate, Route, Routes } from "react-router-dom";
import { PortalProvider, usePortal } from "../../context";
import { HelpdeskRequestService } from "../../services/mvp/HelpdeskRequestService";
import { HelpdeskApiClient } from "../../services/mvp/http/HelpdeskApiClient";
import {
  bootstrapHelpdeskSession,
  sameOriginHelpdeskTransport,
} from "../../services/mvp/http/sameOriginTransport";
import { HelpdeskPortal } from "./HelpdeskPortal";

function Login() {
  return (
    <p role="status">
      Phiên chưa được xác thực hoặc đã hết hạn.{" "}
      <a href="/oauth2/authorization/keycloak">Đăng nhập Keycloak</a>
    </p>
  );
}

function SessionPortal() {
  const { sessionExpired } = usePortal();
  if (sessionExpired) return <Login />;
  return (
    <Routes>
      <Route path="/mvp/helpdesk/*" element={<HelpdeskPortal />} />
      <Route path="*" element={<Navigate to="/mvp/helpdesk" replace />} />
    </Routes>
  );
}

/** Separate local composition: no demo persona or mock service grants access. */
export default function LocalHelpdeskIntegration() {
  const [session, setSession] = useState<
    "loading" | "anonymous" | "expired" | "failed" | HelpdeskRequestService
  >("loading");
  useEffect(() => {
    let active = true;
    bootstrapHelpdeskSession()
      .then((result) => {
        if (!active) return;
        setSession(
          result
            ? new HelpdeskRequestService(
                new HelpdeskApiClient(
                  sameOriginHelpdeskTransport(result.csrfToken),
                  () => {
                    if (active) setSession("expired");
                  },
                ),
              )
            : "anonymous",
        );
      })
      .catch(() => {
        if (active) setSession("failed");
      });
    return () => {
      active = false;
    };
  }, []);
  return (
    <main id="main-content" className="page">
      <header>
        <h1>DX-OS · Helpdesk integration local</h1>
        <Link to="/mvp/helpdesk">Danh sách Helpdesk</Link>
      </header>
      {session === "loading" ? (
        <p role="status">Đang kiểm tra phiên…</p>
      ) : session === "failed" ? (
        <p role="alert">
          Không thể kiểm tra phiên BFF. Kiểm tra HTTPS và kết nối, sau đó tải
          lại trang.
        </p>
      ) : typeof session === "string" ? (
        <Login />
      ) : (
        <PortalProvider helpdeskService={session} helpdeskSession>
          <SessionPortal />
        </PortalProvider>
      )}
    </main>
  );
}

import { useEffect, useState } from "react";
import { usePortal } from "../../context";
import { useSessionOperation } from "../../hooks/useSessionOperation";
import { MvpApplicationError } from "../../services/mvp/errors";
import { HelpdeskClientError } from "../../services/mvp/http/errors";

export function helpdeskErrorMessage(error: unknown) {
  return error instanceof MvpApplicationError ||
    error instanceof HelpdeskClientError
    ? error.message
    : "Không thể tải dữ liệu Helpdesk. Vui lòng tải lại.";
}

/** Cancel obsolete reads; a new loader must never expose a previous resource. */
export function useHelpdeskRead<T>(load: () => Promise<T>) {
  const { expireSession } = usePortal();
  const captureOperation = useSessionOperation();
  const [revision, setRevision] = useState(0);
  const [result, setResult] = useState<{
    load: typeof load;
    captureOperation: typeof captureOperation;
    revision: number;
    data?: T;
    error?: string;
  }>();
  useEffect(() => {
    let active = true;
    const operation = captureOperation();
    Promise.resolve()
      .then(() => {
        if (active && operation.canUpdate()) return load();
      })
      .then(
        (data) => {
          if (active && operation.canUpdate())
            setResult({ load, captureOperation, revision, data });
        },
        (error: unknown) => {
          if (!operation.isCurrent()) return;
          if (
            error instanceof MvpApplicationError &&
            error.code === "UNAUTHENTICATED"
          )
            expireSession();
          if (active && operation.canUpdate())
            setResult({
              load,
              captureOperation,
              revision,
              error: helpdeskErrorMessage(error),
            });
        },
      );
    return () => {
      active = false;
    };
  }, [load, revision, expireSession, captureOperation]);
  const current =
    result?.load === load &&
    result.captureOperation === captureOperation &&
    result.revision === revision
      ? result
      : undefined;
  return {
    data: current?.data,
    error: current?.error,
    loading: current === undefined,
    reload: () => setRevision((value) => value + 1),
    revision,
  };
}

import { useEffect, useState } from "react";
import type { ServiceRequest } from "../domain/request";
import { usePortal } from "../context";
import { safeError } from "../services/RequestService";
import { useSessionOperation } from "./useSessionOperation";

export function useRequests(id?: string) {
  const { role, revision, expireSession, requestService } = usePortal();
  const captureOperation = useSessionOperation();
  const [data, setData] = useState<ServiceRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [attempt, retry] = useState(0);
  useEffect(() => {
    let ignore = false;
    const session = captureOperation();
    setLoading(true);
    setError("");
    setData([]);
    if (!role) {
      setLoading(false);
      return;
    }
    const operation = id
      ? requestService.get(id, role).then((item) => [item])
      : requestService.list(role);
    operation
      .then((items) => {
        if (!ignore && session.canUpdate()) setData(items);
      })
      .catch((e: unknown) => {
        if (!session.isCurrent()) return;
        if (e instanceof Error && "code" in e && e.code === "401") {
          expireSession();
          return;
        }
        if (!ignore && session.canUpdate()) setError(safeError(e));
      })
      .finally(() => {
        if (!ignore && session.canUpdate()) setLoading(false);
      });
    return () => {
      ignore = true;
    };
  }, [
    id,
    role,
    revision,
    attempt,
    expireSession,
    requestService,
    captureOperation,
  ]);
  return { data, loading, error, reload: () => retry((v) => v + 1) };
}

import { useCallback, useEffect, useRef } from "react";
import { usePortal } from "../context";

/** Capture before awaiting: 401 still expires the same session after navigation,
 * while UI updates require the originating screen and session to remain current.
 * Cancelling UI work does not cancel or replay an attempted write.
 */
export function useSessionOperation() {
  const { captureSession } = usePortal();
  const mounted = useRef(false);
  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
    };
  }, []);
  return useCallback(() => {
    const isCurrent = captureSession();
    return {
      isCurrent,
      canUpdate: () => mounted.current && isCurrent(),
    };
  }, [captureSession]);
}

import ReactDOM from "react-dom/client";
