import { beforeEach, afterEach, describe, expect, it, vi } from "vitest";
import { fireEvent, render, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { MemoryRouter } from "react-router-dom";
import { AuthPage } from "./Auth";

beforeEach(() => {
  localStorage.clear();
  sessionStorage.clear();
});
afterEach(() => vi.restoreAllMocks());
function setup(mode: "login" | "register" = "login") {
  return render(
    <MemoryRouter>
      <AuthPage mode={mode} />
    </MemoryRouter>,
  );
}
async function fill(registration = false) {
  const user = userEvent.setup();
  if (registration)
    await user.type(screen.getByLabelText("Họ và tên"), "Người dùng thử");
  await user.type(
    screen.getByLabelText("Email", { exact: true }),
    "preview@example.edu.vn",
  );
  await user.type(
    screen.getByLabelText("Mật khẩu", { exact: true }),
    "Synthetic preview only!",
  );
  if (registration)
    await user.type(
      screen.getByLabelText("Xác nhận mật khẩu"),
      "Synthetic preview only!",
    );
  return user;
}

describe("email/password UI remains blocked", () => {
  it.each([
    "",
    "invalid",
    "a@",
    "a@@b.edu",
    "a b@example.edu",
    "a@example",
    "a@example..edu",
  ])("rejects invalid email %j accessibly", async (value) => {
    setup();
    fireEvent.change(screen.getByLabelText("Email", { exact: true }), {
      target: { value },
    });
    await userEvent.click(screen.getByRole("button", { name: "Đăng nhập" }));
    expect(screen.getByLabelText("Email", { exact: true })).toHaveAttribute(
      "aria-invalid",
      "true",
    );
    expect(screen.getByLabelText("Email", { exact: true })).toHaveFocus();
    expect(screen.getByText(/Nhập email hợp lệ/)).toBeVisible();
  });

  it.each(["preview@example.edu.vn", "preview+test@example.org"])(
    "accepts email %s but never signs in",
    async (value) => {
      setup();
      const user = await fill();
      await user.clear(screen.getByLabelText("Email", { exact: true }));
      await user.type(screen.getByLabelText("Email", { exact: true }), value);
      await user.click(screen.getByRole("button", { name: "Đăng nhập" }));
      expect(await screen.findByRole("alert")).toHaveTextContent(
        "BLOCKED FEATURE",
      );
      expect(screen.getByRole("alert")).toHaveTextContent("Chưa đăng nhập");
      expect(sessionStorage.length).toBe(0);
    },
  );

  it("validates registration name, minimum password length and confirmation", async () => {
    setup("register");
    const user = userEvent.setup();
    await user.click(screen.getByRole("button", { name: "Đăng ký tài khoản" }));
    expect(screen.getByText(/Họ và tên cần/)).toBeVisible();
    expect(screen.getByText(/Mật khẩu cần từ 12/)).toBeVisible();
    expect(screen.getByText("Mật khẩu xác nhận chưa khớp.")).toBeVisible();
    await fill(true);
    await user.clear(screen.getByLabelText("Xác nhận mật khẩu"));
    await user.type(
      screen.getByLabelText("Xác nhận mật khẩu"),
      "Different preview only!",
    );
    await user.click(screen.getByRole("button", { name: "Đăng ký tài khoản" }));
    expect(screen.getByLabelText("Xác nhận mật khẩu")).toHaveAttribute(
      "aria-invalid",
      "true",
    );
    expect(screen.getByLabelText("Xác nhận mật khẩu")).toHaveFocus();
    expect(screen.queryByRole("alert")).not.toBeInTheDocument();
  });

  it.each(["Sinh viên", "Giảng viên"])(
    "accepts %s only as a form selection without granting a session",
    async (role) => {
      setup("register");
      const user = await fill(true);
      expect(screen.getAllByRole("radio")).toHaveLength(2);
      expect(
        screen.queryByRole("radio", { name: /admin|cán bộ|người xử lý/i }),
      ).not.toBeInTheDocument();
      await user.click(screen.getByRole("radio", { name: role }));
      await user.click(
        screen.getByRole("button", { name: "Đăng ký tài khoản" }),
      );
      expect(await screen.findByRole("alert")).toHaveTextContent(
        "Chưa tạo tài khoản",
      );
      expect(localStorage.length).toBe(0);
      expect(sessionStorage.length).toBe(0);
      expect(screen.getByLabelText("Mật khẩu", { exact: true })).toHaveValue(
        "",
      );
      expect(screen.getByLabelText("Xác nhận mật khẩu")).toHaveValue("");
    },
  );

  it.each(["admin", "processor"])("rejects tampered role %s", async (value) => {
    setup("register");
    const user = await fill(true);
    screen
      .getByRole("radio", { name: "Sinh viên" })
      .setAttribute("value", value);
    await user.click(screen.getByRole("button", { name: "Đăng ký tài khoản" }));
    expect(
      screen.getByText("Vui lòng chọn Sinh viên hoặc Giảng viên."),
    ).toBeVisible();
    expect(screen.queryByRole("alert")).not.toBeInTheDocument();
    expect(sessionStorage.length).toBe(0);
  });

  it.each(["login", "register"] as const)(
    "%s never sends, persists or logs credentials and preserves existing demo",
    async (mode) => {
      sessionStorage.setItem("dxos-demo-role", "employee");
      const fetchSpy = vi.spyOn(globalThis, "fetch");
      const xhrSpy = vi.spyOn(XMLHttpRequest.prototype, "send");
      const storageSpy = vi.spyOn(Storage.prototype, "setItem");
      const logs = [
        vi.spyOn(console, "log"),
        vi.spyOn(console, "warn"),
        vi.spyOn(console, "error"),
      ];
      setup(mode);
      const user = await fill(mode === "register");
      await user.dblClick(
        screen.getByRole("button", {
          name: mode === "login" ? "Đăng nhập" : "Đăng ký tài khoản",
        }),
      );
      expect(await screen.findByRole("alert")).toHaveTextContent(
        "BLOCKED FEATURE",
      );
      expect(fetchSpy).not.toHaveBeenCalled();
      expect(xhrSpy).not.toHaveBeenCalled();
      expect(storageSpy).not.toHaveBeenCalled();
      for (const log of logs) expect(log).not.toHaveBeenCalled();
      expect(sessionStorage.getItem("dxos-demo-role")).toBe("employee");
    },
  );

  it("remembers only an opted-in email; removes it immediately when unchecked", async () => {
    const view = setup();
    const user = await fill();
    await user.click(screen.getByRole("checkbox", { name: "Ghi nhớ email" }));
    await user.click(screen.getByRole("button", { name: "Đăng nhập" }));
    expect(await screen.findByRole("alert")).toBeVisible();
    expect({ ...localStorage }).toEqual({
      "dxos-remembered-email-v1": "preview@example.edu.vn",
    });
    view.unmount();
    setup();
    expect(screen.getByLabelText("Email", { exact: true })).toHaveValue(
      "preview@example.edu.vn",
    );
    expect(screen.getByLabelText("Mật khẩu", { exact: true })).toHaveValue("");
    await user.click(screen.getByRole("checkbox", { name: "Ghi nhớ email" }));
    expect(localStorage.length).toBe(0);
  });

  it("works when browser storage is unavailable", async () => {
    vi.spyOn(Storage.prototype, "getItem").mockImplementation(() => {
      throw new Error("Storage unavailable");
    });
    vi.spyOn(Storage.prototype, "setItem").mockImplementation(() => {
      throw new Error("Storage unavailable");
    });
    setup();
    const user = await fill();
    await user.click(screen.getByRole("checkbox", { name: "Ghi nhớ email" }));
    await user.click(screen.getByRole("button", { name: "Đăng nhập" }));
    expect(await screen.findByRole("alert")).toHaveTextContent(
      "BLOCKED FEATURE",
    );
    expect(screen.getByRole("status")).toHaveTextContent(
      "Trình duyệt không cho phép",
    );
  });

  it("shows a local form-checking state and clears secrets immediately", async () => {
    setup();
    const user = await fill();
    await user.click(screen.getByRole("button", { name: "Đăng nhập" }));
    expect(
      screen.getByRole("button", { name: /Đang kiểm tra/ }),
    ).toBeDisabled();
    expect(screen.getByLabelText("Mật khẩu", { exact: true })).toHaveValue("");
    await waitFor(() =>
      expect(screen.getByRole("button", { name: "Đăng nhập" })).toBeEnabled(),
    );
  });

  it("toggles password visibility and keeps recovery blocked with a separate Demo link", async () => {
    setup();
    const user = userEvent.setup();
    const password = screen.getByLabelText("Mật khẩu", { exact: true });
    expect(password).toHaveAttribute("type", "password");
    await user.click(screen.getByRole("button", { name: "Hiện mật khẩu" }));
    expect(password).toHaveAttribute("type", "text");
    await user.click(screen.getByRole("button", { name: "Ẩn mật khẩu" }));
    expect(password).toHaveAttribute("type", "password");
    await user.click(screen.getByRole("button", { name: "Quên mật khẩu?" }));
    expect(screen.getByRole("alert")).toHaveTextContent("BLOCKED FEATURE");
    expect(
      screen.getByRole("link", { name: "Vào phiên Demo" }),
    ).toHaveAttribute("href", "/session");
    expect(screen.getByRole("link", { name: "Đăng ký" })).toHaveAttribute(
      "href",
      "/register",
    );
  });
});

import { useEffect, useRef, useState, type FormEvent } from "react";
import {
  ArrowRight,
  BookOpen,
  Check,
  Eye,
  EyeOff,
  GraduationCap,
  LoaderCircle,
  LockKeyhole,
  Mail,
  ShieldCheck,
  UserRound,
} from "lucide-react";
import { Link } from "react-router-dom";
import "./auth.css";

const EMAIL_KEY = "dxos-remembered-email-v1";
const validEmail = (value: string) =>
  value.length <= 254 && /^[^\s@]+@[^\s@.]+(?:\.[^\s@.]+)+$/.test(value);

function rememberedEmail() {
  try {
    const email = localStorage.getItem(EMAIL_KEY) || "";
    return validEmail(email) ? email : "";
  } catch {
    return "";
  }
}

function PasswordField({
  id,
  label,
  hint,
  error,
  registration = false,
}: {
  id: string;
  label: string;
  hint?: string;
  error?: string;
  registration?: boolean;
}) {
  const [visible, setVisible] = useState(false);
  return (
    <div className="auth-field">
      <label htmlFor={id}>{label}</label>
      <div className="auth-input-wrap">
        <LockKeyhole size={18} aria-hidden="true" />
        <input
          id={id}
          name={id}
          type={visible ? "text" : "password"}
          autoComplete={registration ? "new-password" : "current-password"}
          required
          maxLength={128}
          aria-invalid={!!error}
          aria-describedby={
            [hint && `${id}-hint`, error && `${id}-error`]
              .filter(Boolean)
              .join(" ") || undefined
          }
        />
        <button
          type="button"
          className="auth-eye"
          aria-label={`${visible ? "Ẩn" : "Hiện"} ${label.toLowerCase()}`}
          aria-pressed={visible}
          aria-controls={id}
          onClick={() => setVisible(!visible)}
        >
          {visible ? <EyeOff size={18} /> : <Eye size={18} />}
        </button>
      </div>
      {hint && (
        <p className="auth-hint" id={`${id}-hint`}>
          {hint}
        </p>
      )}
      {error && (
        <p className="auth-error" id={`${id}-error`}>
          {error}
        </p>
      )}
    </div>
  );
}

export function AuthPage({ mode }: { mode: "login" | "register" }) {
  const registration = mode === "register";
  const [email] = useState(rememberedEmail);
  const [remember, setRemember] = useState(!!email);
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [blocked, setBlocked] = useState("");
  const [storageNotice, setStorageNotice] = useState("");
  const [pending, setPending] = useState(false);
  const locked = useRef(false);
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const heading = useRef<HTMLHeadingElement>(null);

  useEffect(() => {
    const previousTitle = document.title;
    document.title = `${registration ? "Đăng ký" : "Đăng nhập"} | DX-OS`;
    heading.current?.focus();
    return () => {
      clearTimeout(timer.current);
      document.title = previousTitle;
    };
  }, [registration]);

  function saveEmail(value: string) {
    try {
      if (value) localStorage.setItem(EMAIL_KEY, value);
      else localStorage.removeItem(EMAIL_KEY);
      setStorageNotice("");
    } catch {
      setStorageNotice(
        "Trình duyệt không cho phép cập nhật email đã ghi nhớ. Bạn có thể quản lý dữ liệu trong cài đặt trình duyệt.",
      );
    }
  }

  function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (locked.current) return;
    const form = event.currentTarget;
    // Credentials stay in the form's transient memory. No auth service or transport is invoked.
    const data = new FormData(form);
    const submittedEmail = String(data.get("email") || "").trim();
    const password = String(data.get("password") || "");
    const next: Record<string, string> = {};
    if (!validEmail(submittedEmail))
      next.email = "Nhập email hợp lệ, ví dụ: ban@example.edu.vn.";
    if (!password || password.length > 128)
      next.password = "Nhập mật khẩu từ 1 đến 128 ký tự.";
    if (registration) {
      const name = String(data.get("fullName") || "").trim();
      if (name.length < 2 || name.length > 100)
        next.fullName = "Họ và tên cần từ 2 đến 100 ký tự.";
      if (password.length < 12 || password.length > 128)
        next.password = "Mật khẩu cần từ 12 đến 128 ký tự.";
      if (!data.get("confirmation") || data.get("confirmation") !== password)
        next.confirmation = "Mật khẩu xác nhận chưa khớp.";
      if (!["student", "lecturer"].includes(String(data.get("accountType"))))
        next.accountType = "Vui lòng chọn Sinh viên hoặc Giảng viên.";
    }
    setErrors(next);
    setBlocked("");
    if (Object.keys(next).length) {
      const firstInvalid = [
        "fullName",
        "email",
        "password",
        "confirmation",
        "accountType",
      ].find((name) => next[name]);
      form.querySelector<HTMLInputElement>(`[name="${firstInvalid}"]`)?.focus();
      return;
    }
    if (!registration) saveEmail(remember ? submittedEmail : "");
    // Clear both secret fields before presenting the local-only blocked state.
    for (const name of ["password", "confirmation"]) {
      const input = form.elements.namedItem(name);
      if (input instanceof HTMLInputElement) input.value = "";
    }
    locked.current = true;
    setPending(true);
    timer.current = setTimeout(() => {
      setPending(false);
      locked.current = false;
      setBlocked(
        `BLOCKED FEATURE · ${registration ? "Đăng ký tài khoản" : "Đăng nhập email/mật khẩu"} chưa khả dụng. Chưa có API Identity được phê duyệt. ${registration ? "Chưa tạo tài khoản." : "Chưa đăng nhập."} Bạn có thể vào phiên Demo để trải nghiệm.`,
      );
    }, 250);
  }

  return (
    <div className="auth-shell">
      <a href="#auth-content" className="skip-link">
        Đến biểu mẫu
      </a>
      <aside
        className="auth-story"
        aria-label="DX-OS University Service Portal"
      >
        <Link
          className="auth-brand"
          to="/login"
          aria-label="DX-OS · Trang đăng nhập"
        >
          <img src="/favicon.svg" alt="" width="42" height="42" />
          <span>
            DX<span className="auth-brand-dash">-</span>OS
            <small>University Service Portal</small>
          </span>
        </Link>
        <div className="auth-story-content">
          <span className="auth-campus">
            <GraduationCap size={19} aria-hidden="true" /> Không gian dịch vụ
            đại học
          </span>
          <h2>
            Kết nối nhu cầu.
            <br />
            Tiếp nối hành trình.
          </h2>
          <p>
            Một nơi để sinh viên và giảng viên gửi yêu cầu hỗ trợ, phối hợp và
            theo dõi tiến độ.
          </p>
          <div className="auth-service-preview">
            <div className="auth-preview-heading">
              <BookOpen size={20} aria-hidden="true" />
              <span>Dịch vụ trong tầm tay</span>
            </div>
            <ul>
              <li>
                <Check size={17} aria-hidden="true" />
                Hỗ trợ CNTT và cơ sở vật chất
              </li>
              <li>
                <Check size={17} aria-hidden="true" />
                Theo dõi từng bước xử lý
              </li>
              <li>
                <Check size={17} aria-hidden="true" />
                Lịch sử yêu cầu rõ ràng
              </li>
            </ul>
            <div className="auth-preview-footer">
              <span className="auth-preview-dot" /> Cùng một trải nghiệm DX-OS
            </div>
          </div>
        </div>
        <p className="auth-story-footer">
          DX-OS Open-Core <span>Cổng dịch vụ đại học</span>
        </p>
      </aside>

      <main className="auth-main" id="auth-content" tabIndex={-1}>
        <div className="auth-topline">
          <span>Bản xem trước giao diện</span>
          <Link to="/session">
            Khám phá Demo <ArrowRight size={15} aria-hidden="true" />
          </Link>
        </div>
        <section className="auth-card" aria-labelledby="auth-title">
          <span className="auth-form-icon">
            <UserRound size={23} aria-hidden="true" />
          </span>
          <h1 id="auth-title" ref={heading} tabIndex={-1}>
            {registration ? "Tạo tài khoản DX-OS" : "Chào mừng trở lại"}
          </h1>
          <p className="auth-intro">
            {registration
              ? "Đăng ký để kết nối với dịch vụ đại học."
              : "Đăng nhập để truy cập không gian dịch vụ của bạn."}
          </p>
          <div className="auth-preview-note">
            <ShieldCheck size={19} aria-hidden="true" />
            <p>
              <strong>Email/mật khẩu chưa khả dụng.</strong> Chỉ xem trước biểu
              mẫu. Không nhập mật khẩu thật.
            </p>
          </div>

          <form
            noValidate
            onSubmit={submit}
            aria-label={registration ? "Đăng ký tài khoản" : "Đăng nhập"}
            aria-busy={pending}
          >
            <fieldset className="auth-fields" disabled={pending}>
              <legend className="sr-only">
                Thông tin {registration ? "đăng ký" : "đăng nhập"}
              </legend>
              {registration && (
                <div className="auth-field">
                  <label htmlFor="fullName">Họ và tên</label>
                  <div className="auth-input-wrap">
                    <UserRound size={18} aria-hidden="true" />
                    <input
                      id="fullName"
                      name="fullName"
                      autoComplete="name"
                      placeholder="Nhập họ và tên"
                      required
                      maxLength={100}
                      aria-invalid={!!errors.fullName}
                      aria-describedby={
                        errors.fullName ? "fullName-error" : undefined
                      }
                    />
                  </div>
                  {errors.fullName && (
                    <p className="auth-error" id="fullName-error">
                      {errors.fullName}
                    </p>
                  )}
                </div>
              )}
              <div className="auth-field">
                <label htmlFor="email">Email</label>
                <div className="auth-input-wrap">
                  <Mail size={18} aria-hidden="true" />
                  <input
                    id="email"
                    name="email"
                    type="email"
                    autoComplete={registration ? "email" : "username"}
                    autoCapitalize="none"
                    spellCheck={false}
                    defaultValue={registration ? "" : email}
                    placeholder="ban@example.edu.vn"
                    required
                    maxLength={254}
                    aria-invalid={!!errors.email}
                    aria-describedby={errors.email ? "email-error" : undefined}
                  />
                </div>
                {errors.email && (
                  <p className="auth-error" id="email-error">
                    {errors.email}
                  </p>
                )}
              </div>
              <PasswordField
                id="password"
                label="Mật khẩu"
                registration={registration}
                hint={
                  registration
                    ? "Từ 12 đến 128 ký tự. Chỉ dùng dữ liệu giả để xem trước."
                    : undefined
                }
                error={errors.password}
              />
              {registration ? (
                <>
                  <PasswordField
                    id="confirmation"
                    label="Xác nhận mật khẩu"
                    registration
                    error={errors.confirmation}
                  />
                  <fieldset
                    className="auth-account-types"
                    aria-describedby={
                      errors.accountType
                        ? "accountType-error"
                        : "accountType-hint"
                    }
                    aria-invalid={!!errors.accountType}
                  >
                    <legend>Bạn là</legend>
                    <label>
                      <input
                        type="radio"
                        name="accountType"
                        value="student"
                        defaultChecked
                      />
                      <GraduationCap size={18} aria-hidden="true" />
                      Sinh viên
                    </label>
                    <label>
                      <input type="radio" name="accountType" value="lecturer" />
                      <BookOpen size={18} aria-hidden="true" />
                      Giảng viên
                    </label>
                  </fieldset>
                  <p className="auth-hint" id="accountType-hint">
                    Chỉ dành cho sinh viên và giảng viên. Quyền xử lý do đơn vị
                    quản trị cấp.
                  </p>
                  {errors.accountType && (
                    <p className="auth-error" id="accountType-error">
                      {errors.accountType}
                    </p>
                  )}
                </>
              ) : (
                <div className="auth-options">
                  <label>
                    <input
                      type="checkbox"
                      checked={remember}
                      onChange={(event) => {
                        setRemember(event.target.checked);
                        if (!event.target.checked) saveEmail("");
                      }}
                    />
                    Ghi nhớ email
                  </label>
                  <button
                    className="auth-text-button"
                    type="button"
                    onClick={() =>
                      setBlocked(
                        "BLOCKED FEATURE · Quên mật khẩu chưa khả dụng. Chờ API khôi phục tài khoản được phê duyệt.",
                      )
                    }
                  >
                    Quên mật khẩu?
                  </button>
                </div>
              )}
              <button
                type="submit"
                className="button primary auth-submit"
                disabled={pending}
              >
                {pending ? (
                  <>
                    <LoaderCircle size={18} aria-hidden="true" />
                    Đang kiểm tra biểu mẫu…
                  </>
                ) : (
                  <>
                    {registration ? "Đăng ký tài khoản" : "Đăng nhập"}
                    <ArrowRight size={18} aria-hidden="true" />
                  </>
                )}
              </button>
            </fieldset>
            {pending && (
              <p className="sr-only" role="status">
                Đang kiểm tra biểu mẫu…
              </p>
            )}
            {blocked && (
              <div className="auth-blocked" role="alert">
                {blocked}
              </div>
            )}
            {storageNotice && (
              <p className="auth-hint" role="status">
                {storageNotice}
              </p>
            )}
          </form>
          <p className="auth-switch">
            {registration ? "Đã có tài khoản?" : "Chưa có tài khoản?"}{" "}
            <Link to={registration ? "/login" : "/register"}>
              {registration ? "Đăng nhập" : "Đăng ký"}
            </Link>
          </p>
          <div className="auth-divider">
            <span>Trải nghiệm bằng dữ liệu mô phỏng</span>
          </div>
          <Link to="/session" className="button secondary auth-demo">
            Vào phiên Demo <ArrowRight size={17} aria-hidden="true" />
          </Link>
          <p className="auth-demo-hint">
            Không cần tài khoản. Không tạo phiên đăng nhập thật.
          </p>
        </section>
        <footer className="auth-footer">
          <LockKeyhole size={14} aria-hidden="true" />
          DX-OS · University Service Portal
        </footer>
      </main>
    </div>
  );
}

import { beforeEach, describe, expect, it, vi } from "vitest";
import { render, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { MemoryRouter, Route, Routes } from "react-router-dom";
import { PortalProvider } from "../context";
import { requestService } from "../services/MockRequestService";
import { NewRequest } from "./NewRequest";

beforeEach(() => {
  sessionStorage.setItem("dxos-demo-role", "employee");
  requestService.reset();
  vi.restoreAllMocks();
});
function setup() {
  return render(
    <MemoryRouter initialEntries={["/requests/new"]}>
      <PortalProvider>
        <Routes>
          <Route path="/requests/new" element={<NewRequest />} />
          <Route path="/requests/:id" element={<p>Chi tiết yêu cầu mới</p>} />
        </Routes>
      </PortalProvider>
    </MemoryRouter>,
  );
}
async function fill() {
  const user = userEvent.setup();
  await user.type(
    screen.getByRole("textbox", { name: /Tiêu đề yêu cầu/ }),
    "Cài đặt phần mềm cho máy tính",
  );
  await user.type(
    screen.getByRole("textbox", { name: /Mô tả chi tiết/ }),
    "Đề nghị cài đặt các công cụ phát triển cho dự án mới.",
  );
  await user.type(screen.getByRole("textbox", { name: /Vị trí/ }), "Tầng 3");
  return user;
}
describe("request form", () => {
  it("shows accessible validation and focuses the first invalid field", async () => {
    setup();
    await userEvent.click(screen.getByRole("button", { name: "Gửi yêu cầu" }));
    expect(screen.getByText("Tiêu đề cần từ 8 đến 120 ký tự.")).toBeVisible();
    expect(
      screen.getByRole("textbox", { name: /Tiêu đề yêu cầu/ }),
    ).toHaveFocus();
    expect(screen.queryByLabelText(/upload/i)).not.toBeInTheDocument();
    expect(screen.getByText("BLOCKED FEATURE")).toBeVisible();
  });
  it("creates a mock request and announces success", async () => {
    setup();
    const user = await fill();
    await user.click(screen.getByRole("button", { name: "Gửi yêu cầu" }));
    expect(await screen.findByText("Chi tiết yêu cầu mới")).toBeVisible();
    expect(screen.getByRole("status")).toHaveTextContent("Đã tạo yêu cầu demo");
  });
  it("blocks duplicate submit and further writes after an uncertain result", async () => {
    const spy = vi.spyOn(requestService, "create");
    setup();
    const user = await fill();
    requestService.setFault("unknown");
    await user.dblClick(screen.getByRole("button", { name: "Gửi yêu cầu" }));
    await waitFor(() =>
      expect(screen.getByRole("alert")).toHaveTextContent(
        "Chưa xác định kết quả",
      ),
    );
    expect(screen.getByRole("button", { name: "Gửi yêu cầu" })).toBeDisabled();
    expect(spy).toHaveBeenCalledTimes(1);
  });
});

import { useRef, useState, type FormEvent } from "react";
import {
  ArrowLeft,
  ArrowRight,
  Building2,
  Headphones,
  Info,
  LoaderCircle,
  LockKeyhole,
  Paperclip,
  ShieldCheck,
} from "lucide-react";
import { Link, useNavigate, useSearchParams } from "react-router-dom";
import {
  kindLabels,
  validateRequest,
  type CreateRequestInput,
  type RequestKind,
} from "../domain/request";
import { usePortal } from "../context";
import { useSessionOperation } from "../hooks/useSessionOperation";
import { PortalError, safeError } from "../services/RequestService";
import { ErrorState, PageHeading } from "../components/ui";

export function NewRequest() {
  const [params] = useSearchParams();
  const navigate = useNavigate();
  const { role, refresh, notify, expireSession, requestService } = usePortal();
  const captureOperation = useSessionOperation();
  const [input, setInput] = useState<CreateRequestInput>({
    kind: params.get("kind") === "facility" ? "facility" : "it",
    title: "",
    description: "",
    priority: "normal",
    location: "",
  });
  const [errors, setErrors] = useState<ReturnType<typeof validateRequest>>({});
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [uncertain, setUncertain] = useState(false);
  const lock = useRef(false);
  const formRef = useRef<HTMLFormElement>(null);
  function update<K extends keyof CreateRequestInput>(
    key: K,
    value: CreateRequestInput[K],
  ) {
    setInput((i) => ({ ...i, [key]: value }));
    setErrors((e) => ({ ...e, [key]: undefined }));
  }
  async function submit(e: FormEvent) {
    e.preventDefault();
    if (lock.current || !role || uncertain) return;
    const problems = validateRequest(input);
    setErrors(problems);
    if (Object.keys(problems).length) {
      const field = Object.keys(problems)[0];
      (
        formRef.current?.elements.namedItem(field) as HTMLElement | null
      )?.focus();
      return;
    }
    lock.current = true;
    setBusy(true);
    setError("");
    const operation = captureOperation();
    try {
      const created = await requestService.create(input, role);
      if (!operation.canUpdate()) return;
      refresh();
      notify("Đã tạo yêu cầu demo. Dữ liệu được lưu trong bộ nhớ.");
      navigate(`/requests/${created.id}`);
    } catch (err) {
      if (!operation.isCurrent()) return;
      if (err instanceof PortalError && err.code === "401") {
        expireSession();
        return;
      }
      if (!operation.canUpdate()) return;
      setError(safeError(err));
      if (err instanceof PortalError && err.code === "COMMIT_OUTCOME_UNKNOWN")
        setUncertain(true);
    } finally {
      lock.current = false;
      if (operation.canUpdate()) setBusy(false);
    }
  }
  return (
    <>
      <Link className="back-link" to="/requests">
        <ArrowLeft size={16} />
        Danh sách yêu cầu
      </Link>
      <PageHeading
        title="Bạn cần hỗ trợ gì?"
        description="Mô tả nhu cầu của bạn. Chúng tôi sẽ chuyển đến đúng nhóm phụ trách."
      />
      <div className="form-layout">
        <form
          ref={formRef}
          className="panel request-form"
          noValidate
          onSubmit={submit}
        >
          <fieldset disabled={busy || uncertain}>
            <legend>
              <span className="step-number">1</span>Chọn dịch vụ
            </legend>
            <div className="service-options">
              {(["it", "facility"] as RequestKind[]).map((kind) => (
                <label
                  key={kind}
                  className={`service-option ${input.kind === kind ? "selected" : ""}`}
                >
                  <input
                    type="radio"
                    name="kind"
                    value={kind}
                    checked={input.kind === kind}
                    onChange={() => update("kind", kind)}
                  />
                  {kind === "it" ? (
                    <Headphones size={25} />
                  ) : (
                    <Building2 size={25} />
                  )}
                  <strong>{kindLabels[kind]}</strong>
                  <small>
                    {kind === "it"
                      ? "Thiết bị, phần mềm, tài khoản"
                      : "Văn phòng, phòng họp, tiện ích"}
                  </small>
                </label>
              ))}
            </div>
          </fieldset>
          <fieldset disabled={busy || uncertain}>
            <legend>
              <span className="step-number">2</span>Thông tin yêu cầu
            </legend>
            <label className="field">
              Tiêu đề yêu cầu <span className="required">*</span>
              <input
                name="title"
                maxLength={120}
                value={input.title}
                onChange={(e) => update("title", e.target.value)}
                placeholder={
                  input.kind === "it"
                    ? "Ví dụ: Cấp quyền truy cập kho mã nguồn dự án"
                    : "Ví dụ: Kiểm tra điều hòa phòng họp Lotus"
                }
                aria-required="true"
                aria-invalid={!!errors.title}
                aria-describedby={errors.title ? "title-error" : undefined}
              />
              {errors.title && (
                <span className="field-error" id="title-error">
                  {errors.title}
                </span>
              )}
            </label>
            <label className="field">
              Mô tả chi tiết <span className="required">*</span>
              <textarea
                name="description"
                rows={5}
                maxLength={2000}
                value={input.description}
                onChange={(e) => update("description", e.target.value)}
                placeholder="Vấn đề bạn đang gặp là gì? Khi nào xảy ra và ảnh hưởng đến công việc như thế nào?"
                aria-required="true"
                aria-invalid={!!errors.description}
                aria-describedby={
                  errors.description ? "description-error" : "description-hint"
                }
              />
              <span className="field-hint" id="description-hint">
                Càng cụ thể, đội ngũ càng hỗ trợ bạn nhanh hơn.{" "}
                <span>{input.description.length}/2000</span>
              </span>
              {errors.description && (
                <span className="field-error" id="description-error">
                  {errors.description}
                </span>
              )}
            </label>
            <div className="field-grid">
              <label className="field">
                Vị trí / khu vực <span className="required">*</span>
                <input
                  name="location"
                  value={input.location}
                  maxLength={100}
                  onChange={(e) => update("location", e.target.value)}
                  placeholder="Ví dụ: Tầng 3 · Khu phát triển"
                  aria-required="true"
                  aria-invalid={!!errors.location}
                  aria-describedby={
                    errors.location ? "location-error" : undefined
                  }
                />
                {errors.location && (
                  <span className="field-error" id="location-error">
                    {errors.location}
                  </span>
                )}
              </label>
              <label className="field">
                Mức độ ưu tiên
                <select
                  name="priority"
                  value={input.priority}
                  onChange={(e) =>
                    update(
                      "priority",
                      e.target.value as CreateRequestInput["priority"],
                    )
                  }
                >
                  <option value="normal">Bình thường</option>
                  <option value="high">Cao</option>
                  <option value="urgent">Khẩn cấp</option>
                </select>
              </label>
            </div>
          </fieldset>
          <div className="attachment-block">
            <Paperclip size={22} />
            <div>
              <strong>
                Tệp đính kèm{" "}
                <span className="blocked-tag">BLOCKED FEATURE</span>
              </strong>
              <p>
                Chờ Storage API có kiểm quyền. Chưa hỗ trợ chọn hoặc tải tệp.
              </p>
            </div>
            <LockKeyhole size={18} />
          </div>
          {error && <ErrorState message={error} />}
          {uncertain && (
            <Link className="text-link" to="/requests">
              Kiểm tra danh sách và lịch sử yêu cầu
            </Link>
          )}
          <div className="form-actions">
            <span>
              <ShieldCheck size={15} />
              Chỉ lưu trong phiên mock
            </span>
            <Link to="/requests" className="button secondary">
              Hủy
            </Link>
            <button
              type="submit"
              className="button primary"
              disabled={busy || uncertain}
            >
              {busy ? <LoaderCircle className="spinner" size={17} /> : null}
              {busy ? "Đang gửi…" : "Gửi yêu cầu"}
              <ArrowRight size={16} />
            </button>
          </div>
        </form>
        <aside className="form-aside">
          <div className="info-card">
            <Info size={23} />
            <h3>
              Một yêu cầu rõ ràng,
              <br />
              một khởi đầu thuận lợi.
            </h3>
            <p>
              Chọn đúng dịch vụ và mô tả đầy đủ để nhóm phụ trách tiếp nhận
              nhanh chóng.
            </p>
            <ol>
              <li>Gửi yêu cầu</li>
              <li>Phê duyệt & phân công</li>
              <li>Xử lý & cập nhật tiến độ</li>
              <li>Hoàn thành & lưu lịch sử</li>
            </ol>
          </div>
          <p className="aside-footnote">
            Đây là quy trình UX mẫu. Workflow API thật chưa được mở qua security
            gate.
          </p>
        </aside>
      </div>
    </>
  );
}

import { useRef, useState } from "react";
import {
  ArrowLeft,
  Building2,
  Headphones,
  LockKeyhole,
  MessageSquare,
  RefreshCw,
  ShieldCheck,
} from "lucide-react";
import { Link, useParams } from "react-router-dom";
import { useRequests } from "../hooks/useRequests";
import { useSessionOperation } from "../hooks/useSessionOperation";
import { usePortal } from "../context";
import { formatDate, kindLabels, type RequestAction } from "../domain/request";
import { PortalError, safeError } from "../services/RequestService";
import {
  ErrorState,
  Loading,
  Modal,
  PageHeading,
  Priority,
  StatusBadge,
  Timeline,
} from "../components/ui";

export function RequestDetail() {
  const { id } = useParams();
  const { data, loading, error, reload } = useRequests(id);
  const { role, refresh, notify, expireSession, requestService } = usePortal();
  const captureOperation = useSessionOperation();
  const [action, setAction] = useState<RequestAction | null>(null);
  const [note, setNote] = useState("");
  const [actionError, setActionError] = useState("");
  const [busy, setBusy] = useState(false);
  const [uncertain, setUncertain] = useState(false);
  const lock = useRef(false);
  if (loading) return <Loading />;
  if (error || !data[0])
    return (
      <ErrorState
        message={error || "Không tìm thấy yêu cầu hoặc yêu cầu không khả dụng."}
        onRetry={reload}
      />
    );
  const item = data[0];
  const actions = role ? requestService.actions(item, role) : [];
  async function execute() {
    if (!action || !role || lock.current || uncertain) return;
    if (note.trim().length < 5) {
      setActionError("Ghi chú cần từ 5 đến 1.000 ký tự.");
      return;
    }
    lock.current = true;
    setBusy(true);
    setActionError("");
    const operation = captureOperation();
    try {
      await requestService.transition(
        item.id,
        action.id,
        note,
        item.version,
        role,
      );
      if (!operation.canUpdate()) return;
      setAction(null);
      refresh();
      notify("Đã cập nhật yêu cầu demo và lịch sử xử lý.");
    } catch (err) {
      if (!operation.isCurrent()) return;
      if (err instanceof PortalError && err.code === "401") {
        expireSession();
        return;
      }
      if (!operation.canUpdate()) return;
      setActionError(safeError(err));
      if (err instanceof PortalError && err.code === "COMMIT_OUTCOME_UNKNOWN")
        setUncertain(true);
    } finally {
      lock.current = false;
      if (operation.canUpdate()) setBusy(false);
    }
  }
  return (
    <>
      <Link className="back-link" to="/requests">
        <ArrowLeft size={16} />
        Danh sách yêu cầu
      </Link>
      <PageHeading
        eyebrow={`${item.id} · ${kindLabels[item.kind]}`}
        title={item.title}
        description={`Tạo bởi ${item.requester} · ${formatDate(item.createdAt)}`}
      >
        <StatusBadge status={item.status} />
      </PageHeading>
      <div className="detail-layout">
        <div>
          <section className="panel detail-content">
            <div className="panel-heading">
              <h2>Nội dung yêu cầu</h2>
              {item.kind === "it" ? (
                <Headphones size={21} />
              ) : (
                <Building2 size={21} />
              )}
            </div>
            <p className="request-description">{item.description}</p>
            <div className="attachment-block">
              <LockKeyhole size={20} />
              <div>
                <strong>
                  Tệp đính kèm{" "}
                  <span className="blocked-tag">BLOCKED FEATURE</span>
                </strong>
                <p>Storage API chưa sẵn sàng để tích hợp an toàn.</p>
              </div>
            </div>
          </section>
          <section className="panel detail-timeline">
            <div className="panel-heading">
              <h2>
                Lịch sử xử lý{" "}
                <span className="count-badge">{item.timeline.length}</span>
              </h2>
              <span className="muted">Mới nhất trước</span>
            </div>
            <Timeline events={item.timeline} />
          </section>
        </div>
        <aside>
          <section className="panel metadata">
            <div className="panel-heading">
              <h2>Thông tin yêu cầu</h2>
            </div>
            <dl>
              <dt>Trạng thái</dt>
              <dd>
                <StatusBadge status={item.status} />
              </dd>
              <dt>Ưu tiên</dt>
              <dd>
                <Priority priority={item.priority} />
              </dd>
              <dt>Dịch vụ</dt>
              <dd>{kindLabels[item.kind]}</dd>
              <dt>Người yêu cầu</dt>
              <dd>{item.requester}</dd>
              <dt>Phòng ban</dt>
              <dd>{item.department}</dd>
              <dt>Nhóm phụ trách</dt>
              <dd>{item.assignee}</dd>
              <dt>Vị trí</dt>
              <dd>{item.location}</dd>
              <dt>Cập nhật gần nhất</dt>
              <dd>{formatDate(item.updatedAt)}</dd>
              <dt>Phiên bản mock</dt>
              <dd>v{item.version}</dd>
            </dl>
          </section>
          <section className="panel action-panel">
            <h2>
              <MessageSquare size={18} />
              Thao tác xử lý
            </h2>
            {actions.length ? (
              <>
                <p>
                  Các thao tác dưới đây là phản hồi mô phỏng, không gọi Workflow
                  API.
                </p>
                {actions.map((a) => (
                  <button
                    key={a.id}
                    disabled={uncertain}
                    className={`button ${a.tone === "danger" ? "danger" : "primary"}`}
                    onClick={() => {
                      setAction(a);
                      setNote("");
                      setActionError("");
                    }}
                  >
                    {a.label}
                  </button>
                ))}
              </>
            ) : (
              <p>
                {item.kind === "it" && item.status === "resolved"
                  ? "IT đã xử lý và thông báo kết quả. Yêu cầu đang chờ người gửi xác nhận hoàn thành."
                  : item.kind === "it" && item.status === "confirmed"
                    ? "Người gửi đã xác nhận hoàn thành. Không có thao tác tiếp theo trong kịch bản mock."
                    : role !== "processor"
                      ? "Chuyển sang vai trò Người xử lý trong Trạng thái phiên để trải nghiệm thao tác demo."
                      : "Yêu cầu đã kết thúc. Không còn thao tác xử lý."}
              </p>
            )}
            {uncertain && (
              <ErrorState message="Kết quả chưa xác định. Kiểm tra lịch sử; không gửi lại thao tác." />
            )}
            <button className="text-link" onClick={reload}>
              <RefreshCw size={14} />
              Tải lại chi tiết
            </button>
          </section>
          <p className="aside-footnote">
            <ShieldCheck size={16} />
            Lịch sử này dùng mock data, chưa phải audit trail từ Core.
          </p>
        </aside>
      </div>
      {action && (
        <Modal
          title={`${action.label} · ${item.id}`}
          onClose={() => {
            if (!busy) setAction(null);
          }}
        >
          <p className="muted">
            Thao tác chỉ thay đổi dữ liệu mock trong bộ nhớ.
          </p>
          <label className="field">
            Ghi chú xử lý
            <textarea
              autoFocus
              rows={4}
              maxLength={1000}
              value={note}
              disabled={busy || uncertain}
              onChange={(e) => setNote(e.target.value)}
              placeholder="Mô tả quyết định hoặc kết quả xử lý…"
            />
          </label>
          {actionError && <ErrorState message={actionError} />}
          <div className="modal-actions">
            <button
              className="button secondary"
              disabled={busy}
              onClick={() => setAction(null)}
            >
              Đóng
            </button>
            <button
              className={`button ${action.tone === "danger" ? "danger" : "primary"}`}
              disabled={busy || uncertain}
              onClick={execute}
            >
              {busy
                ? "Đang cập nhật…"
                : action.id === "confirm"
                  ? action.label
                  : `Xác nhận ${action.label.toLowerCase()}`}
            </button>
          </div>
        </Modal>
      )}
    </>
  );
}

import { useState } from "react";
import { Filter, Plus, Search, SlidersHorizontal } from "lucide-react";
import { Link, useSearchParams } from "react-router-dom";
import { filterRequests, kindLabels, statusLabels } from "../domain/request";
import { usePortal } from "../context";
import { useRequests } from "../hooks/useRequests";
import {
  Empty,
  ErrorState,
  Loading,
  PageHeading,
  RequestTable,
  Timeline,
} from "../components/ui";

export function Requests({
  mode = "list",
}: {
  mode?: "list" | "approvals" | "history";
}) {
  const [params, setParams] = useSearchParams();
  const [page, setPage] = useState(1);
  const { role } = usePortal();
  const { data, loading, error, reload } = useRequests();
  const query = params.get("q") || "";
  const kind = params.get("kind") || "";
  const status = params.get("status") || "";
  const update = (key: string, value: string) => {
    const next = new URLSearchParams(params);
    value ? next.set(key, value) : next.delete(key);
    setParams(next, { replace: true });
    setPage(1);
  };
  const source =
    mode === "approvals"
      ? data.filter((r) =>
          ["pending", "approved", "processing"].includes(r.status),
        )
      : data;
  const filtered = filterRequests(source, query, kind, status);
  const totalPages = Math.max(1, Math.ceil(filtered.length / 6));
  const currentPage = Math.min(page, totalPages);
  const selected = filtered.slice((currentPage - 1) * 6, currentPage * 6);
  const title =
    mode === "history"
      ? "Lịch sử hoạt động"
      : mode === "approvals"
        ? "Bàn phê duyệt & xử lý"
        : "Danh sách yêu cầu";
  return (
    <>
      <PageHeading
        eyebrow="Dịch vụ nội bộ"
        title={title}
        description={
          mode === "approvals"
            ? "Tiếp nhận, phê duyệt và theo dõi công việc của đội ngũ trong kịch bản demo."
            : mode === "history"
              ? "Mỗi thay đổi đều có dấu vết. Lịch sử mới nhất được hiển thị trước."
              : "Tất cả yêu cầu, trạng thái và thông tin bạn cần theo dõi."
        }
      >
        <Link to="/requests/new" className="button primary">
          <Plus size={18} />
          Tạo yêu cầu mới
        </Link>
      </PageHeading>
      {mode === "approvals" && role !== "processor" ? (
        <section className="panel">
          <Empty
            title="Bàn xử lý dành cho người phụ trách"
            description="Đổi sang vai trò Người xử lý trong phiên demo để trải nghiệm phê duyệt."
          >
            <Link to="/session" className="button primary">
              Chọn vai trò demo
            </Link>
          </Empty>
        </section>
      ) : (
        <section className="panel">
          <div className="list-tabs">
            <span className="selected-tab">
              {mode === "history"
                ? "Nhật ký yêu cầu"
                : mode === "approvals"
                  ? "Cần xử lý"
                  : "Tất cả yêu cầu"}
              <span className="count-badge">{source.length}</span>
            </span>
            <span className="muted">
              <SlidersHorizontal size={16} />
              Dữ liệu demo
            </span>
          </div>
          <div className="filters">
            <div className="search-field">
              <Search size={18} />
              <input
                aria-label="Tìm yêu cầu"
                placeholder="Tìm theo mã, tiêu đề hoặc người yêu cầu…"
                value={query}
                onChange={(e) => update("q", e.target.value)}
              />
            </div>
            <label className="filter-select">
              <Filter size={15} />
              <span className="sr-only">Loại dịch vụ</span>
              <select
                value={kind}
                onChange={(e) => update("kind", e.target.value)}
              >
                <option value="">Tất cả dịch vụ</option>
                {Object.entries(kindLabels).map(([value, label]) => (
                  <option key={value} value={value}>
                    {label}
                  </option>
                ))}
              </select>
            </label>
            <label className="filter-select">
              <span className="sr-only">Trạng thái</span>
              <select
                value={status}
                onChange={(e) => update("status", e.target.value)}
              >
                <option value="">Tất cả trạng thái</option>
                {Object.entries(statusLabels).map(([value, label]) => (
                  <option key={value} value={value}>
                    {label}
                  </option>
                ))}
              </select>
            </label>
            {(query || kind || status) && (
              <button
                className="text-link"
                onClick={() => {
                  setParams({});
                  setPage(1);
                }}
              >
                Xóa bộ lọc
              </button>
            )}
          </div>
          {loading ? (
            <Loading />
          ) : error ? (
            <ErrorState message={error} onRetry={reload} />
          ) : !filtered.length ? (
            <Empty />
          ) : mode === "history" ? (
            <div className="history-list">
              {selected.map((r) => (
                <article key={r.id}>
                  <div className="section-title">
                    <Link to={`/requests/${r.id}`} className="text-link">
                      {r.id} · {r.title}
                    </Link>
                  </div>
                  <Timeline events={r.timeline} />
                </article>
              ))}
            </div>
          ) : (
            <RequestTable items={selected} />
          )}
          {!loading && !error && filtered.length > 0 && (
            <div className="pagination">
              <span>
                Hiển thị {(currentPage - 1) * 6 + 1}–
                {Math.min(currentPage * 6, filtered.length)} trên{" "}
                {filtered.length} yêu cầu
              </span>
              <div>
                <button
                  className="button secondary small"
                  disabled={currentPage === 1}
                  onClick={() => setPage(currentPage - 1)}
                >
                  Trước
                </button>
                <span>
                  {currentPage} / {totalPages}
                </span>
                <button
                  className="button secondary small"
                  disabled={currentPage === totalPages}
                  onClick={() => setPage(currentPage + 1)}
                >
                  Sau
                </button>
              </div>
            </div>
          )}
        </section>
      )}
    </>
  );
}

