/**
 * Application service for the reviewed DTO, using an explicitly injected client.
 * Unbound: no transport/default instance, persona, token or Portal composition
 * changes. In particular this does not masquerade as legacy RequestService.
 */
export class HelpdeskRequestService {
  constructor(private readonly client: HelpdeskApiClient) {}

  async create(input: HelpdeskCreateInput) {
    return mapHelpdeskRequestPresentation(await this.client.create(input));
  }

  async list(input: HelpdeskListInput = {}) {
    return mapHelpdeskListPresentation(await this.client.list(input));
  }

  async detail(id: string) {
    return mapHelpdeskRequestPresentation(await this.client.detail(id));
  }

  async triage(id: string, input: HelpdeskVersionInput) {
    return mapHelpdeskRequestPresentation(await this.client.triage(id, input));
  }

  async assign(id: string, input: HelpdeskAssignInput) {
    return mapHelpdeskRequestPresentation(await this.client.assign(id, input));
  }

  async start(id: string, input: HelpdeskVersionInput) {
    return mapHelpdeskRequestPresentation(await this.client.start(id, input));
  }

  async resolve(id: string, input: HelpdeskResolveInput) {
    return mapHelpdeskRequestPresentation(await this.client.resolve(id, input));
  }

  async confirm(id: string, input: HelpdeskVersionInput) {
    return mapHelpdeskRequestPresentation(await this.client.confirm(id, input));
  }

  async history(id: string) {
    return mapHelpdeskHistoryPresentation(await this.client.history(id));
  }
}

/** Structural seam for APP-11 fake service/component integration tests. */
export type HelpdeskAssignmentService = Pick<
  HelpdeskRequestService,
  "detail" | "assign"
>;

import type { AssignmentFormProps } from "../../components/AssignmentForm";
import type { HelpdeskAssignmentService } from "./HelpdeskRequestService";
import type { HelpdeskPortalRequestPresentation } from "./helpdeskPresentation";

/**
 * Prepare the standalone form only from authorized Detail. Caller must keep the
 * form unmounted when this returns null. Eligibility never grants permission.
 * APP-14 mounts this through its separate MVP model, never legacy MOCK data.
 */
export function helpdeskAssignmentFormProps(
  detail: HelpdeskPortalRequestPresentation,
  service: HelpdeskAssignmentService,
  onAuthoritativeDetail: (detail: HelpdeskPortalRequestPresentation) => void,
  isCurrent: () => boolean = () => true,
): AssignmentFormProps | null {
  if (!detail.allowedActions.includes("assign")) return null;

  const eligible = detail.eligibleAssignees;
  const version = detail.assignmentVersion;
  const valid =
    detail.state === "TRIAGED" &&
    Number.isSafeInteger(version) &&
    version >= 0 &&
    eligible != null &&
    eligible.items.length > 0 &&
    eligible.items.every(
      (item) =>
        typeof item.id.value === "string" &&
        item.id.value.trim().length > 0 &&
        item.id.value.length <= 1024,
    );

  return {
    currentAssignee: detail.currentAssignee,
    eligibleAssignees: eligible ?? undefined,
    assignmentPermission: "allowed",
    submission: valid
      ? {
          status: "ready",
          submitAssignment: async (selectedId) => {
            // Membership is checked again; never serialize a name or another token.
            const selected = eligible.items.find(
              (item) => item.id === selectedId,
            );
            if (!selected || typeof selected.id.value !== "string") {
              throw new RangeError(
                "Assignee was not supplied by authorized Detail.",
              );
            }
            await service.assign(detail.id, {
              assigneeId: selected.id.value,
              expectedAssignmentVersion: version,
            });
            // A confirmed write is not undone by leaving the screen/session.
            // Do not start another protected read for the obsolete UI.
            if (!isCurrent()) return;
            // Mutation responses omit names/eligibility at this Backend HEAD.
            // Reload Detail after confirmed success; no optimistic local updates.
            onAuthoritativeDetail(await service.detail(detail.id));
          },
        }
      : {
          status: "blocked",
          reason:
            "Chưa có dữ liệu phân công hợp lệ. Tải lại chi tiết trước khi tiếp tục.",
        },
  };
}

import type {
  AssignmentCommand,
  AssigneeId,
  CreateRequestInput,
  ObservedVersions,
  RequestSnapshot,
  WorkflowActionCommand,
  WorkflowActionName,
} from "./types";

/** Pick existing form fields only. This is not a wire serializer or validator. */
export function createRequestInput(
  input: CreateRequestInput,
): CreateRequestInput {
  return {
    kind: input.kind,
    title: input.title,
    description: input.description,
    priority: input.priority,
    location: input.location,
  };
}

function observedVersions(snapshot: RequestSnapshot): ObservedVersions {
  return {
    workflow: snapshot.workflow.version,
    ...(snapshot.businessVersion === undefined
      ? {}
      : { business: snapshot.businessVersion }),
  };
}

/**
 * Select only an action supplied on this snapshot, preserving its reference.
 * This local check never replaces Backend authorization or freshness checks.
 * Caller-supplied action input is opaque until action field rules are approved.
 */
export function createWorkflowActionCommand(
  snapshot: RequestSnapshot,
  name: WorkflowActionName,
  input: unknown,
): WorkflowActionCommand {
  const action = snapshot.allowedActions.find((item) => item.name === name);
  if (!action) {
    throw new RangeError("Workflow action was not supplied on this snapshot.");
  }
  return {
    kind: "workflow-action",
    requestId: snapshot.id,
    action: { name: action.name, reference: action.reference },
    observedVersions: observedVersions(snapshot),
    input,
  };
}

/** Does not infer assignment authorization from role, state or eligibility. */
export function createAssignmentCommand(
  snapshot: RequestSnapshot,
  assigneeId: AssigneeId,
  input: unknown,
): AssignmentCommand {
  return {
    kind: "assignment",
    requestId: snapshot.id,
    assigneeId,
    observedVersions: observedVersions(snapshot),
    input,
  };
}

/** Internal error categories, not an assumed Backend error envelope. */
export type MvpErrorCode =
  | "UNAUTHENTICATED"
  | "FORBIDDEN"
  | "NOT_FOUND"
  | "CONFLICT"
  | "NETWORK_FAILURE"
  | "COMMIT_OUTCOME_UNKNOWN";

const messages: Record<MvpErrorCode, string> = {
  UNAUTHENTICATED: "Phiên đã hết hạn hoặc chưa được xác thực.",
  FORBIDDEN: "Bạn không có quyền thực hiện thao tác này.",
  NOT_FOUND: "Không tìm thấy yêu cầu hoặc yêu cầu không khả dụng.",
  CONFLICT:
    "Dữ liệu đã thay đổi. Tải lại trước khi quyết định thao tác tiếp theo.",
  NETWORK_FAILURE: "Không thể tải dữ liệu do lỗi kết nối.",
  COMMIT_OUTCOME_UNKNOWN:
    "Chưa xác định kết quả ghi. Không gửi lại; cần đối soát trước khi tiếp tục.",
};

export class MvpApplicationError extends Error {
  constructor(
    readonly code: MvpErrorCode,
    options?: ErrorOptions,
  ) {
    super(messages[code], options);
    this.name = "MvpApplicationError";
  }
}

/** Call only for a known HTTP response; does not inspect or guess JSON fields. */
export function errorFromHttpStatus(
  status: 401 | 403 | 404 | 409,
): MvpApplicationError {
  const codes = {
    401: "UNAUTHENTICATED",
    403: "FORBIDDEN",
    404: "NOT_FOUND",
    409: "CONFLICT",
  } as const;
  return new MvpApplicationError(codes[status]);
}

/**
 * For a failed attempted operation without proof that a write did not commit.
 * A timeout/abort/lost response cannot safely be treated as a rejected write.
 */
export function networkFailure(
  operation: "read" | "write",
  cause?: unknown,
): MvpApplicationError {
  return new MvpApplicationError(
    operation === "write" ? "COMMIT_OUTCOME_UNKNOWN" : "NETWORK_FAILURE",
    { cause },
  );
}

/**
 * Invoke one already-prepared write once. No retry, token refresh, replay,
 * idempotency key, automatic read/reconciliation or session/UI side effects.
 * Run local validation before calling. Unknown failures are conservative because
 * the invocation may have committed. A future adapter must not hide uncertain
 * orchestration outcomes behind an ordinary rejection category.
 */
export async function executeWriteOnce<T>(write: () => Promise<T>): Promise<T> {
  try {
    return await write();
  } catch (error) {
    if (error instanceof MvpApplicationError) {
      if (error.code !== "NETWORK_FAILURE") throw error;
    }
    throw networkFailure("write", error);
  }
}

