import { describe, expect, expectTypeOf, it } from "vitest";
import type { ServiceRequest } from "../../domain/request";
import { helpdeskCursor, helpdeskWire } from "../../test/helpdeskFixtures";
import {
  decodeHelpdeskHistory,
  decodeHelpdeskPage,
  decodeHelpdeskRequest,
} from "./http/codecs";
import { HELPDESK_CONTRACT_HEAD } from "./http/types";
import {
  mapHelpdeskHistoryPresentation,
  mapHelpdeskListPresentation,
  mapHelpdeskRequestPresentation,
  type HelpdeskPortalRequestPresentation,
} from "./helpdeskPresentation";

describe("APP-10 exact PR #63 RequestView mapping", () => {
  it("pins the reviewed Backend HEAD and keeps the legacy MOCK model incompatible", () => {
    expect(HELPDESK_CONTRACT_HEAD).toBe(
      "e12d105c89400a5fd69dd6cc1fca670ff1f04f51",
    );
    expectTypeOf<HelpdeskPortalRequestPresentation>().not.toExtend<ServiceRequest>();
  });

  it.each([
    "SUBMITTED",
    "TRIAGED",
    "IN_PROGRESS",
    "RESOLVED",
    "CONFIRMED",
    "future_state",
  ])(
    "preserves authoritative %s, independent versions and explicit Backend facts",
    (state) => {
      const source = helpdeskWire({ state, assignmentVersion: 3, version: 19 });
      const before = structuredClone(source);
      const view = mapHelpdeskRequestPresentation(
        decodeHelpdeskRequest(source),
      );
      expect(view).toMatchObject({ ...source, kind: "it" });
      expect(view.currentAssignee).toEqual({
        id: { scope: "assignee", value: source.assigneeId },
      });
      expect(view.version).toBe(19);
      expect(view.assignmentVersion).toBe(3);
      for (const field of [
        "status",
        "priority",
        "location",
        "requester",
        "department",
        "createdAt",
        "updatedAt",
        "timeline",
        "history",
        "actor",
        "role",
      ]) {
        expect(view).not.toHaveProperty(field);
      }
      expect(source).toEqual(before);
    },
  );

  it.each([undefined, null, "Tên được phép hiển thị", ""])(
    "keeps optional/hidden display names exactly as supplied: %s",
    (name) => {
      const source = helpdeskWire(
        name === undefined
          ? {}
          : {
              requesterDisplayName: name,
              assigneeDisplayName: name,
            },
      );
      const decoded = decodeHelpdeskRequest(source);
      const view = mapHelpdeskRequestPresentation(decoded);
      if (name === undefined) {
        expect(decoded).not.toHaveProperty("requesterDisplayName");
        expect(view).not.toHaveProperty("requesterDisplayName");
        expect(view).not.toHaveProperty("assigneeDisplayName");
        expect(view.currentAssignee).not.toHaveProperty("displayName");
      } else {
        expect(view.requesterDisplayName).toBe(name);
        expect(view.assigneeDisplayName).toBe(name);
        expect(view.currentAssignee?.displayName).toBe(name);
      }
    },
  );

  it("does not manufacture an assignee from a label when assigneeId is null", () => {
    const view = mapHelpdeskRequestPresentation(
      decodeHelpdeskRequest(
        helpdeskWire({
          assigneeId: null,
          assigneeDisplayName: "Visible label",
        }),
      ),
    );
    expect(view.currentAssignee).toBeNull();
    expect(view.assigneeDisplayName).toBe("Visible label");
  });

  it.each([
    undefined,
    null,
    [],
    [
      { id: "worker-1", displayName: null },
      { id: "worker-2", displayName: "Tên Backend" },
    ],
  ])(
    "preserves eligibility absent/null/empty/populated without granting authority: %j",
    (eligibleAssignees) => {
      const source = helpdeskWire({
        allowedActions: [],
        ...(eligibleAssignees === undefined ? {} : { eligibleAssignees }),
      });
      const decoded = decodeHelpdeskRequest(source);
      const view = mapHelpdeskRequestPresentation(decoded);
      expect(view.allowedActions).toEqual([]);
      expect(view).not.toHaveProperty("canAssign");
      if (eligibleAssignees === undefined) {
        expect(decoded).not.toHaveProperty("eligibleAssignees");
        expect(view).not.toHaveProperty("eligibleAssignees");
      } else if (eligibleAssignees === null) {
        expect(view.eligibleAssignees).toBeNull();
      } else {
        expect(view.eligibleAssignees).toEqual({
          completeness: "unknown",
          items: eligibleAssignees.map((option) => ({
            id: { scope: "assignee", value: option.id },
            displayName: option.displayName,
          })),
        });
        expect(decoded.eligibleAssignees).not.toBe(eligibleAssignees);
      }
    },
  );

  it("preserves only Backend-supplied action strings, including start/assign and unknown names", () => {
    const source = helpdeskWire({
      allowedActions: ["assign", "start", "future_action"],
    });
    const view = mapHelpdeskRequestPresentation(decodeHelpdeskRequest(source));
    expect(view.allowedActions).toEqual(source.allowedActions);
    expect(view.allowedActions).not.toBe(source.allowedActions);
    expect(view.allowedActions).not.toContain("start_work");
  });

  it.each([helpdeskCursor, null])(
    "preserves list items and nextCursor %s",
    (nextCursor) => {
      const view = mapHelpdeskListPresentation(
        decodeHelpdeskPage({ items: [helpdeskWire()], nextCursor }),
      );
      expect(view.items[0]).toEqual(
        mapHelpdeskRequestPresentation(helpdeskWire()),
      );
      expect(view.nextCursor).toBe(nextCursor);
      expect(view).not.toHaveProperty("total");
      expect(
        mapHelpdeskListPresentation(
          decodeHelpdeskPage({ items: [], nextCursor: null }),
        ),
      ).toEqual({ items: [], nextCursor: null });
    },
  );

  it.each(["2026-10-26T01:02:03.123456789Z", 1792976523.125])(
    "maps only HistoryView fields preserving time %s and order",
    (occurredAt) => {
      const source = [
        {
          transitionId: "triage",
          sourceState: "SUBMITTED",
          targetState: "TRIAGED",
          version: 1,
          occurredAt,
          actor: "hidden",
          note: "hidden",
          id: "not-in-dto",
        },
      ];
      const history = mapHelpdeskHistoryPresentation(
        decodeHelpdeskHistory(source),
      );
      expect(history).toEqual([
        {
          transitionId: "triage",
          sourceState: "SUBMITTED",
          targetState: "TRIAGED",
          version: 1,
          occurredAt,
        },
      ]);
      expect(Object.keys(history[0])).toEqual([
        "transitionId",
        "sourceState",
        "targetState",
        "version",
        "occurredAt",
      ]);
      expect(history[0]).not.toHaveProperty("title");
      expect(mapHelpdeskHistoryPresentation(decodeHelpdeskHistory([]))).toEqual(
        [],
      );
    },
  );
});

import type {
  HelpdeskHistoryEntry,
  HelpdeskPage,
  HelpdeskRequest,
} from "./http/types";
import type { Assignee, EligibleAssignees } from "./types";

/**
 * APP-10 projection for the reviewed PR #63 contract. Separate from both wire
 * DTOs and the older normalized/MOCK model: unsupported display fields stay
 * absent. This cannot satisfy the Portal's legacy ServiceRequest interface.
 */
export interface HelpdeskPortalRequestPresentation {
  readonly id: string;
  readonly title: string;
  readonly description: string;
  readonly kind: "it";
  readonly requestType: "IT_HELPDESK";
  readonly workflowInstanceId: string;
  readonly state: string;
  readonly version: number;
  readonly assignmentVersion: number;
  readonly requesterId: string;
  readonly assigneeId: string | null;
  readonly resolution: string | null;
  readonly allowedActions: readonly string[];
  readonly currentAssignee: Assignee | null;
  readonly requesterDisplayName?: string | null;
  readonly assigneeDisplayName?: string | null;
  readonly eligibleAssignees?: EligibleAssignees | null;
}

export interface HelpdeskPortalListPresentation {
  readonly items: readonly HelpdeskPortalRequestPresentation[];
  readonly nextCursor: string | null;
}

export interface HelpdeskPortalHistoryEntry {
  readonly transitionId: string;
  readonly sourceState: string;
  readonly targetState: string;
  readonly version: number;
  readonly occurredAt: string | number;
}

function assignee(id: string, displayName?: string | null): Assignee {
  return {
    id: { scope: "assignee", value: id },
    ...(displayName === undefined ? {} : { displayName }),
  };
}

/** Input is validated by the wire decoder; never infer permissions or names. */
export function mapHelpdeskRequestPresentation(
  source: HelpdeskRequest,
): HelpdeskPortalRequestPresentation {
  return {
    id: source.id,
    title: source.title,
    description: source.description,
    kind: "it",
    requestType: source.requestType,
    workflowInstanceId: source.workflowInstanceId,
    state: source.state,
    version: source.version,
    assignmentVersion: source.assignmentVersion,
    requesterId: source.requesterId,
    assigneeId: source.assigneeId,
    resolution: source.resolution,
    allowedActions: [...source.allowedActions],
    currentAssignee:
      source.assigneeId === null
        ? null
        : assignee(source.assigneeId, source.assigneeDisplayName),
    ...(source.requesterDisplayName === undefined
      ? {}
      : { requesterDisplayName: source.requesterDisplayName }),
    ...(source.assigneeDisplayName === undefined
      ? {}
      : { assigneeDisplayName: source.assigneeDisplayName }),
    ...(source.eligibleAssignees === undefined
      ? {}
      : {
          eligibleAssignees:
            source.eligibleAssignees === null
              ? null
              : {
                  items: source.eligibleAssignees.map((option) =>
                    assignee(option.id, option.displayName),
                  ),
                  // The DTO has no completeness metadata. Do not claim full visibility.
                  completeness: "unknown" as const,
                },
        }),
  };
}

export function mapHelpdeskListPresentation(
  source: HelpdeskPage,
): HelpdeskPortalListPresentation {
  return {
    items: source.items.map(mapHelpdeskRequestPresentation),
    nextCursor: source.nextCursor,
  };
}

/** Only fields actually returned by HistoryView; no actor/note/event ID/title. */
export function mapHelpdeskHistoryPresentation(
  source: readonly HelpdeskHistoryEntry[],
): readonly HelpdeskPortalHistoryEntry[] {
  return source.map((entry) => ({
    transitionId: entry.transitionId,
    sourceState: entry.sourceState,
    targetState: entry.targetState,
    version: entry.version,
    occurredAt: entry.occurredAt,
  }));
}

import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import {
  helpdeskCursor,
  helpdeskId,
  helpdeskWire,
} from "../../../test/helpdeskFixtures";
import { HelpdeskRequestService } from "../HelpdeskRequestService";
import { HelpdeskApiClient } from "./HelpdeskApiClient";
import type { HelpdeskHttpTransport } from "./transport";

const base = "/api/v1/mvp/requests";
const createInput = {
  title: "Sự cố phần mềm",
  description: "Không lưu được báo cáo công việc.",
};
const versionInput = { expectedVersion: 17 };
const assignInput = { assigneeId: "worker-2", expectedAssignmentVersion: 0 };
const resolveInput = {
  ...versionInput,
  resolution: "Đã khắc phục và kiểm tra.",
};
const history = [
  {
    transitionId: "triage",
    sourceState: "SUBMITTED",
    targetState: "TRIAGED",
    version: 1,
    occurredAt: "2026-10-26T01:00:00Z",
  },
];

const routes = [
  {
    name: "create",
    method: "POST",
    path: base,
    body: { ...createInput, requestType: "IT_HELPDESK" },
    status: 201,
    response: helpdeskWire(),
    invoke: (s: HelpdeskRequestService) => s.create(createInput),
  },
  {
    name: "list",
    method: "GET",
    path: base,
    status: 200,
    response: { items: [helpdeskWire()], nextCursor: helpdeskCursor },
    invoke: (s: HelpdeskRequestService) => s.list(),
  },
  {
    name: "detail",
    method: "GET",
    path: `${base}/${helpdeskId}`,
    status: 200,
    response: helpdeskWire(),
    invoke: (s: HelpdeskRequestService) => s.detail(helpdeskId),
  },
  {
    name: "triage",
    method: "POST",
    path: `${base}/${helpdeskId}/triage`,
    body: versionInput,
    status: 200,
    response: helpdeskWire(),
    invoke: (s: HelpdeskRequestService) => s.triage(helpdeskId, versionInput),
  },
  {
    name: "assign",
    method: "POST",
    path: `${base}/${helpdeskId}/assign`,
    body: assignInput,
    status: 200,
    response: helpdeskWire(),
    invoke: (s: HelpdeskRequestService) => s.assign(helpdeskId, assignInput),
  },
  {
    name: "start",
    method: "POST",
    path: `${base}/${helpdeskId}/start`,
    body: versionInput,
    status: 200,
    response: helpdeskWire(),
    invoke: (s: HelpdeskRequestService) => s.start(helpdeskId, versionInput),
  },
  {
    name: "resolve",
    method: "POST",
    path: `${base}/${helpdeskId}/resolve`,
    body: resolveInput,
    status: 200,
    response: helpdeskWire({ resolution: resolveInput.resolution }),
    invoke: (s: HelpdeskRequestService) => s.resolve(helpdeskId, resolveInput),
  },
  {
    name: "confirm",
    method: "POST",
    path: `${base}/${helpdeskId}/confirm`,
    body: versionInput,
    status: 200,
    response: helpdeskWire({ state: "CONFIRMED" }),
    invoke: (s: HelpdeskRequestService) => s.confirm(helpdeskId, versionInput),
  },
  {
    name: "history",
    method: "GET",
    path: `${base}/${helpdeskId}/history`,
    status: 200,
    response: history,
    invoke: (s: HelpdeskRequestService) => s.history(helpdeskId),
  },
] as const;

let assertNoNetworkOrStorage: () => void;
beforeEach(() => {
  const fetchSpy = vi.spyOn(globalThis, "fetch").mockImplementation(() => {
    throw new Error("Unexpected LIVE fetch");
  });
  const xhrSpy = vi
    .spyOn(XMLHttpRequest.prototype, "send")
    .mockImplementation(() => {
      throw new Error("Unexpected LIVE XHR");
    });
  const storageSpy = vi.spyOn(Storage.prototype, "setItem");
  assertNoNetworkOrStorage = () => {
    expect(fetchSpy).not.toHaveBeenCalled();
    expect(xhrSpy).not.toHaveBeenCalled();
    expect(storageSpy).not.toHaveBeenCalled();
  };
});
afterEach(() => {
  try {
    assertNoNetworkOrStorage();
  } finally {
    vi.restoreAllMocks();
  }
});

function fixture(status = 200, body: unknown = helpdeskWire()) {
  const transport = vi
    .fn<HelpdeskHttpTransport>()
    .mockResolvedValue({ status, body });
  const onSessionInvalid = vi.fn();
  const client = new HelpdeskApiClient(transport, onSessionInvalid);
  return {
    transport,
    onSessionInvalid,
    client,
    service: new HelpdeskRequestService(client),
  };
}

describe("APP-13 nine reviewed routes through Application service", () => {
  it.each(routes)(
    "$name: exact method/path/body and one injected attempt",
    async (route) => {
      const { transport, service, onSessionInvalid } = fixture(
        route.status,
        route.response,
      );
      const result = await route.invoke(service);
      const body = "body" in route ? route.body : undefined;
      expect(transport).toHaveBeenCalledExactlyOnceWith({
        method: route.method,
        path: route.path,
        headers: {
          Accept: "application/json",
          ...(body ? { "Content-Type": "application/json" } : {}),
        },
        ...(body ? { body } : {}),
      });
      expect(onSessionInvalid).not.toHaveBeenCalled();
      if (route.name === "history") expect(result).toEqual(history);
      else if (route.name === "list")
        expect(result).toMatchObject({
          nextCursor: helpdeskCursor,
          items: [{ version: 17, assignmentVersion: 0 }],
        });
      else
        expect(result).toMatchObject({
          id: helpdeskId,
          version: 17,
          assignmentVersion: 0,
        });
      expect(transport.mock.calls[0][0].path).not.toContain("/actions");
    },
  );

  it("allowlists create/command fields, sends IT_HELPDESK and never sends caller identity", async () => {
    const { transport, client } = fixture(201);
    const input = {
      ...createInput,
      requestType: "FACILITY",
      requesterId: "forged",
      role: "admin",
      priority: "urgent",
    };
    await client.create(input);
    expect(transport.mock.calls[0][0].body).toEqual({
      ...createInput,
      requestType: "IT_HELPDESK",
    });
    transport.mockResolvedValue({ status: 200, body: helpdeskWire() });
    await client.assign(helpdeskId, {
      ...assignInput,
      expectedVersion: 999,
      actor: "forged",
    } as typeof assignInput);
    expect(transport.mock.calls[1][0].body).toEqual(assignInput);
    await client.resolve(helpdeskId, {
      ...resolveInput,
      note: "not-a-field",
    } as typeof resolveInput);
    expect(transport.mock.calls[2][0].body).toEqual(resolveInput);
  });

  it.each([1, 100])(
    "passes explicit after/limit=%s and preserves pagination",
    async (limit) => {
      const { transport, service } = fixture(200, {
        items: [helpdeskWire()],
        nextCursor: helpdeskCursor,
      });
      const page = await service.list({ after: helpdeskId, limit });
      expect(transport.mock.calls[0][0].path).toBe(
        `${base}?after=${helpdeskId}&limit=${limit}`,
      );
      expect(page.nextCursor).toBe(helpdeskCursor);
      transport.mockResolvedValue({
        status: 200,
        body: { items: [], nextCursor: null },
      });
      expect(await service.list({ after: page.nextCursor! })).toEqual({
        items: [],
        nextCursor: null,
      });
      expect(transport.mock.calls[1][0].path).toBe(
        `${base}?after=${helpdeskCursor}`,
      );
    },
  );

  it.each([0, 101, -1, 1.5, NaN, Infinity])(
    "rejects invalid limit %s before transport",
    (limit) => {
      const { transport, client } = fixture();
      expect(() => client.list({ limit })).toThrow(/không hợp lệ/);
      expect(transport).not.toHaveBeenCalled();
    },
  );

  it("rejects invalid IDs, empty text/resolution and unsafe versions before transport", () => {
    const { transport, client } = fixture();
    const calls = [
      () => client.detail("../actions"),
      () => client.list({ after: "invalid-cursor" }),
      () => client.create({ ...createInput, title: " " }),
      () => client.create({ ...createInput, description: "a".repeat(4001) }),
      () => client.resolve(helpdeskId, { ...resolveInput, resolution: " " }),
      () => client.assign(helpdeskId, { ...assignInput, assigneeId: " " }),
      ...[-1, 0.5, NaN, Infinity, Number.MAX_SAFE_INTEGER + 1].flatMap(
        (version) => [
          () => client.triage(helpdeskId, { expectedVersion: version }),
          () => client.start(helpdeskId, { expectedVersion: version }),
          () => client.confirm(helpdeskId, { expectedVersion: version }),
          () =>
            client.resolve(helpdeskId, {
              ...resolveInput,
              expectedVersion: version,
            }),
          () =>
            client.assign(helpdeskId, {
              ...assignInput,
              expectedAssignmentVersion: version,
            }),
        ],
      ),
    ];
    for (const call of calls) expect(call).toThrow(/không hợp lệ/);
    expect(transport).not.toHaveBeenCalled();
  });
});

describe("APP-13 security/session/error boundaries", () => {
  it.each(
    routes.flatMap((route) =>
      (
        [
          [401, "UNAUTHENTICATED"],
          [403, "FORBIDDEN"],
          [404, "NOT_FOUND"],
          [409, "CONFLICT"],
        ] as const
      ).map(([status, code]) => ({ route, status, code })),
    ),
  )(
    "$route.name: HTTP $status takes precedence over an inconsistent error body, without retry",
    async ({ route, status, code }) => {
      const { service, transport, onSessionInvalid } = fixture(status, {
        code: "COMMIT_OUTCOME_UNKNOWN",
        message: "private identity/resource diagnostic",
      });
      const failure = await route
        .invoke(service)
        .catch((error: unknown) => error);
      expect(failure).toMatchObject({ code });
      expect((failure as Error).message).not.toContain("private");
      expect(transport).toHaveBeenCalledTimes(1);
      expect(onSessionInvalid).toHaveBeenCalledTimes(status === 401 ? 1 : 0);
    },
  );

  it.each([
    [401, "UNAUTHENTICATED"],
    [403, "FORBIDDEN"],
    [404, "NOT_FOUND"],
    [409, "CONFLICT"],
  ] as const)(
    "maps HTTP %s safely on read and write without raw diagnostics",
    async (status, code) => {
      for (const operation of ["read", "write"]) {
        const { client, transport, onSessionInvalid } = fixture(status, {
          message: "sensitive resource/identity",
          code: "diagnostic",
        });
        const failure = await (
          operation === "read"
            ? client.detail(helpdeskId)
            : client.assign(helpdeskId, assignInput)
        ).catch((error: unknown) => error);
        expect(failure).toMatchObject({ code });
        expect((failure as Error).message).not.toContain("sensitive");
        if (status === 404)
          expect((failure as Error).message).toMatch(
            /Không tìm thấy.*không khả dụng/,
          );
        if (status === 409)
          expect((failure as Error).message).toContain("Tải lại");
        expect(transport).toHaveBeenCalledTimes(1);
        expect(onSessionInvalid).toHaveBeenCalledTimes(status === 401 ? 1 : 0);
      }
    },
  );

  it.each([false, true])(
    "401 invalidates once and blocks all later protected operations even if callback throws=%s",
    async (throws) => {
      const { client, transport, service, onSessionInvalid } = fixture(401);
      if (throws)
        onSessionInvalid.mockImplementation(() => {
          throw new Error("UI callback failed");
        });
      await expect(client.detail(helpdeskId)).rejects.toMatchObject({
        code: "UNAUTHENTICATED",
      });
      transport.mockResolvedValue({ status: 200, body: helpdeskWire() });
      for (const route of routes)
        await expect(route.invoke(service)).rejects.toMatchObject({
          code: "UNAUTHENTICATED",
        });
      expect(transport).toHaveBeenCalledTimes(1);
      expect(onSessionInvalid).toHaveBeenCalledTimes(1);
    },
  );

  it.each(routes.filter((route) => route.method === "POST"))(
    "$name is never retried or reconciled automatically after network/unknown write",
    async (route) => {
      for (const mode of [
        "lost response",
        "unknown commit",
        "server failure",
        "timeout",
        "malformed success",
        "unexpected success",
      ]) {
        const { transport, service } = fixture();
        if (mode === "lost response")
          transport.mockRejectedValue(new Error("ACK lost after commit"));
        else
          transport.mockResolvedValue({
            status:
              mode === "unknown commit" || mode === "server failure"
                ? 503
                : mode === "timeout"
                  ? 408
                  : mode === "unexpected success"
                    ? 204
                    : route.status,
            body:
              mode === "unknown commit"
                ? { code: "COMMIT_OUTCOME_UNKNOWN" }
                : { malformed: true },
          });
        await expect(route.invoke(service)).rejects.toMatchObject({
          code: "COMMIT_OUTCOME_UNKNOWN",
        });
        expect(transport).toHaveBeenCalledTimes(1);
      }
    },
  );

  it("keeps network read failure distinct without retry", async () => {
    const { transport, client } = fixture();
    transport.mockRejectedValue(new Error("offline"));
    await expect(client.list()).rejects.toMatchObject({
      code: "NETWORK_FAILURE",
    });
    expect(transport).toHaveBeenCalledTimes(1);
  });

  it.each([
    { requestType: "FACILITY" },
    { version: "17" },
    { assignmentVersion: -1 },
    { version: Number.MAX_SAFE_INTEGER + 1 },
    { state: null },
    { eligibleAssignees: [{ id: "", displayName: null }] },
    { eligibleAssignees: [{ id: "worker", displayName: 123 }] },
    { requesterDisplayName: {} },
    { assigneeDisplayName: 42 },
  ])(
    "rejects malformed RequestView rather than inventing data: %j",
    async (override) => {
      const { client } = fixture(200, { ...helpdeskWire(), ...override });
      await expect(client.detail(helpdeskId)).rejects.toMatchObject({
        code: "INVALID_RESPONSE",
      });
    },
  );

  it.each([
    { items: [], nextCursor: "invalid-cursor" },
    { items: null, nextCursor: null },
    { items: [helpdeskWire({ version: -1 })], nextCursor: null },
    { items: [] },
    [],
    null,
  ])("rejects malformed list envelopes: %j", async (body) => {
    const { service, transport } = fixture(200, body);
    await expect(service.list()).rejects.toMatchObject({
      code: "INVALID_RESPONSE",
    });
    expect(transport).toHaveBeenCalledTimes(1);
  });

  it.each([
    { items: history },
    [{ ...history[0], occurredAt: null }],
    [{ ...history[0], version: "1" }],
    [{ ...history[0], targetState: null }],
    [{ sourceState: "SUBMITTED", targetState: "TRIAGED", version: 1 }],
    null,
  ])("rejects malformed history without inventing fields: %j", async (body) => {
    const { service, transport } = fixture(200, body);
    await expect(service.history(helpdeskId)).rejects.toMatchObject({
      code: "INVALID_RESPONSE",
    });
    expect(transport).toHaveBeenCalledTimes(1);
  });

  it.each([undefined, null, { status: 0 }, { status: 200.5 }, { status: 600 }])(
    "handles invalid transport responses: %j",
    async (response) => {
      const { transport, client } = fixture();
      transport.mockResolvedValue(
        response as Awaited<ReturnType<HelpdeskHttpTransport>>,
      );
      await expect(client.detail(helpdeskId)).rejects.toMatchObject({
        code: "INVALID_RESPONSE",
      });
      await expect(
        client.assign(helpdeskId, assignInput),
      ).rejects.toMatchObject({ code: "COMMIT_OUTCOME_UNKNOWN" });
      expect(transport).toHaveBeenCalledTimes(2);
    },
  );

  it("does not expose HTTP 400/500 diagnostics and does not retry", async () => {
    const { client, transport } = fixture(400, {
      code: "VALIDATION",
      message: "private details",
    });
    await expect(client.assign(helpdeskId, assignInput)).rejects.toMatchObject({
      code: "HTTP_FAILURE",
      status: 400,
    });
    transport.mockResolvedValue({
      status: 500,
      body: { message: "private details" },
    });
    const error = await client.list().catch((failure: unknown) => failure);
    expect(error).toMatchObject({ code: "HTTP_FAILURE", status: 500 });
    expect((error as Error).message).not.toContain("private details");
    expect(transport).toHaveBeenCalledTimes(2);
  });
});

import {
  errorFromHttpStatus,
  MvpApplicationError,
  networkFailure,
} from "../errors";
import {
  decodeHelpdeskHistory,
  decodeHelpdeskPage,
  decodeHelpdeskRequest,
  validateId,
  validateText,
  validateVersion,
} from "./codecs";
import { HelpdeskClientError } from "./errors";
import type { HelpdeskHttpRequest, HelpdeskHttpTransport } from "./transport";
import type {
  HelpdeskAssignInput,
  HelpdeskCreateInput,
  HelpdeskListInput,
  HelpdeskResolveInput,
  HelpdeskVersionInput,
} from "./types";

const BASE = "/api/v1/mvp/requests";

/**
 * PR #63 wire client, unbound to Portal, RequestService and MvpRequestPort.
 * Construction requires an explicit transport; the local BFF adapter is separate.
 * Nine explicit routes only; /start maps to start_work inside Backend, not here.
 */
export class HelpdeskApiClient {
  private sessionInvalid = false;

  constructor(
    private readonly transport: HelpdeskHttpTransport,
    private readonly onSessionInvalid: () => void,
  ) {
    if (
      typeof transport !== "function" ||
      typeof onSessionInvalid !== "function"
    ) {
      throw new HelpdeskClientError("INVALID_INPUT");
    }
  }

  create(input: HelpdeskCreateInput) {
    return this.post(
      BASE,
      {
        title: validateText(input.title, 200),
        description: validateText(input.description, 4000),
        requestType: "IT_HELPDESK",
      },
      201,
    );
  }

  list(input: HelpdeskListInput = {}) {
    const query = new URLSearchParams();
    if (input.after !== undefined) query.set("after", validateId(input.after));
    if (input.limit !== undefined) {
      if (
        !Number.isInteger(input.limit) ||
        input.limit < 1 ||
        input.limit > 100
      ) {
        throw new HelpdeskClientError("INVALID_INPUT");
      }
      query.set("limit", String(input.limit));
    }
    const suffix = query.size === 0 ? "" : `?${query}`;
    return this.get(BASE + suffix, decodeHelpdeskPage);
  }

  detail(id: string) {
    return this.get(this.path(id), decodeHelpdeskRequest);
  }

  triage(id: string, input: HelpdeskVersionInput) {
    return this.post(this.path(id, "/triage"), {
      expectedVersion: validateVersion(input.expectedVersion),
    });
  }

  assign(id: string, input: HelpdeskAssignInput) {
    return this.post(this.path(id, "/assign"), {
      assigneeId: validateText(input.assigneeId, 1024),
      expectedAssignmentVersion: validateVersion(
        input.expectedAssignmentVersion,
      ),
    });
  }

  start(id: string, input: HelpdeskVersionInput) {
    return this.post(this.path(id, "/start"), {
      expectedVersion: validateVersion(input.expectedVersion),
    });
  }

  resolve(id: string, input: HelpdeskResolveInput) {
    return this.post(this.path(id, "/resolve"), {
      expectedVersion: validateVersion(input.expectedVersion),
      resolution: validateText(input.resolution, 4000),
    });
  }

  confirm(id: string, input: HelpdeskVersionInput) {
    return this.post(this.path(id, "/confirm"), {
      expectedVersion: validateVersion(input.expectedVersion),
    });
  }

  history(id: string) {
    return this.get(this.path(id, "/history"), decodeHelpdeskHistory);
  }

  private path(id: string, suffix = "") {
    return `${BASE}/${encodeURIComponent(validateId(id))}${suffix}`;
  }

  private get<T>(path: string, decode: (body: unknown) => T): Promise<T> {
    return this.send(
      { method: "GET", path, headers: { Accept: "application/json" } },
      200,
      decode,
    );
  }

  private post(
    path: string,
    body: Readonly<Record<string, unknown>>,
    status = 200,
  ) {
    return this.send(
      {
        method: "POST",
        path,
        body,
        headers: {
          Accept: "application/json",
          "Content-Type": "application/json",
        },
      },
      status,
      decodeHelpdeskRequest,
    );
  }

  private async send<T>(
    request: HelpdeskHttpRequest,
    expectedStatus: number,
    decode: (body: unknown) => T,
  ): Promise<T> {
    // A 401 closes this client instance. A new approved session needs a new client;
    // no refresh/replay or token storage is introduced here.
    if (this.sessionInvalid) throw errorFromHttpStatus(401);
    const write = request.method === "POST";
    let response;
    try {
      response = await this.transport(request); // Exactly one attempt; never replay.
    } catch (cause) {
      throw networkFailure(write ? "write" : "read", cause);
    }
    if (
      !response ||
      !Number.isInteger(response.status) ||
      response.status < 100 ||
      response.status > 599
    ) {
      const cause = new HelpdeskClientError("INVALID_RESPONSE");
      throw write ? networkFailure("write", cause) : cause;
    }
    if (response.status !== expectedStatus) {
      if (response.status === 401) {
        if (!this.sessionInvalid) {
          this.sessionInvalid = true;
          try {
            this.onSessionInvalid();
          } catch {
            /* Keep the safe 401 boundary. */
          }
        }
        throw errorFromHttpStatus(401);
      }
      const body = response.body;
      const backendCode =
        body !== null &&
        typeof body === "object" &&
        "code" in body &&
        typeof body.code === "string"
          ? body.code
          : undefined;
      const status = response.status;
      if (status === 403 || status === 404 || status === 409) {
        throw errorFromHttpStatus(status);
      }
      if (backendCode === "COMMIT_OUTCOME_UNKNOWN") {
        throw new MvpApplicationError("COMMIT_OUTCOME_UNKNOWN");
      }
      if (
        write &&
        (status === 408 || status >= 500 || (status >= 200 && status < 400))
      ) {
        throw networkFailure(
          "write",
          new HelpdeskClientError("HTTP_FAILURE", status, backendCode),
        );
      }
      throw new HelpdeskClientError("HTTP_FAILURE", status, backendCode);
    }
    try {
      return decode(response.body);
    } catch (cause) {
      // A successful write with an unreadable reply may already be committed.
      throw write ? networkFailure("write", cause) : cause;
    }
  }
}

import { HelpdeskClientError } from "./errors";
import type {
  HelpdeskHistoryEntry,
  HelpdeskPage,
  HelpdeskRequest,
} from "./types";

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

export function validateId(id: string): string {
  if (typeof id !== "string" || !UUID.test(id)) {
    throw new HelpdeskClientError("INVALID_INPUT");
  }
  return id;
}

/** Java Long accepts a wider range; reject unsafe JS numbers, never round/coerce. */
export function validateVersion(version: number): number {
  if (!Number.isSafeInteger(version) || version < 0) {
    throw new HelpdeskClientError("INVALID_INPUT");
  }
  return version;
}

export function validateText(text: string, max: number): string {
  if (
    typeof text !== "string" ||
    text.trim().length === 0 ||
    text.length > max
  ) {
    throw new HelpdeskClientError("INVALID_INPUT");
  }
  return text;
}

function invalidResponse(): never {
  throw new HelpdeskClientError("INVALID_RESPONSE");
}

function object(value: unknown): Record<string, unknown> {
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    return invalidResponse();
  }
  return value as Record<string, unknown>;
}

function text(value: unknown): string {
  return typeof value === "string" ? value : invalidResponse();
}

function nullableText(value: unknown): string | null {
  return value === null ? null : text(value);
}

function id(value: unknown): string {
  const candidate = text(value);
  return UUID.test(candidate) ? candidate : invalidResponse();
}

function version(value: unknown): number {
  return typeof value === "number" && Number.isSafeInteger(value) && value >= 0
    ? value
    : invalidResponse();
}

function array(value: unknown): unknown[] {
  return Array.isArray(value) ? value : invalidResponse();
}

export function decodeHelpdeskRequest(body: unknown): HelpdeskRequest {
  const source = object(body);
  if (source.requestType !== "IT_HELPDESK") return invalidResponse();
  return {
    id: id(source.id),
    title: text(source.title),
    description: text(source.description),
    requestType: "IT_HELPDESK",
    requesterId: text(source.requesterId),
    assigneeId: nullableText(source.assigneeId),
    resolution: nullableText(source.resolution),
    assignmentVersion: version(source.assignmentVersion),
    workflowInstanceId: text(source.workflowInstanceId),
    state: text(source.state),
    version: version(source.version),
    allowedActions: array(source.allowedActions).map(text),
    ...(source.requesterDisplayName === undefined
      ? {}
      : { requesterDisplayName: nullableText(source.requesterDisplayName) }),
    ...(source.assigneeDisplayName === undefined
      ? {}
      : { assigneeDisplayName: nullableText(source.assigneeDisplayName) }),
    ...(source.eligibleAssignees === undefined
      ? {}
      : {
          eligibleAssignees:
            source.eligibleAssignees === null
              ? null
              : array(source.eligibleAssignees).map((value) => {
                  const option = object(value);
                  const assigneeId = text(option.id);
                  if (!assigneeId.trim()) return invalidResponse();
                  return {
                    id: assigneeId,
                    displayName: nullableText(option.displayName),
                  };
                }),
        }),
  };
}

export function decodeHelpdeskPage(body: unknown): HelpdeskPage {
  const source = object(body);
  return {
    items: array(source.items).map(decodeHelpdeskRequest),
    nextCursor: source.nextCursor === null ? null : id(source.nextCursor),
  };
}

export function decodeHelpdeskHistory(
  body: unknown,
): readonly HelpdeskHistoryEntry[] {
  return array(body).map((value) => {
    const source = object(value);
    const occurredAt = source.occurredAt;
    if (
      typeof occurredAt !== "string" &&
      !(typeof occurredAt === "number" && Number.isFinite(occurredAt))
    )
      return invalidResponse();
    return {
      transitionId: text(source.transitionId),
      sourceState: text(source.sourceState),
      targetState: text(source.targetState),
      version: version(source.version),
      occurredAt,
    };
  });
}

/** Local protocol errors, independent of the Backend ApiError wire envelope. */
export type HelpdeskClientErrorCode =
  | "INVALID_INPUT"
  | "INVALID_RESPONSE"
  | "HTTP_FAILURE";

const messages: Record<HelpdeskClientErrorCode, string> = {
  INVALID_INPUT: "Dữ liệu gửi tới Helpdesk API không hợp lệ.",
  INVALID_RESPONSE: "Helpdesk API trả dữ liệu không đúng contract đã review.",
  HTTP_FAILURE: "Helpdesk API chưa thể hoàn tất yêu cầu.",
};

export class HelpdeskClientError extends Error {
  constructor(
    readonly code: HelpdeskClientErrorCode,
    readonly status?: number,
    readonly backendCode?: string,
  ) {
    super(messages[code]);
    this.name = "HelpdeskClientError";
  }
}

import { afterEach, describe, expect, it, vi } from "vitest";
import { HttpApiClient } from "../../HttpApiClient";
import {
  MockRequestService,
  requestService as mockService,
} from "../../MockRequestService";
import { requestService as portalService } from "../../portalService";
import { helpdeskId } from "../../../test/helpdeskFixtures";

afterEach(() => vi.restoreAllMocks());

describe("APP-13 LIVE_BLOCKED regression", () => {
  it("keeps MOCK as composition-root default and blocks all nine Helpdesk routes without network", async () => {
    const fetchSpy = vi.spyOn(globalThis, "fetch");
    const xhrSpy = vi.spyOn(XMLHttpRequest.prototype, "send");
    const client = new HttpApiClient();
    const base = "/api/v1/mvp/requests";
    const routes = [
      ["POST", base],
      ["GET", base],
      ["GET", `${base}/${helpdeskId}`],
      ...["triage", "assign", "start", "resolve", "confirm"].map((action) => [
        "POST",
        `${base}/${helpdeskId}/${action}`,
      ]),
      ["GET", `${base}/${helpdeskId}/history`],
    ] as const;
    expect(routes).toHaveLength(9);
    expect(portalService).toBe(mockService);
    expect(portalService).toBeInstanceOf(MockRequestService);
    expect(client.mode).toBe("BLOCKED");
    for (const [method, path] of routes) {
      await expect(
        client.request(method as "GET" | "POST", path),
      ).rejects.toMatchObject({ code: "LIVE_BLOCKED" });
    }
    expect(fetchSpy).not.toHaveBeenCalled();
    expect(xhrSpy).not.toHaveBeenCalled();
  });
});

import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { helpdeskId, helpdeskWire } from "../../../test/helpdeskFixtures";
import { HelpdeskApiClient } from "./HelpdeskApiClient";
import {
  bootstrapHelpdeskSession,
  sameOriginHelpdeskTransport,
} from "./sameOriginTransport";

const base = "/api/v1/mvp/requests";
beforeEach(() => vi.stubGlobal("location", new URL("https://localhost:8443")));
afterEach(() => vi.unstubAllGlobals());

describe("local same-origin BFF boundary", () => {
  it("bootstraps only session state and keeps CSRF in memory", async () => {
    const fetcher = vi
      .fn<typeof fetch>()
      .mockResolvedValue(
        Response.json({ authenticated: true, csrfToken: "csrf-test" }),
      );
    expect(await bootstrapHelpdeskSession(fetcher)).toEqual({
      csrfToken: "csrf-test",
    });
    expect(fetcher).toHaveBeenCalledExactlyOnceWith(
      "/bff/session",
      expect.objectContaining({
        credentials: "same-origin",
        mode: "same-origin",
        redirect: "error",
        cache: "no-store",
      }),
    );
    expect(sessionStorage.length).toBe(0);
    expect(localStorage.length).toBe(0);
  });

  it.each([false, true])(
    "rejects unusable session state (malformed=%s)",
    async (malformed) => {
      const fetcher = vi
        .fn<typeof fetch>()
        .mockResolvedValue(Response.json({ authenticated: malformed }));
      if (malformed)
        await expect(bootstrapHelpdeskSession(fetcher)).rejects.toThrow();
      else expect(await bootstrapHelpdeskSession(fetcher)).toBeNull();
    },
  );

  it.each(["http://localhost:8443", "https://portal.example.test"])(
    "blocks non-local or insecure origins: %s",
    async (origin) => {
      vi.stubGlobal("location", new URL(origin));
      const fetcher = vi.fn<typeof fetch>();
      await expect(bootstrapHelpdeskSession(fetcher)).rejects.toThrow();
      expect(() => sameOriginHelpdeskTransport("csrf", fetcher)).toThrow();
      expect(fetcher).not.toHaveBeenCalled();
    },
  );

  it("maps exactly the nine routes with CSRF only on POST and no auth headers", async () => {
    const fetcher = vi
      .fn<typeof fetch>()
      .mockImplementation(async () => Response.json({}));
    const transport = sameOriginHelpdeskTransport("csrf-test", fetcher);
    const routes = [
      ["GET", `${base}?limit=20&after=${helpdeskId}`],
      ["POST", base],
      ["GET", `${base}/${helpdeskId}`],
      ["GET", `${base}/${helpdeskId}/history`],
      ...["triage", "assign", "start", "resolve", "confirm"].map((a) => [
        "POST",
        `${base}/${helpdeskId}/${a}`,
      ]),
    ];
    for (const [method, path] of routes) {
      await transport({
        method: method as "GET" | "POST",
        path,
        headers: { Accept: "application/json" },
        body: {},
      });
      const [url, init] = fetcher.mock.calls.at(-1)!;
      expect(url).toBe(`/bff${path}`);
      expect(init).toMatchObject({
        credentials: "same-origin",
        mode: "same-origin",
        redirect: "error",
        cache: "no-store",
      });
      const headers = new Headers(init?.headers);
      expect(headers.has("Authorization")).toBe(false);
      expect(headers.has("X-Role")).toBe(false);
      expect(headers.get("X-CSRF-TOKEN")).toBe(
        method === "POST" ? "csrf-test" : null,
      );
    }
    expect(fetcher).toHaveBeenCalledTimes(9);
  });

  it.each([
    ["GET", "https://evil.test/api/v1/mvp/requests"],
    ["GET", "//evil.test/api/v1/mvp/requests"],
    ["GET", `${base}/../requests`],
    ["POST", `${base}/${helpdeskId}/delete`],
    ["GET", `${base}/${helpdeskId}/triage`],
    ["POST", `${base}/${helpdeskId}/history`],
    ["GET", `${base}?target=evil`],
    ["POST", `${base}?limit=1`],
    ["GET", `${base}?limit=1&limit=2`],
    ["GET", `${base}#fragment`],
  ])("rejects unapproved route %s %s before fetch", async (method, path) => {
    const fetcher = vi.fn<typeof fetch>();
    await expect(
      sameOriginHelpdeskTransport(
        "csrf",
        fetcher,
      )({
        method: method as "GET" | "POST",
        path,
        headers: { Accept: "application/json" },
      }),
    ).rejects.toThrow();
    expect(fetcher).not.toHaveBeenCalled();
  });

  it.each([
    [403, "FORBIDDEN"],
    [404, "NOT_FOUND"],
    [409, "CONFLICT"],
  ])("preserves %s without retry", async (status, code) => {
    const fetcher = vi
      .fn<typeof fetch>()
      .mockResolvedValue(new Response("", { status: Number(status) }));
    const client = new HelpdeskApiClient(
      sameOriginHelpdeskTransport("csrf", fetcher),
      vi.fn(),
    );
    await expect(
      client.triage(helpdeskId, { expectedVersion: 0 }),
    ).rejects.toMatchObject({ code });
    expect(fetcher).toHaveBeenCalledTimes(1);
  });

  it("invalidates a 401 session and does not replay further operations", async () => {
    const fetcher = vi
      .fn<typeof fetch>()
      .mockResolvedValue(new Response("", { status: 401 }));
    const invalid = vi.fn();
    const client = new HelpdeskApiClient(
      sameOriginHelpdeskTransport("csrf", fetcher),
      invalid,
    );
    await expect(client.list()).rejects.toMatchObject({
      code: "UNAUTHENTICATED",
    });
    await expect(
      client.create({ title: "test", description: "test" }),
    ).rejects.toMatchObject({ code: "UNAUTHENTICATED" });
    expect(invalid).toHaveBeenCalledTimes(1);
    expect(fetcher).toHaveBeenCalledTimes(1);
  });

  it.each(["lost", "unknown", "malformed"])(
    "reports uncertain write (%s) without retry",
    async (failure) => {
      const fetcher = vi.fn<typeof fetch>();
      if (failure === "lost")
        fetcher.mockRejectedValue(new TypeError("connection lost"));
      else
        fetcher.mockResolvedValue(
          failure === "unknown"
            ? Response.json({ code: "COMMIT_OUTCOME_UNKNOWN" }, { status: 503 })
            : new Response("not-json", { status: 201 }),
        );
      const client = new HelpdeskApiClient(
        sameOriginHelpdeskTransport("csrf", fetcher),
        vi.fn(),
      );
      await expect(
        client.create({ title: "test", description: "test" }),
      ).rejects.toMatchObject({ code: "COMMIT_OUTCOME_UNKNOWN" });
      expect(fetcher).toHaveBeenCalledTimes(1);
    },
  );

  it("handles read network failure and valid committed responses", async () => {
    const fetcher = vi
      .fn<typeof fetch>()
      .mockRejectedValueOnce(new TypeError("offline"))
      .mockResolvedValueOnce(Response.json(helpdeskWire(), { status: 201 }));
    const client = new HelpdeskApiClient(
      sameOriginHelpdeskTransport("csrf", fetcher),
      vi.fn(),
    );
    await expect(client.list()).rejects.toMatchObject({
      code: "NETWORK_FAILURE",
    });
    expect(
      (await client.create({ title: "test", description: "test" })).id,
    ).toBe(helpdeskId);
    expect(fetcher).toHaveBeenCalledTimes(2);
  });
});

import type { HelpdeskHttpTransport } from "./transport";

const BASE = "/api/v1/mvp/requests";
const UUID = "[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}";
const READ = new RegExp(`^${BASE}/${UUID}(?:/history)?$`, "i");
const WRITE = new RegExp(
  `^${BASE}/${UUID}/(?:triage|assign|start|resolve|confirm)$`,
  "i",
);

function requireLocalHttps() {
  if (
    location.protocol !== "https:" ||
    !["localhost", "127.0.0.1", "[::1]"].includes(location.hostname)
  )
    throw new Error(
      "Helpdesk integration requires a trusted local HTTPS origin.",
    );
}

/** CSRF stays in memory; OAuth credentials remain at the BFF. */
export async function bootstrapHelpdeskSession(fetcher: typeof fetch = fetch) {
  requireLocalHttps();
  const response = await fetcher("/bff/session", {
    method: "GET",
    credentials: "same-origin",
    mode: "same-origin",
    redirect: "error",
    cache: "no-store",
    headers: { Accept: "application/json" },
  });
  if (response.status === 401) return null;
  if (!response.ok) throw new Error("Unable to load BFF session.");
  const body: unknown = await response.json();
  if (body && typeof body === "object" && "authenticated" in body) {
    if (body.authenticated === false) return null;
    if (
      body.authenticated === true &&
      "csrfToken" in body &&
      typeof body.csrfToken === "string" &&
      body.csrfToken.trim()
    ) {
      return { csrfToken: body.csrfToken };
    }
  }
  throw new Error("Invalid BFF session response.");
}

export function sameOriginHelpdeskTransport(
  csrfToken: string,
  fetcher: typeof fetch = fetch,
): HelpdeskHttpTransport {
  requireLocalHttps();
  if (!csrfToken.trim()) throw new Error("BFF CSRF token is required.");
  return async (request) => {
    requireLocalHttps();
    const url = new URL(request.path, location.origin);
    const list = url.pathname === BASE;
    const allowed =
      request.method === "GET"
        ? list || READ.test(url.pathname)
        : request.method === "POST" && (list || WRITE.test(url.pathname));
    if (
      !allowed ||
      url.origin !== location.origin ||
      url.pathname + url.search !== request.path ||
      url.hash ||
      (url.search && (request.method !== "GET" || !list)) ||
      [...url.searchParams.keys()].some(
        (key) =>
          !["after", "limit"].includes(key) ||
          url.searchParams.getAll(key).length !== 1,
      )
    ) {
      throw new Error("Unapproved Helpdesk route.");
    }
    const response = await fetcher(`/bff${request.path}`, {
      method: request.method,
      credentials: "same-origin",
      mode: "same-origin",
      redirect: "error",
      cache: "no-store",
      headers: {
        Accept: "application/json",
        ...(request.method === "POST"
          ? {
              "Content-Type": "application/json",
              "X-CSRF-TOKEN": csrfToken,
            }
          : {}),
      },
      ...(request.method === "POST"
        ? { body: JSON.stringify(request.body) }
        : {}),
    });
    const text = await response.text();
    let body: unknown;
    try {
      body = JSON.parse(text);
    } catch {
      /* Preserve HTTP errors with empty/non-JSON bodies. */
    }
    return { status: response.status, body };
  };
}

/** The concrete transport handles JSON and the BFF session boundary. */
export interface HelpdeskHttpRequest {
  readonly method: "GET" | "POST";
  /** Relative path only, scoped to the reviewed Helpdesk namespace. */
  readonly path: string;
  readonly headers: Readonly<{
    Accept: "application/json";
    "Content-Type"?: "application/json";
  }>;
  readonly body?: Readonly<Record<string, unknown>>;
}

export interface HelpdeskHttpResponse {
  readonly status: number;
  readonly body?: unknown;
}

/**
 * Injected boundary; the client selects no host, credentials or integration mode.
 * Resolve ALL HTTP responses, including non-2xx; reject only if no usable response
 * was obtained. One invocation must mean one attempt, with no automatic retry,
 * redirect replay, token-refresh replay or write reconciliation.
 */
export type HelpdeskHttpTransport = (
  request: HelpdeskHttpRequest,
) => Promise<HelpdeskHttpResponse>;

/** Wire records from PR #63, exact review SHA below. Not Portal/MOCK models. */
export const HELPDESK_CONTRACT_HEAD =
  "e12d105c89400a5fd69dd6cc1fca670ff1f04f51" as const;

export interface HelpdeskCreateInput {
  readonly title: string;
  readonly description: string;
}

export interface HelpdeskVersionInput {
  readonly expectedVersion: number;
}

export interface HelpdeskAssignInput {
  readonly assigneeId: string;
  readonly expectedAssignmentVersion: number;
}

export interface HelpdeskResolveInput extends HelpdeskVersionInput {
  readonly resolution: string;
}

export interface HelpdeskListInput {
  readonly after?: string;
  readonly limit?: number;
}

export interface HelpdeskAssigneeOption {
  readonly id: string;
  readonly displayName: string | null;
}

/** HelpdeskService.RequestView; preserve missing, null and empty detail fields. */
export interface HelpdeskRequest {
  readonly id: string;
  readonly title: string;
  readonly description: string;
  readonly requestType: "IT_HELPDESK";
  readonly requesterId: string;
  readonly assigneeId: string | null;
  readonly resolution: string | null;
  readonly assignmentVersion: number;
  readonly workflowInstanceId: string;
  readonly state: string;
  readonly version: number;
  /** Backend HTTP capability names, including assign/start; never inferred. */
  readonly allowedActions: readonly string[];
  readonly requesterDisplayName?: string | null;
  readonly assigneeDisplayName?: string | null;
  readonly eligibleAssignees?: readonly HelpdeskAssigneeOption[] | null;
}

export interface HelpdeskPage {
  readonly items: readonly HelpdeskRequest[];
  readonly nextCursor: string | null;
}

/** No synthetic id, actor, note or title is added to the authorized projection. */
export interface HelpdeskHistoryEntry {
  readonly transitionId: string;
  readonly sourceState: string;
  readonly targetState: string;
  readonly version: number;
  /** Java Instant: preserve Jackson ISO text/numeric output without Date coercion. */
  readonly occurredAt: string | number;
}

import type {
  AssignmentCommand,
  AuthorizedHistory,
  CreateRequestInput,
  EligibleAssignees,
  RequestId,
  RequestList,
  RequestSnapshot,
  WorkflowActionCommand,
} from "./types";

/**
 * CANDIDATE Application boundary, deliberately unbound to Portal and HTTP.
 * Implementations return authoritative, authorized projections. Names here do
 * not register endpoints, HTTP methods, JSON fields or JWT authorities.
 *
 * Pagination/filtering, assignment authorization, wire validation, write
 * preconditions and reconciliation remain pending Backend/security approval.
 * No operation may automatically retry a write, including after authentication.
 */
export interface MvpRequestPort {
  create(input: CreateRequestInput): Promise<RequestSnapshot>;
  list(): Promise<RequestList>;
  detail(id: RequestId): Promise<RequestSnapshot>;
  workflowAction(command: WorkflowActionCommand): Promise<RequestSnapshot>;
  assignment(command: AssignmentCommand): Promise<RequestSnapshot>;
  eligibleAssignees(id: RequestId): Promise<EligibleAssignees>;
  history(id: RequestId): Promise<AuthorizedHistory>;
}

import { afterEach, describe, expect, expectTypeOf, it, vi } from "vitest";
import type { ServiceRequest } from "../../domain/request";
import type { MvpRequestPort } from "./port";
import {
  mapMvpEligibleAssignees,
  mapMvpListPresentation,
  mapMvpRequestPresentation,
  type MvpPortalRequestPresentation,
} from "./presentation";
import { projectAuthorizedHistory } from "./projections";
import type {
  Assignee,
  AuthorizedHistory,
  EligibleAssignees,
  RequestSnapshot,
  WorkflowActionName,
} from "./types";

function snapshot(): RequestSnapshot {
  return {
    id: "mapping-request",
    details: {
      kind: "it",
      title: "Phần mềm nội bộ không lưu được báo cáo",
      description:
        "Dữ liệu normalized dành riêng cho unit test mapping Application.",
      priority: "high",
      location: "Văn phòng tầng 3",
    },
    workflow: {
      state: "RESOLVED",
      version: { scope: "workflow", value: { opaque: "workflow-revision" } },
    },
    businessVersion: { scope: "business", value: "business-revision" },
    allowedActions: [
      { name: "confirm", reference: { opaque: "action-reference" } },
    ],
    currentAssignee: {
      id: { scope: "assignee", value: { opaque: "assignee-reference" } },
      displayName: "Người xử lý được phép hiển thị",
    },
  };
}

afterEach(() => vi.restoreAllMocks());

describe("APP-10 normalized MVP presentation mapping", () => {
  it("maps only the shared display fields without adding server-owned identity", () => {
    const source = snapshot();
    const view = mapMvpRequestPresentation(source);
    expect(view).toMatchObject({ id: source.id, ...source.details });
    for (const key of [
      "requester",
      "department",
      "createdAt",
      "updatedAt",
      "actor",
      "role",
    ]) {
      expect(view).not.toHaveProperty(key);
    }
    expectTypeOf<MvpPortalRequestPresentation>().not.toExtend<ServiceRequest>();
  });

  it("retains requester, department and timestamps only when actually supplied", () => {
    const source = snapshot();
    const details = {
      ...source.details,
      requester: "Tên người gửi từ projection được phép xem",
      department: "Phòng vận hành",
      createdAt: "2026-10-25T01:00:00Z",
      updatedAt: "2026-10-25T02:00:00Z",
    };
    const view = mapMvpRequestPresentation({ ...source, details });
    expect(view).toMatchObject(details);
    expect(view.createdAt).toBe(details.createdAt);
    expect(view.updatedAt).toBe(details.updatedAt);
  });

  it.each(["RESOLVED", "CONFIRMED", "resolved", "UNRECOGNIZED_BACKEND_STATE"])(
    "preserves state %s without inventing a MOCK status or terminal classification",
    (state) => {
      const source = snapshot();
      const view = mapMvpRequestPresentation({
        ...source,
        workflow: { ...source.workflow, state },
      });
      expect(view.state).toBe(state);
      expect(view).not.toHaveProperty("status");
      expect(view).not.toHaveProperty("isTerminal");
      expect(view).not.toHaveProperty("closed");
    },
  );

  it("preserves separate authoritative Workflow/business tokens, including opaque values", () => {
    const source = snapshot();
    const view = mapMvpRequestPresentation(source);
    expect(view.workflowVersion).toBe(source.workflow.version);
    expect(view.workflowVersion.value).toBe(source.workflow.version.value);
    expect(view.businessVersion).toBe(source.businessVersion);
    expect(view).not.toHaveProperty("version");
  });

  it("does not manufacture a business version when only Workflow version is supplied", () => {
    const { businessVersion: _omitted, ...source } = snapshot();
    expect(mapMvpRequestPresentation(source)).not.toHaveProperty(
      "businessVersion",
    );
  });

  it.each<WorkflowActionName>(["triage", "start_work", "resolve", "confirm"])(
    "preserves supplied action %s and its reference without creating a legacy alias",
    (name) => {
      const source = snapshot();
      const reference = { opaque: `test-only-${name}` };
      const view = mapMvpRequestPresentation({
        ...source,
        allowedActions: [{ name, reference }],
      });
      expect(view.allowedActions).toEqual([{ name, reference }]);
      expect(view.allowedActions[0].reference).toBe(reference);
      expect(view.allowedActions[0]).not.toHaveProperty("id");
      expect(view.allowedActions[0]).not.toHaveProperty("label");
    },
  );

  it("does not derive capabilities from role/state or add assignment as a Workflow action", () => {
    const source = { ...snapshot(), role: "processor", allowedActions: [] };
    const view = mapMvpRequestPresentation(source);
    expect(view.allowedActions).toEqual([]);
    expect(view).not.toHaveProperty("role");
    expect(view).not.toHaveProperty("canAssign");
    expect(view).not.toHaveProperty("actions");
  });

  it("keeps assignee reference separate from display name", () => {
    const source = snapshot();
    const view = mapMvpRequestPresentation(source);
    expect(view.currentAssignee?.id).toBe(source.currentAssignee?.id);
    expect(view.currentAssignee?.displayName).toBe(
      source.currentAssignee?.displayName,
    );
    expect(view.assigneeDisplayName).toBe(source.currentAssignee?.displayName);
    expect(view.currentAssignee).not.toBe(source.currentAssignee);
    expect(view.currentAssignee?.id.value).not.toBe(view.assigneeDisplayName);
    expect(view).not.toHaveProperty("assignee");
  });

  it("preserves null assignment without synthesizing a group or display placeholder", () => {
    const view = mapMvpRequestPresentation({
      ...snapshot(),
      currentAssignee: null,
    });
    expect(view.currentAssignee).toBeNull();
    expect(view).not.toHaveProperty("assigneeDisplayName");
    expect(view).not.toHaveProperty("eligibleAssignees");
  });

  it("does not turn absent history into an empty, complete timeline", () => {
    const view = mapMvpRequestPresentation(snapshot());
    expect(view).not.toHaveProperty("history");
    expect(view).not.toHaveProperty("timeline");
  });

  it("preserves authorized redaction, event order and history completeness", () => {
    const history: AuthorizedHistory = {
      completeness: "partial",
      events: [
        { id: "visible-2", at: "2026-10-25T02:00:00Z", title: "Kết quả xử lý" },
        {
          id: "visible-1",
          at: "2026-10-25T01:00:00Z",
          title: "Tiếp nhận",
          actor: "Tên đã được phép xem",
        },
        {
          id: "visible-note",
          at: "2026-10-25T00:00:00Z",
          title: "Ghi chú",
          note: "Nội dung đã lọc quyền",
        },
      ],
    };
    const view = mapMvpRequestPresentation({ ...snapshot(), history });
    expect(view.history).toEqual(history);
    expect(view.history).not.toBe(history);
    expect(view.history?.events[0]).not.toHaveProperty("actor");
    expect(view.history?.events[0]).not.toHaveProperty("note");
    expect(view.history?.events[1]).not.toHaveProperty("note");
    expect(view.history?.events[2]).not.toHaveProperty("actor");
  });

  it.each(["complete", "partial", "unknown"] as const)(
    "preserves empty %s list/history/eligibility without inventing totals or authority",
    (completeness) => {
      expect(mapMvpListPresentation({ items: [], completeness })).toEqual({
        items: [],
        completeness,
      });
      const view = mapMvpRequestPresentation(
        { ...snapshot(), history: { events: [], completeness } },
        { eligibleAssignees: { items: [], completeness } },
      );
      expect(view.history).toEqual({ events: [], completeness });
      expect(view.eligibleAssignees).toEqual({ items: [], completeness });
      expect(view).not.toHaveProperty("canAssign");
      expect(view).not.toHaveProperty("total");
    },
  );

  it("uses explicitly provided authorized-detail eligibility without treating it as assignment permission", () => {
    const assignee: Assignee = {
      id: { scope: "assignee", value: "test-id" },
      displayName: "Người xử lý hợp lệ",
    };
    const eligible: EligibleAssignees = {
      items: [assignee],
      completeness: "partial",
    };
    const view = mapMvpRequestPresentation(snapshot(), {
      eligibleAssignees: eligible,
    });
    expect(view.eligibleAssignees).toEqual(eligible);
    expect(view.eligibleAssignees?.items[0].id).toBe(assignee.id);
    expect(view.eligibleAssignees?.items).not.toBe(eligible.items);
    expect(mapMvpEligibleAssignees(eligible)).toEqual(eligible);
    expect(view).not.toHaveProperty("canAssign");
    expect(view.allowedActions.map((action) => action.name)).toEqual([
      "confirm",
    ]);
  });

  it("copies list items without mutating snapshots or claiming a complete collection", () => {
    const source = snapshot();
    const before = structuredClone(source);
    const view = mapMvpListPresentation({
      items: [source],
      completeness: "partial",
    });
    expect(view.items[0]).toEqual(mapMvpRequestPresentation(source));
    expect(view.items[0].allowedActions).not.toBe(source.allowedActions);
    expect(view.completeness).toBe("partial");
    expect(view).not.toHaveProperty("total");
    expect(source).toEqual(before);
  });
});

describe("APP-10 fake MvpRequestPort read projections", () => {
  it("maps fake detail/list/history without HTTP, automatic enrichment fetches or writes", async () => {
    const fetchSpy = vi.spyOn(globalThis, "fetch").mockImplementation(() => {
      throw new Error("Unexpected LIVE fetch");
    });
    const xhrSpy = vi
      .spyOn(XMLHttpRequest.prototype, "send")
      .mockImplementation(() => {
        throw new Error("Unexpected LIVE XMLHttpRequest");
      });
    const detail = snapshot();
    const history: AuthorizedHistory = {
      events: [
        {
          id: "visible",
          at: "2026-10-25T01:00:00Z",
          title: "Sự kiện được phép xem",
        },
      ],
      completeness: "unknown",
    };
    const eligible: EligibleAssignees = { items: [], completeness: "unknown" };
    const port = {
      create: vi.fn<MvpRequestPort["create"]>(),
      list: vi
        .fn<MvpRequestPort["list"]>()
        .mockResolvedValue({ items: [detail], completeness: "unknown" }),
      detail: vi.fn<MvpRequestPort["detail"]>().mockResolvedValue(detail),
      workflowAction: vi.fn<MvpRequestPort["workflowAction"]>(),
      assignment: vi.fn<MvpRequestPort["assignment"]>(),
      eligibleAssignees: vi.fn<MvpRequestPort["eligibleAssignees"]>(),
      history: vi.fn<MvpRequestPort["history"]>().mockResolvedValue(history),
    } satisfies MvpRequestPort;
    const view = mapMvpRequestPresentation(await port.detail(detail.id));
    expect(view.state).toBe(detail.workflow.state);
    expect(view).not.toHaveProperty("history");
    expect(view).not.toHaveProperty("eligibleAssignees");
    // Explicit normalized authorized-detail enrichment, not a guessed wire field.
    const enriched = mapMvpRequestPresentation(detail, {
      eligibleAssignees: eligible,
    });
    expect(enriched.eligibleAssignees).toEqual(eligible);
    const list = mapMvpListPresentation(await port.list());
    expect(list.items[0]).toEqual(view);
    expect(list.completeness).toBe("unknown");
    const projectedHistory = projectAuthorizedHistory(
      await port.history(detail.id),
    );
    expect(projectedHistory.events[0]).not.toHaveProperty("actor");
    expect(projectedHistory.events[0]).not.toHaveProperty("note");
    expect(port.detail).toHaveBeenCalledTimes(1);
    expect(port.list).toHaveBeenCalledTimes(1);
    expect(port.history).toHaveBeenCalledTimes(1);
    expect(port.eligibleAssignees).not.toHaveBeenCalled();
    expect(port.create).not.toHaveBeenCalled();
    expect(port.workflowAction).not.toHaveBeenCalled();
    expect(port.assignment).not.toHaveBeenCalled();
    expect(fetchSpy).not.toHaveBeenCalled();
    expect(xhrSpy).not.toHaveBeenCalled();
  });
});

import type { ServiceRequest } from "../../domain/request";
import { projectAuthorizedHistory } from "./projections";
import type {
  Assignee,
  AuthorizedHistory,
  BusinessVersion,
  EligibleAssignees,
  ProjectionCompleteness,
  RequestList,
  RequestSnapshot,
  ServerAllowedAction,
  WorkflowVersion,
} from "./types";

type SharedDisplayFields = Pick<
  ServiceRequest,
  "id" | "title" | "description" | "kind" | "priority" | "location"
>;
type OptionalDisplayFields = Partial<
  Pick<ServiceRequest, "requester" | "department" | "createdAt" | "updatedAt">
>;

/**
 * CANDIDATE internal presentation projection of already-normalized data.
 * Shared display fields align with Portal; this is deliberately NOT a
 * ServiceRequest, wire DTO, state mapper, validator or RequestService adapter.
 * No Backend state -> MOCK status or opaque version -> number conversion exists.
 */
export type MvpPortalRequestPresentation = Readonly<
  SharedDisplayFields &
    OptionalDisplayFields & {
      state: string;
      workflowVersion: WorkflowVersion;
      businessVersion?: BusinessVersion;
      allowedActions: readonly ServerAllowedAction[];
      currentAssignee: Assignee | null;
      assigneeDisplayName?: string;
      history?: AuthorizedHistory;
      eligibleAssignees?: EligibleAssignees;
    }
>;

export interface MvpPortalListPresentation {
  readonly items: readonly MvpPortalRequestPresentation[];
  readonly completeness: ProjectionCompleteness;
}

/**
 * Explicit normalized enrichment from an authorized detail projection, NOT an
 * assumed JSON field/envelope. RequestSnapshot currently has no eligibility
 * member. Its approved DTO/port mapping remains pending. Missing enrichment
 * never triggers another request or implies assignment permission.
 */
export interface AuthorizedDetailPresentationData {
  readonly eligibleAssignees?: EligibleAssignees;
}

function copyAssignee(assignee: Assignee): Assignee {
  return {
    id: assignee.id,
    ...(assignee.displayName === undefined
      ? {}
      : { displayName: assignee.displayName }),
  };
}

/** Preserve opaque assignee IDs and completeness; eligibility is not authority. */
export function mapMvpEligibleAssignees(
  eligible: EligibleAssignees,
): EligibleAssignees {
  return {
    items: eligible.items.map(copyAssignee),
    completeness: eligible.completeness,
  };
}

/**
 * Pure read projection. No role/state permission rules, placeholders, identity
 * invention, action aliases, write payloads or automatic history/eligibility
 * fetches. Opaque versions/references retain their original identity and value.
 */
export function mapMvpRequestPresentation(
  snapshot: RequestSnapshot,
  detailData: AuthorizedDetailPresentationData = {},
): MvpPortalRequestPresentation {
  const details = snapshot.details;
  return {
    id: snapshot.id,
    title: details.title,
    description: details.description,
    kind: details.kind,
    priority: details.priority,
    location: details.location,
    ...(details.requester === undefined
      ? {}
      : { requester: details.requester }),
    ...(details.department === undefined
      ? {}
      : { department: details.department }),
    ...(details.createdAt === undefined
      ? {}
      : { createdAt: details.createdAt }),
    ...(details.updatedAt === undefined
      ? {}
      : { updatedAt: details.updatedAt }),
    state: snapshot.workflow.state,
    workflowVersion: snapshot.workflow.version,
    ...(snapshot.businessVersion === undefined
      ? {}
      : { businessVersion: snapshot.businessVersion }),
    allowedActions: snapshot.allowedActions.map((action) => ({
      name: action.name,
      reference: action.reference,
    })),
    currentAssignee:
      snapshot.currentAssignee === null
        ? null
        : copyAssignee(snapshot.currentAssignee),
    ...(snapshot.currentAssignee?.displayName == null
      ? {}
      : { assigneeDisplayName: snapshot.currentAssignee.displayName }),
    ...(snapshot.history === undefined
      ? {}
      : { history: projectAuthorizedHistory(snapshot.history) }),
    ...(detailData.eligibleAssignees === undefined
      ? {}
      : {
          eligibleAssignees: mapMvpEligibleAssignees(
            detailData.eligibleAssignees,
          ),
        }),
  };
}

/** Never treats a partial/unknown list as the complete Portal collection. */
export function mapMvpListPresentation(
  list: RequestList,
): MvpPortalListPresentation {
  return {
    items: list.items.map((snapshot) => mapMvpRequestPresentation(snapshot)),
    completeness: list.completeness,
  };
}

import type { AuthorizedHistory } from "./types";

/**
 * Copy an already-authorized normalized history. This does not authorize raw
 * audit events, decode wire DTOs, sort events or infer missing actor/note data.
 * Completeness is preserved; absence of an event is not a recovery guarantee.
 */
export function projectAuthorizedHistory(
  history: AuthorizedHistory,
): AuthorizedHistory {
  return {
    completeness: history.completeness,
    events: history.events.map((event) => ({
      id: event.id,
      at: event.at,
      title: event.title,
      ...(event.actor === undefined ? {} : { actor: event.actor }),
      ...(event.note === undefined ? {} : { note: event.note }),
    })),
  };
}

/**
 * CANDIDATE normalized Application models, not JSON DTOs or an HTTP contract.
 * No transport or authority is defined here. A future approved adapter must
 * validate wire data before supplying these models; TypeScript is not validation.
 */
export type RequestId = string;
export type RequestKind = "it" | "facility";
export type RequestPriority = "normal" | "high" | "urgent";

/** Business action meanings accepted for IT MVP v0.1, not transition IDs. */
export type WorkflowActionName =
  "triage" | "start_work" | "resolve" | "confirm";

/** Opaque values: no assumptions about numeric counters, ETags or equality. */
export interface WorkflowVersion {
  readonly scope: "workflow";
  readonly value: unknown;
}

export interface BusinessVersion {
  readonly scope: "business";
  readonly value: unknown;
}

export interface WorkflowSnapshot {
  /** Preserve authoritative state, including CONFIRMED; no local state machine. */
  readonly state: string;
  readonly version: WorkflowVersion;
}

/** Reference supplied by an approved mapping; never manufactured from a label. */
export interface AssigneeId {
  readonly scope: "assignee";
  readonly value: unknown;
}

export interface Assignee {
  readonly id: AssigneeId;
  /** A missing/hidden name must never be manufactured from an ID or persona. */
  readonly displayName?: string | null;
}

export interface ServerAllowedAction {
  readonly name: WorkflowActionName;
  /** Opaque backend evidence; not necessarily a transition ID or a wire field. */
  readonly reference: unknown;
}

export interface CreateRequestInput {
  readonly kind: RequestKind;
  readonly title: string;
  readonly description: string;
  readonly priority: RequestPriority;
  readonly location: string;
}

export interface RequestDetails extends CreateRequestInput {
  readonly requester?: string;
  readonly department?: string;
  readonly createdAt?: string;
  readonly updatedAt?: string;
}

/** Missing actor/note stays missing after authorization filtering. */
export interface AuthorizedHistoryEvent {
  readonly id: string;
  readonly at: string;
  readonly title: string;
  readonly actor?: string;
  readonly note?: string;
}

/** Internal completeness marker, not a pagination or recovery protocol. */
export type ProjectionCompleteness = "complete" | "partial" | "unknown";

export interface AuthorizedHistory {
  readonly events: readonly AuthorizedHistoryEvent[];
  readonly completeness: ProjectionCompleteness;
}

export interface RequestSnapshot {
  readonly id: RequestId;
  readonly details: RequestDetails;
  readonly workflow: WorkflowSnapshot;
  readonly businessVersion?: BusinessVersion;
  /** Supplied projection only; never inferred from persona, role or state. */
  readonly allowedActions: readonly ServerAllowedAction[];
  readonly currentAssignee: Assignee | null;
  /** Absent means not supplied, not an empty or fully visible history. */
  readonly history?: AuthorizedHistory;
}

export interface RequestList {
  readonly items: readonly RequestSnapshot[];
  readonly completeness: ProjectionCompleteness;
}

/** Eligibility is not evidence that the caller is authorized to assign. */
export interface EligibleAssignees {
  readonly items: readonly Assignee[];
  readonly completeness: ProjectionCompleteness;
}

/**
 * Evidence observed on a snapshot, not a prescribed concurrency protocol.
 * Backend must confirm which version each command needs and how it is sent.
 */
export interface ObservedVersions {
  readonly workflow: WorkflowVersion;
  readonly business?: BusinessVersion;
}

export interface WorkflowActionCommand {
  readonly kind: "workflow-action";
  readonly requestId: RequestId;
  readonly action: ServerAllowedAction;
  readonly observedVersions: ObservedVersions;
  /** Required fields/guards remain unconfirmed; no generic note rule assumed. */
  readonly input: unknown;
}

export interface AssignmentCommand {
  readonly kind: "assignment";
  readonly requestId: RequestId;
  readonly assigneeId: AssigneeId;
  readonly observedVersions: ObservedVersions;
  readonly input: unknown;
}

import { requestService as mockService } from "./MockRequestService";
import type { RequestService } from "./RequestService";

// The composition root binds an interface to mock mode. No env flag can enable LIVE.
export const requestService: RequestService = mockService;
export const demoControls = {
  setFault: mockService.setFault.bind(mockService),
  reset: mockService.reset.bind(mockService),
};

import { afterEach, describe, expect, it, vi } from "vitest";
import { MockRequestService } from "./MockRequestService";
import { HttpApiClient } from "./HttpApiClient";
import type { ActionId, CreateRequestInput } from "../domain/request";

const input: CreateRequestInput = {
  kind: "it",
  title: "Kiểm tra thiết bị mới",
  description: "Thiết bị mới cần được kiểm tra và cài đặt phần mềm.",
  priority: "normal",
  location: "Phòng kỹ thuật",
};
afterEach(() => vi.restoreAllMocks());
describe("closed HTTP boundary", () => {
  it("never calls fetch, including unregistered Workflow routes and mutations", async () => {
    const fetchSpy = vi.spyOn(globalThis, "fetch");
    const client = new HttpApiClient();
    for (const method of ["GET", "POST", "PUT", "PATCH", "DELETE"] as const) {
      await expect(
        client.request(method, "/api/v1/workflow-instances", {}),
      ).rejects.toMatchObject({ code: "LIVE_BLOCKED" });
    }
    expect(fetchSpy).not.toHaveBeenCalled();
  });
});
describe("mock application responses", () => {
  it.each(["it", "facility"] as const)(
    "supports the shared create/approve/process/history UI contract for %s",
    async (kind) => {
      const service = new MockRequestService(0);
      const fetchSpy = vi.spyOn(globalThis, "fetch");
      const created = await service.create({ ...input, kind }, "employee");
      expect(created.status).toBe("pending");
      expect(service.actions(created, "employee")).toEqual([]);
      const approved = await service.transition(
        created.id,
        "approve",
        "Đồng ý triển khai",
        0,
        "processor",
      );
      const processing = await service.transition(
        created.id,
        "start",
        "Đã tiếp nhận xử lý",
        approved.version,
        "processor",
      );
      const completed = await service.transition(
        created.id,
        "complete",
        "Đã kiểm tra hoàn tất",
        processing.version,
        "processor",
      );
      expect(completed.timeline).toHaveLength(4);
      expect(completed.status).toBe(kind === "it" ? "resolved" : "completed");
      expect(service.actions(completed, "processor")).toEqual([]);
      await expect(
        service.transition(
          created.id,
          "start",
          "Không được mở lại",
          completed.version,
          "processor",
        ),
      ).rejects.toMatchObject({ code: "403" });
      if (kind === "it") {
        expect(service.actions(completed, "employee")).toEqual([
          { id: "confirm", label: "Xác nhận hoàn thành" },
        ]);
        const confirmed = await service.transition(
          completed.id,
          "confirm",
          "Đã kiểm tra kết quả",
          completed.version,
          "employee",
        );
        expect(confirmed.status).toBe("confirmed");
        expect(confirmed.version).toBe(completed.version + 1);
        expect(confirmed.timeline).toHaveLength(5);
        expect(confirmed.timeline.slice(-2)).toMatchObject([
          {
            title: "IT đã xử lý và thông báo kết quả",
            actor: "Trần Bình",
            note: "Đã kiểm tra hoàn tất",
          },
          {
            title: "Người gửi đã xác nhận hoàn thành",
            actor: "Mai An",
            note: "Đã kiểm tra kết quả",
          },
        ]);
        for (const role of ["employee", "processor"] as const) {
          expect(service.actions(confirmed, role)).toEqual([]);
          for (const action of ["confirm", "complete", "close"] as ActionId[]) {
            await expect(
              service.transition(
                confirmed.id,
                action,
                "Không thêm thao tác đóng",
                confirmed.version,
                role,
              ),
            ).rejects.toMatchObject({ code: "403" });
          }
        }
        expect(await service.get(confirmed.id, "employee")).toEqual(confirmed);
      } else {
        expect(service.actions(completed, "employee")).toEqual([]);
        await expect(
          service.transition(
            completed.id,
            "confirm",
            "Không thêm nghiệm thu",
            completed.version,
            "employee",
          ),
        ).rejects.toMatchObject({ code: "403" });
        expect(await service.get(completed.id, "employee")).toEqual(completed);
      }
      expect(fetchSpy).not.toHaveBeenCalled();
    },
  );
  it("scopes mock fixtures and gives identical hidden/missing responses", async () => {
    const service = new MockRequestService(0);
    expect(
      (await service.list("employee")).every((r) => r.requester === "Mai An"),
    ).toBe(true);
    const hidden = await service.get("DX-1047", "employee").catch((e) => e);
    const missing = await service.get("NOT-FOUND", "employee").catch((e) => e);
    expect(hidden.message).toBe(missing.message);
    expect(hidden.code).toBe("404");
    expect((await service.get("DX-1047", "processor")).id).toBe("DX-1047");
  });
  it("prevents stale writes and disallowed actor actions in fixtures", async () => {
    const service = new MockRequestService(0);
    await expect(
      service.transition(
        "DX-1048",
        "approve",
        "Đồng ý yêu cầu",
        99,
        "processor",
      ),
    ).rejects.toMatchObject({ code: "CONFLICT" });
    await expect(
      service.transition("DX-1048", "approve", "Đồng ý yêu cầu", 0, "employee"),
    ).rejects.toMatchObject({ code: "403" });
  });
  it("does not mutate after validation failure", async () => {
    const service = new MockRequestService(0);
    const before = await service.list("processor");
    await expect(
      service.create({ ...input, title: "" }, "employee"),
    ).rejects.toMatchObject({ code: "VALIDATION" });
    expect(await service.list("processor")).toEqual(before);
  });
  it.each(["network", "401", "403", "404"] as const)(
    "exposes %s once, without a read retry",
    async (fault) => {
      const service = new MockRequestService(0);
      service.setFault(fault);
      await expect(service.list("employee")).rejects.toBeInstanceOf(Error);
      expect((await service.list("employee")).length).toBeGreaterThan(0);
    },
  );
  it("never retries uncertain create or transition writes", async () => {
    const service = new MockRequestService(0);
    const create = vi.spyOn(service, "create");
    const transition = vi.spyOn(service, "transition");
    service.setFault("unknown");
    await expect(service.create(input, "employee")).rejects.toMatchObject({
      code: "COMMIT_OUTCOME_UNKNOWN",
    });
    expect(create).toHaveBeenCalledTimes(1);
    service.setFault("unknown");
    await expect(
      service.transition(
        "DX-1048",
        "approve",
        "Đồng ý triển khai",
        0,
        "processor",
      ),
    ).rejects.toMatchObject({ code: "COMMIT_OUTCOME_UNKNOWN" });
    expect(transition).toHaveBeenCalledTimes(1);
    expect((await service.get("DX-1048", "processor")).status).toBe("pending");
  });
  it("returns isolated copies and resets fixtures", async () => {
    const service = new MockRequestService(0);
    const rows = await service.list("employee");
    rows[0].title = "changed";
    expect((await service.get(rows[0].id, "employee")).title).not.toBe(
      "changed",
    );
    await service.create(input, "employee");
    service.reset();
    expect(await service.list("processor")).toHaveLength(10);
  });
});

describe("APP-08 IT confirmation MOCK guards", () => {
  it("permits only the original employee requester, checking stored data again on write", async () => {
    const service = new MockRequestService(0);
    const own = await service.get("DX-1042", "employee");
    const other = await service.get("DX-1044", "processor");
    expect(own.requester).toBe("Mai An");
    expect(other.requester).toBe("Đức Minh");
    expect(service.actions(other, "employee")).toEqual([]);
    for (const item of [own, other]) {
      expect(service.actions(item, "processor")).toEqual([]);
      await expect(
        service.transition(
          item.id,
          "confirm",
          "Xác nhận thay người gửi",
          item.version,
          "processor",
        ),
      ).rejects.toMatchObject({ code: "403" });
      expect(await service.get(item.id, "processor")).toEqual(item);
    }
    // A caller-mutated snapshot cannot grant access to the stored request.
    expect(
      service.actions({ ...other, requester: "Mai An" }, "employee"),
    ).toEqual([{ id: "confirm", label: "Xác nhận hoàn thành" }]);
    const hidden = await service
      .transition(
        other.id,
        "confirm",
        "Không sở hữu yêu cầu",
        other.version,
        "employee",
      )
      .catch((error: unknown) => error);
    const missing = await service
      .transition(
        "NOT-FOUND",
        "confirm",
        "Không tồn tại yêu cầu",
        other.version,
        "employee",
      )
      .catch((error: unknown) => error);
    expect(hidden).toMatchObject({ code: "404" });
    expect(missing).toMatchObject({
      code: "404",
      message: (hidden as Error).message,
    });
    expect(await service.get(other.id, "processor")).toEqual(other);
  });

  it("does not let a processor confirm even a request that processor created", async () => {
    const service = new MockRequestService(0);
    const created = await service.create(input, "processor");
    const approved = await service.transition(
      created.id,
      "approve",
      "Đã kiểm tra phiếu",
      created.version,
      "processor",
    );
    const processing = await service.transition(
      created.id,
      "start",
      "Đã tiếp nhận việc",
      approved.version,
      "processor",
    );
    const resolved = await service.transition(
      created.id,
      "complete",
      "Đã xử lý sự cố",
      processing.version,
      "processor",
    );
    expect(resolved.status).toBe("resolved");
    expect(service.actions(resolved, "processor")).toEqual([]);
    expect(service.actions(resolved, "employee")).toEqual([]);
    await expect(
      service.transition(
        resolved.id,
        "confirm",
        "Tự xác nhận kết quả",
        resolved.version,
        "processor",
      ),
    ).rejects.toMatchObject({ code: "403" });
    await expect(
      service.transition(
        resolved.id,
        "confirm",
        "Không sở hữu phiếu",
        resolved.version,
        "employee",
      ),
    ).rejects.toMatchObject({ code: "404" });
    expect(await service.get(resolved.id, "processor")).toEqual(resolved);
  });

  it.each([
    "pending",
    "approved",
    "processing",
    "completed",
    "confirmed",
    "rejected",
  ] as const)(
    "does not offer requester confirmation for IT status %s",
    async (status) => {
      const service = new MockRequestService(0);
      const own = await service.get("DX-1042", "employee");
      expect(service.actions({ ...own, status }, "employee")).toEqual([]);
    },
  );

  it("rejects premature confirmation against the actual stored status without mutation", async () => {
    const service = new MockRequestService(0);
    const before = await service.get("DX-1046", "employee");
    await expect(
      service.transition(
        before.id,
        "confirm",
        "Chưa hoàn tất xử lý",
        before.version,
        "employee",
      ),
    ).rejects.toMatchObject({ code: "403" });
    expect(await service.get(before.id, "employee")).toEqual(before);
  });

  it("preserves version, note validation and single mutation under concurrent confirmation", async () => {
    const service = new MockRequestService(0);
    const before = await service.get("DX-1042", "employee");
    await expect(
      service.transition(
        before.id,
        "confirm",
        "Đã kiểm tra kết quả",
        before.version - 1,
        "employee",
      ),
    ).rejects.toMatchObject({ code: "CONFLICT" });
    for (const note of ["", "1234", "a".repeat(1001)]) {
      await expect(
        service.transition(
          before.id,
          "confirm",
          note,
          before.version,
          "employee",
        ),
      ).rejects.toMatchObject({ code: "VALIDATION" });
      expect(await service.get(before.id, "employee")).toEqual(before);
    }
    const outcomes = await Promise.allSettled([
      service.transition(
        before.id,
        "confirm",
        "Đã kiểm tra kết quả",
        before.version,
        "employee",
      ),
      service.transition(
        before.id,
        "confirm",
        "Đã kiểm tra kết quả",
        before.version,
        "employee",
      ),
    ]);
    expect(
      outcomes.filter((outcome) => outcome.status === "fulfilled"),
    ).toHaveLength(1);
    expect(
      outcomes.find((outcome) => outcome.status === "rejected"),
    ).toMatchObject({ status: "rejected", reason: { code: "CONFLICT" } });
    const after = await service.get(before.id, "employee");
    expect(after.status).toBe("confirmed");
    expect(after.version).toBe(before.version + 1);
    expect(after.timeline).toHaveLength(before.timeline.length + 1);
    expect(after.timeline.at(-1)?.actor).toBe(before.requester);
  });

  it("never retries or mutates after an uncertain confirmation", async () => {
    const service = new MockRequestService(0);
    const before = await service.get("DX-1042", "employee");
    const transition = vi.spyOn(service, "transition");
    service.setFault("unknown");
    await expect(
      service.transition(
        before.id,
        "confirm",
        "Đã kiểm tra kết quả",
        before.version,
        "employee",
      ),
    ).rejects.toMatchObject({ code: "COMMIT_OUTCOME_UNKNOWN" });
    expect(transition).toHaveBeenCalledTimes(1);
    expect(await service.get(before.id, "employee")).toEqual(before);
  });
});

