  letter-spacing: 0.3px;
  border-radius: 5px;
  padding: 5px 8px;
  display: flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
}
.environment > span {
  height: 5px;
  width: 5px;
  border-radius: 50%;
  background: #b7811c;
}
.icon-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: none;
  border: 0;
  width: 32px;
  height: 32px;
  border-radius: 6px;
  color: #5c687d;
}
.icon-button:hover {
  background: #edf1f7;
  color: var(--indigo);
}
.menu-button {
  display: none;
}
main {
  flex: 1;
  padding: 34px 35px 32px;
  max-width: 1600px;
  width: 100%;
  margin: auto;
}
.page-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 27px;
}
.page-heading p.muted {
  font-size: 13px;
  margin-top: 8px;
}
.eyebrow {
  font-size: 12px;
  color: #5c6880;
  margin-bottom: 8px;
}
.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: 1px solid transparent;
  border-radius: 7px;
  padding: 10px 15px;
  min-height: 39px;
  font-size: 12px;
  font-weight: 500;
  white-space: nowrap;
  transition:
    background 0.15s,
    box-shadow 0.15s;
}
.primary {
  background: var(--indigo);
  color: white;
  border-color: var(--indigo);
  box-shadow: 0 2px 3px #222d650d;
}
.primary:hover:not(:disabled) {
  background: #3c48a1;
  box-shadow: 0 3px 9px #404d9b24;
}
.secondary {
  background: white;
  border-color: #dce2ec;
  color: #4d5870;
}
.secondary:hover:not(:disabled) {
  background: #f2f5fa;
}
.danger {
  background: #fff2f1;
  color: #ad3535;
  border-color: #f2d1cc;
}
.danger:hover:not(:disabled) {
  background: #ffe7e4;
}
.small {
  font-size: 12px;
  padding: 6px 11px;
  min-height: 30px;
}
.full-width {
  width: 100%;
}
.muted {
  color: var(--muted);
}
.text-link {
  font-size: 12px;
  font-weight: 500;
  color: var(--indigo);
  display: inline-flex;
  align-items: center;
  gap: 7px;
  background: transparent;
  border: none;
  padding: 0;
}
.text-link:hover {
  text-decoration: underline;
}
.overview-layout {
  display: grid;
  grid-template-columns: minmax(0, 1.85fr) minmax(265px, 1fr);
  gap: 20px;
  margin-bottom: 23px;
}
.welcome-panel {
  border: 1px solid #dce4ef;
  background: #eff3f9;
  min-height: 250px;
  border-radius: 12px;
  position: relative;
  overflow: hidden;
  display: flex;
  justify-content: space-between;
}
.welcome-copy {
  padding: 26px 28px;
  z-index: 2;
}
.welcome-label {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: 11px;
  color: #586982;
}
.welcome-label > span {
  height: 5px;
  width: 5px;
  background: #468c88;
  border-radius: 50%;
}
.welcome-copy h2 {
  font-size: 26px;
  letter-spacing: -1px;
  line-height: 1.4;
  font-weight: 600;
  margin: 13px 0 9px;
  color: #233557;
}
.welcome-copy p {
  font-size: 12px;
  line-height: 1.9;
  color: #586881;
}
.welcome-link {
  display: inline-flex;
  gap: 11px;
  align-items: center;
  font-size: 12px;
  font-weight: 500;
  margin-top: 17px;
  color: #354b7a;
}
.portal-illustration {
  position: relative;
  min-width: 210px;
  align-self: stretch;
  width: 43%;
  background: radial-gradient(ellipse at center, #dbe9f1, transparent 70%);
}
.orbit {
  position: absolute;
  border: 1px solid #d3deea;
  left: 50%;
  top: 47%;
  transform: translate(-50%, -50%) rotate(-25deg);
  border-radius: 50%;
  width: 210px;
  height: 135px;
}
.orbit-two {
  width: 235px;
  height: 180px;
  transform: translate(-50%, -50%) rotate(38deg);
  border-style: dashed;
  border-color: #cddbe5;
}
.illustration-core {
  position: absolute;
  top: 47%;
  left: 50%;
  transform: translate(-50%, -50%) rotate(-8deg);
  width: 91px;
  height: 100px;
  background: linear-gradient(145deg, #fff, #e6edf8);
  border: 1px solid #fff;
  border-radius: 20px;
  box-shadow: 8px 12px 20px #344b7b16;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 3px;
  color: #4d65a3;
}
.illustration-core span {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.5px;
}
.floating-node {
  display: grid;
  place-items: center;
  position: absolute;
  width: 44px;
  height: 44px;
  background: #fff;
  border: 1px solid #e1e8f0;
  border-radius: 12px;
  box-shadow: 0 5px 10px #42547b0c;
}
.node-it {
  top: 32px;
  left: 15px;
  color: #5463a9;
  transform: rotate(-9deg);
}
.node-facility {
  right: 19px;
  top: 63px;
  color: #1f7370;
  transform: rotate(8deg);
}
.node-check {
  bottom: 45px;
  left: 20px;
  color: #26726d;
  transform: rotate(6deg);
}
.illustration-caption {
  position: absolute;
  bottom: 18px;
  width: 100%;
  text-align: center;
  color: #59687e;
  font-size: 10px;
}
.quick-services {
  background: #fff;
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 19px 20px 10px;
}
.section-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}
.section-title > span {
  font-size: 11px;
  color: #5f6879;
}
.service-link {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 19px 0;
  border-bottom: 1px solid #edf0f5;
}
.service-link > span:nth-child(2) {
  min-width: 0;
  flex: 1;
}
.service-link strong {
  font-size: 13px;
  display: block;
}
.service-link small {
  font-size: 11px;
  display: block;
  color: #5d687c;
  margin-top: 3px;
}
.service-link > svg {
  color: #5e687c;
}
.service-icon {
  height: 43px;
  width: 43px;
  border-radius: 11px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.indigo {
  background: #eef0fc;
  color: #5863a7;
}
.teal {
  background: #e8f5f1;
  color: #167463;
}
.quick-note {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  font-size: 11px;
  padding-top: 12px;
  color: #5d687b;
}
.metrics {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  background: white;
  border: 1px solid var(--border);
  border-radius: 10px;
  margin-bottom: 25px;
  padding: 20px 0;
}
.metric {
  position: relative;
  overflow: hidden;
  padding: 0 23px;
  border-right: 1px solid var(--border);
}
.metric:last-child {
  border: 0;
}
.metric > div:first-child {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  color: #5b6880;
  font-size: 12px;
}
.metric > div:first-child > svg {
  color: #5c687c;
}
.metric > strong {
  display: block;
  font-size: 30px;
  font-weight: 500;
  letter-spacing: -1px;
  margin: 7px 0 4px;
  line-height: 1.4;
}
.metric > strong > small {
  font-size: 11px;
  font-weight: 400;
  color: #5d6879;
  letter-spacing: 0;
  margin-left: 9px;
}
.metric > p {
  font-size: 10px;
  display: flex;
  align-items: center;
  gap: 5px;
  position: relative;
  z-index: 1;
}
.metric-dot {
  height: 5px;
  width: 5px;
  border-radius: 50%;
}
.amber {
  background: #c49a43;
}
.indigo-dot {
  background: #7c85c4;
}
.metric-success {
  color: #1c7462;
}
.mini-bars {
  position: absolute;
  right: 23px;
  bottom: 23px;
  display: flex;
  height: 30px;
  gap: 3px;
  align-items: flex-end;
  opacity: 0.55;
}
.mini-bars i {
  width: 4px;
  background: #aebcdd;
  border-radius: 2px;
}
.panel {
  background: white;
  border: 1px solid var(--border);
  border-radius: 10px;
  overflow: hidden;
}
.panel-heading {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 20px 23px;
  gap: 15px;
}
.panel-heading h2 {
  font-size: 15px;
  display: flex;
  align-items: center;
  gap: 9px;
}
.panel-heading p {
  font-size: 12px;
  margin-top: 4px;
}
.count-badge {
  font-size: 11px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 22px;
  height: 19px;
  background: #eff2f7;
  color: #5c6881;
  border-radius: 5px;
  padding: 0 6px;
  font-weight: 400;
}
.table-scroll {
  position: relative;
  overflow-x: auto;
}
table {
  border-collapse: collapse;
  width: 100%;
  text-align: left;
  white-space: nowrap;
}
th {
  font-weight: 400;
  font-size: 11px;
  color: #5c687d;
  background: #f9fafc;
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  padding: 10px 18px;
}
th:first-child,
td:first-child {
  padding-left: 23px;
}
td {
  padding: 13px 18px;
  border-bottom: 1px solid #eef1f6;
  font-size: 12px;
}
tr:last-child td {
  border: 0;
}
tbody tr:hover {
  background: #fafbfe;
}
.request-title {
  display: block;
  max-width: 410px;
  white-space: normal;
}
.request-title strong {
  font-size: 12px;
  font-weight: 500;
  display: block;
  margin-top: 3px;
  min-width: 210px;
}
.request-title:hover strong {
  color: var(--indigo);
}
.request-id {
  font-size: 10px;
  color: #566984;
}
.request-id > span {
  color: #5d687a;
}
.badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 10px;
  line-height: 1.7;
  border: 1px solid transparent;
  padding: 3px 7px;
  border-radius: 5px;
  white-space: nowrap;
}
.status-pending {
  color: #8b5f13;
  background: #fff8e9;
  border-color: #f4e8c9;
}
.status-approved {
  color: #4e698e;
  background: #eff5fb;
  border-color: #dce8f3;
}
.status-processing {
  color: #5a60b0;
  background: #f0f0fd;
  border-color: #e3e3f7;
}
.status-completed {
  color: #177463;
  background: #eaf7f2;
  border-color: #d9efe6;
}
.status-rejected {
  color: #ab4750;
  background: #fff0f0;
  border-color: #f5dedf;
}
.priority {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  color: #5d687e;
}
.priority > span {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #8e9bb1;
}
.priority-high > span {
  background: #d2a04b;
}
.priority-urgent > span {
  background: #d26868;
}
.date-cell {
  color: #5b687c;
  font-size: 11px;
}
.tiny {
  width: 24px;
  height: 24px;
  font-size: 11px;
}
.person {
  display: flex;
  align-items: center;
  gap: 7px;
  white-space: nowrap;
}
.dashboard-bottom {
  display: grid;
  grid-template-columns: minmax(0, 1.85fr) minmax(265px, 1fr);
  gap: 20px;
  margin-top: 23px;
}
.activity-panel .panel-heading {
  padding-bottom: 10px;
}
.timeline {
  list-style: none;
  margin: 0;
  padding: 18px 25px;
}
.timeline li {
  display: grid;
  grid-template-columns: 22px 1fr;
  gap: 12px;
  position: relative;
  padding-bottom: 24px;
}
.timeline li:last-child {
  padding-bottom: 0;
}
.timeline li:before {
  content: "";
  position: absolute;
  left: 10px;
  top: 23px;
  bottom: 0;
  width: 1px;
  background: #e7edf3;
}
.timeline li:last-child:before {
  display: none;
}
.timeline-dot {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: #f0f3f8;
  color: #5a687e;
  display: grid;
  place-items: center;
  position: relative;
}
.timeline-dot.latest {
  background: #e6f4ee;
  color: #22745d;
}
.timeline-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  flex-wrap: wrap;
  line-height: 1.6;
}
.timeline-title strong {
  font-size: 12px;
  font-weight: 500;
}
.timeline-title time {
  font-size: 10px;
  color: #5e6879;
}
.timeline p {
  font-size: 11px;
  margin: 5px 0;
  line-height: 1.8;
}
.timeline-actor {
  font-size: 10px;
  color: #5d687a;
}
.platform-note {
  border: 1px solid #e0eae7;
  border-radius: 10px;
  background: #f0f6f3;
  padding: 24px;
}
.platform-note h2 {
  font-size: 19px;
  line-height: 1.5;
  letter-spacing: -0.5px;
  margin-top: 13px;
  color: #35574f;
}
.platform-note p {
  font-size: 12px;
  line-height: 1.9;
  margin: 11px 0 16px;
  color: #546d65;
  max-width: 280px;
}
.platform-note .text-link {
  color: #2e7363;
}
.mock-footnote {
  font-size: 10px;
  display: block;
  color: #5c6878;
  margin-top: 17px;
  line-height: 1.9;
}
.footer {
  padding: 13px 35px 20px;
  font-size: 10px;
  color: #5e6879;
  display: flex;
  gap: 20px;
  justify-content: space-between;
}
.footer-separator {
  padding: 0 8px;
  color: #616873;
}
.filters {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 18px 22px;
  flex-wrap: wrap;
}
.search-field {
  display: flex;
  align-items: center;
  gap: 9px;
  flex: 1;
  min-width: 210px;
  border: 1px solid #e0e5ef;
  background: white;
  border-radius: 6px;
  padding: 8px 11px;
  color: #5d687a;
}
.search-field input {
  border: none;
  background: transparent;
  width: 100%;
  font-size: 12px;
  min-width: 0;
}
.filter-select {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 0 9px;
  color: #5c687a;
  border: 1px solid #e0e5ef;
  border-radius: 6px;
  background: white;
}
.filter-select select {
  border: 0;
  background: transparent;
  padding: 9px 0;
  font-size: 12px;
  color: #5a687e;
  max-width: 150px;
}
.list-tabs {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  padding: 0 23px;
  border-bottom: 1px solid var(--border);
  min-height: 57px;
}
.selected-tab {
  display: flex;
  align-items: center;
  gap: 10px;
  align-self: stretch;
  border-bottom: 2px solid var(--indigo);
  font-size: 13px;
  color: var(--indigo);
}
.list-tabs > .muted {
  font-size: 11px;
  display: flex;
  gap: 7px;
  align-items: center;
}
.pagination {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 15px;
  padding: 17px 23px;
  border-top: 1px solid var(--border);
  color: #5b687c;
  font-size: 11px;
}
.pagination > div {
  display: flex;
  gap: 12px;
  align-items: center;
}
.empty,
.loading-state {
  text-align: center;
  padding: 65px 25px;
  display: flex;
  align-items: center;
  flex-direction: column;
  gap: 10px;
}
.empty-icon {
  display: grid;
  place-items: center;
  width: 62px;
  height: 62px;
  background: #f1f4fa;
  border-radius: 20px;
  color: #56688a;
  margin-bottom: 8px;
}
.empty p {
  font-size: 13px;
  max-width: 390px;
}
.empty .button {
  margin-top: 12px;
}
.error-state {
  display: flex;
  gap: 12px;
  align-items: flex-start;
  background: #fff6f4;
  border: 1px solid #f2ddd7;
  border-radius: 8px;
  padding: 17px;
  color: #a24f3d;
  margin: 16px 22px;
}
.error-state strong {
  font-size: 13px;
}
.error-state p {
  font-size: 12px;
  margin: 5px 0 12px;
  color: #93584d;
}
.error-link {
  margin-left: 12px;
  color: #93584d;
}
.loading-state {
  color: #596884;
  font-size: 13px;
}
.spinner {
  animation: spin 1s linear infinite;
}
.skeleton {
  height: 12px;
  max-width: 420px;
  width: 80%;
  background: #e9eef6;
  border-radius: 4px;
}
.skeleton.short {
  max-width: 280px;
  opacity: 0.6;
}
.back-link {
  font-size: 12px;
  color: #5c687d;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 18px;
}
.form-layout,
.detail-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 286px;
  gap: 25px;
}
.request-form {
  padding: 27px;
}
.request-form fieldset {
  padding: 0;
  border: 0;
  margin: 0 0 30px;
  min-width: 0;
}
.request-form legend {
  font-size: 15px;
  font-weight: 600;
  margin-bottom: 19px;
  display: flex;
  align-items: center;
  gap: 9px;
}
.step-number {
  display: inline-grid;
  place-items: center;
  width: 23px;
  height: 23px;
  border-radius: 6px;
  background: #f0f2fa;
  color: #57659a;
  font-size: 12px;
}
.service-options {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 13px;
}
.service-option {
  border: 1px solid #e0e6ef;
  border-radius: 9px;
  padding: 17px;
  display: flex;
  align-items: flex-start;
  flex-direction: column;
  position: relative;
  cursor: pointer;
  color: #586788;
}
.service-option.selected {
  border-color: #7d89c2;
  background: #f7f8ff;
  box-shadow: 0 0 0 1px #7d89c2;
}
.service-option input {
  position: absolute;
  right: 13px;
  top: 13px;
  accent-color: var(--indigo);
}
.service-option strong {
  font-size: 13px;
  color: #36456a;
  margin: 9px 0 3px;
}
.service-option small {
  font-size: 11px;
  color: #5c687e;
}
.field {
  display: block;
  font-size: 13px;
  font-weight: 500;
  margin: 0 0 19px;
  color: #4e5c74;
}
.required {
  color: #a44e44;
}
.field input,
.field textarea,
.field select {
  display: block;
  width: 100%;
  margin-top: 8px;
  padding: 10px 12px;
  background: #fff;
  border: 1px solid #dfe5ef;
  border-radius: 6px;
  font-size: 12px;
  color: #34415a;
  min-width: 0;
}
.field textarea {
  resize: vertical;
  line-height: 1.9;
}
.field input::placeholder,
.field textarea::placeholder {
  color: #5e6879;
}
.field [aria-invalid="true"] {
  border-color: #c56a60;
}
.field-hint {
  display: flex;
  justify-content: space-between;
  font-size: 10px;
  color: #5d687a;
  font-weight: 400;
  margin-top: 7px;
  gap: 8px;
  line-height: 1.9;
}
.field-error {
  display: block;
  font-size: 12px;
  color: #ad4641;
  margin-top: 6px;
}
.field-grid {
  display: grid;
  grid-template-columns: 1.3fr 1fr;
  gap: 16px;
}
.attachment-block {
  display: flex;
  align-items: center;
  gap: 13px;
  background: #f9fafc;
  border: 1px dashed #dce3ec;
  border-radius: 8px;
  padding: 19px 16px;
  color: #5c687a;
}
.attachment-block > div {
  flex: 1;
}
.attachment-block strong {
  font-size: 12px;
  color: #5a6880;
  font-weight: 500;
}
.attachment-block p {
  font-size: 11px;
  margin-top: 5px;
  color: #5c6879;
}
.blocked-tag {
  font-size: 9px;
  padding: 3px 6px;
  border: 1px solid #e7dfd0;
  border-radius: 4px;
  background: #fbf7ee;
  color: #7e6421;
  display: inline-flex;
  white-space: nowrap;
  letter-spacing: 0.2px;
  vertical-align: middle;
  margin-left: 5px;
}
.form-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  justify-content: flex-end;
  padding-top: 25px;
  margin-top: 24px;
  border-top: 1px solid var(--border);
}
.form-actions > span {
  margin-right: auto;
  font-size: 10px;
  color: #5a687e;
  display: flex;
  align-items: center;
  gap: 6px;
}
.info-card {
  padding: 25px;
  background: #eef3f9;
  border: 1px solid #e1e7f1;
  border-radius: 10px;
  color: #51698c;
}
.info-card h3 {
  font-size: 17px;
  line-height: 1.7;
  color: #405779;
  margin: 15px 0 12px;
  font-weight: 500;
}
.info-card p {
  font-size: 12px;
  line-height: 1.9;
  color: #576882;
}
.info-card ol {
  padding-left: 19px;
  font-size: 12px;
  line-height: 3;
  color: #53698a;
  margin: 19px 0 0;
}
.aside-footnote {
  font-size: 11px;
  line-height: 1.9;
  color: #5b687a;
  margin: 16px 7px;
  display: flex;
  align-items: flex-start;
  gap: 6px;
}
.history-list {
  padding: 0 23px;
}
.history-list article {
  border-top: 1px solid var(--border);
  padding: 20px 0;
}
.history-list .timeline {
  padding: 20px 0 0;
}
.detail-content {
  margin-bottom: 22px;
}
.request-description {
  padding: 0 23px 25px;
  font-size: 14px;
  line-height: 2;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.detail-content .attachment-block {
  margin: 0 23px 23px;
}
.detail-timeline .panel-heading {
  border-bottom: 1px solid var(--border);
}
.detail-timeline .panel-heading > .muted {
  font-size: 11px;
}
.metadata dl {
  padding: 0 21px 20px;
  margin: 0;
}
.metadata dt {
  font-size: 11px;
  color: #5d6879;
  margin-top: 17px;
}
.metadata dd {
  margin: 5px 0 0;
  font-size: 12px;
  color: #4f5d77;
  overflow-wrap: anywhere;
}
.action-panel {
  padding: 21px;
  margin-top: 20px;
}
.action-panel h2 {
  display: flex;
  gap: 7px;
  align-items: center;
  font-size: 14px;
}
.action-panel p {
  font-size: 12px;
  margin: 11px 0 18px;
  line-height: 1.9;
}
.action-panel > .button {
  display: flex;
  width: 100%;
  margin: 9px 0;
}
.action-panel > .text-link {
  margin-top: 12px;
}
.action-panel .error-state {
  margin: 15px 0;
}
.detail-layout > .panel {
  align-self: start;
}
dialog {
  border: 1px solid #d9e1ed;
  border-radius: 13px;
  padding: 26px;
  max-width: 500px;
  width: calc(100% - 32px);
  box-shadow: 0 18px 70px #1c2b4b33;
  color: var(--text);
  animation: dialog-in 0.15s ease-out;
}
dialog::backdrop {
  background: #17244266;
  backdrop-filter: blur(3px);
}
.modal-heading {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 20px;
}
.modal-heading h2 {
  font-size: 17px;
}
dialog > p {
  font-size: 13px;
  margin: 12px 0 20px;
}
.modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 23px;
}
dialog .error-state {
  margin: 10px 0;
}
.toast {
  position: fixed;
  bottom: 24px;
  left: calc(50% + 100px);
  transform: translateX(-50%);
  display: flex;
  gap: 11px;
  align-items: center;
  z-index: 150;
  background: #fff;
  border: 1px solid #d8e9e1;
  box-shadow: 0 7px 30px #203d6220;
  border-radius: 9px;
  padding: 14px 17px;
  font-size: 12px;
  max-width: calc(100% - 32px);
  width: max-content;
}
.toast > span {
  background: #e8f6ed;
  color: #237557;
  width: 21px;
  height: 21px;
  text-align: center;
  border-radius: 50%;
}
.toast > button {
  background: none;
  border: 0;
  margin-left: 10px;
  font-size: 20px;
  color: #5d6877;
}
.session-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 26px;
  max-width: 1050px;
  margin: 33px auto;
}
.session-story {
  background: var(--navy);
  color: white;
  border-radius: 13px;
  padding: 43px;
  display: flex;
  flex-direction: column;
  min-height: 570px;
  position: relative;
  overflow: hidden;
}
.session-story:after {
  content: "";
  position: absolute;
  width: 330px;
  height: 330px;
  bottom: -200px;
  right: -90px;
  border: 50px solid #25385c;
  border-radius: 50%;
  pointer-events: none;
}
.session-symbol {
  color: #88c8c2;
  margin-bottom: 34px;
}
.session-story h2 {
  font-size: 30px;
  line-height: 1.5;
  letter-spacing: -1px;
  font-weight: 500;
}
.session-story p {
  color: #a8bad3;
  font-size: 13px;
  line-height: 2;
  margin-top: 20px;
  max-width: 290px;
}
.session-benefits {
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin: 34px 0;
}
.session-benefits span {
  display: flex;
  gap: 11px;
  align-items: center;
  font-size: 13px;
  color: #d0dbea;
}
.session-benefits svg {
  color: #79c5b6;
}
.session-signature {
  font-size: 14px;
  letter-spacing: 2px;
  margin-top: auto;
  z-index: 1;
}
.session-signature > span {
  display: block;
  font-size: 10px;
  color: #8a9fbe;
  letter-spacing: 0;
  margin-top: 5px;
}
.session-card {
  padding: 32px;
}
.session-card h2 {
  font-size: 20px;
  margin: 20px 0 8px;
  letter-spacing: -0.5px;
}
.session-card > .muted {
  font-size: 13px;
  line-height: 1.9;
}
.session-status {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
  color: #5b687f;
  background: #f6f8fb;
  border-radius: 6px;
  padding: 10px 12px;
  margin: 21px 0;
}
.session-status .status-dot {
  margin: 0;
}
.role-picker {
  border: 0;
  padding: 0;
  margin: 24px 0;
}
.role-picker legend {
  font-size: 12px;
  color: #576884;
  margin-bottom: 10px;
}
.role-picker label {
  display: flex;
  align-items: center;
  gap: 10px;
  border: 1px solid var(--border);
  border-radius: 7px;
  padding: 13px;
  margin: 10px 0;
  cursor: pointer;
}
.role-picker label.selected {
  border-color: #818bc5;
  background: #f8f9ff;
}
.role-picker input {
  accent-color: var(--indigo);
}
.role-picker strong {
  font-size: 13px;
  display: block;
  font-weight: 500;
}
.role-picker small {
  display: block;
  font-size: 11px;
  color: #5c687c;
  margin-top: 3px;
}
.session-tools {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  margin-top: 16px;
  flex-wrap: wrap;
}
.blocked-login {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding-top: 22px;
  border-top: 1px solid var(--border);
  margin-top: 25px;
  color: #5b687d;
  font-size: 12px;
}
.blocked-login strong {
  font-size: 10px;
  font-weight: 500;
}
.blocked-login small {
  font-size: 10px;
  display: block;
  margin-top: 5px;
  line-height: 1.8;
}
.integration-banner {
  display: flex;
  align-items: center;
  gap: 17px;
  background: #edf6f2;
  border: 1px solid #d7e8df;
  border-radius: 10px;
  padding: 23px;
  margin-bottom: 21px;
}
.integration-banner h2 {
  color: #397163;
  font-size: 14px;
}
.integration-banner p {
  font-size: 12px;
  color: #4d6e62;
  margin-top: 4px;
}
.integration-banner > .blocked-tag {
  margin-left: auto;
}
.architecture-strip {
  display: flex;
  align-items: center;
  justify-content: space-around;
  text-align: center;
  padding: 27px;
  margin-bottom: 23px;
  gap: 15px;
}
.architecture-strip > div {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 7px;
  color: #576886;
}
.architecture-strip strong {
  font-size: 13px;
  color: #4e6386;
}
.architecture-strip small {
  font-size: 11px;
}
.architecture-strip .architecture-gate {
  color: #826223;
}
.architecture-gate strong {
  color: #81622c;
}
.architecture-arrow {
  font-size: 23px;
  color: #5c687a;
}
.integration-list {
  display: flex;
  flex-direction: column;
  gap: 13px;
}
.integration-item {
  display: flex;
  align-items: flex-start;
  padding: 23px;
  gap: 18px;
}
.integration-icon {
  background: #f2f5fa;
  color: #556887;
  display: grid;
  place-items: center;
  width: 43px;
  height: 43px;
  border-radius: 10px;
}
.integration-item > div:nth-child(2) {
  flex: 1;
}
.integration-item h2 {
  font-size: 14px;
}
.integration-item strong {
  display: block;
  font-size: 12px;
  font-weight: 400;
  color: #5b6880;
  margin-top: 2px;
}
.integration-item p {
  font-size: 12px;
  margin-top: 9px;
  line-height: 1.9;
}
.integration-state {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 6px;
}
.integration-state > span:last-child {
  font-size: 11px;
  color: #5b687d;
}
.integration-tools {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 22px;
  margin-top: 25px;
}
.developer-panel {
  padding: 24px;
}
.developer-panel h2 {
  font-size: 14px;
  display: flex;
  align-items: center;
  gap: 8px;
}
.developer-panel > p {
  font-size: 12px;
  line-height: 1.9;
  margin: 14px 0;
}
.developer-panel .field {
  margin-top: 20px;
}
.developer-panel > .text-link {
  display: flex;
  margin-top: 17px;
}
.inline-notice {
  font-size: 12px;
  background: #fffaec;
  color: #826228;
  border: 1px solid #efe3c4;
  padding: 12px;
  border-radius: 6px;
  margin: 15px 0;
}
.sidebar-overlay {
  display: none;
}
@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}
@keyframes dialog-in {
  from {
    opacity: 0;
    transform: translateY(5px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
@media (min-width: 1500px) {
  body {
    font-size: 14px;
  }
  main {
    padding: 40px 48px;
  }
  .welcome-panel {
    min-height: 272px;
  }
  .welcome-copy {
    padding: 29px 34px;
  }
  .welcome-copy h2 {
    font-size: 30px;
  }
  .welcome-copy p {
    font-size: 13px;
  }
  .portal-illustration {
    max-width: 300px;
  }
  .nav-item {
    font-size: 14px;
  }
  .request-title strong {
    font-size: 13px;
  }
  .panel-heading h2 {
    font-size: 14px;
  }
  td {
    padding-top: 16px;
    padding-bottom: 16px;
  }
}
@media (max-width: 1200px) {
  .sidebar {
    width: 220px;
    padding-left: 13px;
    padding-right: 13px;
  }
  .main-shell {
    margin-left: 220px;
  }
  main {
    padding: 28px 25px;
  }
  .topbar {
    padding: 0 25px;
  }
  .overview-layout,
  .dashboard-bottom {
    grid-template-columns: minmax(0, 1.6fr) minmax(240px, 1fr);
    gap: 16px;
  }
  .welcome-copy {
    padding: 25px 22px;
  }
  .welcome-copy h2 {
    font-size: 24px;
  }
  .portal-illustration {
    min-width: 145px;
  }
  .orbit {
    width: 170px;
  }
  .orbit-two {
    width: 190px;
  }
  .node-facility {
    right: 8px;
    top: 45px;
  }
  .floating-node {
    width: 36px;
    height: 36px;
  }
  .node-it {
    left: 0;
    top: 29px;
  }
  .node-check {
    left: 0;
  }
  .illustration-core {
    width: 77px;
    height: 89px;
  }
  .metric {
    padding: 0 16px;
  }
  .mini-bars {
    display: none;
  }
  .form-layout,
  .detail-layout {
    grid-template-columns: minmax(0, 1fr) 255px;
    gap: 18px;
  }
  .session-story {
    padding: 32px;
  }
  .session-story h2 {
    font-size: 25px;
  }
  .global-search input {
    width: 110px;
  }
  .session-card {
    padding: 26px;
  }
  th,
  td {
    padding-left: 12px;
    padding-right: 12px;
  }
}
@media (max-width: 1000px) {
  .sidebar {
    width: 205px;
  }
  .main-shell {
    margin-left: 205px;
  }
  .brand {
    padding-left: 8px;
  }
  .nav-item {
    font-size: 12px;
    gap: 8px;
  }
  .workspace {
    padding: 9px 6px;
    gap: 7px;
  }
  .workspace strong {
    font-size: 11px;
  }
  .workspace small {
    font-size: 10px;
  }
  .topbar {
    padding: 0 22px;
  }
  .topbar-right {
    gap: 10px;
  }
  .global-search {
    display: none;
  }
  .overview-layout {
    grid-template-columns: 1fr;
  }
  .quick-services {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 0 23px;
    padding: 17px 22px;
  }
  .quick-services .section-title {
    grid-column: 1/-1;
  }
  .quick-note {
    grid-column: 1/-1;
    padding-top: 9px;
  }
  .welcome-panel {
    min-height: 250px;
  }
  .portal-illustration {
    max-width: 260px;
    width: 40%;
  }
  .orbit {
    width: 230px;
  }
  .orbit-two {
    width: 240px;
  }
  .node-it {
    left: 15px;
    top: 40px;
  }
  .node-facility {
    right: 20px;
    top: 60px;
  }
  .node-check {
    left: 20px;
    bottom: 40px;
  }
  .welcome-copy h2 {
    font-size: 28px;
  }
  .metrics {
    grid-template-columns: 1fr 1fr;
    row-gap: 23px;
  }
  .metric:nth-child(2) {
    border: 0;
  }
  .dashboard-bottom {
    grid-template-columns: 1fr;
  }
  .platform-note {
    display: none;
  }
  .form-layout,
  .detail-layout {
    grid-template-columns: 1fr;
  }
  .form-aside {
    display: none;
  }
  .detail-layout > aside {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 18px;
    align-items: start;
  }
  .action-panel {
    margin-top: 0;
  }
  .detail-layout > aside > .aside-footnote {
    grid-column: 1/-1;
  }
  .session-layout {
    grid-template-columns: 1fr;
    max-width: 540px;
  }
  .session-story {
    min-height: 0;
    padding: 30px;
  }
  .session-story h2 {
    font-size: 25px;
  }
  .session-symbol {
    margin-bottom: 18px;
  }
  .session-benefits {
    margin: 20px 0;
  }
  .session-signature {
    margin-top: 15px;
  }
  .integration-tools {
    grid-template-columns: 1fr;
  }
  .footer {
    padding-left: 25px;
    padding-right: 25px;
  }
  .footer > span:last-child {
    display: none;
  }
  .page-heading {
    align-items: flex-start;
  }
  .page-heading > .button {
    margin-top: 5px;
  }
  .architecture-strip {
    padding: 23px 13px;
    gap: 8px;
  }
  .architecture-strip small {
    font-size: 10px;
  }
  .architecture-strip strong {
    font-size: 12px;
  }
  .breadcrumb {
    font-size: 11px;
  }
  .request-form {
    padding: 23px;
  }
  h1 {
    font-size: 24px;
  }
}
@media (max-width: 760px) {
  .sidebar {
    transform: translateX(-100%);
    transition: transform 0.2s;
    width: 248px;
