  .metric {
    padding: 0 20px;
  }
  .metric > p {
    font-size: 10px;
  }
  .panel-heading {
    padding: 18px;
  }
  .panel-heading h2 {
    font-size: 14px;
  }
  .panel-heading p {
    font-size: 11px;
  }
  .panel-heading .text-link {
    font-size: 11px;
  }
  .table-scroll {
    margin-bottom: 2px;
  }
  .request-title {
    max-width: 300px;
  }
  .request-title strong {
