:root {
  --font: "Be Vietnam Pro", sans-serif;
  --canvas: #f7f9fc;
  --text: #273650;
  --muted: #5e6b80;
  --navy: #192e50;
  --indigo: #505db0;
  --teal: #268a7b;
  --border: #e6ebf2;
  --radius: 10px;
  color-scheme: light;
}

/*
 * DX-OS University Enterprise skin
 * Design inspiration: modern enterprise SaaS. Not affiliated with any university.
 * Visual-only extension to the established Issue #39 design system.
 */
:root {
  --canvas: #f5f7fc;
  --text: #192b47;
  --muted: #5e6f89;
  --navy: #121c3e;
  --indigo: #365fe7;
  --teal: #1598bb;
  --border: #e5eaf3;
  --radius: 12px;
  --campus-shadow: 0 5px 24px rgba(29, 51, 94, 0.035);
}
body { background: var(--canvas); }
.sidebar {
  background: #111b3a;
  border-right: 1px solid #202e55;
  color: #f7f9ff;
  padding-top: 26px;
  box-shadow: 8px 0 26px rgba(15, 30, 72, 0.04);
}
.sidebar .brand { padding-bottom: 27px; }
.sidebar .brand > span:first-of-type { color: #fff; letter-spacing: -0.7px; }
.sidebar .brand small { color: #b2c0df; letter-spacing: .15px; font-weight: 500; }
.sidebar .brand-dash { color: #7da4ff; }
.sidebar .brand-version {
  color: #b4caff; border-color: #334266; background: #202d52;
}
.sidebar .workspace {
  background: #1b294d;
  border-color: #304166;
  padding: 13px 10px;
}
.sidebar .workspace-mark { background: #294477; color: #d5e5ff; }
.sidebar .workspace strong { color: #eff4ff; }
.sidebar .workspace small, .sidebar .workspace > svg { color: #b1bfda; }
.sidebar .nav-label { color: #91a4c8; text-transform: uppercase; letter-spacing: 1px; font-size: 10px; font-weight: 600; }
.sidebar .nav-item {
  color: #c1cde5;
  font-weight: 500;
  border: 1px solid transparent;
  border-radius: 9px;
  min-height: 44px;
  transition: background-color .16s ease, color .16s ease;
}
.sidebar .nav-item:hover { background: #202e55; color: #fff; }
.sidebar .nav-item.active {
  background: #3260da;
  color: #fff;
  box-shadow: 0 4px 14px rgba(26, 70, 184, .2);
  border-color: #4474f4;
}
.sidebar .nav-pill { background: #25365d; color: #d5e5ff; }
.sidebar .status-dot { background: #f3bb61; }
.sidebar .demo-card { background: #1c2a50; border: 1px solid #32436a; }
.sidebar .demo-card-icon, .sidebar .demo-card strong { color: #eef4ff; }
.sidebar .demo-card p { color: #b5c4e1; }
.sidebar .demo-card a { color: #95bcff; }
.sidebar .profile { border-color: #324267; }
.sidebar .profile strong { color: #f2f6ff; }
.sidebar .profile small, .sidebar .profile > svg { color: #b4c1dd; }
.sidebar .avatar { color: #e4eeff; background: #3658a1; }
.sidebar .profile:hover { background: #1c2a50; }
.main-shell { background: #f6f8fd; }
.topbar {
  background: rgba(255, 255, 255, .97);
  border-bottom: 1px solid #e7ebf3;
  box-shadow: 0 1px 4px rgba(39, 57, 99, .025);
}
.breadcrumb strong { color: #183158; font-weight: 650; }
.global-search {
  background: #f5f7fb;
  border: 1px solid #e5eaf1;
  border-radius: 9px;
  min-height: 36px;
  padding: 0 11px;
}
.global-search input { width: 185px; }
.environment { color: #865e13; background: #fff7e5; border: 1px solid #f5e5b9; border-radius: 20px; }
.environment > span { background: #cc9230; }
main { max-width: 1680px; width: 100%; margin: 0 auto; }
.page-heading h1 { color: #172b4c; font-size: clamp(23px, 2vw, 30px); letter-spacing: -.8px; }
.page-heading .eyebrow { color: #3b64bf; font-weight: 650; letter-spacing: .7px; }
.panel, .metric, .campus-service-card { border: 1px solid var(--border); box-shadow: var(--campus-shadow); border-radius: 13px; }
.button.primary { background: #315ddd; color: #fff; border-color: #315ddd; box-shadow: 0 4px 10px rgba(34, 74, 183, .12); }
.button.primary:hover { background: #244dc7; }
.button.secondary { background: #fff; }
.button:focus-visible, .sidebar a:focus-visible { outline: 3px solid #76b7ff; outline-offset: 3px; }
.badge { border-radius: 999px; font-weight: 650; }
.count-badge { border-radius: 999px; }
.panel-heading { padding: 21px 24px; }
.table-scroll th { background: #f8faff; color: #566782; }
.table-scroll tbody tr:hover { background: #f9fbff; }
.field input, .field textarea, .field select, .search-field, .filter-select { border-color: #dce4f1; }
.field input:focus, .field textarea:focus, .field select:focus { border-color: #4b78e4; }

/* Dashboard, inspired by a clean SaaS analytics command center. */
.campus-overline {
  display: inline-flex; gap: 8px; align-items: center;
  color: #4263a2; font-size: 11px; font-weight: 650;
  letter-spacing: .8px; text-transform: uppercase;
}
.campus-dashboard-intro {
  display: flex; align-items: center; justify-content: space-between;
  gap: 20px; margin: 1px 0 24px;
}
.campus-dashboard-intro p { font-size: 13px; line-height: 1.7; }
.campus-dashboard-intro .intro-chip {
  padding: 10px 13px; white-space: nowrap; border-radius: 9px;
  background: #eaf0ff; color: #365fbb; font-size: 12px; font-weight: 600;
}
.campus-metrics {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 16px;
  border: 0; padding: 0; background: transparent;
  margin-bottom: 20px;
}
.campus-metrics .metric {
  border: 1px solid var(--border);
  background: #fff;
  padding: 23px 22px 22px;
  min-height: 162px;
  overflow: hidden;
}
.campus-metrics .metric:last-child { border: 1px solid var(--border); }
.campus-metrics .metric > div:first-child {
  display: flex; justify-content: space-between; align-items: center;
  gap: 14px; margin-bottom: 15px;
}
.campus-metrics .metric > div:first-child span { color: #647590; font-size: 12px; font-weight: 600; }
.campus-metrics .metric > div:first-child svg { color: #5272b5; padding: 7px; width: 33px; height: 33px; background: #edf2ff; border-radius: 10px; }
.campus-metrics .metric > strong { font-size: 30px; line-height: 1.12; letter-spacing: -.9px; color: #18294c; display: block; margin-bottom: 10px; }
.campus-metrics .metric > p { font-size: 11px; color: #5e6f89; line-height: 1.6; }
.campus-metrics .metric > strong small { font-size: 11px; color: #7b8ba4; font-weight: 500; margin-left: 7px; }
.campus-dashboard-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.62fr) minmax(300px, 1fr);
  gap: 20px;
  margin-bottom: 20px;
}
.campus-chart-panel { padding-bottom: 18px; min-width: 0; }
.campus-chart-meta { display: flex; justify-content: space-between; align-items: center; padding: 0 24px; gap: 10px; }
.campus-chart-meta p { font-size: 12px; }
.campus-chart-count { display: flex; align-items: baseline; gap: 10px; margin: 13px 24px 0; }
.campus-chart-count strong { font-size: 28px; font-weight: 700; letter-spacing: -.8px; color: #1e3355; }
.campus-chart-count span { font-size: 12px; color: #5e6f89; }
.campus-chart {
  margin: 19px 24px 0;
  padding: 18px 8px 4px;
  min-height: 218px;
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: clamp(8px, 2vw, 20px);
  align-items: end;
  background: repeating-linear-gradient(to top, transparent 0, transparent 49px, #e9edf5 50px);
  border-bottom: 1px solid #e6ecf3;
}
.campus-chart-bar {
  display: flex; flex-direction: column; height: 205px;
  justify-content: flex-end; align-items: center;
  gap: 10px;
  min-width: 0;
}
.campus-chart-track { width: min(100%, 44px); height: 170px; display: flex; align-items: flex-end; }
.campus-chart-fill {
  background: linear-gradient(180deg, #4f83ee, #b7ceff);
  width: 100%; border-radius: 6px 6px 0 0;
  min-height: 4px; transition: height .2s ease;
}
.campus-chart-bar:nth-child(2n) .campus-chart-fill { background: linear-gradient(180deg, #57a9de, #c7eaf7); }
.campus-chart-label { font-size: 10px; color: #6a7891; text-align: center; white-space: nowrap; }
.campus-chart-legend { display: flex; gap: 8px; align-items: center; margin: 17px 25px 0; color: #5e6f89; font-size: 11px; }
.campus-chart-legend:before { content: ""; width: 9px; height: 9px; border-radius: 3px; background: #4f83ee; }
.campus-activity-panel { min-width: 0; }
.campus-activity-panel .timeline { padding: 6px 24px 17px; }
.campus-activity-panel .timeline li { padding-bottom: 14px; }
.campus-activity-panel .timeline li div { min-width: 0; }
.campus-services-header { display: flex; justify-content: space-between; align-items: center; margin: 26px 0 13px; gap: 10px; }
.campus-services-header h2 { font-size: 16px; color: #243958; }
.campus-services-header p { font-size: 12px; }
.campus-service-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 18px; margin-bottom: 22px; }
.campus-service-card {
  background: #fff; display: flex; align-items: center;
  padding: 20px 22px; gap: 14px; min-width: 0;
  transition: border-color .15s ease, box-shadow .15s ease;
}
.campus-service-card:hover { border-color: #a7bfe7; box-shadow: 0 8px 22px rgba(30,55,94,.07); }
.campus-service-card > span:nth-child(2) { flex: 1; min-width: 0; }
.campus-service-card strong { display: block; font-size: 13px; color: #22385b; }
.campus-service-card small { display: block; margin-top: 5px; font-size: 11px; color: #5e6f89; line-height: 1.7; }
.campus-service-card > svg { color: #72839e; }
.campus-service-card .service-icon { height: 48px; width: 48px; border-radius: 12px; }
.campus-recent { margin-top: 4px; margin-bottom: 24px; }
.campus-recent .panel-heading { border-bottom: 1px solid #eff2f7; }
.campus-recent .panel-heading p { font-size: 12px; margin-top: 5px; }
.campus-recent .table-scroll { padding-bottom: 6px; }
.campus-recent .request-title strong { font-weight: 600; }
.campus-activity-panel .timeline li { line-height: 1.5; }

/* Demo identity remains clearly marked as a simulation. */
.session-story { background: #142a53; }
.session-card { box-shadow: var(--campus-shadow); }
.role-picker label.selected { border-color: #4d7ae3; background: #f4f7ff; }

/* Base app responsiveness: keep sidebar overlay and existing route behavior. */
@media (max-width: 1180px) {
  .campus-metrics { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .campus-dashboard-grid { grid-template-columns: 1fr; }
  .campus-activity-panel .timeline { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); column-gap: 15px; }
}
@media (max-width: 760px) {
  .sidebar { padding-top: 22px; }
  .campus-dashboard-intro { align-items: flex-start; flex-direction: column; gap: 8px; }
  .campus-dashboard-intro .intro-chip { white-space: normal; }
  .campus-metrics { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
  .campus-metrics .metric { min-height: 132px; padding: 16px 14px; }
  .campus-metrics .metric > strong { font-size: 26px; }
  .campus-metrics .metric > div:first-child svg { width: 29px; height: 29px; }
  .campus-services-header { flex-direction: column; align-items: flex-start; }
  .campus-service-grid { grid-template-columns: 1fr; gap: 11px; }
  .campus-dashboard-grid { gap: 14px; }
  .campus-chart { margin-inline: 16px; gap: 9px; }
  .campus-chart-bar { height: 180px; }
  .campus-chart-track { height: 147px; }
  .campus-chart-meta { padding-inline: 16px; }
  .campus-chart-count { margin-inline: 16px; }
  .campus-activity-panel .timeline { grid-template-columns: 1fr; }
  .campus-service-card { padding: 16px; }
  .global-search input { width: 100px; }
  .topbar { padding-inline: 16px; }
}
@media (max-width: 390px) {
  .campus-metrics .metric { padding: 13px 10px; }
  .campus-metrics .metric > div:first-child span { font-size: 11px; }
  .campus-metrics .metric > strong { font-size: 24px; }
  .campus-chart-label { font-size: 9px; }
}
@media (prefers-reduced-motion: reduce) {
  .campus-chart-fill, .campus-service-card, .sidebar .nav-item { transition: none; }
}

import { test, expect } from "@playwright/test";
import AxeBuilder from "@axe-core/playwright";
import { mkdir } from "node:fs/promises";
import { resolve } from "node:path";

const evidence = resolve("..", "docs", "evidence", "issue39-portal", "auth");

for (const route of ["login", "register"]) {
  test(`${route}: responsive layouts, keyboard, WCAG and screenshots`, async ({
    page,
  }) => {
    test.setTimeout(60000);
    for (const [width, height, name] of [
      [1440, 1100, "desktop"],
      [834, 1112, "tablet"],
      [390, 844, "mobile"],
      [320, 740, "small-mobile"],
    ] as const) {
      await page.setViewportSize({ width, height });
      await page.goto(`/${route}`);
      await page.waitForLoadState("networkidle");
      await page.evaluate(() => document.fonts.ready);
      await expect(page.getByRole("heading", { level: 1 })).toBeFocused();
      expect(
        await page.evaluate(() => document.documentElement.scrollWidth),
      ).toBe(width);
      await page.keyboard.press("Tab");
      await expect(
        page.getByLabel(route === "login" ? "Email" : "Họ và tên", {
          exact: true,
        }),
      ).toBeFocused();
      const results = await new AxeBuilder({ page })
        .withTags(["wcag2a", "wcag2aa", "wcag21aa"])
        .analyze();
      expect(results.violations).toEqual([]);
      await mkdir(evidence, { recursive: true });
      await page.screenshot({
        path: resolve(evidence, `${route}-${name}.png`),
        fullPage: true,
        animations: "disabled",
      });
    }
    await page
      .getByRole("button", {
        name: route === "login" ? "Đăng nhập" : "Đăng ký tài khoản",
        exact: true,
      })
      .click();
    await expect(page.getByLabel("Email", { exact: true })).toHaveAttribute(
      "aria-invalid",
      "true",
    );
    expect(
      (
        await new AxeBuilder({ page })
          .withTags(["wcag2a", "wcag2aa", "wcag21aa"])
          .analyze()
      ).violations,
    ).toEqual([]);
  });
}

test("blocked forms never send credentials, register APIs or grant a demo role", async ({
  page,
}) => {
  const outgoing: string[] = [];
  const consoleMessages: string[] = [];
  const errors: string[] = [];
  page.on("request", (request) => {
    if (
      ["fetch", "xhr", "ping", "websocket"].includes(request.resourceType()) ||
      request.method() !== "GET" ||
      !request.url().startsWith("http://127.0.0.1:4173/")
    )
      outgoing.push(`${request.method()} ${request.url()}`);
  });
  page.on("console", (message) => consoleMessages.push(message.text()));
  page.on("pageerror", (error) => errors.push(error.message));
  await page.goto("/login");
  await page
    .getByLabel("Email", { exact: true })
    .fill("preview@example.edu.vn");
  await page
    .getByLabel("Mật khẩu", { exact: true })
    .fill("Synthetic preview only!");
  await page.getByRole("checkbox", { name: "Ghi nhớ email" }).check();
  await page.getByRole("button", { name: "Đăng nhập", exact: true }).click();
  await expect(page.getByRole("alert")).toContainText("BLOCKED FEATURE");
  await expect(page).toHaveURL(/\/login$/);
  await expect(page.getByLabel("Mật khẩu", { exact: true })).toHaveValue("");
  expect(await page.evaluate(() => ({ ...localStorage }))).toEqual({
    "dxos-remembered-email-v1": "preview@example.edu.vn",
  });
  expect(await page.evaluate(() => ({ ...sessionStorage }))).toEqual({});
  await page.reload();
  await expect(page.getByLabel("Email", { exact: true })).toHaveValue(
    "preview@example.edu.vn",
  );
  await expect(page.getByLabel("Mật khẩu", { exact: true })).toHaveValue("");
  await page.getByRole("checkbox", { name: "Ghi nhớ email" }).uncheck();
  await page.getByRole("button", { name: "Quên mật khẩu?" }).click();
  await expect(page.getByRole("alert")).toContainText("BLOCKED FEATURE");
  await page.getByRole("link", { name: "Đăng ký", exact: true }).click();
  await expect(page).toHaveURL(/\/register$/);
  await page.getByLabel("Họ và tên").fill("Người dùng thử");
  await page
    .getByLabel("Email", { exact: true })
    .fill("preview@example.edu.vn");
  await page
    .getByLabel("Mật khẩu", { exact: true })
    .fill("Synthetic preview only!");
  await page
    .getByLabel("Xác nhận mật khẩu", { exact: true })
    .fill("Different preview only!");
  await page.getByRole("button", { name: "Đăng ký tài khoản" }).click();
  await expect(page.getByText("Mật khẩu xác nhận chưa khớp.")).toBeVisible();
  await expect(
    page.getByLabel("Xác nhận mật khẩu", { exact: true }),
  ).toBeFocused();
  await page
    .getByLabel("Xác nhận mật khẩu", { exact: true })
    .fill("Synthetic preview only!");
  await expect(page.getByRole("radio")).toHaveCount(2);
  await page.getByRole("radio", { name: "Giảng viên", exact: true }).check();
  await page.getByRole("button", { name: "Đăng ký tài khoản" }).click();
  await expect(page.getByRole("alert")).toContainText("Chưa tạo tài khoản");
  await expect(page).toHaveURL(/\/register$/);
  for (const label of ["Mật khẩu", "Xác nhận mật khẩu"])
    await expect(page.getByLabel(label, { exact: true })).toHaveValue("");
  expect(await page.evaluate(() => ({ ...localStorage }))).toEqual({});
  expect(await page.evaluate(() => ({ ...sessionStorage }))).toEqual({});
  expect(outgoing).toEqual([]);
  expect(
    consoleMessages.some((message) =>
      message.includes("Synthetic preview only!"),
    ),
  ).toBe(false);
  expect(errors).toEqual([]);
  expect(
    (
      await new AxeBuilder({ page })
        .withTags(["wcag2a", "wcag2aa", "wcag21aa"])
        .analyze()
    ).violations,
  ).toEqual([]);
  await page.getByRole("link", { name: "Đăng nhập", exact: true }).click();
  await expect(page.getByLabel("Mật khẩu", { exact: true })).toHaveValue("");
  await page.getByRole("link", { name: "Vào phiên Demo", exact: true }).click();
  await expect(page).toHaveURL(/\/session$/);
  await page
    .getByRole("button", { name: "Vào phiên demo", exact: true })
    .click();
  await expect(
    page.getByRole("heading", { name: /Chào buổi sáng/ }),
  ).toBeVisible();
});

