package com.tricore.dxos.portal;

import java.net.URI;

final class PortalOrigin {
    private PortalOrigin() {}

    static String checked(String value) {
        URI uri = URI.create(value);
        if (!"https".equals(uri.getScheme()) || uri.getHost() == null
                || uri.getUserInfo() != null || uri.getRawQuery() != null
                || uri.getRawFragment() != null || uri.getRawPath() != null && !uri.getRawPath().isEmpty()
                || value.endsWith("/")) {
            throw new IllegalArgumentException("Portal public origin must be an HTTPS origin without path or credentials");
        }
        return uri.toString();
    }
}

package com.tricore.dxos.portal;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.http.HttpMethod;
import org.springframework.http.HttpStatus;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configurers.AbstractHttpConfigurer;
import org.springframework.security.oauth2.client.OAuth2AuthorizedClientManager;
import org.springframework.security.oauth2.client.OAuth2AuthorizedClientProviderBuilder;
import org.springframework.security.oauth2.client.registration.ClientRegistrationRepository;
import org.springframework.security.oauth2.core.AuthorizationGrantType;
import org.springframework.security.oauth2.core.ClientAuthenticationMethod;
import org.springframework.security.oauth2.client.web.DefaultOAuth2AuthorizedClientManager;
import org.springframework.security.oauth2.client.web.HttpSessionOAuth2AuthorizedClientRepository;
import org.springframework.security.oauth2.client.web.OAuth2AuthorizedClientRepository;
import org.springframework.security.oauth2.client.web.OAuth2AuthorizationRequestCustomizers;
import org.springframework.security.oauth2.client.web.DefaultOAuth2AuthorizationRequestResolver;
import org.springframework.security.oauth2.client.oidc.web.logout.OidcClientInitiatedLogoutSuccessHandler;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.authentication.HttpStatusEntryPoint;

@Configuration(proxyBeanMethods = false)
class PortalSecurity {
    @Bean
    SecurityFilterChain portalFilterChain(HttpSecurity http, ClientRegistrationRepository registrations,
            @Value("${dxos.portal-bff.public-origin}") String publicOrigin) throws Exception {
        String origin = PortalOrigin.checked(publicOrigin);
        var registration = registrations.findByRegistrationId("keycloak");
        if (registration == null || registration.getClientSecret() == null
                || registration.getClientSecret().isBlank()
                || "tricore-api".equals(registration.getClientId())
                || !ClientAuthenticationMethod.CLIENT_SECRET_BASIC.equals(registration.getClientAuthenticationMethod())
                || !AuthorizationGrantType.AUTHORIZATION_CODE.equals(registration.getAuthorizationGrantType())
                || !(origin + "/login/oauth2/code/keycloak").equals(registration.getRedirectUri())) {
            throw new IllegalArgumentException("Portal OIDC client must be confidential with the pinned HTTPS callback");
        }
        var resolver = new DefaultOAuth2AuthorizationRequestResolver(registrations, "/oauth2/authorization");
        resolver.setAuthorizationRequestCustomizer(OAuth2AuthorizationRequestCustomizers.withPkce());
        var logout = new OidcClientInitiatedLogoutSuccessHandler(registrations);
        logout.setPostLogoutRedirectUri(origin + "/");
        http.authorizeHttpRequests(authorize -> authorize
                .requestMatchers(HttpMethod.GET, "/bff/session").permitAll()
                .requestMatchers("/bff/api/**").authenticated()
                .requestMatchers(HttpMethod.POST, "/bff/logout").authenticated()
                .requestMatchers("/bff/**").denyAll()
                .anyRequest().permitAll())
            .oauth2Login(oauth -> oauth.authorizationEndpoint(endpoint -> endpoint.authorizationRequestResolver(resolver)))
            .httpBasic(AbstractHttpConfigurer::disable)
            .formLogin(AbstractHttpConfigurer::disable)
            .exceptionHandling(exceptions -> exceptions.defaultAuthenticationEntryPointFor(
                    new HttpStatusEntryPoint(HttpStatus.UNAUTHORIZED),
                    request -> request.getServletPath().startsWith("/bff/api/")))
            .logout(config -> config.logoutUrl("/bff/logout")
                    .invalidateHttpSession(true).deleteCookies("__Host-DXOS-Portal")
                    .logoutSuccessHandler(logout));
        // CSRF remains enabled. The session endpoint supplies the token for same-origin writes.
        return http.build();
    }

    @Bean
    OAuth2AuthorizedClientRepository authorizedClientRepository() {
        return new HttpSessionOAuth2AuthorizedClientRepository();
    }

    @Bean
    OAuth2AuthorizedClientManager authorizedClientManager(
            ClientRegistrationRepository registrations, OAuth2AuthorizedClientRepository repository) {
        var manager = new DefaultOAuth2AuthorizedClientManager(registrations, repository);
        manager.setAuthorizedClientProvider(OAuth2AuthorizedClientProviderBuilder.builder()
                .authorizationCode().refreshToken().build());
        return manager;
    }
}

package com.tricore.dxos.portal;

import org.springframework.http.CacheControl;
import org.springframework.http.ResponseEntity;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.security.core.Authentication;
import org.springframework.security.web.csrf.CsrfToken;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RestController;

import java.util.Map;

@RestController
class PortalSessionController {
    private final PortalAuthorization authorization;

    PortalSessionController(PortalAuthorization authorization) {
        this.authorization = authorization;
    }

    @GetMapping("/bff/session")
    ResponseEntity<Map<String, Object>> session(Authentication authentication, CsrfToken csrf,
                                                HttpServletRequest request) {
        boolean active = authorization.usableToken(authentication, request) != null;
        Map<String, Object> body = active
                ? Map.of("authenticated", true, "csrfToken", csrf.getToken())
                : Map.of("authenticated", false);
        return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(body);
    }
}

package com.tricore.dxos.portal;

import org.junit.jupiter.api.Test;
import org.springframework.http.ResponseEntity;
import org.springframework.security.oauth2.client.OAuth2AuthorizedClient;
import org.springframework.security.oauth2.client.OAuth2AuthorizedClientManager;
import org.springframework.security.oauth2.client.authentication.OAuth2AuthenticationToken;
import org.springframework.security.oauth2.client.registration.ClientRegistration;
import org.springframework.security.oauth2.core.AuthorizationGrantType;
import org.springframework.security.oauth2.core.OAuth2AccessToken;
import org.springframework.security.oauth2.core.OAuth2AuthorizationException;
import org.springframework.security.oauth2.core.OAuth2Error;
import org.springframework.security.oauth2.core.user.DefaultOAuth2User;
import org.springframework.security.core.authority.SimpleGrantedAuthority;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.mock.web.MockHttpSession;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Instant;
import java.util.List;
import java.util.Map;
import java.util.UUID;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

class PortalBackendClientTest {
    @Test
    void publicOriginIsPinnedHttps() {
        assertEquals("https://portal.example.test", PortalOrigin.checked("https://portal.example.test"));
        for (String value : new String[]{"http://portal.example.test", "https://portal.example.test/path",
                "https://user:secret@portal.example.test", "https://portal.example.test?next=other"}) {
            assertThrows(IllegalArgumentException.class, () -> PortalOrigin.checked(value), value);
        }
    }

    @Test
    void backendOriginMustBeHttpsOrLiteralLoopback() {
        assertEquals("https://api.example.test", PortalBackendClient.checkedBackend("https://api.example.test").toString());
        assertEquals("http://127.0.0.1:8080", PortalBackendClient.checkedBackend("http://127.0.0.1:8080").toString());
        for (String value : new String[]{"http://api.example.test", "http://localhost:8080",
                "https://user:secret@api.example.test", "https://api.example.test/other",
                "https://api.example.test?target=other"}) {
            assertThrows(IllegalArgumentException.class, () -> PortalBackendClient.checkedBackend(value), value);
        }
    }

    @Test
    @SuppressWarnings("unchecked")
    void onlyServerHeldBearerIsForwardedAndRedirectsAreRejected() throws Exception {
        HttpClient http = mock(HttpClient.class);
        HttpResponse<InputStream> upstream = response(302, new ByteArrayInputStream(new byte[0]));
        when(http.send(any(HttpRequest.class), any(HttpResponse.BodyHandler.class))).thenReturn(upstream);
        PortalBackendClient bff = bff(manager(), http);
        ResponseEntity<?> result = bff.get(UUID.fromString("00000000-0000-0000-0000-000000000001"),
                principal(), new MockHttpServletRequest());
        assertEquals(502, result.getStatusCode().value());
        var request = org.mockito.ArgumentCaptor.forClass(HttpRequest.class);
        verify(http).send(request.capture(), any(HttpResponse.BodyHandler.class));
        assertEquals("Bearer server-access-token", request.getValue().headers().firstValue("Authorization").orElseThrow());
        assertEquals("https://api.example.test/api/v1/mvp/requests/00000000-0000-0000-0000-000000000001",
                request.getValue().uri().toString());
        assertTrue(request.getValue().headers().firstValue("Cookie").isEmpty());
        assertTrue(request.getValue().headers().firstValue("X-User").isEmpty());
        assertTrue(request.getValue().headers().firstValue("X-Role").isEmpty());
    }

    @Test
    @SuppressWarnings("unchecked")
    void failedWriteIsReportedAsUncertainWithoutRetry() throws Exception {
        HttpClient http = mock(HttpClient.class);
        when(http.send(any(HttpRequest.class), any(HttpResponse.BodyHandler.class)))
                .thenThrow(new IOException("connection lost after send"));
        PortalBackendClient bff = bff(manager(), http);
        MockHttpServletRequest request = new MockHttpServletRequest();
        request.setContent("{}".getBytes(java.nio.charset.StandardCharsets.UTF_8));
        ResponseEntity<?> result = bff.create(request, principal());
        assertEquals(503, result.getStatusCode().value());
        assertEquals("COMMIT_OUTCOME_UNKNOWN", ((Map<?, ?>) result.getBody()).get("code"));
        verify(http, times(1)).send(any(HttpRequest.class), any(HttpResponse.BodyHandler.class));
    }

    @Test
    void oversizedWriteIsRejectedBeforeAuthorizationOrNetwork() {
        HttpClient http = mock(HttpClient.class);
        OAuth2AuthorizedClientManager manager = mock(OAuth2AuthorizedClientManager.class);
        PortalBackendClient bff = bff(manager, http);
        MockHttpServletRequest request = new MockHttpServletRequest();
        request.setContent(new byte[32_769]);
        assertEquals(413, bff.create(request, principal()).getStatusCode().value());
        verifyNoInteractions(manager, http);
    }

    @Test
    void upstreamBodyBelowLimitIsReturnedAndClosed() throws Exception {
        byte[] body = "{}".getBytes(java.nio.charset.StandardCharsets.UTF_8);
        CloseTrackingInputStream stream = new CloseTrackingInputStream(body);
        HttpClient http = httpResponse(200, stream);

        ResponseEntity<?> result = bff(manager(), http).get(id(), principal(), new MockHttpServletRequest());

        assertEquals(200, result.getStatusCode().value());
        assertTrue(java.util.Arrays.equals(body, (byte[]) result.getBody()));
        assertTrue(stream.closed);
    }

    @Test
    void upstreamBodyAtLimitIsReturnedAndClosed() throws Exception {
        CloseTrackingInputStream stream = new CloseTrackingInputStream(new byte[2_000_000]);
        HttpClient http = httpResponse(200, stream);

        ResponseEntity<?> result = bff(manager(), http).get(id(), principal(), new MockHttpServletRequest());

        assertEquals(200, result.getStatusCode().value());
        assertEquals(2_000_000, ((byte[]) result.getBody()).length);
        assertTrue(stream.closed);
    }

    @Test
    void upstreamBodyOverLimitIsRejectedAndClosedBeforeFullRead() throws Exception {
        CloseTrackingInputStream stream = new CloseTrackingInputStream(new byte[2_000_010]);
        HttpClient http = httpResponse(200, stream);

        ResponseEntity<?> result = bff(manager(), http).get(id(), principal(), new MockHttpServletRequest());

        assertEquals(502, result.getStatusCode().value());
        assertEquals(null, result.getBody());
        assertEquals(9, stream.available());
        assertTrue(stream.closed);
    }

    @Test
    void upstreamReadFailureOnWriteIsUncertainAndNeverReplayed() throws Exception {
        FailingInputStream stream = new FailingInputStream();
        HttpClient http = httpResponse(200, stream);
        MockHttpServletRequest request = new MockHttpServletRequest();
        request.setContent("{}".getBytes(java.nio.charset.StandardCharsets.UTF_8));

        ResponseEntity<?> result = bff(manager(), http).create(request, principal());

        assertEquals(503, result.getStatusCode().value());
        assertEquals(Map.of("code", "COMMIT_OUTCOME_UNKNOWN"), result.getBody());
        verify(http, times(1)).send(any(HttpRequest.class), any(HttpResponse.BodyHandler.class));
        assertTrue(stream.closed);
    }

    @Test
    void missingAuthorizationInvalidatesSessionWithoutCallingBackend() {
        OAuth2AuthorizedClientManager manager = mock(OAuth2AuthorizedClientManager.class);
        assertUnusable(manager);
    }

    @Test
    void missingBackendTokenInvalidatesSessionWithoutCallingBackend() {
        OAuth2AuthorizedClientManager manager = mock(OAuth2AuthorizedClientManager.class);
        OAuth2AuthorizedClient client = mock(OAuth2AuthorizedClient.class);
        when(manager.authorize(any())).thenReturn(client);
        assertUnusable(manager);
    }

    @Test
    void expiredTokenWithoutRefreshInvalidatesSessionWithoutCallingBackend() {
        assertUnusable(managerWithToken(new OAuth2AccessToken(OAuth2AccessToken.TokenType.BEARER,
                "expired-token", Instant.now().minusSeconds(300), Instant.now().minusSeconds(1))));
    }

    @Test
    void refreshedTokenIsUsedInsteadOfExpiredToken() throws Exception {
        OAuth2AuthorizedClientManager manager = managerWithToken(new OAuth2AccessToken(
                OAuth2AccessToken.TokenType.BEARER, "refreshed-token", Instant.now(), Instant.now().plusSeconds(300)));
        HttpClient http = httpResponse(200, new ByteArrayInputStream(new byte[0]));

        ResponseEntity<?> result = bff(manager, http).get(id(), principal(), new MockHttpServletRequest());

        assertEquals(200, result.getStatusCode().value());
        var request = org.mockito.ArgumentCaptor.forClass(HttpRequest.class);
        verify(http).send(request.capture(), any(HttpResponse.BodyHandler.class));
        assertEquals("Bearer refreshed-token", request.getValue().headers().firstValue("Authorization").orElseThrow());
    }

    @Test
    void refreshFailureInvalidatesSessionWithoutCallingBackend() {
        OAuth2AuthorizedClientManager manager = mock(OAuth2AuthorizedClientManager.class);
        when(manager.authorize(any())).thenThrow(new OAuth2AuthorizationException(
                new OAuth2Error("invalid_grant", "sensitive provider detail", null)));
        assertUnusable(manager);
    }

    @Test
    void revokedBackendAuthorizationReturnsSanitized401AndInvalidatesSession() throws Exception {
        HttpClient http = httpResponse(401, new ByteArrayInputStream("sensitive".getBytes()));
        MockHttpServletRequest request = new MockHttpServletRequest();
        MockHttpSession session = (MockHttpSession) request.getSession();

        ResponseEntity<?> result = bff(manager(), http).get(id(), principal(), request);

        assertEquals(401, result.getStatusCode().value());
        assertEquals(null, result.getBody());
        assertTrue(session.isInvalid());
    }

    @org.junit.jupiter.params.ParameterizedTest
    @org.junit.jupiter.params.provider.ValueSource(ints = {403, 404, 409})
    void backendDenialPreservesSessionAndStatus(int status) throws Exception {
        HttpClient http = httpResponse(status, new ByteArrayInputStream("{}".getBytes()));
        MockHttpServletRequest request = new MockHttpServletRequest();
        MockHttpSession session = (MockHttpSession) request.getSession();

        ResponseEntity<?> result = bff(manager(), http).get(id(), principal(), request);

        assertEquals(status, result.getStatusCode().value());
        assertTrue(!session.isInvalid());
        verify(http, times(1)).send(any(HttpRequest.class), any(HttpResponse.BodyHandler.class));
    }

    @Test
    void onlyApprovedPathsAndMethodsAreMapped() throws Exception {
        HttpClient http = mock(HttpClient.class);
        var mvc = org.springframework.test.web.servlet.setup.MockMvcBuilders
                .standaloneSetup(bff(manager(), http)).build();

        mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders
                .get("/bff/api/v1/mvp/other"))
                .andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isNotFound());
        mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders
                .post("/bff/api/v1/mvp/requests/00000000-0000-0000-0000-000000000001/delete"))
                .andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isNotFound());
        mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders
                .put("/bff/api/v1/mvp/requests"))
                .andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isMethodNotAllowed());
        verifyNoInteractions(http);
    }

    private static void assertUnusable(OAuth2AuthorizedClientManager manager) {
        HttpClient http = mock(HttpClient.class);
        MockHttpServletRequest request = new MockHttpServletRequest();
        MockHttpSession session = (MockHttpSession) request.getSession();

        ResponseEntity<?> result = bff(manager, http).get(id(), principal(), request);

        assertEquals(401, result.getStatusCode().value());
        assertEquals(null, result.getBody());
        assertTrue(session.isInvalid());
        verifyNoInteractions(http);
    }

    private static PortalBackendClient bff(OAuth2AuthorizedClientManager manager, HttpClient http) {
        return new PortalBackendClient(new PortalAuthorization(manager), "https://api.example.test", http);
    }

    private static UUID id() {
        return UUID.fromString("00000000-0000-0000-0000-000000000001");
    }

    private static HttpClient httpResponse(int status, InputStream stream) throws Exception {
        HttpClient http = mock(HttpClient.class);
        HttpResponse<InputStream> upstream = response(status, stream);
        when(http.send(any(HttpRequest.class), any(HttpResponse.BodyHandler.class)))
                .thenReturn(upstream);
        return http;
    }

    @SuppressWarnings("unchecked")
    private static HttpResponse<InputStream> response(int status, InputStream stream) {
        HttpResponse<InputStream> response = mock(HttpResponse.class);
        when(response.statusCode()).thenReturn(status);
        when(response.body()).thenReturn(stream);
        return response;
    }

    private static final class CloseTrackingInputStream extends ByteArrayInputStream {
        private boolean closed;

        private CloseTrackingInputStream(byte[] bytes) {
            super(bytes);
        }

        @Override
        public void close() throws IOException {
            closed = true;
            super.close();
        }
    }

    private static final class FailingInputStream extends InputStream {
        private boolean closed;

        @Override
        public int read() throws IOException {
            throw new IOException("secret upstream detail");
        }

        @Override
        public void close() {
            closed = true;
        }
    }

    private static OAuth2AuthorizedClientManager manager() {
        return managerWithToken(new OAuth2AccessToken(OAuth2AccessToken.TokenType.BEARER,
                "server-access-token", Instant.now(), Instant.now().plusSeconds(300)));
    }

    private static OAuth2AuthorizedClientManager managerWithToken(OAuth2AccessToken token) {
        OAuth2AuthorizedClientManager manager = mock(OAuth2AuthorizedClientManager.class);
        ClientRegistration registration = ClientRegistration.withRegistrationId("keycloak")
                .clientId("test").clientSecret("test")
                .authorizationGrantType(AuthorizationGrantType.AUTHORIZATION_CODE)
                .redirectUri("{baseUrl}/login/oauth2/code/{registrationId}")
                .authorizationUri("https://idp.example.test/auth")
                .tokenUri("https://idp.example.test/token").build();
        when(manager.authorize(any())).thenReturn(new OAuth2AuthorizedClient(registration, "test-user", token));
        return manager;
    }

    private static OAuth2AuthenticationToken principal() {
        var user = new DefaultOAuth2User(List.of(new SimpleGrantedAuthority("ROLE_USER")),
                Map.of("sub", "test-user"), "sub");
        return new OAuth2AuthenticationToken(user, user.getAuthorities(), "keycloak");
    }
}

package com.tricore.dxos.portal;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.BeforeEach;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;
import org.springframework.boot.test.context.TestConfiguration;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Import;
import org.springframework.security.oauth2.client.registration.ClientRegistration;
import org.springframework.security.oauth2.client.registration.ClientRegistrationRepository;
import org.springframework.security.oauth2.client.registration.InMemoryClientRegistrationRepository;
import org.springframework.security.oauth2.client.OAuth2AuthorizedClient;
import org.springframework.security.oauth2.client.OAuth2AuthorizedClientManager;
import org.springframework.security.oauth2.core.AuthorizationGrantType;
import org.springframework.security.oauth2.core.ClientAuthenticationMethod;
import org.springframework.security.oauth2.core.OAuth2AccessToken;
import org.springframework.security.oauth2.core.OAuth2AuthorizationException;
import org.springframework.security.oauth2.core.OAuth2Error;
import org.springframework.mock.web.MockHttpSession;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.test.web.servlet.MockMvc;

import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.oauth2Login;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.header;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.when;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.verifyNoInteractions;

import java.time.Instant;

@WebMvcTest(controllers = {PortalSessionController.class, PortalBackendClient.class},
        properties = {"dxos.portal-bff.backend-base-url=http://127.0.0.1:1",
                "dxos.portal-bff.public-origin=https://portal.example.test"})
@Import({PortalSecurity.class, PortalAuthorization.class, PortalSecurityTest.Registration.class})
class PortalSecurityTest {
    @Autowired MockMvc mvc;
    @MockitoBean OAuth2AuthorizedClientManager manager;
    @MockitoBean PortalBackendClient backend;

    @BeforeEach
    void usableAuthorization() {
        OAuth2AuthorizedClient client = org.mockito.Mockito.mock(OAuth2AuthorizedClient.class);
        when(client.getAccessToken()).thenReturn(new OAuth2AccessToken(OAuth2AccessToken.TokenType.BEARER,
                "test-only-access-token", Instant.now(), Instant.now().plusSeconds(300)));
        when(manager.authorize(any())).thenReturn(client);
    }

    @Test
    void anonymousSessionDoesNotExposeTokens() throws Exception {
        mvc.perform(get("/bff/session"))
                .andExpect(status().isOk())
                .andExpect(header().string("Cache-Control", "no-store"))
                .andExpect(jsonPath("$.authenticated").value(false))
                .andExpect(jsonPath("$.accessToken").doesNotExist());
    }

    @Test
    void forgedHeadersCannotEnterBackendApi() throws Exception {
        mvc.perform(get("/bff/api/v1/mvp/requests")
                        .header("X-User", "admin").header("X-Role", "workflow:read"))
                .andExpect(status().isUnauthorized());
    }

    @Test
    void logoutRequiresCsrf() throws Exception {
        mvc.perform(post("/bff/logout").with(oauth2Login()))
                .andExpect(status().isForbidden());
    }

    @Test
    void apiWriteRequiresTheSessionCsrfHeader() throws Exception {
        MockHttpSession session = new MockHttpSession();
        String body = mvc.perform(get("/bff/session").session(session).with(oauth2Login()))
                .andExpect(status().isOk()).andReturn().getResponse().getContentAsString();
        String token = new com.fasterxml.jackson.databind.ObjectMapper().readTree(body).get("csrfToken").asText();

        mvc.perform(post("/bff/api/v1/mvp/requests").session(session).with(oauth2Login())
                        .contentType("application/json").content("{}"))
                .andExpect(status().isForbidden());
        mvc.perform(post("/bff/api/v1/mvp/requests").session(session).with(oauth2Login())
                        .header("X-CSRF-TOKEN", "forged").contentType("application/json").content("{}"))
                .andExpect(status().isForbidden());
        verifyNoInteractions(backend);

        mvc.perform(post("/bff/api/v1/mvp/requests").session(session).with(oauth2Login())
                        .header("X-CSRF-TOKEN", token).contentType("application/json").content("{}"))
                .andExpect(status().isOk());
        verify(backend).create(any(), any());
    }

    @Test
    void signedInSessionReturnsOnlySessionStateAndCsrf() throws Exception {
        mvc.perform(get("/bff/session").with(oauth2Login()))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.authenticated").value(true))
                .andExpect(jsonPath("$.csrfToken").isString())
                .andExpect(jsonPath("$.accessToken").doesNotExist());
    }

    @Test
    void failedRefreshDoesNotReportHealthySessionOrExposeProviderDetails() throws Exception {
        when(manager.authorize(any())).thenThrow(new OAuth2AuthorizationException(
                new OAuth2Error("invalid_grant", "sensitive provider detail", null)));
        MockHttpSession session = new MockHttpSession();

        mvc.perform(get("/bff/session").session(session).with(oauth2Login()))
                .andExpect(status().isOk())
                .andExpect(header().string("Cache-Control", "no-store"))
                .andExpect(jsonPath("$.authenticated").value(false))
                .andExpect(jsonPath("$.csrfToken").doesNotExist())
                .andExpect(jsonPath("$.accessToken").doesNotExist());
        assertThat(session.isInvalid()).isTrue();
    }

    @Test
    void missingAuthorizationDoesNotReportHealthySession() throws Exception {
        when(manager.authorize(any())).thenReturn(null);
        MockHttpSession session = new MockHttpSession();

        mvc.perform(get("/bff/session").session(session).with(oauth2Login()))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.authenticated").value(false))
                .andExpect(jsonPath("$.csrfToken").doesNotExist());
        assertThat(session.isInvalid()).isTrue();
    }

    @Test
    void authorizationRedirectUsesPkce() throws Exception {
        String redirect = mvc.perform(get("/oauth2/authorization/keycloak"))
                .andExpect(status().is3xxRedirection())
                .andReturn().getResponse().getRedirectedUrl();
        assertThat(redirect).contains("code_challenge=").contains("code_challenge_method=S256")
                .contains("state=");
    }

    @Test
    void publicOrReusedApiClientCannotConfigureTheBff() {
        var security = new PortalSecurity();
        for (ClientRegistration client : new ClientRegistration[]{
                Registration.client("tricore-api", ClientAuthenticationMethod.CLIENT_SECRET_BASIC),
                Registration.client("portal-test", ClientAuthenticationMethod.NONE)}) {
            var registrations = new InMemoryClientRegistrationRepository(client);
            assertThatThrownBy(() -> security.portalFilterChain(null, registrations, "https://portal.example.test"))
                    .isInstanceOf(IllegalArgumentException.class);
        }
    }

    @TestConfiguration(proxyBeanMethods = false)
    static class Registration {
        @Bean
        ClientRegistrationRepository registrations() {
            return new InMemoryClientRegistrationRepository(client("portal-test", ClientAuthenticationMethod.CLIENT_SECRET_BASIC));
        }

        static ClientRegistration client(String clientId, ClientAuthenticationMethod method) {
            return ClientRegistration.withRegistrationId("keycloak")
                    .clientId(clientId).clientSecret("test-only").clientAuthenticationMethod(method)
                    .authorizationGrantType(AuthorizationGrantType.AUTHORIZATION_CODE)
                    .redirectUri("https://portal.example.test/login/oauth2/code/keycloak")
                    .scope("openid")
                    .authorizationUri("https://idp.example.test/auth")
                    .tokenUri("https://idp.example.test/token")
                    .jwkSetUri("https://idp.example.test/keys")
                    .userInfoUri("https://idp.example.test/userinfo")
                    .userNameAttributeName("sub").build();
        }
    }
}

param([switch]$ExecuteDisposable, [string]$JavaHome = 'C:\Program Files\Java\jdk-21.0.11')
$ErrorActionPreference = 'Stop'
$root = (Resolve-Path (Join-Path $PSScriptRoot '..')).Path
$backend = Join-Path $root 'backend'
$container = 'dxos-b06-' + [Guid]::NewGuid().ToString('N')
$success = $false
$started = $false
$locationPushed = $false
$keys = @('JAVA_HOME','Path','POSTGRES_PASSWORD','HELPDESK_DISPOSABLE_URL','HELPDESK_DISPOSABLE_PASSWORD','WORKFLOW_EVENT_GUARD_LOCAL_DISPOSABLE')
$saved = @{}
foreach ($name in $keys) { $saved[$name] = [Environment]::GetEnvironmentVariable($name,'Process') }
try {
    if (-not $ExecuteDisposable) { throw 'Use -ExecuteDisposable to approve the local ephemeral Docker database.' }
    foreach ($role in @('EMPLOYEE','COORDINATOR','WORKER','FOREIGN')) {
        $key = 'B06_' + $role + '_ACCESS_TOKEN'
        if ([string]::IsNullOrWhiteSpace([Environment]::GetEnvironmentVariable($key,'Process'))) {
            throw ('Missing Keycloak test access token: ' + $key)
        }
    }
    if (-not (Test-Path -LiteralPath (Join-Path $JavaHome 'bin\java.exe') -PathType Leaf)) { throw 'JDK 21 missing' }
    if (-not (Get-Command docker -ErrorAction SilentlyContinue)) { throw 'Docker CLI missing' }
    $engine = & docker --context desktop-linux info --format '{{.OSType}}'
    if ($LASTEXITCODE -ne 0 -or $engine -ne 'linux') { throw 'Local Docker Linux Engine required' }
    if (@(Get-NetTCPConnection -State Listen -ErrorAction Stop | Where-Object LocalPort -eq 55439).Count) { throw 'Disposable PostgreSQL port 55439 is occupied' }
    $env:JAVA_HOME = $JavaHome
    $env:Path = "$JavaHome\bin;$env:Path"
    $originalPreference = $ErrorActionPreference
    try {
        $ErrorActionPreference = 'Continue'
        $versionOutput = & (Join-Path $JavaHome 'bin\java.exe') -version 2>&1 | Out-String
    } finally { $ErrorActionPreference = $originalPreference }
    if ($versionOutput -notmatch 'version "21\.') { throw 'Only JDK 21 is supported' }
    $head = (& git -C $root rev-parse HEAD).Trim()
    if ($LASTEXITCODE -ne 0 -or $head -notmatch '^[0-9a-f]{40}$') { throw 'Unverifiable HEAD' }
    Write-Output ('B06_HEAD=' + $head)
    Write-Output 'B06_DB=jdbc:postgresql://127.0.0.1:55439/helpdesk_disposable_test'
    $pw = [Guid]::NewGuid().ToString('N') + [Guid]::NewGuid().ToString('N')
    $env:POSTGRES_PASSWORD = $pw
    $dockerArgs = @('--context','desktop-linux','run','--rm','-d','--pull=never','--name',$container,
        '--label',('dxos.helpdesk.owner=' + $container),'--mount','type=tmpfs,destination=/var/lib/postgresql/data','-p','127.0.0.1:55439:5432',
        '-e','POSTGRES_USER=helpdesk_test','-e','POSTGRES_DB=helpdesk_disposable_test',
        '-e','POSTGRES_PASSWORD','postgres:17.11-alpine')
    # Separate image pull so progress output cannot contaminate the container-id check.
    $null = & docker --context desktop-linux pull 'postgres:17.11-alpine' 2>&1
    if ($LASTEXITCODE -ne 0) { throw 'PostgreSQL 17 image not available' }
    $id = (& docker @dockerArgs 2>&1 | Out-String).Trim()
    if ($LASTEXITCODE -ne 0 -or $id -notmatch '^[0-9a-f]{64}$') { throw 'Disposable PG17 launch failed' }
    $started = $true
    $ready = $false
    for ($i=0; $i -lt 60; $i++) {
        $null = & docker --context desktop-linux exec $id pg_isready -U helpdesk_test -d helpdesk_disposable_test 2>&1
        if ($LASTEXITCODE -eq 0) { $ready=$true; break }
        Start-Sleep -Seconds 1
    }
    if (-not $ready) { throw 'Disposable PG17 not ready' }
    $env:HELPDESK_DISPOSABLE_URL='jdbc:postgresql://127.0.0.1:55439/helpdesk_disposable_test'
    $env:HELPDESK_DISPOSABLE_PASSWORD=$pw
    $env:WORKFLOW_EVENT_GUARD_LOCAL_DISPOSABLE='true'
    Push-Location $backend
    $locationPushed = $true
    $argsGradle = @('--no-daemon','--no-configuration-cache','--rerun-tasks','test',
        '--tests','com.tricore.dxos.infrastructure.workflow.HelpdeskConfigurationTest',
        '--tests','com.tricore.dxos.infrastructure.workflow.HelpdeskHttpPostgresTest')
    $originalPreference = $ErrorActionPreference
    try {
        $ErrorActionPreference = 'Continue'
        & '.\gradlew.bat' @argsGradle
        $gradleExit = $LASTEXITCODE
    } finally { $ErrorActionPreference = $originalPreference }
    if ($gradleExit -ne 0) { throw 'Gradle focused tests failed' }
    foreach ($suite in @(@{Name='HelpdeskConfigurationTest';Tests=2},@{Name='HelpdeskHttpPostgresTest';Tests=47})) {
        $prefix='com.tricore.dxos.infrastructure.workflow.'
        $xmlFile=Join-Path $backend ('build\test-results\test\TEST-'+$prefix+$suite.Name+'.xml')
        if (-not (Test-Path -LiteralPath $xmlFile -PathType Leaf)) { throw 'JUnit report absent' }
        [xml]$doc=Get-Content -LiteralPath $xmlFile -Raw
        $s=$doc.testsuite
        if ([int]$s.tests -ne $suite.Tests -or [int]$s.failures -ne 0 -or [int]$s.errors -ne 0 -or [int]$s.skipped -ne 0) {
            throw ('JUnit verification failed: '+$suite.Name)
        }
        Write-Output ($suite.Name + '=' + $s.tests + '_PASS_0_FAIL_0_SKIP')
    }
    Write-Output 'B06_RESULT=PASS'
    $success = $true
} catch {
    Write-Output 'B06_RESULT=FAIL'
    Write-Output ('B06_FAILURE_TYPE=' + $_.Exception.GetType().Name)
} finally {
    if ($locationPushed) { Pop-Location }
    foreach ($name in $keys) { [Environment]::SetEnvironmentVariable($name,$saved[$name],'Process') }
    if ($started) {
        $owned = (& docker --context desktop-linux inspect --format '{{.Id}}|{{.Name}}|{{index .Config.Labels "dxos.helpdesk.owner"}}' $id | Out-String).Trim()
        if ($LASTEXITCODE -ne 0 -or $owned -ne ($id + '|/' + $container + '|' + $container)) { throw 'Refusing cleanup: container ID/ownership mismatch' }
        $null = & docker --context desktop-linux rm -f $id
        if ($LASTEXITCODE -ne 0) { throw 'Owned disposable container cleanup failed' }
    }
    if ($started) { Write-Output 'B06_EPHEMERAL_CONTAINER=CLEANED' }
}
if ($success) { exit 0 } else { exit 1 }

param(
    [Parameter(Mandatory)][string]$KeycloakIssuer,
    [Parameter(Mandatory)][string[]]$Subjects,
    [ValidatePattern('(?-i)\A[a-z][a-z0-9_]{0,62}\z')][string]$Schema = 'helpdesk_demo',
    [ValidatePattern('(?-i)\A[a-z0-9_-]{1,63}\z')][string]$Tenant = 'demo',
    [string]$TrustedDemoRealmFile
)
$ErrorActionPreference = 'Stop'
$uri = $null
if (-not [Uri]::TryCreate($KeycloakIssuer, [UriKind]::Absolute, [ref]$uri) -or
    $uri.Scheme -notin @('http','https') -or $uri.UserInfo -or $uri.Query -or $uri.Fragment -or
    $Subjects.Count -ne 3 -or
    @($Subjects | Where-Object { [string]::IsNullOrWhiteSpace($_) -or $_ -match '[\x00-\x1f\x7f]' }).Count -gt 0 -or
    @($Subjects | Select-Object -Unique).Count -ne 3) {
    throw 'Supply the exact issuer and three distinct user sub values'
}
$names = @($null, $null, $null)
if ($TrustedDemoRealmFile) {
    # Operator supplies the original trusted local realm provisioning file, never a Portal payload.
    try { $realm = Get-Content -LiteralPath $TrustedDemoRealmFile -Raw | ConvertFrom-Json }
    catch { throw 'Cannot read trusted demo realm file; contents suppressed' }
    if (-not $uri.IsLoopback -or $realm.realm -isnot [string] -or
        [string]::IsNullOrWhiteSpace($realm.realm) -or
        $uri.AbsolutePath -cne ('/realms/' + [Uri]::EscapeDataString($realm.realm))) {
        throw 'Trusted demo realm must match the exact local issuer realm'
    }
    $usernames = @('employee-demo','coordinator-demo','worker-demo')
    for ($i=0; $i -lt 3; $i++) {
        $users = @($realm.users | Where-Object { $_.username -ceq $usernames[$i] })
        if ($users.Count -ne 1 -or $users[0].id -isnot [string] -or
            $users[0].id -cne $Subjects[$i] -or
            $users[0].firstName -isnot [string] -or $users[0].lastName -isnot [string] -or
            [string]::IsNullOrWhiteSpace($users[0].firstName) -or [string]::IsNullOrWhiteSpace($users[0].lastName)) {
            throw 'Trusted demo identity must have one matching username, exact subject and supplied name'
        }
        $names[$i] = $users[0].firstName.Trim() + ' ' + $users[0].lastName.Trim()
        if ($names[$i].Length -gt 200 -or $names[$i] -match '[\x00-\x1f\x7f]') {
            throw 'Invalid trusted demo display name'
        }
    }
}
function Encode([string]$Value) {
    [Convert]::ToBase64String([Text.UTF8Encoding]::new($false,$true).GetBytes($Value)).TrimEnd('=').Replace('+','-').Replace('/','_')
}
for ($i=0; $i -lt 3; $i++) {
    $actor = 'oidc:' + (Encode $KeycloakIssuer) + '.' + (Encode $Subjects[$i])
    $flags = @('true,false,false','false,true,false','false,false,true')[$i]
    $nameSql = if ($null -eq $names[$i]) { 'NULL' } else { "'" + $names[$i].Replace("'", "''") + "'" }
    "INSERT INTO $Schema.tenant_memberships VALUES ('$Tenant','$actor',true);"
    "INSERT INTO $Schema.helpdesk_actors (tenant_id,actor_id,submitter,coordinator,worker,display_name) VALUES ('$Tenant','$actor',$flags,$nameSql);"
}

param(
    [Parameter(Mandatory)][ValidatePattern('(?-i)\A[a-z][a-z0-9_]{0,23}\z')][string]$RunId,
    [ValidateRange(1024,65535)][int]$Port = 55440,
    [ValidatePattern('(?-i)\A[a-z0-9_-]{1,63}\z')][string]$Tenant = 'demo',
    [string]$KeycloakIssuer,
    [string]$EmployeeSubject,
    [string]$CoordinatorSubject,
    [string]$WorkerSubject,
    [switch]$Execute,
    [string]$ConfirmDemoDatabase,
    [string]$TrustedDemoRealmFile
)
$ErrorActionPreference = 'Stop'
$root = (Resolve-Path (Join-Path $PSScriptRoot '..')).Path
$database = 'helpdesk_disposable_' + $RunId
$container = 'dxos-helpdesk-' + $RunId
$volume = $container + '-data'
$schema = 'helpdesk_demo'
$owner = 'helpdesk_owner_' + $RunId
$runtime = 'helpdesk_runtime_' + $RunId
$image = 'postgres:17.11-alpine'

function Invoke-DemoDocker([string[]]$Arguments) {
    $output = & docker --context desktop-linux @Arguments 2>&1
    if ($LASTEXITCODE -ne 0) { throw ('Docker operation failed: ' + $Arguments[0]) }
    return $output
}
function Sql([string]$Text, [string]$User, [string]$Password) {
    $previous = $env:PGPASSWORD
    try {
        $env:PGPASSWORD = $Password
        $output = $Text | & docker --context desktop-linux exec -i -e PGPASSWORD -e HELPDESK_RUNTIME_PASSWORD $container `
            psql -X -q -A -t -w -h 127.0.0.1 -U $User -d $database -v ON_ERROR_STOP=1 2>&1
        if ($LASTEXITCODE -ne 0) { throw 'SQL operation failed; no SQL/credentials logged. Container retained for inspection.' }
        return $output
    } finally { $env:PGPASSWORD = $previous }
}
function Secret([string]$Name) {
    $value = [Environment]::GetEnvironmentVariable($Name, 'Process')
    if ([string]::IsNullOrEmpty($value)) {
        $secure = Read-Host $Name -AsSecureString
        $ptr = [Runtime.InteropServices.Marshal]::SecureStringToBSTR($secure)
        try { $value = [Runtime.InteropServices.Marshal]::PtrToStringBSTR($ptr) }
        finally { [Runtime.InteropServices.Marshal]::ZeroFreeBSTR($ptr) }
    }
    if ($value.Length -lt 24 -or $value -match '[\x00-\x1f\x7f]') { throw "$Name requires at least 24 characters and no control characters" }
    return $value
}
# The existing candidate accepts exactly this loopback database/runtime naming convention.
$subjects = @($EmployeeSubject, $CoordinatorSubject, $WorkerSubject)
$seedActors = -not [string]::IsNullOrEmpty($KeycloakIssuer) -or @($subjects | Where-Object { $_ }).Count -gt 0
if ($seedActors) {
    $actorSeed = & (Join-Path $PSScriptRoot 'helpdesk-local-actor-seed.ps1') -KeycloakIssuer $KeycloakIssuer `
        -Subjects $subjects -Schema $schema -Tenant $Tenant -TrustedDemoRealmFile $TrustedDemoRealmFile
} elseif ($TrustedDemoRealmFile) { throw 'Trusted demo names require the exact issuer and all three subjects' }
if ($Execute -and $ConfirmDemoDatabase -cne $database) { throw "Execution requires -ConfirmDemoDatabase $database" }
$files = @('db/migration/V3__create_workflow_persistence.sql', 'db/helpdesk/policy-schema.sql',
    'db/helpdesk/schema.sql', 'db/helpdesk/definition.sql', 'db/helpdesk/runtime-grants.sql')
$sql = foreach ($file in $files) {
    (Get-Content -LiteralPath (Join-Path $root ('backend/src/main/resources/' + $file)) -Raw).
        Replace('${flyway:defaultSchema}', $schema).Replace('${helpdesk:runtimeRole}', $runtime)
}
if (-not (Get-Command docker -ErrorAction SilentlyContinue)) { throw 'Docker CLI required' }
$endpoint = (Invoke-DemoDocker -Arguments @('context','inspect','desktop-linux','--format','{{.Endpoints.docker.Host}}') | Out-String).Trim()
if ($endpoint -notmatch '^npipe:/{4}\./pipe/dockerDesktopLinuxEngine$') { throw 'Only the local Docker Desktop Linux named pipe is supported' }
if ((Invoke-DemoDocker -Arguments @('info','--format','{{.OSType}}') | Out-String).Trim() -ne 'linux') { throw 'Local Linux engine required' }
$null = Invoke-DemoDocker -Arguments @('image','inspect',$image,'--format','{{.Id}}')
if (@(Invoke-DemoDocker -Arguments @('ps','-a','--format','{{.Names}}')) -contains $container -or
    @(Invoke-DemoDocker -Arguments @('volume','ls','--format','{{.Name}}')) -contains $volume) { throw 'Demo container or volume already exists; use a new RunId. Nothing changed.' }
if (@(Get-NetTCPConnection -State Listen -ErrorAction Stop | Where-Object LocalPort -eq $Port).Count) { throw 'Demo port is occupied' }
Write-Output "PREFLIGHT=PASS DATABASE=$database ENDPOINT=127.0.0.1:$Port CONTAINER=$container VOLUME=$volume"
if (-not $Execute) { Write-Output 'SETUP=NOT_RUN (use -Execute and -ConfirmDemoDatabase)'; return }

$savedPostgres = $env:POSTGRES_PASSWORD
$savedRuntime = $env:HELPDESK_RUNTIME_PASSWORD
try {
    $setupPassword = Secret 'HELPDESK_SETUP_PASSWORD'
    $runtimePassword = Secret 'HELPDESK_RUNTIME_PASSWORD'
    if ($setupPassword -ceq $runtimePassword) { throw 'Setup and runtime passwords must differ' }
    $env:POSTGRES_PASSWORD = $setupPassword
    $env:HELPDESK_RUNTIME_PASSWORD = $runtimePassword
    $instance = [Guid]::NewGuid().ToString('N')
    $null = Invoke-DemoDocker -Arguments @('volume','create','--label',"dxos.helpdesk.demo=$RunId",'--label',"dxos.helpdesk.instance=$instance",$volume)
    $createdVolume = (Invoke-DemoDocker -Arguments @('volume','inspect',$volume) | Out-String) | ConvertFrom-Json
    if ($createdVolume[0].Labels.'dxos.helpdesk.instance' -cne $instance) { throw 'Refusing an existing volume (concurrent setup); nothing deleted' }
    $null = Invoke-DemoDocker -Arguments @('run','-d','--pull=never','--name',$container,'--label',"dxos.helpdesk.demo=$RunId",
        '-p',"127.0.0.1:${Port}:5432",'--mount',"type=volume,source=$volume,target=/var/lib/postgresql/data",
        '-e',"POSTGRES_DB=$database",'-e','POSTGRES_USER=helpdesk_setup','-e','POSTGRES_PASSWORD',
        '-e','POSTGRES_INITDB_ARGS=--auth-host=scram-sha-256',$image,
        '-c','log_statement=none','-c','log_min_error_statement=panic')
    $created = ((Invoke-DemoDocker -Arguments @('inspect',$container) | Out-String) | ConvertFrom-Json)[0]
    $binding = @($created.HostConfig.PortBindings.'5432/tcp')
    if ($created.Config.Labels.'dxos.helpdesk.demo' -cne $RunId -or $binding.Count -ne 1 -or
        $binding[0].HostIp -cne '127.0.0.1' -or $binding[0].HostPort -ne [string]$Port -or
        @($created.Mounts | Where-Object { $_.Type -eq 'volume' -and $_.Name -ceq $volume -and $_.Destination -ceq '/var/lib/postgresql/data' }).Count -ne 1) {
        throw 'Demo container isolation mismatch; resources retained'
    }
    $ready = $false
    for ($i=0; $i -lt 60; $i++) {
        $null = & docker --context desktop-linux exec $container pg_isready -h 127.0.0.1 -U helpdesk_setup -d $database 2>&1
        if ($LASTEXITCODE -eq 0) { $ready = $true; break }
        Start-Sleep -Seconds 1
    }
    if (-not $ready) { throw 'PostgreSQL not ready; resources retained, no automatic deletion' }
    $version = [int](Sql 'SHOW server_version_num;' 'helpdesk_setup' $setupPassword)
    if ($version -lt 170000 -or $version -ge 180000) { throw 'PostgreSQL 17 required' }
    $seed = @"
INSERT INTO $schema.tenant_guards VALUES ('$Tenant',0);
INSERT INTO $schema.workflow_definition_bindings VALUES ('$Tenant','mvp_request','it-helpdesk',1,true);
"@
    if ($seedActors) {
        $seed += "`n" + ($actorSeed -join "`n")
    }
    $install = @"
BEGIN;
CREATE ROLE $owner NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS NOINHERIT;
\getenv runtime_secret HELPDESK_RUNTIME_PASSWORD
CREATE ROLE $runtime LOGIN PASSWORD :'runtime_secret' NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS NOINHERIT;
REVOKE ALL ON DATABASE $database FROM PUBLIC;
REVOKE ALL ON DATABASE postgres, template1 FROM PUBLIC;
GRANT CONNECT ON DATABASE $database TO $runtime;
REVOKE ALL ON SCHEMA public FROM PUBLIC;
CREATE SCHEMA $schema AUTHORIZATION $owner;
SET LOCAL ROLE $owner;
ALTER DEFAULT PRIVILEGES IN SCHEMA $schema REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC;
ALTER DEFAULT PRIVILEGES IN SCHEMA $schema REVOKE ALL ON TABLES FROM PUBLIC;
$($sql -join "`n")
$seed
REVOKE ALL ON SCHEMA $schema FROM PUBLIC;
REVOKE ALL ON ALL TABLES IN SCHEMA $schema FROM PUBLIC;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA $schema FROM PUBLIC;
SET CONSTRAINTS ALL IMMEDIATE;
COMMIT;
"@
    $null = Sql $install 'helpdesk_setup' $setupPassword
    # Fresh TCP login asserts the runtime credential, seed, sealing and effective privileges.
    $expectedActors = if ($seedActors) { 3 } else { 0 }
    $verify = @'
BEGIN READ ONLY;
DO $check$
BEGIN
    IF current_user <> 'RUNTIME' OR EXISTS (SELECT FROM pg_roles WHERE rolname=current_user AND
        (rolsuper OR rolcreatedb OR rolcreaterole OR rolreplication OR rolbypassrls)) OR
        EXISTS (SELECT FROM pg_auth_members WHERE member=(SELECT oid FROM pg_roles WHERE rolname=current_user)) OR
        has_database_privilege(current_user,current_database(),'CREATE') OR
        has_database_privilege(current_user,current_database(),'TEMP') OR
        EXISTS (SELECT FROM pg_database WHERE datallowconn AND datname<>current_database() AND has_database_privilege(current_user,oid,'CONNECT')) OR
        has_schema_privilege(current_user,'helpdesk_demo','CREATE') OR has_schema_privilege(current_user,'public','CREATE') THEN
        RAISE EXCEPTION 'runtime role is overprivileged';
    END IF;
    IF (SELECT count(*) FROM pg_class WHERE relnamespace='helpdesk_demo'::regnamespace AND relkind='r') <> 13 OR
        EXISTS (SELECT FROM pg_class WHERE relnamespace='helpdesk_demo'::regnamespace AND relowner=(SELECT oid FROM pg_roles WHERE rolname=current_user)) OR
        EXISTS (SELECT FROM pg_class c CROSS JOIN LATERAL aclexplode(c.relacl) a WHERE c.relnamespace='helpdesk_demo'::regnamespace AND a.grantee=0) OR
        EXISTS (SELECT FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE p.pronamespace='helpdesk_demo'::regnamespace AND a.grantee=0) OR
        (SELECT count(*) FROM pg_proc WHERE pronamespace='helpdesk_demo'::regnamespace) <> 4 OR
        EXISTS (SELECT FROM pg_proc WHERE pronamespace='helpdesk_demo'::regnamespace AND (prosecdef OR proname LIKE 'wf_port_%')) THEN
        RAISE EXCEPTION 'schema ownership/PUBLIC grants/function inventory mismatch';
    END IF;
    IF EXISTS (SELECT FROM pg_class WHERE relnamespace='helpdesk_demo'::regnamespace AND relkind='r' AND
        (has_table_privilege(current_user,oid,'DELETE,TRUNCATE,TRIGGER,REFERENCES,UPDATE') OR
         has_table_privilege(current_user,oid,'SELECT') <> (relname <> 'workflow_policy_audit') OR
         has_table_privilege(current_user,oid,'INSERT') <> (relname IN ('resource_registry','resource_acl','helpdesk_requests','workflow_instances','workflow_transition_history')))) OR
        EXISTS (SELECT FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid
            WHERE c.relnamespace='helpdesk_demo'::regnamespace AND a.attnum>0 AND NOT a.attisdropped AND
            has_column_privilege(current_user,c.oid,a.attnum,'UPDATE') <>
            ((c.relname='tenant_guards' AND a.attname='acl_revision') OR
             (c.relname='resource_acl' AND a.attname='granted') OR
             (c.relname='helpdesk_requests' AND a.attname IN ('assignee_id','assignment_version','resolution')) OR
             (c.relname='workflow_instances' AND a.attname IN ('current_state','runtime_version','lifecycle','updated_at_seconds','updated_at_nanos')))) THEN
        RAISE EXCEPTION 'runtime data grants mismatch';
    END IF;
    IF (SELECT count(*) FROM helpdesk_demo.workflow_definitions WHERE definition_id='it-helpdesk' AND definition_version=1 AND initial_state='SUBMITTED' AND provisioning_transaction<>txid_current()) <> 1 OR
        (SELECT count(*) FROM helpdesk_demo.workflow_definition_states) <> 5 OR
        (SELECT count(*) FROM helpdesk_demo.workflow_definition_transitions) <> 4 OR
        (SELECT count(*) FROM helpdesk_demo.workflow_definition_bindings WHERE tenant_id='TENANT' AND resource_type='mvp_request' AND definition_id='it-helpdesk' AND definition_version=1 AND active) <> 1 OR
        (SELECT count(*) FROM helpdesk_demo.tenant_guards WHERE tenant_id='TENANT') <> 1 OR
        (SELECT count(*) FROM helpdesk_demo.tenant_memberships WHERE active) <> ACTORS OR
        (SELECT count(*) FROM helpdesk_demo.helpdesk_actors) <> ACTORS THEN
        RAISE EXCEPTION 'definition/seed verification failed';
    END IF;
END;
$check$;
ROLLBACK;
SELECT 'TCP_LOGIN_AND_CATALOG=PASS';
'@
    Sql ($verify.Replace('RUNTIME',$runtime).Replace('TENANT',$Tenant).Replace('ACTORS',[string]$expectedActors)) $runtime $runtimePassword
    Write-Output "SETUP=PASS SCHEMA=$schema RUNTIME=$runtime ACTORS=$expectedActors"
    Write-Output 'KEYCLOAK_E2E=NOT_VERIFIED (supplied subjects are provisioning input, not proof of authentication)'
} finally {
    $env:POSTGRES_PASSWORD = $savedPostgres
    $env:HELPDESK_RUNTIME_PASSWORD = $savedRuntime
    $setupPassword = $null; $runtimePassword = $null; $install = $null
}

$ErrorActionPreference = 'Stop'
$seedScript = Join-Path $PSScriptRoot 'helpdesk-local-actor-seed.ps1'
$subjects = @('synthetic-employee','synthetic-coordinator','synthetic-worker')
$issuer = 'http://127.0.0.1:8182/realms/tricore'
$realm = @{ realm='tricore'; users=@(
    @{ username='employee-demo'; id=$subjects[0]; firstName='Employee'; lastName='Demo' },
    @{ username='coordinator-demo'; id=$subjects[1]; firstName='Coordinator'; lastName='Demo' },
    @{ username='worker-demo'; id=$subjects[2]; firstName='Worker'; lastName='Demo' }
) }
$file = Join-Path ([IO.Path]::GetTempPath()) ('dxos-demo-identities-' + [Guid]::NewGuid().ToString('N') + '.json')
function Assert([bool]$Condition, [string]$Message) { if (-not $Condition) { throw $Message } }
function Reject([scriptblock]$Action) {
    $rejected = $false
    try { $null = & $Action } catch { $rejected = $true }
    Assert $rejected 'Expected provisioning rejection'
}
try {
    $realm | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath $file -Encoding UTF8
    $bare = @(& $seedScript -KeycloakIssuer $issuer -Subjects $subjects)
    $named = @(& $seedScript -KeycloakIssuer $issuer -Subjects $subjects -TrustedDemoRealmFile $file)
    Assert ($named.Count -eq 6) 'Expected three memberships and three actors'
    foreach ($name in @('Employee Demo','Coordinator Demo','Worker Demo')) {
        Assert (($named -join "`n").Contains("'$name'")) 'Missing trusted display name'
    }
    Write-Output 'PASS verified-name-present'
    Assert (@($bare | Where-Object { $_ -match ',NULL\);$' }).Count -eq 3) 'Missing NULL fallback'
    Write-Output 'PASS null-fallback'
    $withoutNames = @($named | ForEach-Object { $_ -replace "'(Employee|Coordinator|Worker) Demo'(?=\);$)", 'NULL' })
    Assert (($withoutNames -join "`n") -ceq ($bare -join "`n")) 'Display names changed canonical actor, membership or authority flags'
    Write-Output 'PASS canonical-subject-and-authority-unchanged'
    Reject { & $seedScript -KeycloakIssuer $issuer -Subjects @('wrong-subject',$subjects[1],$subjects[2]) -TrustedDemoRealmFile $file }
    Write-Output 'PASS mismatched-subject-rejected'
    Reject { & $seedScript -KeycloakIssuer ($issuer + '-other') -Subjects $subjects -TrustedDemoRealmFile $file }
    Write-Output 'PASS mismatched-realm-rejected'
    $realm.users[0].firstName = "Emplo'yee"
    $realm | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath $file -Encoding UTF8
    $escaped = @(& $seedScript -KeycloakIssuer $issuer -Subjects $subjects -TrustedDemoRealmFile $file)
    Assert (($escaped -join "`n").Contains("'Emplo''yee Demo'")) 'Display name must be SQL escaped'
    Write-Output 'PASS name-sql-escaped'
    $realm.users += $realm.users[0]
    $realm | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath $file -Encoding UTF8
    Reject { & $seedScript -KeycloakIssuer $issuer -Subjects $subjects -TrustedDemoRealmFile $file }
    Write-Output 'PASS ambiguous-user-rejected'
} finally { if (Test-Path -LiteralPath $file) { Remove-Item -LiteralPath $file } }

package com.tricore.dxos.core.data;

import java.io.InputStream;

/**
 * One read resource: metadata and stream describe the same object version.
 * Caller closes this resource, including after partial consumption or failure.
 * The adapter owns the returned stream and releases it on close; close is idempotent.
 * The stream is single-use and unusable after close (INVALID_INPUT).
 * Closing the stream also releases its underlying read resources.
 * Metadata remains available after close.
 * Adapters normalize failures during lazy reads and close to StorageException,
 * never exposing raw provider IOExceptions or causes through the stream.
 */
public interface ObjectContent extends AutoCloseable {
    ObjectMetadata metadata();

    InputStream content();

    @Override
    void close();
}

package com.tricore.dxos.core.data;

/** Opaque, case-sensitive key within the configured storage namespace; preserved verbatim. */
public record ObjectKey(String value) {
    public ObjectKey {
        value = StorageValues.text(value);
    }
}

package com.tricore.dxos.core.data;

import java.util.Map;

/** Immutable content description; length is the exact byte count, including zero. */
public record ObjectMetadata(ObjectKey key, String contentType, long contentLength,
                             Map<String, String> customMetadata) {
    public ObjectMetadata {
        StorageValues.required(key);
        contentType = StorageValues.text(contentType);
        if (contentLength < 0) {
            throw new StorageException(StorageErrorCode.INVALID_INPUT);
        }
        StorageValues.required(customMetadata).forEach((name, value) -> {
            StorageValues.text(name);
            StorageValues.required(value);
        });
        customMetadata = Map.copyOf(customMetadata);
    }
}

package com.tricore.dxos.core.data;

/**
 * Provider-neutral Data capability. All invalid inputs and operational failures use
 * StorageException. No database/object-storage distributed transaction is implied.
 */
public interface ObjectStoragePort {
    /**
     * Synchronously consumes content from its current position through EOF, requiring
     * the exact declared byte length (mismatch or caller-input read failure is INVALID_INPUT).
     * Never closes or retains caller input. Returns stored metadata on success.
     * CREATE_ONLY must enforce absence
     * even with concurrent writers; conflict leaves the existing object unchanged.
     * OVERWRITE replaces content and metadata; no version comparison is provided.
     * Other failures may have an uncertain provider outcome; no blanket rollback guarantee.
     */
    ObjectMetadata store(StoreObjectCommand command);

    /** Returns an owned read resource for try-with-resources; missing key is NOT_FOUND. */
    ObjectContent read(ObjectKey key);

    /** Returns metadata without opening a content resource; missing key is NOT_FOUND. */
    ObjectMetadata metadata(ObjectKey key);

    /** Removes the object and its metadata; missing key is NOT_FOUND, including repeated delete. */
    void delete(ObjectKey key);
}

package com.tricore.dxos.core.data;

/** Stable Data capability errors; transport and provider mappings belong outside Core. */
public enum StorageErrorCode {
    INVALID_INPUT,
    NOT_FOUND,
    CONFLICT,
    UNAVAILABLE,
    ACCESS_FAILURE
}

package com.tricore.dxos.core.data;

import java.util.Objects;

/** Sanitized failure: no external message, provider cause, suppression or stack trace. */
public final class StorageException extends RuntimeException {
    private final StorageErrorCode code;

    public StorageException(StorageErrorCode code) {
        super(Objects.requireNonNull(code, "code").name(), null, false, false);
        this.code = code;
    }

    public StorageErrorCode code() {
        return code;
    }
}

package com.tricore.dxos.core.data;

/** Data-local structural validation; invalid contract inputs use the normalized error. */
final class StorageValues {
    private StorageValues() {}

    static <T> T required(T value) {
        if (value == null) {
            throw new StorageException(StorageErrorCode.INVALID_INPUT);
        }
        return value;
    }

    static String text(String value) {
        if (required(value).isBlank()) {
            throw new StorageException(StorageErrorCode.INVALID_INPUT);
        }
        return value;
    }
}

package com.tricore.dxos.core.data;

/** Mandatory write policy; no implicit default. */
public enum StoreMode {
    /** Create only if absent; an existing key produces CONFLICT without changing it. */
    CREATE_ONLY,
    /** Create if absent, otherwise replace both content and all metadata. */
    OVERWRITE
}

package com.tricore.dxos.core.data;

import java.io.InputStream;

/** Single-use synchronous input. Caller owns and closes content on success and failure. */
public record StoreObjectCommand(ObjectMetadata metadata, InputStream content, StoreMode mode) {
    public StoreObjectCommand {
        StorageValues.required(metadata);
        StorageValues.required(content);
        StorageValues.required(mode);
    }
}

package com.tricore.dxos.core.data;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.util.HashMap;
import java.util.Map;

/** Contract fake only. Small fixtures are buffered here; production adapters must stream. */
final class InMemoryObjectStorage implements ObjectStoragePort {
    private record Stored(ObjectMetadata metadata, byte[] bytes) {}

    private final Map<ObjectKey, Stored> objects = new HashMap<>();

    @Override
    public synchronized ObjectMetadata store(StoreObjectCommand command) {
        StorageValues.required(command);
        ObjectMetadata metadata = command.metadata();
        if (command.mode() == StoreMode.CREATE_ONLY && objects.containsKey(metadata.key())) {
            throw new StorageException(StorageErrorCode.CONFLICT);
        }
        byte[] bytes;
        try {
            bytes = command.content().readAllBytes();
        } catch (IOException error) {
            // Caller-input read failure is invalid input, never a provider cause.
            throw new StorageException(StorageErrorCode.INVALID_INPUT);
        }
        if (bytes.length != metadata.contentLength()) {
            throw new StorageException(StorageErrorCode.INVALID_INPUT);
        }
        objects.put(metadata.key(), new Stored(metadata, bytes));
        return metadata;
    }

    @Override
    public synchronized ObjectContent read(ObjectKey key) {
        Stored stored = load(key);
        return new ReadResource(stored);
    }

    @Override
    public synchronized ObjectMetadata metadata(ObjectKey key) {
        return load(key).metadata();
    }

    @Override
    public synchronized void delete(ObjectKey key) {
        load(key);
        objects.remove(key);
    }

    private Stored load(ObjectKey key) {
        Stored stored = objects.get(StorageValues.required(key));
        if (stored == null) {
            throw new StorageException(StorageErrorCode.NOT_FOUND);
        }
        return stored;
    }

    private static final class ReadResource implements ObjectContent {
        private final ObjectMetadata metadata;
        private final InputStream stream;
        private boolean closed;

        private ReadResource(Stored stored) {
            metadata = stored.metadata();
            ByteArrayInputStream bytes = new ByteArrayInputStream(stored.bytes());
            stream = new InputStream() {
                @Override
                public int read() {
                    requireOpen();
                    return bytes.read();
                }

                @Override
                public int read(byte[] buffer, int offset, int length) {
                    requireOpen();
                    return bytes.read(buffer, offset, length);
                }

                @Override
                public void close() {
                    ReadResource.this.close();
                }
            };
        }

        @Override
        public ObjectMetadata metadata() {
            return metadata;
        }

        @Override
        public InputStream content() {
            requireOpen();
            return stream;
        }

        @Override
        public void close() {
            closed = true;
        }

        private void requireOpen() {
            if (closed) {
                throw new StorageException(StorageErrorCode.INVALID_INPUT);
            }
        }
    }
}

package com.tricore.dxos.core.data;

import org.junit.jupiter.api.Test;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

class ObjectStoragePortTest {
    private static final ObjectKey KEY = new ObjectKey("documents/report");
    private final ObjectStoragePort storage = new InMemoryObjectStorage();

    @Test
    void storesReadsAndLooksUpMatchingMetadata() throws IOException {
        StoreObjectCommand command = command("hello", StoreMode.CREATE_ONLY);
        assertThat(storage.store(command)).isEqualTo(command.metadata());
        assertThat(storage.metadata(KEY)).isEqualTo(command.metadata());
        try (var object = storage.read(KEY)) {
            assertThat(object.metadata()).isEqualTo(command.metadata());
            assertThat(object.content().readAllBytes()).isEqualTo("hello".getBytes(StandardCharsets.UTF_8));
        }
    }

    @Test
    void deletesContentAndMetadataAndReportsMissingObjects() {
        storage.store(command("hello", StoreMode.CREATE_ONLY));
        storage.delete(KEY);
        assertError(() -> storage.read(KEY), StorageErrorCode.NOT_FOUND);
        assertError(() -> storage.metadata(KEY), StorageErrorCode.NOT_FOUND);
        assertError(() -> storage.delete(KEY), StorageErrorCode.NOT_FOUND);
    }

    @Test
    void createOnlyConflictPreservesContentMetadataAndCallerStream() throws IOException {
        ObjectMetadata original = storage.store(command("original", StoreMode.CREATE_ONLY));
        TrackedInput input = new TrackedInput("changed");
        assertError(() -> storage.store(new StoreObjectCommand(metadata(7), input, StoreMode.CREATE_ONLY)),
                StorageErrorCode.CONFLICT);
        assertThat(input.closed).isFalse();
        assertThat(storage.metadata(KEY)).isEqualTo(original);
        try (var object = storage.read(KEY)) {
            assertThat(object.content().readAllBytes()).isEqualTo("original".getBytes(StandardCharsets.UTF_8));
        }
        input.close();
    }

    @Test
    void overwriteCreatesOrReplacesContentAndAllMetadata() throws IOException {
        storage.store(command("first", StoreMode.OVERWRITE));
        ObjectMetadata replacement = new ObjectMetadata(KEY, "application/octet-stream", 1, Map.of());
        storage.store(new StoreObjectCommand(replacement, new ByteArrayInputStream(new byte[]{42}), StoreMode.OVERWRITE));
        assertThat(storage.metadata(KEY)).isEqualTo(replacement);
        try (var object = storage.read(KEY)) {
            assertThat(object.metadata()).isEqualTo(replacement);
            assertThat(object.content().readAllBytes()).containsExactly((byte) 42);
        }
    }

    @Test
    void rejectsInvalidKeysMetadataCommandsAndPortInputs() {
        for (String key : new String[]{null, "", "  "}) {
            assertError(() -> new ObjectKey(key), StorageErrorCode.INVALID_INPUT);
        }
        assertError(() -> new ObjectMetadata(null, "text/plain", 0, Map.of()), StorageErrorCode.INVALID_INPUT);
        assertError(() -> new ObjectMetadata(KEY, null, 0, Map.of()), StorageErrorCode.INVALID_INPUT);
        assertError(() -> new ObjectMetadata(KEY, " ", 0, Map.of()), StorageErrorCode.INVALID_INPUT);
        assertError(() -> metadata(-1), StorageErrorCode.INVALID_INPUT);
        assertError(() -> new ObjectMetadata(KEY, "text/plain", 0, null), StorageErrorCode.INVALID_INPUT);
        assertError(() -> new ObjectMetadata(KEY, "text/plain", 0, Map.of(" ", "x")), StorageErrorCode.INVALID_INPUT);
        Map<String, String> invalid = new HashMap<>();
        invalid.put("name", null);
        assertError(() -> new ObjectMetadata(KEY, "text/plain", 0, invalid), StorageErrorCode.INVALID_INPUT);
        invalid.clear();
        invalid.put(null, "value");
        assertError(() -> new ObjectMetadata(KEY, "text/plain", 0, invalid), StorageErrorCode.INVALID_INPUT);
        assertError(() -> new StoreObjectCommand(null, InputStream.nullInputStream(), StoreMode.CREATE_ONLY),
                StorageErrorCode.INVALID_INPUT);
        assertError(() -> new StoreObjectCommand(metadata(0), null, StoreMode.CREATE_ONLY), StorageErrorCode.INVALID_INPUT);
        assertError(() -> new StoreObjectCommand(metadata(0), InputStream.nullInputStream(), null), StorageErrorCode.INVALID_INPUT);
        assertError(() -> storage.store(null), StorageErrorCode.INVALID_INPUT);
        assertError(() -> storage.read(null), StorageErrorCode.INVALID_INPUT);
        assertError(() -> storage.metadata(null), StorageErrorCode.INVALID_INPUT);
        assertError(() -> storage.delete(null), StorageErrorCode.INVALID_INPUT);
    }

    @Test
    void rejectsLengthMismatchWithoutClosingCallerInput() throws IOException {
        for (long length : new long[]{0, 99}) {
            TrackedInput input = new TrackedInput("replacement");
            assertError(() -> storage.store(new StoreObjectCommand(metadata(length), input, StoreMode.OVERWRITE)),
                    StorageErrorCode.INVALID_INPUT);
            assertThat(input.closed).isFalse();
            input.close();
        }
    }

    @Test
    void callerClosesInputAndReadResourceReleasesStreamIdempotently() throws IOException {
        TrackedInput input = new TrackedInput("hello");
        storage.store(new StoreObjectCommand(metadata(5), input, StoreMode.CREATE_ONLY));
        assertThat(input.closed).isFalse();
        input.close();
        assertThat(input.closed).isTrue();
        ObjectContent resource = storage.read(KEY);
        InputStream stream;
        try (resource) {
            stream = resource.content();
            assertThat(stream.read()).isEqualTo('h');
        }
        resource.close();
        assertThat(resource.metadata()).isEqualTo(metadata(5));
        assertError(() -> resource.content(), StorageErrorCode.INVALID_INPUT);
        assertError(() -> stream.read(), StorageErrorCode.INVALID_INPUT);
        try (var another = storage.read(KEY)) {
            another.content().close();
            assertError(() -> another.content(), StorageErrorCode.INVALID_INPUT);
        }
    }

    @Test
    void readSnapshotKeepsContentAndMetadataTogetherAcrossOverwriteAndDelete() throws IOException {
        ObjectMetadata original = storage.store(command("old", StoreMode.CREATE_ONLY));
        try (var object = storage.read(KEY)) {
            storage.store(command("new content", StoreMode.OVERWRITE));
            storage.delete(KEY);
            assertThat(object.metadata()).isEqualTo(original);
            assertThat(object.content().readAllBytes()).isEqualTo("old".getBytes(StandardCharsets.UTF_8));
        }
    }

    @Test
    void zeroLengthContentAndOpaqueKeysAndDefensiveMetadataAreSupported() {
        assertThat(new ObjectKey(" Mixed/Key ").value()).isEqualTo(" Mixed/Key ");
        Map<String, String> custom = new HashMap<>(Map.of("name", "original"));
        ObjectMetadata metadata = new ObjectMetadata(KEY, "application/octet-stream", 0, custom);
        custom.put("name", "changed");
        assertThat(metadata.customMetadata()).containsEntry("name", "original");
        assertThatThrownBy(() -> metadata.customMetadata().put("x", "y")).isInstanceOf(UnsupportedOperationException.class);
        assertThat(storage.store(new StoreObjectCommand(metadata, InputStream.nullInputStream(), StoreMode.CREATE_ONLY)))
                .isEqualTo(metadata);
    }

    @Test
    void normalizedErrorsExposeOnlyStableCodes() {
        for (StorageErrorCode code : StorageErrorCode.values()) {
            StorageException error = new StorageException(code);
            error.addSuppressed(new IOException("provider secret"));
            assertThat(error.code()).isEqualTo(code);
            assertThat(error.getMessage()).isEqualTo(code.name());
            assertThat(error.getCause()).isNull();
            assertThat(error.getStackTrace()).isEmpty();
            assertThat(error.getSuppressed()).isEmpty();
        }
    }

    @Test
    void inputReadFailureIsSanitizedWithoutTakingOwnership() {
        boolean[] closed = {false};
        InputStream broken = new InputStream() {
            @Override
            public int read() throws IOException {
                throw new IOException("sensitive input details");
            }

            @Override
            public void close() {
                closed[0] = true;
            }
        };
        assertError(() -> storage.store(new StoreObjectCommand(metadata(1), broken, StoreMode.CREATE_ONLY)),
                StorageErrorCode.INVALID_INPUT);
        assertThat(closed[0]).isFalse();
        assertError(() -> storage.metadata(KEY), StorageErrorCode.NOT_FOUND);
    }

    @Test
    void consumesFromCurrentPositionAndClosesReadResourceAfterConsumerFailure() throws IOException {
        ByteArrayInputStream input = new ByteArrayInputStream("prefixhello".getBytes(StandardCharsets.UTF_8));
        assertThat(input.skip(6)).isEqualTo(6);
        storage.store(new StoreObjectCommand(metadata(5), input, StoreMode.CREATE_ONLY));
        ObjectContent resource = storage.read(KEY);
        InputStream stream = resource.content();
        assertThatThrownBy(() -> {
            try (resource) {
                assertThat(stream.read()).isEqualTo('h');
                throw new IllegalStateException("consumer failure");
            }
        }).isInstanceOf(IllegalStateException.class);
        assertError(() -> stream.read(), StorageErrorCode.INVALID_INPUT);
    }

    @Test
    void concurrentCreateOnlyWritersHaveExactlyOneWinner() throws Exception {
        CountDownLatch start = new CountDownLatch(1);
        var executor = Executors.newFixedThreadPool(2);
        try {
            var first = executor.submit(() -> createAfterSignal(start));
            var second = executor.submit(() -> createAfterSignal(start));
            start.countDown();
            assertThat(java.util.List.of(first.get(5, TimeUnit.SECONDS), second.get(5, TimeUnit.SECONDS)))
                    .containsExactlyInAnyOrder("STORED", "CONFLICT");
            assertThat(storage.metadata(KEY)).isEqualTo(metadata(5));
        } finally {
            executor.shutdownNow();
        }
    }

    private String createAfterSignal(CountDownLatch start) throws InterruptedException {
        if (!start.await(5, TimeUnit.SECONDS)) {
            throw new IllegalStateException("start signal timed out");
        }
        try {
            storage.store(command("hello", StoreMode.CREATE_ONLY));
            return "STORED";
        } catch (StorageException error) {
            return error.code().name();
        }
    }

    private static ObjectMetadata metadata(long length) {
        return new ObjectMetadata(KEY, "text/plain", length, Map.of("source", "test"));
    }

    private static StoreObjectCommand command(String content, StoreMode mode) {
        byte[] bytes = content.getBytes(StandardCharsets.UTF_8);
        return new StoreObjectCommand(metadata(bytes.length), new ByteArrayInputStream(bytes), mode);
    }

    private static void assertError(org.assertj.core.api.ThrowableAssert.ThrowingCallable operation, StorageErrorCode code) {
        assertThatThrownBy(operation).isInstanceOfSatisfying(StorageException.class,
                error -> assertThat(error.code()).isEqualTo(code));
    }

    private static final class TrackedInput extends ByteArrayInputStream {
        private boolean closed;

        private TrackedInput(String content) {
            super(content.getBytes(StandardCharsets.UTF_8));
        }

        @Override
        public void close() throws IOException {
            closed = true;
            super.close();
        }
    }
}

@Test
void runtimeInputReadFailureIsSanitizedWithoutClosingInputOrOverwritingObject() throws IOException {
    ObjectMetadata original = storage.store(command("original", StoreMode.CREATE_ONLY));
    boolean[] closed = {false};
    InputStream broken = new InputStream() {
        @Override
        public int read() {
            throw new IllegalStateException("sensitive input details");
        }

        @Override
        public void close() {
            closed[0] = true;
        }
    };
    assertThatThrownBy(() -> storage.store(new StoreObjectCommand(metadata(1), broken, StoreMode.OVERWRITE)))
            .isInstanceOfSatisfying(StorageException.class, error -> {
                assertThat(error.code()).isEqualTo(StorageErrorCode.INVALID_INPUT);
                assertThat(error.getMessage()).isEqualTo(StorageErrorCode.INVALID_INPUT.name());
                assertThat(error.getCause()).isNull();
                assertThat(error.getSuppressed()).isEmpty();
                assertThat(error.getStackTrace()).isEmpty();
            });
    assertThat(closed[0]).isFalse();
    assertThat(storage.metadata(KEY)).isEqualTo(original);
    try (var object = storage.read(KEY)) {
        assertThat(object.metadata()).isEqualTo(original);
        assertThat(object.content().readAllBytes()).isEqualTo("original".getBytes(StandardCharsets.UTF_8));
    }
}

