} from "./helpdeskPresentation";

describe("APP-10 exact PR #63 RequestView mapping", () => {
  it("pins the reviewed Backend HEAD and keeps the legacy MOCK model incompatible", () => {
    expect(HELPDESK_CONTRACT_HEAD).toBe(
      "e12d105c89400a5fd69dd6cc1fca670ff1f04f51",
    );
    expectTypeOf<HelpdeskPortalRequestPresentation>().not.toExtend<ServiceRequest>();
  });

  it.each([
    "SUBMITTED",
    "TRIAGED",
    "IN_PROGRESS",
    "RESOLVED",
    "CONFIRMED",
    "future_state",
  ])(
    "preserves authoritative %s, independent versions and explicit Backend facts",
    (state) => {
      const source = helpdeskWire({ state, assignmentVersion: 3, version: 19 });
      const before = structuredClone(source);
      const view = mapHelpdeskRequestPresentation(
        decodeHelpdeskRequest(source),
      );
      expect(view).toMatchObject({ ...source, kind: "it" });
      expect(view.currentAssignee).toEqual({
        id: { scope: "assignee", value: source.assigneeId },
      });
      expect(view.version).toBe(19);
      expect(view.assignmentVersion).toBe(3);
      for (const field of [
        "status",
        "priority",
        "location",
        "requester",
        "department",
        "createdAt",
        "updatedAt",
        "timeline",
        "history",
        "actor",
        "role",
      ]) {
        expect(view).not.toHaveProperty(field);
      }
      expect(source).toEqual(before);
    },
  );

  it.each([undefined, null, "Tên được phép hiển thị", ""])(
    "keeps optional/hidden display names exactly as supplied: %s",
    (name) => {
      const source = helpdeskWire(
        name === undefined
          ? {}
          : {
              requesterDisplayName: name,
              assigneeDisplayName: name,
            },
      );
      const decoded = decodeHelpdeskRequest(source);
      const view = mapHelpdeskRequestPresentation(decoded);
      if (name === undefined) {
        expect(decoded).not.toHaveProperty("requesterDisplayName");
        expect(view).not.toHaveProperty("requesterDisplayName");
        expect(view).not.toHaveProperty("assigneeDisplayName");
        expect(view.currentAssignee).not.toHaveProperty("displayName");
      } else {
        expect(view.requesterDisplayName).toBe(name);
        expect(view.assigneeDisplayName).toBe(name);
        expect(view.currentAssignee?.displayName).toBe(name);
      }
    },
  );

  it("does not manufacture an assignee from a label when assigneeId is null", () => {
    const view = mapHelpdeskRequestPresentation(
      decodeHelpdeskRequest(
        helpdeskWire({
          assigneeId: null,
          assigneeDisplayName: "Visible label",
        }),
      ),
    );
    expect(view.currentAssignee).toBeNull();
    expect(view.assigneeDisplayName).toBe("Visible label");
  });

  it.each([
    undefined,
    null,
    [],
    [
      { id: "worker-1", displayName: null },
      { id: "worker-2", displayName: "Tên Backend" },
    ],
  ])(
    "preserves eligibility absent/null/empty/populated without granting authority: %j",
    (eligibleAssignees) => {
      const source = helpdeskWire({
        allowedActions: [],
        ...(eligibleAssignees === undefined ? {} : { eligibleAssignees }),
      });
      const decoded = decodeHelpdeskRequest(source);
      const view = mapHelpdeskRequestPresentation(decoded);
      expect(view.allowedActions).toEqual([]);
      expect(view).not.toHaveProperty("canAssign");
      if (eligibleAssignees === undefined) {
        expect(decoded).not.toHaveProperty("eligibleAssignees");
        expect(view).not.toHaveProperty("eligibleAssignees");
      } else if (eligibleAssignees === null) {
        expect(view.eligibleAssignees).toBeNull();
      } else {
        expect(view.eligibleAssignees).toEqual({
          completeness: "unknown",
          items: eligibleAssignees.map((option) => ({
            id: { scope: "assignee", value: option.id },
            displayName: option.displayName,
          })),
        });
        expect(decoded.eligibleAssignees).not.toBe(eligibleAssignees);
      }
    },
  );

  it("preserves only Backend-supplied action strings, including start/assign and unknown names", () => {
    const source = helpdeskWire({
      allowedActions: ["assign", "start", "future_action"],
    });
    const view = mapHelpdeskRequestPresentation(decodeHelpdeskRequest(source));
    expect(view.allowedActions).toEqual(source.allowedActions);
    expect(view.allowedActions).not.toBe(source.allowedActions);
    expect(view.allowedActions).not.toContain("start_work");
  });

  it.each([helpdeskCursor, null])(
    "preserves list items and nextCursor %s",
    (nextCursor) => {
      const view = mapHelpdeskListPresentation(
        decodeHelpdeskPage({ items: [helpdeskWire()], nextCursor }),
      );
      expect(view.items[0]).toEqual(
        mapHelpdeskRequestPresentation(helpdeskWire()),
      );
      expect(view.nextCursor).toBe(nextCursor);
      expect(view).not.toHaveProperty("total");
      expect(
        mapHelpdeskListPresentation(
          decodeHelpdeskPage({ items: [], nextCursor: null }),
        ),
      ).toEqual({ items: [], nextCursor: null });
    },
  );

  it.each(["2026-10-26T01:02:03.123456789Z", 1792976523.125])(
    "maps only HistoryView fields preserving time %s and order",
    (occurredAt) => {
      const source = [
        {
          transitionId: "triage",
          sourceState: "SUBMITTED",
          targetState: "TRIAGED",
          version: 1,
          occurredAt,
          actor: "hidden",
          note: "hidden",
          id: "not-in-dto",
        },
      ];
      const history = mapHelpdeskHistoryPresentation(
        decodeHelpdeskHistory(source),
      );
      expect(history).toEqual([
        {
          transitionId: "triage",
          sourceState: "SUBMITTED",
          targetState: "TRIAGED",
          version: 1,
          occurredAt,
        },
      ]);
      expect(Object.keys(history[0])).toEqual([
        "transitionId",
        "sourceState",
        "targetState",
        "version",
        "occurredAt",
      ]);
      expect(history[0]).not.toHaveProperty("title");
      expect(mapHelpdeskHistoryPresentation(decodeHelpdeskHistory([]))).toEqual(
        [],
      );
    },
  );
});

import type {
  HelpdeskHistoryEntry,
  HelpdeskPage,
  HelpdeskRequest,
} from "./http/types";
import type { Assignee, EligibleAssignees } from "./types";

/**
 * APP-10 projection for the reviewed PR #63 contract. Separate from both wire
 * DTOs and the older normalized/MOCK model: unsupported display fields stay
 * absent. This cannot satisfy the Portal's legacy ServiceRequest interface.
 */
export interface HelpdeskPortalRequestPresentation {
  readonly id: string;
  readonly title: string;
  readonly description: string;
  readonly kind: "it";
  readonly requestType: "IT_HELPDESK";
  readonly workflowInstanceId: string;
  readonly state: string;
  readonly version: number;
  readonly assignmentVersion: number;
  readonly requesterId: string;
  readonly assigneeId: string | null;
  readonly resolution: string | null;
  readonly allowedActions: readonly string[];
  readonly currentAssignee: Assignee | null;
  readonly requesterDisplayName?: string | null;
  readonly assigneeDisplayName?: string | null;
  readonly eligibleAssignees?: EligibleAssignees | null;
}

export interface HelpdeskPortalListPresentation {
  readonly items: readonly HelpdeskPortalRequestPresentation[];
  readonly nextCursor: string | null;
}

export interface HelpdeskPortalHistoryEntry {
  readonly transitionId: string;
  readonly sourceState: string;
  readonly targetState: string;
  readonly version: number;
  readonly occurredAt: string | number;
}

function assignee(id: string, displayName?: string | null): Assignee {
  return {
    id: { scope: "assignee", value: id },
    ...(displayName === undefined ? {} : { displayName }),
  };
}

/** Input is validated by the wire decoder; never infer permissions or names. */
export function mapHelpdeskRequestPresentation(
  source: HelpdeskRequest,
): HelpdeskPortalRequestPresentation {
  return {
    id: source.id,
    title: source.title,
    description: source.description,
    kind: "it",
    requestType: source.requestType,
    workflowInstanceId: source.workflowInstanceId,
    state: source.state,
    version: source.version,
    assignmentVersion: source.assignmentVersion,
    requesterId: source.requesterId,
    assigneeId: source.assigneeId,
    resolution: source.resolution,
    allowedActions: [...source.allowedActions],
    currentAssignee:
      source.assigneeId === null
        ? null
        : assignee(source.assigneeId, source.assigneeDisplayName),
    ...(source.requesterDisplayName === undefined
      ? {}
      : { requesterDisplayName: source.requesterDisplayName }),
    ...(source.assigneeDisplayName === undefined
      ? {}
      : { assigneeDisplayName: source.assigneeDisplayName }),
    ...(source.eligibleAssignees === undefined
      ? {}
      : {
          eligibleAssignees:
            source.eligibleAssignees === null
              ? null
              : {
                  items: source.eligibleAssignees.map((option) =>
                    assignee(option.id, option.displayName),
                  ),
                  // The DTO has no completeness metadata. Do not claim full visibility.
                  completeness: "unknown" as const,
                },
        }),
  };
}

export function mapHelpdeskListPresentation(
  source: HelpdeskPage,
): HelpdeskPortalListPresentation {
  return {
    items: source.items.map(mapHelpdeskRequestPresentation),
    nextCursor: source.nextCursor,
  };
}

/** Only fields actually returned by HistoryView; no actor/note/event ID/title. */
export function mapHelpdeskHistoryPresentation(
  source: readonly HelpdeskHistoryEntry[],
): readonly HelpdeskPortalHistoryEntry[] {
  return source.map((entry) => ({
    transitionId: entry.transitionId,
    sourceState: entry.sourceState,
    targetState: entry.targetState,
    version: entry.version,
    occurredAt: entry.occurredAt,
  }));
}

import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import {
  helpdeskCursor,
  helpdeskId,
  helpdeskWire,
} from "../../../test/helpdeskFixtures";
import { HelpdeskRequestService } from "../HelpdeskRequestService";
import { HelpdeskApiClient } from "./HelpdeskApiClient";
import type { HelpdeskHttpTransport } from "./transport";

const base = "/api/v1/mvp/requests";
const createInput = {
  title: "Sự cố phần mềm",
  description: "Không lưu được báo cáo công việc.",
};
const versionInput = { expectedVersion: 17 };
const assignInput = { assigneeId: "worker-2", expectedAssignmentVersion: 0 };
const resolveInput = {
  ...versionInput,
  resolution: "Đã khắc phục và kiểm tra.",
};
const history = [
  {
    transitionId: "triage",
    sourceState: "SUBMITTED",
    targetState: "TRIAGED",
    version: 1,
    occurredAt: "2026-10-26T01:00:00Z",
  },
];

const routes = [
  {
    name: "create",
    method: "POST",
    path: base,
    body: { ...createInput, requestType: "IT_HELPDESK" },
    status: 201,
    response: helpdeskWire(),
    invoke: (s: HelpdeskRequestService) => s.create(createInput),
  },
  {
    name: "list",
    method: "GET",
    path: base,
    status: 200,
    response: { items: [helpdeskWire()], nextCursor: helpdeskCursor },
    invoke: (s: HelpdeskRequestService) => s.list(),
  },
  {
    name: "detail",
    method: "GET",
    path: `${base}/${helpdeskId}`,
    status: 200,
    response: helpdeskWire(),
    invoke: (s: HelpdeskRequestService) => s.detail(helpdeskId),
  },
  {
    name: "triage",
    method: "POST",
    path: `${base}/${helpdeskId}/triage`,
    body: versionInput,
    status: 200,
    response: helpdeskWire(),
    invoke: (s: HelpdeskRequestService) => s.triage(helpdeskId, versionInput),
  },
  {
    name: "assign",
    method: "POST",
    path: `${base}/${helpdeskId}/assign`,
    body: assignInput,
    status: 200,
    response: helpdeskWire(),
    invoke: (s: HelpdeskRequestService) => s.assign(helpdeskId, assignInput),
  },
  {
    name: "start",
    method: "POST",
    path: `${base}/${helpdeskId}/start`,
    body: versionInput,
    status: 200,
    response: helpdeskWire(),
    invoke: (s: HelpdeskRequestService) => s.start(helpdeskId, versionInput),
  },
  {
    name: "resolve",
    method: "POST",
    path: `${base}/${helpdeskId}/resolve`,
    body: resolveInput,
    status: 200,
    response: helpdeskWire({ resolution: resolveInput.resolution }),
    invoke: (s: HelpdeskRequestService) => s.resolve(helpdeskId, resolveInput),
  },
  {
    name: "confirm",
    method: "POST",
    path: `${base}/${helpdeskId}/confirm`,
    body: versionInput,
    status: 200,
    response: helpdeskWire({ state: "CONFIRMED" }),
    invoke: (s: HelpdeskRequestService) => s.confirm(helpdeskId, versionInput),
  },
  {
    name: "history",
    method: "GET",
    path: `${base}/${helpdeskId}/history`,
    status: 200,
    response: history,
    invoke: (s: HelpdeskRequestService) => s.history(helpdeskId),
  },
] as const;

let assertNoNetworkOrStorage: () => void;
beforeEach(() => {
  const fetchSpy = vi.spyOn(globalThis, "fetch").mockImplementation(() => {
    throw new Error("Unexpected LIVE fetch");
  });
  const xhrSpy = vi
    .spyOn(XMLHttpRequest.prototype, "send")
    .mockImplementation(() => {
      throw new Error("Unexpected LIVE XHR");
    });
  const storageSpy = vi.spyOn(Storage.prototype, "setItem");
  assertNoNetworkOrStorage = () => {
    expect(fetchSpy).not.toHaveBeenCalled();
    expect(xhrSpy).not.toHaveBeenCalled();
    expect(storageSpy).not.toHaveBeenCalled();
  };
});
afterEach(() => {
  try {
    assertNoNetworkOrStorage();
  } finally {
    vi.restoreAllMocks();
  }
});

function fixture(status = 200, body: unknown = helpdeskWire()) {
  const transport = vi
    .fn<HelpdeskHttpTransport>()
    .mockResolvedValue({ status, body });
  const onSessionInvalid = vi.fn();
  const client = new HelpdeskApiClient(transport, onSessionInvalid);
  return {
    transport,
    onSessionInvalid,
    client,
    service: new HelpdeskRequestService(client),
  };
}

describe("APP-13 nine reviewed routes through Application service", () => {
  it.each(routes)(
    "$name: exact method/path/body and one injected attempt",
    async (route) => {
      const { transport, service, onSessionInvalid } = fixture(
        route.status,
        route.response,
      );
      const result = await route.invoke(service);
      const body = "body" in route ? route.body : undefined;
      expect(transport).toHaveBeenCalledExactlyOnceWith({
        method: route.method,
        path: route.path,
        headers: {
          Accept: "application/json",
          ...(body ? { "Content-Type": "application/json" } : {}),
        },
        ...(body ? { body } : {}),
      });
      expect(onSessionInvalid).not.toHaveBeenCalled();
      if (route.name === "history") expect(result).toEqual(history);
      else if (route.name === "list")
        expect(result).toMatchObject({
          nextCursor: helpdeskCursor,
          items: [{ version: 17, assignmentVersion: 0 }],
        });
      else
        expect(result).toMatchObject({
          id: helpdeskId,
          version: 17,
          assignmentVersion: 0,
        });
      expect(transport.mock.calls[0][0].path).not.toContain("/actions");
    },
  );

  it("allowlists create/command fields, sends IT_HELPDESK and never sends caller identity", async () => {
    const { transport, client } = fixture(201);
    const input = {
      ...createInput,
      requestType: "FACILITY",
      requesterId: "forged",
      role: "admin",
      priority: "urgent",
    };
    await client.create(input);
    expect(transport.mock.calls[0][0].body).toEqual({
      ...createInput,
      requestType: "IT_HELPDESK",
    });
    transport.mockResolvedValue({ status: 200, body: helpdeskWire() });
    await client.assign(helpdeskId, {
      ...assignInput,
      expectedVersion: 999,
      actor: "forged",
    } as typeof assignInput);
    expect(transport.mock.calls[1][0].body).toEqual(assignInput);
    await client.resolve(helpdeskId, {
      ...resolveInput,
      note: "not-a-field",
    } as typeof resolveInput);
    expect(transport.mock.calls[2][0].body).toEqual(resolveInput);
  });

  it.each([1, 100])(
    "passes explicit after/limit=%s and preserves pagination",
    async (limit) => {
      const { transport, service } = fixture(200, {
        items: [helpdeskWire()],
        nextCursor: helpdeskCursor,
      });
      const page = await service.list({ after: helpdeskId, limit });
      expect(transport.mock.calls[0][0].path).toBe(
        `${base}?after=${helpdeskId}&limit=${limit}`,
      );
      expect(page.nextCursor).toBe(helpdeskCursor);
      transport.mockResolvedValue({
        status: 200,
        body: { items: [], nextCursor: null },
      });
      expect(await service.list({ after: page.nextCursor! })).toEqual({
        items: [],
        nextCursor: null,
      });
      expect(transport.mock.calls[1][0].path).toBe(
        `${base}?after=${helpdeskCursor}`,
      );
    },
  );

  it.each([0, 101, -1, 1.5, NaN, Infinity])(
    "rejects invalid limit %s before transport",
    (limit) => {
      const { transport, client } = fixture();
      expect(() => client.list({ limit })).toThrow(/không hợp lệ/);
      expect(transport).not.toHaveBeenCalled();
    },
  );

  it("rejects invalid IDs, empty text/resolution and unsafe versions before transport", () => {
    const { transport, client } = fixture();
    const calls = [
      () => client.detail("../actions"),
      () => client.list({ after: "invalid-cursor" }),
      () => client.create({ ...createInput, title: " " }),
      () => client.create({ ...createInput, description: "a".repeat(4001) }),
      () => client.resolve(helpdeskId, { ...resolveInput, resolution: " " }),
      () => client.assign(helpdeskId, { ...assignInput, assigneeId: " " }),
      ...[-1, 0.5, NaN, Infinity, Number.MAX_SAFE_INTEGER + 1].flatMap(
        (version) => [
          () => client.triage(helpdeskId, { expectedVersion: version }),
          () => client.start(helpdeskId, { expectedVersion: version }),
          () => client.confirm(helpdeskId, { expectedVersion: version }),
          () =>
            client.resolve(helpdeskId, {
              ...resolveInput,
              expectedVersion: version,
            }),
          () =>
            client.assign(helpdeskId, {
              ...assignInput,
              expectedAssignmentVersion: version,
            }),
        ],
      ),
    ];
    for (const call of calls) expect(call).toThrow(/không hợp lệ/);
    expect(transport).not.toHaveBeenCalled();
  });
});

describe("APP-13 security/session/error boundaries", () => {
  it.each(
    routes.flatMap((route) =>
      (
        [
          [401, "UNAUTHENTICATED"],
          [403, "FORBIDDEN"],
          [404, "NOT_FOUND"],
          [409, "CONFLICT"],
        ] as const
      ).map(([status, code]) => ({ route, status, code })),
    ),
  )(
    "$route.name: HTTP $status takes precedence over an inconsistent error body, without retry",
    async ({ route, status, code }) => {
      const { service, transport, onSessionInvalid } = fixture(status, {
        code: "COMMIT_OUTCOME_UNKNOWN",
        message: "private identity/resource diagnostic",
      });
      const failure = await route
        .invoke(service)
        .catch((error: unknown) => error);
      expect(failure).toMatchObject({ code });
      expect((failure as Error).message).not.toContain("private");
      expect(transport).toHaveBeenCalledTimes(1);
      expect(onSessionInvalid).toHaveBeenCalledTimes(status === 401 ? 1 : 0);
    },
  );

  it.each([
    [401, "UNAUTHENTICATED"],
    [403, "FORBIDDEN"],
    [404, "NOT_FOUND"],
    [409, "CONFLICT"],
  ] as const)(
    "maps HTTP %s safely on read and write without raw diagnostics",
    async (status, code) => {
      for (const operation of ["read", "write"]) {
        const { client, transport, onSessionInvalid } = fixture(status, {
          message: "sensitive resource/identity",
          code: "diagnostic",
        });
        const failure = await (
          operation === "read"
            ? client.detail(helpdeskId)
            : client.assign(helpdeskId, assignInput)
        ).catch((error: unknown) => error);
        expect(failure).toMatchObject({ code });
        expect((failure as Error).message).not.toContain("sensitive");
        if (status === 404)
          expect((failure as Error).message).toMatch(
            /Không tìm thấy.*không khả dụng/,
          );
        if (status === 409)
          expect((failure as Error).message).toContain("Tải lại");
        expect(transport).toHaveBeenCalledTimes(1);
        expect(onSessionInvalid).toHaveBeenCalledTimes(status === 401 ? 1 : 0);
      }
    },
  );

  it.each([false, true])(
    "401 invalidates once and blocks all later protected operations even if callback throws=%s",
    async (throws) => {
      const { client, transport, service, onSessionInvalid } = fixture(401);
      if (throws)
        onSessionInvalid.mockImplementation(() => {
          throw new Error("UI callback failed");
        });
      await expect(client.detail(helpdeskId)).rejects.toMatchObject({
        code: "UNAUTHENTICATED",
      });
      transport.mockResolvedValue({ status: 200, body: helpdeskWire() });
      for (const route of routes)
        await expect(route.invoke(service)).rejects.toMatchObject({
          code: "UNAUTHENTICATED",
        });
      expect(transport).toHaveBeenCalledTimes(1);
      expect(onSessionInvalid).toHaveBeenCalledTimes(1);
    },
  );

  it.each(routes.filter((route) => route.method === "POST"))(
    "$name is never retried or reconciled automatically after network/unknown write",
    async (route) => {
      for (const mode of [
        "lost response",
        "unknown commit",
        "server failure",
        "timeout",
        "malformed success",
        "unexpected success",
      ]) {
        const { transport, service } = fixture();
        if (mode === "lost response")
          transport.mockRejectedValue(new Error("ACK lost after commit"));
        else
          transport.mockResolvedValue({
            status:
              mode === "unknown commit" || mode === "server failure"
                ? 503
                : mode === "timeout"
                  ? 408
                  : mode === "unexpected success"
                    ? 204
                    : route.status,
            body:
              mode === "unknown commit"
                ? { code: "COMMIT_OUTCOME_UNKNOWN" }
                : { malformed: true },
          });
        await expect(route.invoke(service)).rejects.toMatchObject({
          code: "COMMIT_OUTCOME_UNKNOWN",
        });
        expect(transport).toHaveBeenCalledTimes(1);
      }
    },
  );

  it("keeps network read failure distinct without retry", async () => {
    const { transport, client } = fixture();
    transport.mockRejectedValue(new Error("offline"));
    await expect(client.list()).rejects.toMatchObject({
      code: "NETWORK_FAILURE",
    });
    expect(transport).toHaveBeenCalledTimes(1);
  });

  it.each([
    { requestType: "FACILITY" },
    { version: "17" },
    { assignmentVersion: -1 },
    { version: Number.MAX_SAFE_INTEGER + 1 },
    { state: null },
    { eligibleAssignees: [{ id: "", displayName: null }] },
    { eligibleAssignees: [{ id: "worker", displayName: 123 }] },
    { requesterDisplayName: {} },
    { assigneeDisplayName: 42 },
  ])(
    "rejects malformed RequestView rather than inventing data: %j",
    async (override) => {
      const { client } = fixture(200, { ...helpdeskWire(), ...override });
      await expect(client.detail(helpdeskId)).rejects.toMatchObject({
        code: "INVALID_RESPONSE",
      });
    },
  );

  it.each([
    { items: [], nextCursor: "invalid-cursor" },
    { items: null, nextCursor: null },
    { items: [helpdeskWire({ version: -1 })], nextCursor: null },
    { items: [] },
    [],
    null,
  ])("rejects malformed list envelopes: %j", async (body) => {
    const { service, transport } = fixture(200, body);
    await expect(service.list()).rejects.toMatchObject({
      code: "INVALID_RESPONSE",
    });
    expect(transport).toHaveBeenCalledTimes(1);
  });

  it.each([
    { items: history },
    [{ ...history[0], occurredAt: null }],
    [{ ...history[0], version: "1" }],
    [{ ...history[0], targetState: null }],
    [{ sourceState: "SUBMITTED", targetState: "TRIAGED", version: 1 }],
    null,
  ])("rejects malformed history without inventing fields: %j", async (body) => {
    const { service, transport } = fixture(200, body);
    await expect(service.history(helpdeskId)).rejects.toMatchObject({
      code: "INVALID_RESPONSE",
    });
    expect(transport).toHaveBeenCalledTimes(1);
  });

  it.each([undefined, null, { status: 0 }, { status: 200.5 }, { status: 600 }])(
    "handles invalid transport responses: %j",
    async (response) => {
      const { transport, client } = fixture();
      transport.mockResolvedValue(
        response as Awaited<ReturnType<HelpdeskHttpTransport>>,
      );
      await expect(client.detail(helpdeskId)).rejects.toMatchObject({
        code: "INVALID_RESPONSE",
      });
      await expect(
        client.assign(helpdeskId, assignInput),
      ).rejects.toMatchObject({ code: "COMMIT_OUTCOME_UNKNOWN" });
      expect(transport).toHaveBeenCalledTimes(2);
    },
  );

  it("does not expose HTTP 400/500 diagnostics and does not retry", async () => {
    const { client, transport } = fixture(400, {
      code: "VALIDATION",
      message: "private details",
    });
    await expect(client.assign(helpdeskId, assignInput)).rejects.toMatchObject({
      code: "HTTP_FAILURE",
      status: 400,
    });
    transport.mockResolvedValue({
      status: 500,
      body: { message: "private details" },
    });
    const error = await client.list().catch((failure: unknown) => failure);
    expect(error).toMatchObject({ code: "HTTP_FAILURE", status: 500 });
    expect((error as Error).message).not.toContain("private details");
    expect(transport).toHaveBeenCalledTimes(2);
  });
});

import {
  errorFromHttpStatus,
  MvpApplicationError,
  networkFailure,
} from "../errors";
import {
  decodeHelpdeskHistory,
  decodeHelpdeskPage,
  decodeHelpdeskRequest,
  validateId,
  validateText,
  validateVersion,
} from "./codecs";
import { HelpdeskClientError } from "./errors";
import type { HelpdeskHttpRequest, HelpdeskHttpTransport } from "./transport";
import type {
  HelpdeskAssignInput,
  HelpdeskCreateInput,
  HelpdeskListInput,
  HelpdeskResolveInput,
  HelpdeskVersionInput,
} from "./types";

const BASE = "/api/v1/mvp/requests";

/**
 * PR #63 wire client, unbound to Portal, RequestService and MvpRequestPort.
 * No concrete network transport is shipped. Construction requires injection.
 * Nine explicit routes only; /start maps to start_work inside Backend, not here.
 */
export class HelpdeskApiClient {
  private sessionInvalid = false;

  constructor(
    private readonly transport: HelpdeskHttpTransport,
    private readonly onSessionInvalid: () => void,
  ) {
    if (
      typeof transport !== "function" ||
      typeof onSessionInvalid !== "function"
    ) {
      throw new HelpdeskClientError("INVALID_INPUT");
    }
  }

  create(input: HelpdeskCreateInput) {
    return this.post(
      BASE,
      {
        title: validateText(input.title, 200),
        description: validateText(input.description, 4000),
        requestType: "IT_HELPDESK",
      },
      201,
    );
  }

  list(input: HelpdeskListInput = {}) {
    const query = new URLSearchParams();
    if (input.after !== undefined) query.set("after", validateId(input.after));
    if (input.limit !== undefined) {
      if (
        !Number.isInteger(input.limit) ||
        input.limit < 1 ||
        input.limit > 100
      ) {
        throw new HelpdeskClientError("INVALID_INPUT");
      }
      query.set("limit", String(input.limit));
    }
    const suffix = query.size === 0 ? "" : `?${query}`;
    return this.get(BASE + suffix, decodeHelpdeskPage);
  }

  detail(id: string) {
    return this.get(this.path(id), decodeHelpdeskRequest);
  }

  triage(id: string, input: HelpdeskVersionInput) {
    return this.post(this.path(id, "/triage"), {
      expectedVersion: validateVersion(input.expectedVersion),
    });
  }

  assign(id: string, input: HelpdeskAssignInput) {
    return this.post(this.path(id, "/assign"), {
      assigneeId: validateText(input.assigneeId, 1024),
      expectedAssignmentVersion: validateVersion(
        input.expectedAssignmentVersion,
      ),
    });
  }

  start(id: string, input: HelpdeskVersionInput) {
    return this.post(this.path(id, "/start"), {
      expectedVersion: validateVersion(input.expectedVersion),
    });
  }

  resolve(id: string, input: HelpdeskResolveInput) {
    return this.post(this.path(id, "/resolve"), {
      expectedVersion: validateVersion(input.expectedVersion),
      resolution: validateText(input.resolution, 4000),
    });
  }

  confirm(id: string, input: HelpdeskVersionInput) {
    return this.post(this.path(id, "/confirm"), {
      expectedVersion: validateVersion(input.expectedVersion),
    });
  }

  history(id: string) {
    return this.get(this.path(id, "/history"), decodeHelpdeskHistory);
  }

  private path(id: string, suffix = "") {
    return `${BASE}/${encodeURIComponent(validateId(id))}${suffix}`;
  }

  private get<T>(path: string, decode: (body: unknown) => T): Promise<T> {
    return this.send(
      { method: "GET", path, headers: { Accept: "application/json" } },
      200,
      decode,
    );
  }

  private post(
    path: string,
    body: Readonly<Record<string, unknown>>,
    status = 200,
  ) {
    return this.send(
      {
        method: "POST",
        path,
        body,
        headers: {
          Accept: "application/json",
          "Content-Type": "application/json",
        },
      },
      status,
      decodeHelpdeskRequest,
    );
  }

  private async send<T>(
    request: HelpdeskHttpRequest,
    expectedStatus: number,
    decode: (body: unknown) => T,
  ): Promise<T> {
    // A 401 closes this client instance. A new approved session needs a new client;
    // no refresh/replay or token storage is introduced here.
    if (this.sessionInvalid) throw errorFromHttpStatus(401);
    const write = request.method === "POST";
    let response;
    try {
      response = await this.transport(request); // Exactly one attempt; never replay.
    } catch (cause) {
      throw networkFailure(write ? "write" : "read", cause);
    }
    if (
      !response ||
      !Number.isInteger(response.status) ||
      response.status < 100 ||
      response.status > 599
    ) {
      const cause = new HelpdeskClientError("INVALID_RESPONSE");
      throw write ? networkFailure("write", cause) : cause;
    }
    if (response.status !== expectedStatus) {
      if (response.status === 401) {
        if (!this.sessionInvalid) {
          this.sessionInvalid = true;
          try {
            this.onSessionInvalid();
          } catch {
            /* Keep the safe 401 boundary. */
          }
        }
        throw errorFromHttpStatus(401);
      }
      const body = response.body;
      const backendCode =
        body !== null &&
        typeof body === "object" &&
        "code" in body &&
        typeof body.code === "string"
          ? body.code
          : undefined;
      const status = response.status;
      if (status === 403 || status === 404 || status === 409) {
        throw errorFromHttpStatus(status);
      }
      if (backendCode === "COMMIT_OUTCOME_UNKNOWN") {
        throw new MvpApplicationError("COMMIT_OUTCOME_UNKNOWN");
      }
      if (
        write &&
        (status === 408 || status >= 500 || (status >= 200 && status < 400))
      ) {
        throw networkFailure(
          "write",
          new HelpdeskClientError("HTTP_FAILURE", status, backendCode),
        );
      }
      throw new HelpdeskClientError("HTTP_FAILURE", status, backendCode);
    }
    try {
      return decode(response.body);
    } catch (cause) {
      // A successful write with an unreadable reply may already be committed.
      throw write ? networkFailure("write", cause) : cause;
    }
  }
}

import { HelpdeskClientError } from "./errors";
import type {
  HelpdeskHistoryEntry,
  HelpdeskPage,
  HelpdeskRequest,
} from "./types";

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

export function validateId(id: string): string {
  if (typeof id !== "string" || !UUID.test(id)) {
    throw new HelpdeskClientError("INVALID_INPUT");
  }
  return id;
}

/** Java Long accepts a wider range; reject unsafe JS numbers, never round/coerce. */
export function validateVersion(version: number): number {
  if (!Number.isSafeInteger(version) || version < 0) {
    throw new HelpdeskClientError("INVALID_INPUT");
  }
  return version;
}

export function validateText(text: string, max: number): string {
  if (
    typeof text !== "string" ||
    text.trim().length === 0 ||
    text.length > max
  ) {
    throw new HelpdeskClientError("INVALID_INPUT");
  }
  return text;
}

function invalidResponse(): never {
  throw new HelpdeskClientError("INVALID_RESPONSE");
}

function object(value: unknown): Record<string, unknown> {
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    return invalidResponse();
  }
  return value as Record<string, unknown>;
}

function text(value: unknown): string {
  return typeof value === "string" ? value : invalidResponse();
}

function nullableText(value: unknown): string | null {
  return value === null ? null : text(value);
}

function id(value: unknown): string {
  const candidate = text(value);
  return UUID.test(candidate) ? candidate : invalidResponse();
}

function version(value: unknown): number {
  return typeof value === "number" && Number.isSafeInteger(value) && value >= 0
    ? value
    : invalidResponse();
}

function array(value: unknown): unknown[] {
  return Array.isArray(value) ? value : invalidResponse();
}

export function decodeHelpdeskRequest(body: unknown): HelpdeskRequest {
  const source = object(body);
  if (source.requestType !== "IT_HELPDESK") return invalidResponse();
  return {
    id: id(source.id),
    title: text(source.title),
    description: text(source.description),
    requestType: "IT_HELPDESK",
    requesterId: text(source.requesterId),
    assigneeId: nullableText(source.assigneeId),
    resolution: nullableText(source.resolution),
    assignmentVersion: version(source.assignmentVersion),
    workflowInstanceId: text(source.workflowInstanceId),
    state: text(source.state),
    version: version(source.version),
    allowedActions: array(source.allowedActions).map(text),
    ...(source.requesterDisplayName === undefined
      ? {}
      : { requesterDisplayName: nullableText(source.requesterDisplayName) }),
    ...(source.assigneeDisplayName === undefined
      ? {}
      : { assigneeDisplayName: nullableText(source.assigneeDisplayName) }),
    ...(source.eligibleAssignees === undefined
      ? {}
      : {
          eligibleAssignees:
            source.eligibleAssignees === null
              ? null
              : array(source.eligibleAssignees).map((value) => {
                  const option = object(value);
                  const assigneeId = text(option.id);
                  if (!assigneeId.trim()) return invalidResponse();
                  return {
                    id: assigneeId,
                    displayName: nullableText(option.displayName),
                  };
                }),
        }),
  };
}

export function decodeHelpdeskPage(body: unknown): HelpdeskPage {
  const source = object(body);
  return {
    items: array(source.items).map(decodeHelpdeskRequest),
    nextCursor: source.nextCursor === null ? null : id(source.nextCursor),
  };
}

export function decodeHelpdeskHistory(
  body: unknown,
): readonly HelpdeskHistoryEntry[] {
  return array(body).map((value) => {
    const source = object(value);
    const occurredAt = source.occurredAt;
    if (
      typeof occurredAt !== "string" &&
      !(typeof occurredAt === "number" && Number.isFinite(occurredAt))
    )
      return invalidResponse();
    return {
      transitionId: text(source.transitionId),
      sourceState: text(source.sourceState),
      targetState: text(source.targetState),
      version: version(source.version),
      occurredAt,
    };
  });
}

/** Local protocol errors, independent of the Backend ApiError wire envelope. */
export type HelpdeskClientErrorCode =
  | "INVALID_INPUT"
  | "INVALID_RESPONSE"
  | "HTTP_FAILURE";

const messages: Record<HelpdeskClientErrorCode, string> = {
  INVALID_INPUT: "Dữ liệu gửi tới Helpdesk API không hợp lệ.",
  INVALID_RESPONSE: "Helpdesk API trả dữ liệu không đúng contract đã review.",
  HTTP_FAILURE: "Helpdesk API chưa thể hoàn tất yêu cầu.",
};

export class HelpdeskClientError extends Error {
  constructor(
    readonly code: HelpdeskClientErrorCode,
    readonly status?: number,
    readonly backendCode?: string,
  ) {
    super(messages[code]);
    this.name = "HelpdeskClientError";
  }
}

import { afterEach, describe, expect, it, vi } from "vitest";
import { HttpApiClient } from "../../HttpApiClient";
import {
  MockRequestService,
  requestService as mockService,
} from "../../MockRequestService";
import { requestService as portalService } from "../../portalService";
import { helpdeskId } from "../../../test/helpdeskFixtures";

afterEach(() => vi.restoreAllMocks());

describe("APP-13 LIVE_BLOCKED regression", () => {
  it("keeps MOCK as composition-root default and blocks all nine Helpdesk routes without network", async () => {
    const fetchSpy = vi.spyOn(globalThis, "fetch");
    const xhrSpy = vi.spyOn(XMLHttpRequest.prototype, "send");
    const client = new HttpApiClient();
    const base = "/api/v1/mvp/requests";
    const routes = [
      ["POST", base],
      ["GET", base],
      ["GET", `${base}/${helpdeskId}`],
      ...["triage", "assign", "start", "resolve", "confirm"].map((action) => [
        "POST",
        `${base}/${helpdeskId}/${action}`,
      ]),
      ["GET", `${base}/${helpdeskId}/history`],
    ] as const;
    expect(routes).toHaveLength(9);
    expect(portalService).toBe(mockService);
    expect(portalService).toBeInstanceOf(MockRequestService);
    expect(client.mode).toBe("BLOCKED");
    for (const [method, path] of routes) {
      await expect(
        client.request(method as "GET" | "POST", path),
      ).rejects.toMatchObject({ code: "LIVE_BLOCKED" });
    }
    expect(fetchSpy).not.toHaveBeenCalled();
    expect(xhrSpy).not.toHaveBeenCalled();
  });
});

/** JSON decoding/authentication belong to a future separately approved transport. */
export interface HelpdeskHttpRequest {
  readonly method: "GET" | "POST";
  /** Relative path only, scoped to the reviewed Helpdesk namespace. */
  readonly path: string;
  readonly headers: Readonly<{
    Accept: "application/json";
    "Content-Type"?: "application/json";
  }>;
  readonly body?: Readonly<Record<string, unknown>>;
}

export interface HelpdeskHttpResponse {
  readonly status: number;
  readonly body?: unknown;
}

/**
 * Injected function only: no fetch implementation, host, credentials or LIVE flag.
 * Resolve ALL HTTP responses, including non-2xx; reject only if no usable response
 * was obtained. One invocation must mean one attempt, with no automatic retry,
 * redirect replay, token-refresh replay or write reconciliation.
 */
export type HelpdeskHttpTransport = (
  request: HelpdeskHttpRequest,
) => Promise<HelpdeskHttpResponse>;

/** Wire records from PR #63, exact review SHA below. Not Portal/MOCK models. */
export const HELPDESK_CONTRACT_HEAD =
  "e12d105c89400a5fd69dd6cc1fca670ff1f04f51" as const;

export interface HelpdeskCreateInput {
  readonly title: string;
  readonly description: string;
}

export interface HelpdeskVersionInput {
  readonly expectedVersion: number;
}

export interface HelpdeskAssignInput {
  readonly assigneeId: string;
  readonly expectedAssignmentVersion: number;
}

export interface HelpdeskResolveInput extends HelpdeskVersionInput {
  readonly resolution: string;
}

export interface HelpdeskListInput {
  readonly after?: string;
  readonly limit?: number;
}

export interface HelpdeskAssigneeOption {
  readonly id: string;
  readonly displayName: string | null;
}

/** HelpdeskService.RequestView; preserve missing, null and empty detail fields. */
export interface HelpdeskRequest {
  readonly id: string;
  readonly title: string;
  readonly description: string;
  readonly requestType: "IT_HELPDESK";
  readonly requesterId: string;
  readonly assigneeId: string | null;
  readonly resolution: string | null;
  readonly assignmentVersion: number;
  readonly workflowInstanceId: string;
  readonly state: string;
  readonly version: number;
  /** Backend HTTP capability names, including assign/start; never inferred. */
  readonly allowedActions: readonly string[];
  readonly requesterDisplayName?: string | null;
  readonly assigneeDisplayName?: string | null;
  readonly eligibleAssignees?: readonly HelpdeskAssigneeOption[] | null;
}

export interface HelpdeskPage {
  readonly items: readonly HelpdeskRequest[];
  readonly nextCursor: string | null;
}

/** No synthetic id, actor, note or title is added to the authorized projection. */
export interface HelpdeskHistoryEntry {
  readonly transitionId: string;
  readonly sourceState: string;
  readonly targetState: string;
  readonly version: number;
  /** Java Instant: preserve Jackson ISO text/numeric output without Date coercion. */
  readonly occurredAt: string | number;
}

import type {
  AssignmentCommand,
  AuthorizedHistory,
  CreateRequestInput,
  EligibleAssignees,
  RequestId,
  RequestList,
  RequestSnapshot,
  WorkflowActionCommand,
} from "./types";

/**
 * CANDIDATE Application boundary, deliberately unbound to Portal and HTTP.
 * Implementations return authoritative, authorized projections. Names here do
 * not register endpoints, HTTP methods, JSON fields or JWT authorities.
 *
 * Pagination/filtering, assignment authorization, wire validation, write
 * preconditions and reconciliation remain pending Backend/security approval.
 * No operation may automatically retry a write, including after authentication.
 */
export interface MvpRequestPort {
  create(input: CreateRequestInput): Promise<RequestSnapshot>;
  list(): Promise<RequestList>;
  detail(id: RequestId): Promise<RequestSnapshot>;
  workflowAction(command: WorkflowActionCommand): Promise<RequestSnapshot>;
  assignment(command: AssignmentCommand): Promise<RequestSnapshot>;
  eligibleAssignees(id: RequestId): Promise<EligibleAssignees>;
  history(id: RequestId): Promise<AuthorizedHistory>;
}

