beforeEach(() => {
  sessionStorage.setItem("dxos-demo-role", "employee");
  vi.stubGlobal("matchMedia", () => ({
    matches: false,
    addEventListener: vi.fn(),
    removeEventListener: vi.fn(),
  }));
  fetchSpy = vi
    .spyOn(globalThis, "fetch")
    .mockRejectedValue(new Error("Unexpected LIVE fetch"));
  xhrSpy = vi.spyOn(XMLHttpRequest.prototype, "send").mockImplementation(() => {
    throw new Error("Unexpected LIVE XHR");
  });
});
afterEach(() => {
  expect(fetchSpy).not.toHaveBeenCalled();
  expect(xhrSpy).not.toHaveBeenCalled();
  vi.restoreAllMocks();
  vi.unstubAllGlobals();
});
function clientFixture(transport: HelpdeskHttpTransport) {
  const invalid = vi.fn();
  return {
    service: new HelpdeskRequestService(
      new HelpdeskApiClient(transport, invalid),
    ),
    invalid,
  };
}
function mount(service?: MvpHelpdeskRequestPort, path = ROOT) {
  return render(
    <MemoryRouter initialEntries={[path]}>
      <App helpdeskService={service} />
    </MemoryRouter>,
  );
}
function deferred<T>() {
  let resolve!: (value: T) => void;
  const promise = new Promise<T>((res) => {
    resolve = res;
  });
  return { promise, resolve };
}

describe("APP-14 Portal MVP presentation integration", () => {
  it("runs Create → List → Detail → Triage → Assign → Start → Resolve → Confirm → History through fake transport", async () => {
    const fake = fakeHelpdeskTransport();
    const { service } = clientFixture(fake.transport);
    const legacy = vi.spyOn(defaultService, "list");
    const user = userEvent.setup();
    mount(service);
    expect(await screen.findByText("Chưa có yêu cầu IT")).toBeVisible();
    await user.click(screen.getByRole("link", { name: "Tạo yêu cầu IT" }));
    await user.type(
      screen.getByRole("textbox", { name: "Tiêu đề yêu cầu" }),
      "Sự cố phần mềm APP-14",
    );
    await user.type(
      screen.getByRole("textbox", { name: "Mô tả chi tiết" }),
      "Không thể lưu báo cáo công việc.",
    );
    await user.dblClick(screen.getByRole("button", { name: "Gửi yêu cầu IT" }));
    await user.click(
      await screen.findByRole("link", { name: /Sự cố phần mềm APP-14/ }),
    );
    expect(await screen.findByTestId("mvp-state")).toHaveTextContent(
      "SUBMITTED",
    );
    expect(
      screen.queryByRole("form", { name: "Phân công xử lý" }),
    ).not.toBeInTheDocument();
    await user.dblClick(screen.getByRole("button", { name: "Tiếp nhận" }));
    await waitFor(() =>
      expect(screen.getByTestId("mvp-state")).toHaveTextContent("TRIAGED"),
    );
    await user.selectOptions(
      screen.getByRole("combobox", { name: "Người xử lý" }),
      "choice-0",
    );
    await user.dblClick(screen.getByRole("button", { name: "Phân công" }));
    await waitFor(() =>
      expect(screen.getByTestId("mvp-assignment-version")).toHaveTextContent(
        "1",
      ),
    );
    expect(screen.getByTestId("mvp-version")).toHaveTextContent("2");
    expect(fake.history).toHaveLength(1);
    await user.dblClick(screen.getByRole("button", { name: "Bắt đầu xử lý" }));
    await waitFor(() =>
      expect(screen.getByTestId("mvp-state")).toHaveTextContent("IN_PROGRESS"),
    );
    await user.click(screen.getByRole("button", { name: "Ghi kết quả xử lý" }));
    expect(
      await screen.findByText("Kết quả xử lý không được để trống."),
    ).toBeVisible();
    await user.type(
      screen.getByRole("textbox", { name: "Kết quả xử lý" }),
      "Đã khắc phục lỗi lưu báo cáo.",
    );
    await user.dblClick(
      screen.getByRole("button", { name: "Ghi kết quả xử lý" }),
    );
    await waitFor(() =>
      expect(screen.getByTestId("mvp-state")).toHaveTextContent("RESOLVED"),
    );
    await user.dblClick(
      screen.getByRole("button", { name: "Xác nhận hoàn thành" }),
    );
    await waitFor(() =>
      expect(screen.getByTestId("mvp-state")).toHaveTextContent("CONFIRMED"),
    );
    const history = screen.getByRole("region", { name: "Lịch sử Workflow" });
    expect(within(history).getAllByRole("listitem")).toHaveLength(4);
    expect(within(history).getByText("start_work")).toBeVisible();
    expect(history).not.toHaveTextContent(/actor|ghi chú|event.id/i);
    expect(
      screen.queryByRole("button", { name: "Xác nhận hoàn thành" }),
    ).not.toBeInTheDocument();
    const mutations = fake.calls.filter((request) => request.method === "POST");
    expect(mutations.map((request) => request.path.split("/").at(-1))).toEqual([
      "requests",
      "triage",
      "assign",
      "start",
      "resolve",
      "confirm",
    ]);
    expect(mutations[0].body).toEqual({
      title: "Sự cố phần mềm APP-14",
      description: "Không thể lưu báo cáo công việc.",
      requestType: "IT_HELPDESK",
    });
    expect(mutations[2].body).toEqual({
      assigneeId: "fake-worker",
      expectedAssignmentVersion: 0,
    });
    expect(mutations[3].body).toEqual({ expectedVersion: 2 });
    expect(mutations[4].body).toEqual({
      expectedVersion: 3,
      resolution: "Đã khắc phục lỗi lưu báo cáo.",
    });
    expect(mutations[5].body).toEqual({ expectedVersion: 4 });
    expect(legacy).not.toHaveBeenCalled();
  });

  it("does not mount the MVP service by default or make network requests", async () => {
    mount();
    expect(
      await screen.findByText("MVP chưa được gắn service kiểm thử"),
    ).toBeVisible();
    expect(
      screen.queryByRole("link", { name: "IT Helpdesk MVP · kiểm thử" }),
    ).not.toBeInTheDocument();
  });

  it("honors service capabilities even when role and state suggest other actions", async () => {
    sessionStorage.setItem("dxos-demo-role", "processor");
    const transport = vi
      .fn<HelpdeskHttpTransport>()
      .mockImplementation(async (request) => ({
        status: 200,
        body: request.path.endsWith("/history")
          ? []
          : helpdeskWire({
              state: "future_authoritative_state",
              allowedActions: [],
              eligibleAssignees: [{ id: "worker", displayName: null }],
            }),
      }));
    mount(clientFixture(transport).service, `${ROOT}/${helpdeskId}`);
    expect(await screen.findByTestId("mvp-state")).toHaveTextContent(
      "future_authoritative_state",
    );
    expect(screen.queryByRole("form")).not.toBeInTheDocument();
    expect(
      screen.queryByRole("button", { name: "Tiếp nhận" }),
    ).not.toBeInTheDocument();
    expect(
      screen.getAllByText("Tên không được cung cấp").length,
    ).toBeGreaterThan(0);
    expect(screen.getByText("test-requester-subject")).toBeVisible();
    expect(transport).toHaveBeenCalledTimes(2);
  });

  it.each([
    { eligibleAssignees: undefined },
    { eligibleAssignees: null },
    { eligibleAssignees: [] },
  ])(
    "blocks assignment for eligibility $eligibleAssignees without inventing options",
    async ({ eligibleAssignees }) => {
      const wire = helpdeskWire({ eligibleAssignees });
      const transport = vi
        .fn<HelpdeskHttpTransport>()
        .mockImplementation(async (request) => ({
          status: 200,
          body: request.path.endsWith("/history") ? [] : wire,
        }));
      mount(clientFixture(transport).service, `${ROOT}/${helpdeskId}`);
      expect(
        await screen.findByRole("button", { name: "Phân công" }),
      ).toBeDisabled();
      fireEvent.submit(screen.getByRole("form"));
      expect(transport).toHaveBeenCalledTimes(2);
    },
  );

  it("blocks missing assignmentVersion supplied by a fake presentation port", async () => {
    const { service } = clientFixture(fakeHelpdeskTransport().transport);
    vi.spyOn(service, "detail").mockResolvedValue({
      ...mapHelpdeskRequestPresentation(
        helpdeskWire({
          eligibleAssignees: [{ id: "worker", displayName: null }],
        }),
      ),
      assignmentVersion: undefined as unknown as number,
    });
    vi.spyOn(service, "history").mockResolvedValue([]);
    const assign = vi.spyOn(service, "assign");
    mount(service, `${ROOT}/${helpdeskId}`);
    expect(
      await screen.findByRole("button", { name: "Phân công" }),
    ).toBeDisabled();
    fireEvent.submit(screen.getByRole("form"));
    expect(assign).not.toHaveBeenCalled();
  });

  it.each([403, 404])(
    "renders safe read HTTP %s without leaking resource data",
    async (status) => {
      const transport = vi
        .fn<HelpdeskHttpTransport>()
        .mockResolvedValue({ status, body: { message: "sensitive resource" } });
      mount(clientFixture(transport).service, `${ROOT}/${helpdeskId}`);
      const alert = await screen.findByRole("alert");
      expect(alert).toHaveTextContent(
        status === 403
          ? "Bạn không có quyền"
          : "Không tìm thấy yêu cầu hoặc yêu cầu không khả dụng",
      );
      expect(alert).not.toHaveTextContent("sensitive");
      expect(screen.queryByTestId("mvp-state")).not.toBeInTheDocument();
    },
  );

  it("expires the Portal on 401 and stops protected operations", async () => {
    const transport = vi
      .fn<HelpdeskHttpTransport>()
      .mockResolvedValue({ status: 401 });
    const { service, invalid } = clientFixture(transport);
    mount(service);
    expect(
      await screen.findByRole("heading", { name: "Bắt đầu trải nghiệm" }),
    ).toBeVisible();
    expect(invalid).toHaveBeenCalledTimes(1);
    expect(sessionStorage.getItem("dxos-demo-role")).toBeNull();
    expect(transport).toHaveBeenCalledTimes(1);
    await expect(service.list()).rejects.toMatchObject({
      code: "UNAUTHENTICATED",
    });
    expect(transport).toHaveBeenCalledTimes(1);
  });

  it.each([401, 403, 404])(
    "handles mutation HTTP %s without displaying stale protected Detail or retrying",
    async (status) => {
      const wire = helpdeskWire({
        state: "SUBMITTED",
        allowedActions: ["triage"],
      });
      const transport = vi
        .fn<HelpdeskHttpTransport>()
        .mockImplementation(async (request) =>
          request.method === "POST"
            ? { status, body: { message: "private diagnostic" } }
            : {
                status: 200,
                body: request.path.endsWith("/history") ? [] : wire,
              },
        );
      const { service, invalid } = clientFixture(transport);
      mount(service, `${ROOT}/${helpdeskId}`);
      await userEvent
        .setup()
        .dblClick(await screen.findByRole("button", { name: "Tiếp nhận" }));
      if (status === 401) {
        expect(
          await screen.findByRole("heading", { name: "Bắt đầu trải nghiệm" }),
        ).toBeVisible();
        expect(invalid).toHaveBeenCalledTimes(1);
        expect(sessionStorage.getItem("dxos-demo-role")).toBeNull();
      } else {
        expect(await screen.findByRole("alert")).not.toHaveTextContent(
          "private",
        );
      }
      expect(screen.queryByTestId("mvp-state")).not.toBeInTheDocument();
      expect(
        transport.mock.calls.filter(([request]) => request.method === "POST"),
      ).toHaveLength(1);
    },
  );

  it("does not substitute assignmentVersion for a missing Workflow version", async () => {
    const { service } = clientFixture(fakeHelpdeskTransport().transport);
    vi.spyOn(service, "detail").mockResolvedValue({
      ...mapHelpdeskRequestPresentation(
        helpdeskWire({ allowedActions: ["triage"], assignmentVersion: 17 }),
      ),
      version: undefined as unknown as number,
    });
    vi.spyOn(service, "history").mockResolvedValue([]);
    const triage = vi.spyOn(service, "triage");
    mount(service, `${ROOT}/${helpdeskId}`);
    expect(
      await screen.findByRole("button", { name: "Tiếp nhận" }),
    ).toBeDisabled();
    fireEvent.click(screen.getByRole("button", { name: "Tiếp nhận" }));
    expect(triage).not.toHaveBeenCalled();
  });

  it("hides Detail when History is denied, then recovers only via an explicit read reload", async () => {
    let denied = true;
    const transport = vi
      .fn<HelpdeskHttpTransport>()
      .mockImplementation(async (request) =>
        request.path.endsWith("/history")
          ? { status: denied ? 403 : 200, body: [] }
          : { status: 200, body: helpdeskWire() },
      );
    mount(clientFixture(transport).service, `${ROOT}/${helpdeskId}`);
    expect(await screen.findByRole("alert")).toHaveTextContent(
      "Bạn không có quyền",
    );
    expect(screen.queryByTestId("mvp-state")).not.toBeInTheDocument();
    denied = false;
    await userEvent
      .setup()
      .click(screen.getByRole("button", { name: "Tải lại dữ liệu" }));
    expect(await screen.findByTestId("mvp-state")).toHaveTextContent("TRIAGED");
    expect(transport).toHaveBeenCalledTimes(4);
  });

  it("renders loading, nextCursor and explicit read reload without replacing cursor with a total", async () => {
    const pending = deferred<Awaited<ReturnType<HelpdeskHttpTransport>>>();
    const transport = vi
      .fn<HelpdeskHttpTransport>()
      .mockReturnValueOnce(pending.promise)
      .mockResolvedValue({
        status: 200,
        body: { items: [], nextCursor: null },
      });
    const user = userEvent.setup();
    mount(clientFixture(transport).service);
    expect(screen.getByRole("status")).toHaveTextContent("Đang tải");
    await act(async () =>
      pending.resolve({
        status: 200,
        body: { items: [helpdeskWire()], nextCursor: helpdeskCursor },
      }),
    );
    await user.click(await screen.findByRole("button", { name: "Trang tiếp" }));
    expect(await screen.findByText("Chưa có yêu cầu IT")).toBeVisible();
    expect(transport.mock.calls[1][0].path).toBe(
      `/api/v1/mvp/requests?after=${helpdeskCursor}&limit=20`,
    );
    await user.click(screen.getByRole("button", { name: "Tải lại danh sách" }));
    await waitFor(() => expect(transport).toHaveBeenCalledTimes(3));
  });

  it.each(["triage", "assign"] as const)(
    "%s conflict stops writes until explicit successful Detail/history reload",
    async (action) => {
      let version = 7;
      const wire = () =>
        helpdeskWire({
          state: action === "triage" ? "SUBMITTED" : "TRIAGED",
          version,
          assignmentVersion: 2,
          allowedActions: [action],
          eligibleAssignees: [{ id: "worker", displayName: "Tên kiểm thử" }],
        });
      const transport = vi
        .fn<HelpdeskHttpTransport>()
        .mockImplementation(async (request) =>
          request.method === "POST"
            ? { status: 409 }
            : {
                status: 200,
                body: request.path.endsWith("/history") ? [] : wire(),
              },
        );
      const user = userEvent.setup();
      mount(clientFixture(transport).service, `${ROOT}/${helpdeskId}`);
      await screen.findByTestId("mvp-state");
      if (action === "assign")
        await user.selectOptions(screen.getByRole("combobox"), "choice-0");
      const name = action === "triage" ? "Tiếp nhận" : "Phân công";
      await user.dblClick(screen.getByRole("button", { name }));
      expect(await screen.findByRole("alert")).toHaveTextContent(
        "Dữ liệu đã thay đổi",
      );
      expect(screen.getByRole("button", { name })).toBeDisabled();
      expect(transport).toHaveBeenCalledTimes(3);
      version = 12;
      await user.click(
        screen.getByRole("button", { name: "Tải lại chi tiết và lịch sử" }),
      );
      await waitFor(() =>
        expect(screen.getByTestId("mvp-version")).toHaveTextContent("12"),
      );
      if (action === "assign")
        await user.selectOptions(screen.getByRole("combobox"), "choice-0");
      expect(screen.getByRole("button", { name })).toBeEnabled();
      expect(transport).toHaveBeenCalledTimes(5);
      // The read releases a conflict only. It never replays the failed mutation.
      expect(
        transport.mock.calls.filter(([request]) => request.method === "POST"),
      ).toHaveLength(1);
    },
  );

  it.each(["triage", "assign"] as const)(
    "%s unknown outcome stays blocked across reload and feature navigation",
    async (action) => {
      const wire = helpdeskWire({
        state: action === "triage" ? "SUBMITTED" : "TRIAGED",
        allowedActions: [action],
        eligibleAssignees: [{ id: "worker", displayName: null }],
      });
      const transport = vi
        .fn<HelpdeskHttpTransport>()
        .mockImplementation(async (request) => {
          if (request.method === "POST")
            throw new Error("lost ACK after possible commit");
          return {
            status: 200,
            body: request.path.endsWith("/history")
              ? []
              : request.path.includes("?")
                ? { items: [wire], nextCursor: null }
                : wire,
          };
        });
      const user = userEvent.setup();
      mount(clientFixture(transport).service, `${ROOT}/${helpdeskId}`);
      await screen.findByTestId("mvp-state");
      if (action === "assign")
        await user.selectOptions(screen.getByRole("combobox"), "choice-0");
      const name = action === "triage" ? "Tiếp nhận" : "Phân công";
      await user.dblClick(screen.getByRole("button", { name }));
      expect(await screen.findByRole("alert")).toHaveTextContent(
        "Không gửi lại",
      );
      await user.click(
        screen.getByRole("button", { name: "Tải lại chi tiết và lịch sử" }),
      );
      await screen.findByTestId("mvp-state");
      expect(screen.getByRole("button", { name })).toBeDisabled();
      await user.click(
        screen.getByRole("link", { name: "Danh sách yêu cầu IT" }),
      );
      await user.click(
        await screen.findByRole("link", { name: /Không thể lưu báo cáo/ }),
      );
      await screen.findByTestId("mvp-state");
      expect(screen.getByRole("button", { name })).toBeDisabled();
      expect(
        transport.mock.calls.filter(([request]) => request.method === "POST"),
      ).toHaveLength(1);
    },
  );

  it("keeps unknown create locked across leaving and reopening the form", async () => {
    const transport = vi
      .fn<HelpdeskHttpTransport>()
      .mockImplementation(async (request) => {
        if (request.method === "POST")
          return { status: 503, body: { code: "COMMIT_OUTCOME_UNKNOWN" } };
        return { status: 200, body: { items: [], nextCursor: null } };
      });
    const user = userEvent.setup();
    mount(clientFixture(transport).service, `${ROOT}/new`);
    await user.type(
      screen.getByRole("textbox", { name: "Tiêu đề yêu cầu" }),
      "Title",
    );
    await user.type(
      screen.getByRole("textbox", { name: "Mô tả chi tiết" }),
      "Description",
    );
    await user.dblClick(screen.getByRole("button", { name: "Gửi yêu cầu IT" }));
    expect(await screen.findByRole("alert")).toHaveTextContent("Không gửi lại");
    await user.click(
      screen.getByRole("link", { name: "Xem danh sách và đối soát" }),
    );
    await user.click(
      await screen.findByRole("link", { name: "Tạo yêu cầu IT" }),
    );
    expect(
      screen.getByRole("button", { name: "Gửi yêu cầu IT" }),
    ).toBeDisabled();
    expect(
      transport.mock.calls.filter(([request]) => request.method === "POST"),
    ).toHaveLength(1);
  });

  it("keeps authoritative assignee/state until deferred assignment and Detail reload finish, locking all mutations", async () => {
    const fake = fakeHelpdeskTransport(
      helpdeskWire({ state: "TRIAGED", version: 17, assignmentVersion: 0 }),
    );
    const pending = deferred<void>();
    const transport = vi
      .fn<HelpdeskHttpTransport>()
      .mockImplementation(async (request) => {
        if (request.method === "POST") await pending.promise;
        return fake.transport(request);
      });
    const user = userEvent.setup();
    mount(clientFixture(transport).service, `${ROOT}/${helpdeskId}`);
    await screen.findByTestId("mvp-state");
    await user.selectOptions(screen.getByRole("combobox"), "choice-0");
    await user.dblClick(screen.getByRole("button", { name: "Phân công" }));
    expect(screen.getByTestId("mvp-assignment-version")).toHaveTextContent("0");
    expect(screen.getByText("test-worker-subject")).toBeVisible();
    expect(
      screen.getByRole("button", { name: "Bắt đầu xử lý" }),
    ).toBeDisabled();
    expect(
      screen.getByRole("button", { name: "Tải lại chi tiết và lịch sử" }),
    ).toBeDisabled();
    expect(
      transport.mock.calls.filter(([request]) => request.method === "POST"),
    ).toHaveLength(1);
    await act(async () => pending.resolve());
    await waitFor(() =>
      expect(screen.getByTestId("mvp-assignment-version")).toHaveTextContent(
        "1",
      ),
    );
    expect(screen.getByTestId("mvp-version")).toHaveTextContent("17");
    expect(screen.getByText("fake-worker")).toBeVisible();
  });

  it("never reads the injected service without the existing demo session", async () => {
    sessionStorage.clear();
    const transport = vi.fn<HelpdeskHttpTransport>();
    mount(clientFixture(transport).service);
    expect(
      await screen.findByRole("heading", { name: "Bắt đầu trải nghiệm" }),
    ).toBeVisible();
    expect(transport).not.toHaveBeenCalled();
  });

  it.each([false, true])(
    "ignores obsolete service read data/401 when replaced (401=%s)",
    async (unauthenticated) => {
      const previous = deferred<Awaited<ReturnType<HelpdeskHttpTransport>>>();
      const oldService = clientFixture(() => previous.promise).service;
      const nextTransport = vi.fn<HelpdeskHttpTransport>().mockResolvedValue({
        status: 200,
        body: {
          items: [helpdeskWire({ title: "New service result" })],
          nextCursor: null,
        },
      });
      const next = clientFixture(nextTransport).service;
      const view = mount(oldService);
      view.rerender(
        <MemoryRouter initialEntries={[ROOT]}>
          <App helpdeskService={next} />
        </MemoryRouter>,
      );
      expect(
        await screen.findByRole("link", { name: /New service result/ }),
      ).toBeVisible();
      await act(async () =>
        previous.resolve(
          unauthenticated
            ? { status: 401 }
            : { status: 200, body: { items: [], nextCursor: null } },
        ),
      );
      expect(
        screen.getByRole("link", { name: /New service result/ }),
      ).toBeVisible();
      expect(sessionStorage.getItem("dxos-demo-role")).toBe("employee");
    },
  );
});

import {
  useCallback,
  useEffect,
  useRef,
  useState,
  type FormEvent,
} from "react";
import {
  Link,
  Route,
  Routes,
  useNavigate,
  useParams,
  useSearchParams,
} from "react-router-dom";
import { AssignmentForm } from "../../components/AssignmentForm";
import { Empty, ErrorState, Loading, PageHeading } from "../../components/ui";
import { usePortal } from "../../context";
import { useSessionOperation } from "../../hooks/useSessionOperation";
import { helpdeskAssignmentFormProps } from "../../services/mvp/assignmentBinding";
import {
  executeWriteOnce,
  MvpApplicationError,
} from "../../services/mvp/errors";
import type { MvpHelpdeskRequestPort } from "../../services/mvp/helpdeskPortalPort";
import { useHelpdeskRead } from "./useHelpdeskRead";

const ROOT = "/mvp/helpdesk";
const CREATE = "helpdesk:create";
const labels = {
  triage: "Tiếp nhận",
  start: "Bắt đầu xử lý",
  resolve: "Ghi kết quả xử lý",
  confirm: "Xác nhận hoàn thành",
} as const;
type WorkflowAction = keyof typeof labels;
const validVersion = (value: number) =>
  Number.isSafeInteger(value) && value >= 0;
const validText = (value: string, max: number) =>
  value.trim().length > 0 && value.length <= max;
const personName = (name: string | null | undefined) =>
  name || "Tên không được cung cấp";

/** Shared write lock is scoped to the provider, so navigation cannot replay a
 * pending/unknown write. Only a user-requested authoritative read releases 409.
 */
function useHelpdeskWrite(key: string) {
  const portal = usePortal();
  const captureOperation = useSessionOperation();
  const currentOperation = captureOperation();
  const invoked = useRef(false);
  const acceptRead = useCallback(() => {
    invoked.current = false;
  }, []);
  const stopped = portal.helpdeskWriteStops.get(key);
  const busy = portal.helpdeskPending.has(key);
  async function run(write: () => Promise<unknown>, after: () => void) {
    if (
      !portal.role ||
      stopped ||
      invoked.current ||
      !portal.beginHelpdeskWrite(key)
    )
      return;
    invoked.current = true;
    const operation = captureOperation();
    try {
      await executeWriteOnce(write);
      if (operation.canUpdate()) after();
    } catch (error) {
      // executeWriteOnce always normalizes unknown write failures.
      const failure = error as MvpApplicationError;
      // An old session cannot stop its successor. Unknown writes remain stopped
      // across navigation/logout; their outcome still needs approved recovery.
      if (
        failure.code === "COMMIT_OUTCOME_UNKNOWN" ||
        (operation.isCurrent() && failure.code !== "UNAUTHENTICATED")
      )
        portal.stopHelpdeskWrite(key, failure);
      if (failure.code === "UNAUTHENTICATED" && operation.isCurrent())
        portal.expireSession();
    } finally {
      portal.endHelpdeskWrite(key);
    }
  }
  return {
    run,
    busy,
    stopped,
    blocked: busy || Boolean(stopped),
    portal,
    acceptRead,
    isCurrent: currentOperation.canUpdate,
  };
}

export function HelpdeskPortal() {
  const { helpdeskService } = usePortal();
  if (!helpdeskService)
    return (
      <Empty
        title="MVP chưa được gắn service kiểm thử"
        description="MOCK mặc định vẫn hoạt động. Tích hợp LIVE tiếp tục BLOCKED."
      />
    );
  return (
    <>
      <p className="aside-footnote">
        IT Helpdesk MVP · service kiểm thử được inject · LIVE BLOCKED
      </p>
      <Routes>
        <Route index element={<HelpdeskList service={helpdeskService} />} />
        <Route
          path="new"
          element={<HelpdeskCreate service={helpdeskService} />}
        />
        <Route path=":id" element={<DetailRoute service={helpdeskService} />} />
        <Route
          path="*"
          element={
            <Empty
              title="Không tìm thấy trang MVP"
              description="Chọn danh sách yêu cầu để tiếp tục."
            />
          }
        />
      </Routes>
    </>
  );
}

function HelpdeskList({ service }: { service: MvpHelpdeskRequestPort }) {
  const [params, setParams] = useSearchParams();
  const after = params.get("after") ?? undefined;
  const load = useCallback(
    () => service.list({ ...(after ? { after } : {}), limit: 20 }),
    [service, after],
  );
  const read = useHelpdeskRead(load);
  return (
    <>
      <PageHeading
        title="IT Helpdesk MVP"
        description="Yêu cầu IT Support trong phiên kiểm thử."
      >
        <Link className="button primary" to={`${ROOT}/new`}>
          Tạo yêu cầu IT
        </Link>
      </PageHeading>
      <section className="panel">
        <div className="panel-heading">
          <h2>Danh sách yêu cầu</h2>
          <button
            className="text-link"
            disabled={read.loading}
            onClick={read.reload}
          >
            Tải lại danh sách
          </button>
        </div>
        {read.loading ? (
          <Loading />
        ) : read.error ? (
          <ErrorState message={read.error} onRetry={read.reload} />
        ) : !read.data?.items.length ? (
          <Empty
            title="Chưa có yêu cầu IT"
            description="Tạo yêu cầu để bắt đầu phiên kiểm thử."
          />
        ) : (
          <div className="table-scroll">
            <table>
              <caption className="sr-only">Yêu cầu IT Helpdesk MVP</caption>
              <thead>
                <tr>
                  <th>Yêu cầu</th>
                  <th>Trạng thái</th>
                  <th>Người yêu cầu</th>
                  <th>Người xử lý</th>
                </tr>
              </thead>
              <tbody>
                {read.data.items.map((item) => (
                  <tr key={item.id}>
                    <td>
                      <Link
                        className="request-title"
                        to={`${ROOT}/${encodeURIComponent(item.id)}`}
                      >
                        <span className="request-id">{item.id}</span>
                        <strong>{item.title}</strong>
                      </Link>
                    </td>
                    <td>
                      <span className="badge">{item.state}</span>
                    </td>
                    <td>{personName(item.requesterDisplayName)}</td>
                    <td>
                      {item.assigneeId === null
                        ? "Chưa phân công"
                        : personName(item.assigneeDisplayName)}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
        <div className="pagination">
          <button
            className="button secondary small"
            disabled={read.loading || !after}
            onClick={() => setParams({})}
          >
            Trang đầu
          </button>
          <button
            className="button secondary small"
            disabled={read.loading || !read.data?.nextCursor}
            onClick={() => {
              if (read.data?.nextCursor)
                setParams({ after: read.data.nextCursor });
            }}
          >
            Trang tiếp
          </button>
        </div>
      </section>
    </>
  );
}

function HelpdeskCreate({ service }: { service: MvpHelpdeskRequestPort }) {
  const navigate = useNavigate();
  const write = useHelpdeskWrite(CREATE);
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [invalid, setInvalid] = useState(false);
  async function submit(event: FormEvent) {
    event.preventDefault();
    if (write.blocked) return;
    if (!validText(title, 200) || !validText(description, 4000)) {
      setInvalid(true);
      return;
    }
    let id: string | undefined;
    await write.run(
      async () => {
        id = (await service.create({ title, description })).id;
      },
      () => {
        // Return to the authoritative list; the new resource can be opened there.
        if (id) navigate(ROOT);
      },
    );
  }
  return (
    <>
      <Link className="back-link" to={ROOT}>
        Danh sách yêu cầu IT
      </Link>
      <PageHeading
        title="Tạo yêu cầu IT Support"
        description="Chỉ dùng dữ liệu kiểm thử; loại yêu cầu IT_HELPDESK."
      />
      <div className="form-layout">
        <form
          className="panel request-form"
          aria-label="Tạo yêu cầu IT"
          onSubmit={submit}
        >
          <fieldset disabled={write.blocked}>
            <legend>Thông tin yêu cầu</legend>
            <label className="field">
              Tiêu đề yêu cầu
              <input
                required
                maxLength={200}
                value={title}
                onChange={(event) => setTitle(event.target.value)}
              />
            </label>
            <label className="field">
              Mô tả chi tiết
              <textarea
                required
                maxLength={4000}
                rows={5}
                value={description}
                onChange={(event) => setDescription(event.target.value)}
              />
            </label>
          </fieldset>
          {invalid && (
            <p className="field-error" role="alert">
              Tiêu đề và mô tả không được để trống.
            </p>
          )}
          {write.stopped && <ErrorState message={write.stopped.message} />}
          <div className="form-actions">
            <Link to={ROOT} className="button secondary">
              Xem danh sách và đối soát
            </Link>
            <button className="button primary" disabled={write.blocked}>
              {write.busy ? "Đang gửi…" : "Gửi yêu cầu IT"}
            </button>
          </div>
        </form>
      </div>
    </>
  );
}

function DetailRoute({ service }: { service: MvpHelpdeskRequestPort }) {
  const { id = "" } = useParams();
  return <HelpdeskDetail key={id} id={id} service={service} />;
}

function HelpdeskDetail({
  id,
  service,
}: {
  id: string;
  service: MvpHelpdeskRequestPort;
}) {
  const write = useHelpdeskWrite(id);
  const [resolution, setResolution] = useState("");
  const [invalid, setInvalid] = useState(false);
  const [reloadIntent, setReloadIntent] = useState(false);
  const load = useCallback(async () => {
    const [detail, history] = await Promise.all([
      service.detail(id),
      service.history(id),
    ]);
    return { detail, history };
  }, [service, id]);
  const read = useHelpdeskRead(load);
  useEffect(() => {
    if (read.data) write.acceptRead();
  }, [read.data, write.acceptRead]);
  useEffect(() => {
    if (reloadIntent && read.data) {
      write.portal.releaseHelpdeskReadStop(id);
      setReloadIntent(false);
    }
  }, [reloadIntent, read.data, id, write.portal.releaseHelpdeskReadStop]);
  function reload() {
    if (!write.busy) {
      setReloadIntent(true);
      read.reload();
    }
  }
  if (read.loading) return <Loading />;
  if (read.error || !read.data)
    return (
      <ErrorState
        message={
          read.error ?? "Không tìm thấy yêu cầu hoặc yêu cầu không khả dụng."
        }
        onRetry={reload}
      />
    );
  const { detail, history } = read.data;
  if (
    write.stopped?.code === "FORBIDDEN" ||
    write.stopped?.code === "NOT_FOUND"
  ) {
    return <ErrorState message={write.stopped.message} onRetry={reload} />;
  }
  const actions = (Object.keys(labels) as WorkflowAction[]).filter((action) =>
    detail.allowedActions.includes(action),
  );
  const blocked = write.blocked || !validVersion(detail.version);
  const assignment = helpdeskAssignmentFormProps(
    detail,
    service,
    () => {
      if (write.isCurrent()) read.reload();
    },
    write.isCurrent,
  );
  const binding = assignment?.submission;
  // The APP-11 binding owns ID membership, assignment guard and Detail reload.
  // Wrap only its invocation to share the Portal's pending/uncertain write stop.
  const assignmentSubmission =
    binding?.status === "ready"
      ? {
          ...binding,
          submitAssignment: async (
            selected: Parameters<typeof binding.submitAssignment>[0],
          ) => {
            await write.run(
              () => binding.submitAssignment(selected),
              () => {},
            );
          },
        }
      : binding;
  async function transition(action: WorkflowAction) {
    if (blocked || !detail.allowedActions.includes(action)) return;
    if (action === "resolve" && !validText(resolution, 4000)) {
      setInvalid(true);
      return;
    }
    setInvalid(false);
    await write.run(
      () =>
        action === "resolve"
          ? service.resolve(id, { expectedVersion: detail.version, resolution })
          : service[action](id, { expectedVersion: detail.version }),
      () => {
        setResolution("");
        read.reload();
      },
    );
  }
  return (
    <>
      <Link className="back-link" to={ROOT}>
        Danh sách yêu cầu IT
      </Link>
      <PageHeading
        eyebrow={detail.id}
        title={detail.title}
        description="IT Support · dữ liệu từ service kiểm thử"
      >
        <span className="badge">{detail.state}</span>
      </PageHeading>
      <div className="detail-layout">
        <div>
          <section className="panel detail-content">
            <div className="panel-heading">
              <h2>Nội dung yêu cầu</h2>
            </div>
            <p className="request-description">{detail.description}</p>
            {detail.resolution !== null && (
              <>
                <h2>Kết quả xử lý</h2>
                <p>{detail.resolution}</p>
              </>
            )}
          </section>
          <section
            className="panel detail-timeline"
            aria-label="Lịch sử Workflow"
          >
            <div className="panel-heading">
              <h2>Lịch sử xử lý</h2>
            </div>
            {!history.length ? (
              <Empty
                title="Chưa có lịch sử được cung cấp"
                description="Chỉ hiển thị lịch sử được phép đọc từ service."
              />
            ) : (
              <ol className="timeline">
                {history.map((entry, index) => (
                  <li key={index}>
                    <span className="timeline-dot" aria-hidden="true" />
                    <div>
                      <div className="timeline-title">
                        <strong>{entry.transitionId}</strong>
                        <span>{entry.occurredAt}</span>
                      </div>
                      <p>
                        {entry.sourceState} → {entry.targetState}
                      </p>
                      <p>Workflow version: {entry.version}</p>
                    </div>
                  </li>
                ))}
              </ol>
            )}
          </section>
        </div>
        <aside>
          <section className="panel metadata">
            <div className="panel-heading">
              <h2>Thông tin yêu cầu</h2>
            </div>
            <dl>
              <dt>Trạng thái Workflow</dt>
              <dd data-testid="mvp-state">{detail.state}</dd>
              <dt>Workflow version</dt>
              <dd data-testid="mvp-version">{detail.version}</dd>
              <dt>Assignment version</dt>
              <dd data-testid="mvp-assignment-version">
                {detail.assignmentVersion ?? "Chưa được cung cấp"}
              </dd>
              <dt>Người yêu cầu</dt>
              <dd>{personName(detail.requesterDisplayName)}</dd>
              <dt>Requester ID</dt>
              <dd>{detail.requesterId}</dd>
              <dt>Người xử lý</dt>
              <dd>
                {detail.assigneeId === null
                  ? "Chưa phân công"
                  : personName(detail.assigneeDisplayName)}
              </dd>
              {detail.assigneeId !== null && (
                <>
                  <dt>Assignee ID</dt>
                  <dd>{detail.assigneeId}</dd>
                </>
              )}
            </dl>
          </section>
          <section className="panel action-panel">
            <h2>Thao tác xử lý</h2>
            {write.stopped && <ErrorState message={write.stopped.message} />}
            {!actions.length && !assignment && (
              <p>Không có thao tác được service cung cấp.</p>
            )}
            <fieldset disabled={blocked}>
              <legend className="sr-only">Workflow actions</legend>
              {actions.includes("resolve") && (
                <label className="field">
                  Kết quả xử lý
                  <textarea
                    maxLength={4000}
                    rows={4}
                    value={resolution}
                    onChange={(event) => setResolution(event.target.value)}
                  />
                </label>
              )}
              {invalid && (
                <p className="field-error" role="alert">
                  Kết quả xử lý không được để trống.
                </p>
              )}
              {actions.map((action) => (
                <button
                  type="button"
                  className="button primary"
                  key={action}
                  disabled={blocked}
                  onClick={(event) => {
                    if (event.detail <= 1) transition(action);
                  }}
                >
                  {labels[action]}
                </button>
              ))}
            </fieldset>
            <button
              className="text-link"
              disabled={write.busy}
              onClick={reload}
            >
              Tải lại chi tiết và lịch sử
            </button>
          </section>
          {assignment && (
            <fieldset disabled={write.blocked} aria-label="Phân công yêu cầu">
              <legend className="sr-only">Assignment</legend>
              <AssignmentForm
                key={read.revision}
                {...assignment}
                loading={write.busy}
                submission={
                  write.stopped
                    ? { status: "blocked", reason: write.stopped.message }
                    : assignmentSubmission
                }
              />
            </fieldset>
          )}
        </aside>
      </div>
    </>
  );
}

import { useEffect, useState } from "react";
import { usePortal } from "../../context";
import { useSessionOperation } from "../../hooks/useSessionOperation";
import { MvpApplicationError } from "../../services/mvp/errors";
import { HelpdeskClientError } from "../../services/mvp/http/errors";

export function helpdeskErrorMessage(error: unknown) {
  return error instanceof MvpApplicationError ||
    error instanceof HelpdeskClientError
    ? error.message
    : "Không thể tải dữ liệu Helpdesk. Vui lòng tải lại.";
}

/** Cancel obsolete reads; a new loader must never expose a previous resource. */
export function useHelpdeskRead<T>(load: () => Promise<T>) {
  const { expireSession } = usePortal();
  const captureOperation = useSessionOperation();
  const [revision, setRevision] = useState(0);
  const [result, setResult] = useState<{
    load: typeof load;
    captureOperation: typeof captureOperation;
    revision: number;
    data?: T;
    error?: string;
  }>();
  useEffect(() => {
    let active = true;
    const operation = captureOperation();
    Promise.resolve()
      .then(() => {
        if (active && operation.canUpdate()) return load();
      })
      .then(
        (data) => {
          if (active && operation.canUpdate())
            setResult({ load, captureOperation, revision, data });
        },
        (error: unknown) => {
          if (!operation.isCurrent()) return;
          if (
            error instanceof MvpApplicationError &&
            error.code === "UNAUTHENTICATED"
          )
            expireSession();
          if (active && operation.canUpdate())
            setResult({
              load,
              captureOperation,
              revision,
              error: helpdeskErrorMessage(error),
            });
        },
      );
    return () => {
      active = false;
    };
  }, [load, revision, expireSession, captureOperation]);
  const current =
    result?.load === load &&
    result.captureOperation === captureOperation &&
    result.revision === revision
      ? result
      : undefined;
  return {
    data: current?.data,
    error: current?.error,
    loading: current === undefined,
    reload: () => setRevision((value) => value + 1),
    revision,
  };
}

import { useCallback, useEffect, useRef } from "react";
import { usePortal } from "../context";

/** Capture before awaiting: 401 still expires the same session after navigation,
 * while UI updates require the originating screen and session to remain current.
 * Cancelling UI work does not cancel or replay an attempted write.
 */
export function useSessionOperation() {
  const { captureSession } = usePortal();
  const mounted = useRef(false);
  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
    };
  }, []);
  return useCallback(() => {
    const isCurrent = captureSession();
    return {
      isCurrent,
      canUpdate: () => mounted.current && isCurrent(),
    };
  }, [captureSession]);
}

import type { AssignmentFormProps } from "../../components/AssignmentForm";
import type { HelpdeskAssignmentService } from "./HelpdeskRequestService";
import type { HelpdeskPortalRequestPresentation } from "./helpdeskPresentation";

/**
 * Prepare the standalone form only from authorized Detail. Caller must keep the
 * form unmounted when this returns null. Eligibility never grants permission.
 * APP-14 mounts this through its separate MVP model, never legacy MOCK data.
 */
export function helpdeskAssignmentFormProps(
  detail: HelpdeskPortalRequestPresentation,
  service: HelpdeskAssignmentService,
  onAuthoritativeDetail: (detail: HelpdeskPortalRequestPresentation) => void,
  isCurrent: () => boolean = () => true,
): AssignmentFormProps | null {
  if (!detail.allowedActions.includes("assign")) return null;

  const eligible = detail.eligibleAssignees;
  const version = detail.assignmentVersion;
  const valid =
    detail.state === "TRIAGED" &&
    Number.isSafeInteger(version) &&
    version >= 0 &&
    eligible != null &&
    eligible.items.length > 0 &&
    eligible.items.every(
      (item) =>
        typeof item.id.value === "string" &&
        item.id.value.trim().length > 0 &&
        item.id.value.length <= 1024,
    );

  return {
    currentAssignee: detail.currentAssignee,
    eligibleAssignees: eligible ?? undefined,
    assignmentPermission: "allowed",
    submission: valid
      ? {
          status: "ready",
          submitAssignment: async (selectedId) => {
            // Membership is checked again; never serialize a name or another token.
            const selected = eligible.items.find(
              (item) => item.id === selectedId,
            );
            if (!selected || typeof selected.id.value !== "string") {
              throw new RangeError(
                "Assignee was not supplied by authorized Detail.",
              );
            }
            await service.assign(detail.id, {
              assigneeId: selected.id.value,
              expectedAssignmentVersion: version,
            });
            // A confirmed write is not undone by leaving the screen/session.
            // Do not start another protected read for the obsolete UI.
            if (!isCurrent()) return;
            // Mutation responses omit names/eligibility at this Backend HEAD.
            // Reload Detail after confirmed success; no optimistic local updates.
            onAuthoritativeDetail(await service.detail(detail.id));
          },
        }
      : {
          status: "blocked",
          reason:
            "Chưa có dữ liệu phân công hợp lệ. Tải lại chi tiết trước khi tiếp tục.",
        },
  };
}

import { helpdeskId, helpdeskWire } from "./helpdeskFixtures";
import type {
  HelpdeskHistoryEntry,
  HelpdeskRequest,
} from "../services/mvp/http/types";
import type {
  HelpdeskHttpRequest,
  HelpdeskHttpTransport,
} from "../services/mvp/http/transport";

/** Test-only Backend simulation. Never imported by main.tsx or default App.
 * Capabilities are fixture responses, not Portal authorization rules.
 */
export function fakeHelpdeskTransport(seed?: HelpdeskRequest) {
  let current = seed;
  const calls: HelpdeskHttpRequest[] = [];
  const history: HelpdeskHistoryEntry[] = [];
  const capabilities: Record<string, string[]> = {
    SUBMITTED: ["triage"],
    TRIAGED: ["assign", "start"],
    IN_PROGRESS: ["resolve"],
    RESOLVED: ["confirm"],
    CONFIRMED: [],
  };
  function response(detail = false): HelpdeskRequest {
    const value = {
      ...current!,
      allowedActions:
        current!.state === "TRIAGED" && current!.assigneeId === null
          ? ["assign"]
          : (capabilities[current!.state] ?? current!.allowedActions),
    };
    const {
      requesterDisplayName: _requester,
      assigneeDisplayName: _assignee,
      eligibleAssignees: _eligible,
      ...bare
    } = value;
    return detail
      ? {
          ...bare,
          requesterDisplayName: "Người gửi kiểm thử",
          ...(bare.assigneeId
            ? { assigneeDisplayName: "Người xử lý kiểm thử" }
            : {}),
          ...(bare.allowedActions.includes("assign")
            ? {
                eligibleAssignees: [
                  { id: "fake-worker", displayName: "Người xử lý kiểm thử" },
                ],
              }
            : {}),
        }
      : bare;
  }
  const transport: HelpdeskHttpTransport = async (request) => {
    calls.push(structuredClone(request));
    const url = new URL(request.path, "http://fake.invalid");
    const base = "/api/v1/mvp/requests";
    if (url.pathname === base && request.method === "POST") {
      current = helpdeskWire({
        id: helpdeskId,
        title: request.body!.title as string,
        description: request.body!.description as string,
        state: "SUBMITTED",
        version: 1,
        assignmentVersion: 0,
        assigneeId: null,
      });
      return { status: 201, body: response() };
    }
    if (url.pathname === base && request.method === "GET")
      return {
        status: 200,
        body: {
          items: current && !url.searchParams.has("after") ? [response()] : [],
          nextCursor: null,
        },
      };
    if (!current || !url.pathname.startsWith(`${base}/${current.id}`))
      return { status: 404 };
    const command = url.pathname.slice(`${base}/${current.id}`.length);
    if (request.method === "GET") {
      if (command === "") return { status: 200, body: response(true) };
      if (command === "/history")
        return { status: 200, body: structuredClone(history) };
      return { status: 404 };
    }
    const action = command.slice(1);
    if (!response().allowedActions.includes(action)) return { status: 403 };
    if (action === "assign") {
      if (request.body?.expectedAssignmentVersion !== current.assignmentVersion)
        return { status: 409 };
      current = {
        ...current,
        assigneeId: request.body!.assigneeId as string,
        assignmentVersion: current.assignmentVersion + 1,
      };
      return { status: 200, body: response() };
    }
    if (request.body?.expectedVersion !== current.version)
      return { status: 409 };
    const target: Record<string, string> = {
      triage: "TRIAGED",
      start: "IN_PROGRESS",
      resolve: "RESOLVED",
      confirm: "CONFIRMED",
    };
    if (!target[action]) return { status: 404 };
    if (action === "start" && current.assigneeId === null)
      return { status: 403 };
    const sourceState = current.state;
    current = {
      ...current,
      state: target[action],
      version: current.version + 1,
      ...(action === "resolve"
        ? { resolution: request.body!.resolution as string }
        : {}),
    };
    history.push({
      transitionId: action === "start" ? "start_work" : action,
      sourceState,
      targetState: current.state,
      version: current.version,
      occurredAt: "2026-10-26T10:30:00Z",
    });
    return { status: 200, body: response() };
  };
  return { transport, calls, history };
}

import { test, expect } from "@playwright/test";
import AxeBuilder from "@axe-core/playwright";

test("APP-14 fake transport journey reuses Portal shell with no API/external requests", async ({
  page,
}) => {
  test.skip(
    !test.info().project.metadata.fakeHelpdeskPreview,
    "Use tests/mvp.playwright.config.ts for the explicit fake preview entry.",
  );
  const unexpected: string[] = [];
  const errors: string[] = [];
  page.on("request", (request) => {
    if (
      !request.url().startsWith("http://127.0.0.1:4173/") ||
      /\/api\//.test(request.url())
    )
      unexpected.push(request.url());
  });
  page.on("pageerror", (error) => errors.push(error.message));
  await page.goto("/tests/mvp-preview.html");
  await page.getByRole("button", { name: "Vào phiên demo" }).click();
  await page.getByRole("link", { name: "IT Helpdesk MVP · kiểm thử" }).click();
  await expect(
    page.getByText("Chưa có yêu cầu IT", { exact: true }),
  ).toBeVisible();
  await page.getByRole("link", { name: "Tạo yêu cầu IT", exact: true }).click();
  await page
    .getByRole("textbox", { name: "Tiêu đề yêu cầu" })
    .fill("APP-14 kiểm tra báo cáo công việc");
  await page
    .getByRole("textbox", { name: "Mô tả chi tiết" })
    .fill("Không lưu được báo cáo trong phần mềm nội bộ.");
  await page.getByRole("button", { name: "Gửi yêu cầu IT" }).dblclick();
  await page
    .getByRole("link", { name: /APP-14 kiểm tra báo cáo công việc/ })
    .click();
  await expect(page.getByTestId("mvp-state")).toHaveText("SUBMITTED");
  await page.getByRole("button", { name: "Tiếp nhận", exact: true }).dblclick();
  await expect(page.getByTestId("mvp-state")).toHaveText("TRIAGED");
  await page
    .getByRole("combobox", { name: "Người xử lý" })
    .selectOption("choice-0");
  await page.getByRole("button", { name: "Phân công", exact: true }).dblclick();
  await expect(page.getByTestId("mvp-assignment-version")).toHaveText("1");
  await expect(page.getByTestId("mvp-version")).toHaveText("2");
  await page.getByRole("button", { name: "Bắt đầu xử lý" }).click();
  await expect(page.getByTestId("mvp-state")).toHaveText("IN_PROGRESS");
  await page
    .getByRole("textbox", { name: "Kết quả xử lý" })
    .fill("Đã sửa lỗi và kiểm tra lưu báo cáo.");
  await page.getByRole("button", { name: "Ghi kết quả xử lý" }).click();
  await expect(page.getByTestId("mvp-state")).toHaveText("RESOLVED");
  await page.getByRole("button", { name: "Xác nhận hoàn thành" }).dblclick();
  await expect(page.getByTestId("mvp-state")).toHaveText("CONFIRMED");
  await expect(
    page
      .getByRole("region", { name: "Lịch sử Workflow" })
      .getByRole("listitem"),
  ).toHaveCount(4);
  await page
    .getByRole("button", { name: "Tải lại chi tiết và lịch sử" })
    .click();
  await expect(page.getByTestId("mvp-state")).toHaveText("CONFIRMED");
  for (const width of [1440, 390]) {
    await page.setViewportSize({ width, height: 1100 });
    expect(
      await page.evaluate(
        () => document.documentElement.scrollWidth <= innerWidth,
      ),
    ).toBeTruthy();
    const result = await new AxeBuilder({ page })
      .withTags(["wcag2a", "wcag2aa", "wcag21aa"])
      .analyze();
    expect(result.violations.map(({ id }) => id)).toEqual([]);
  }
  expect(unexpected).toEqual([]);
  expect(errors).toEqual([]);
});

