      await openSession(user);
      await act(async () => pending.resolve({ status: 401 }));
      expect(
        screen.getByRole("heading", { name: "Bắt đầu trải nghiệm" }),
      ).toBeVisible();
      expect(sessionStorage.getItem("dxos-demo-role")).toBeNull();
    },
