@ParameterizedTest
@MethodSource("trailingContent")
void rejectsTrailingContentBeforeCallingRuntime(String suffix, String body, String trailing) throws Exception {
    mvc.perform(post(BASE + suffix).contentType(MediaType.APPLICATION_JSON).content(body + " " + trailing)
                    .requestAttr(WorkflowController.TRUSTED_ACTOR_ATTRIBUTE, ACTOR))
            .andExpect(status().isBadRequest())
            .andExpect(jsonPath("$.status").value(400))
            .andExpect(jsonPath("$.code").value("INVALID_BODY"))
            .andExpect(jsonPath("$.errors").isEmpty())
            .andExpect(content().string(not(containsString("attacker"))))
            .andExpect(content().string(not(containsString("evil"))));
    verifyNoInteractions(runtime, requestService);
}

private static Stream<Arguments> trailingContent() {
    return Stream.of(
            new String[]{"", CREATE, "{\"actorId\":\"attacker\"}"},
            new String[]{"/instance-1/activate", "{}", "{\"lifecycle\":\"COMPLETED\"}"},
            new String[]{"/instance-1/transitions", TRANSITION, "{\"targetState\":\"evil\"}"})
            .flatMap(input -> Stream.of(input[2], "[]", "null", "42", "true", "\"extra\"", "not-json")
                    .map(trailing -> Arguments.of(input[0], input[1], trailing)));
}

@ParameterizedTest
@ValueSource(strings = {"", "/instance-1/activate", "/instance-1/transitions"})
void rejectsTrailingContentForVendorJson(String suffix) throws Exception {
    String body = suffix.isEmpty() ? CREATE : suffix.endsWith("activate") ? "{}" : TRANSITION;
    mvc.perform(post(BASE + suffix).contentType("application/vnd.workflow+json").content(body + " null")
                    .requestAttr(WorkflowController.TRUSTED_ACTOR_ATTRIBUTE, ACTOR))
            .andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("INVALID_BODY"));
    verifyNoInteractions(runtime);
}

@ParameterizedTest
@ValueSource(strings = {"", "/instance-1/activate", "/instance-1/transitions"})
void acceptsTrailingJsonWhitespace(String suffix) throws Exception {
    when(runtime.createInstance("instance-1", "publication", 7, RESOURCE)).thenReturn(initial());
    when(runtime.activateInstance("instance-1")).thenReturn(initial().activate(DEFINITION, NOW));
    when(runtime.executeTransition(any())).thenReturn(initial().activate(DEFINITION, NOW).transition(DEFINITION,
            new TransitionCommand("instance-1", "submit", ACTOR, 0), NOW));
    String body = suffix.isEmpty() ? CREATE : suffix.endsWith("activate") ? "{}" : TRANSITION;
    mvc.perform(post(BASE + suffix).contentType(MediaType.APPLICATION_JSON).content(body + " \t\r\n")
                    .requestAttr(WorkflowController.TRUSTED_ACTOR_ATTRIBUTE, ACTOR))
            .andExpect(status().is(suffix.isEmpty() ? 201 : 200));
    if (suffix.isEmpty()) verify(runtime).createInstance("instance-1", "publication", 7, RESOURCE);
    else if (suffix.endsWith("activate")) verify(runtime).activateInstance("instance-1");
    else verify(runtime).executeTransition(new TransitionCommand("instance-1", "submit", ACTOR, 0));
    verifyNoMoreInteractions(runtime);
}

@Test
void leavesSharedMapperAndRequestMessageConversionUnchanged() throws Exception {
    assertThat(objectMapper.isEnabled(DeserializationFeature.FAIL_ON_TRAILING_TOKENS)).isFalse();
    CreateRequestDto input = new CreateRequestDto("Repair printer", "Printer is offline", "IT_SUPPORT");
    UUID id = UUID.fromString("f3bf54b7-fdab-4b45-85dd-94cbd8587a9d");
    when(requestService.create(input)).thenReturn(new RequestResponse(id, input.title(), input.description(),
            input.requestType(), RequestStatus.NEW, null, null, 0L, NOW, NOW));
    mvc.perform(post("/api/v1/requests").contentType(MediaType.APPLICATION_JSON).content("""
            {"title":"Repair printer","description":"Printer is offline","requestType":"IT_SUPPORT"} {}
            """))
            .andExpect(status().isCreated()).andExpect(jsonPath("$.id").value(id.toString()));
    verify(requestService).create(input);
    verifyNoMoreInteractions(requestService);
    verifyNoInteractions(runtime);
}

package com.tricore.dxos.gateway.workflow.controller;

import com.tricore.dxos.common.error.ApiError;
import com.tricore.dxos.core.workflow.WorkflowErrorCode;
import com.tricore.dxos.core.workflow.WorkflowException;
import org.springframework.http.ResponseEntity;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.web.HttpMediaTypeNotSupportedException;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.ServletRequestBindingException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;
import org.springframework.web.method.annotation.HandlerMethodValidationException;

import java.util.Map;
import java.util.TreeMap;

@RestControllerAdvice(assignableTypes = WorkflowController.class)
public class WorkflowExceptionHandler {
    @ExceptionHandler(WorkflowException.class)
    public ResponseEntity<ApiError> workflow(WorkflowException exception) {
        WorkflowErrorCode code = exception.code();
        int status = switch (code) {
            case INSTANCE_ALREADY_EXISTS, VERSION_CONFLICT, TRANSITION_NOT_ALLOWED, INSTANCE_COMPLETED -> 409;
            case DEFINITION_NOT_FOUND, INSTANCE_NOT_FOUND -> 404;
            case INVALID_TRANSITION -> 422;
            case OPERATION_FAILURE, COMMIT_OUTCOME_UNKNOWN -> 500;
        };
        String message = switch (code) {
            case INSTANCE_ALREADY_EXISTS -> "Workflow instance already exists";
            case VERSION_CONFLICT -> "Workflow version conflict";
            case DEFINITION_NOT_FOUND -> "Workflow definition version not found";
            case INSTANCE_NOT_FOUND -> "Workflow instance not found";
            case INVALID_TRANSITION -> "Unknown workflow transition";
            case TRANSITION_NOT_ALLOWED -> "Workflow operation is not allowed in the current state";
            case INSTANCE_COMPLETED -> "Workflow instance is completed";
            case OPERATION_FAILURE -> "Workflow operation failed";
            case COMMIT_OUTCOME_UNKNOWN ->
                    "Commit outcome is unknown; the write may have committed. Reconcile authoritative instance/history; do not automatically retry";
        };
        return error(status, code.name(), message, Map.of());
    }

    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<ApiError> validation(MethodArgumentNotValidException exception) {
        Map<String, String> errors = new TreeMap<>();
        exception.getBindingResult().getFieldErrors()
                .forEach(field -> errors.putIfAbsent(field.getField(), field.getDefaultMessage()));
        return error(400, "VALIDATION_FAILED", "Workflow input is invalid", errors);
    }

    @ExceptionHandler(HandlerMethodValidationException.class)
    public ResponseEntity<ApiError> methodValidation(HandlerMethodValidationException exception) {
        return exception.isForReturnValue() ? internalFailure()
                : error(400, "VALIDATION_FAILED", "Workflow input is invalid", Map.of());
    }

    @ExceptionHandler(HttpMessageNotReadableException.class)
    public ResponseEntity<ApiError> invalidBody() {
        return error(400, "INVALID_BODY", "JSON fields are not accepted by this endpoint", Map.of());
    }

    @ExceptionHandler(HttpMediaTypeNotSupportedException.class)
    public ResponseEntity<ApiError> unsupportedMediaType() {
        return error(415, "UNSUPPORTED_MEDIA_TYPE", "Workflow input requires application/json", Map.of());
    }

    @ExceptionHandler(ServletRequestBindingException.class)
    public ResponseEntity<ApiError> missingTrustedActor() {
        return error(401, "AUTHENTICATION_REQUIRED", "A verified workflow actor is required", Map.of());
    }

    @ExceptionHandler(Exception.class)
    public ResponseEntity<ApiError> internalFailure() {
        return error(500, "INTERNAL_ERROR", "Workflow operation failed", Map.of());
    }

    private ResponseEntity<ApiError> error(int status, String code, String message, Map<String, String> errors) {
        return ResponseEntity.status(status).body(new ApiError(status, code, message, errors));
    }
}

package com.tricore.dxos.core.workflow;

import com.tricore.dxos.gateway.workflow.controller.WorkflowController;
import com.tricore.dxos.gateway.workflow.controller.WorkflowExceptionHandler;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.EnumSource;
import org.junit.jupiter.params.provider.ValueSource;
import org.springframework.context.annotation.Profile;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.web.bind.annotation.RestController;

import java.time.Clock;
import java.time.ZoneOffset;

import static com.tricore.dxos.core.workflow.WorkflowInstanceTest.*;
import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import static org.springframework.test.web.servlet.setup.MockMvcBuilders.standaloneSetup;

/** HTTP/domain integration with a contract fixture, not evidence of PostgreSQL or authentication. */
class WorkflowHttpRuntimeTest {
    private static final String BASE = "/api/v1/workflow-instances";
    private static final WorkflowDefinition DEFINITION = WorkflowDefinitionTest.approval();
    private static final String TRANSITION = "{\"transitionId\":\"submit\",\"expectedVersion\":0}";
    private final InMemoryWorkflowPersistence persistence = spy(new InMemoryWorkflowPersistence());
    private final WorkflowRuntime runtime = new WorkflowRuntime(persistence,
            Clock.fixed(NOW.plusNanos(123), ZoneOffset.UTC));
    private MockMvc mvc;

    @RestController
    @Profile("workflow-http-tests")
    static class TestController extends WorkflowController {
        TestController(WorkflowRuntime runtime) {
            super(runtime);
        }
    }

    @BeforeEach
    void setUp() {
        persistence.provision(DEFINITION);
        persistence.provision(WorkflowDefinitionTest.delivery());
        mvc = standaloneSetup(new TestController(runtime))
                .setControllerAdvice(new WorkflowExceptionHandler()).build();
    }

    @Test
    void executesTwoIndependentDefinitionsWithAuthoritativeReadsAndStableVersions() throws Exception {
        mvc.perform(post(BASE).contentType(MediaType.APPLICATION_JSON).content(createBody(DEFINITION.definitionId(), 7)))
                .andExpect(status().isCreated()).andExpect(jsonPath("$.definitionVersion").value(7));
        mvc.perform(post(BASE + "/instance-1/activate")).andExpect(status().isOk())
                .andExpect(jsonPath("$.runtimeVersion").value(0));
        mvc.perform(post(BASE + "/instance-1/transitions").contentType(MediaType.APPLICATION_JSON).content(TRANSITION)
                        .requestAttr(WorkflowController.TRUSTED_ACTOR_ATTRIBUTE, ACTOR))
                .andExpect(status().isOk()).andExpect(jsonPath("$.instance.currentState").value("review"));
        mvc.perform(post(BASE + "/instance-1/transitions").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"transitionId\":\"publish\",\"expectedVersion\":1}")
                        .requestAttr(WorkflowController.TRUSTED_ACTOR_ATTRIBUTE, ACTOR))
                .andExpect(status().isOk()).andExpect(jsonPath("$.instance.lifecycle").value("COMPLETED"));

        WorkflowDefinition delivery = WorkflowDefinitionTest.delivery();
        mvc.perform(post(BASE).contentType(MediaType.APPLICATION_JSON)
                        .content(createBody(delivery.definitionId(), delivery.definitionVersion()).replace("instance-1", "instance-2")))
                .andExpect(status().isCreated()).andExpect(jsonPath("$.definitionVersion").value(delivery.definitionVersion()));
        mvc.perform(post(BASE + "/instance-2/activate")).andExpect(status().isOk());
        mvc.perform(post(BASE + "/instance-2/transitions").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"transitionId\":\"dispatch\",\"expectedVersion\":0}")
                        .requestAttr(WorkflowController.TRUSTED_ACTOR_ATTRIBUTE, ACTOR))
                .andExpect(status().isOk()).andExpect(jsonPath("$.instance.lifecycle").value("COMPLETED"));
        mvc.perform(get(BASE + "/instance-1/history")).andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(2)).andExpect(jsonPath("$[1].resultingRuntimeVersion").value(2));
        mvc.perform(get(BASE + "/instance-2")).andExpect(status().isOk())
                .andExpect(jsonPath("$.definitionVersion").value(delivery.definitionVersion()))
                .andExpect(jsonPath("$.runtimeVersion").value(1))
                .andExpect(jsonPath("$.updatedAt").value(NOW.plusNanos(123).toString()));
    }

    @ParameterizedTest
    @ValueSource(strings = {"missing", "missing-version"})
    void duplicateIdTakesPrecedenceOverMissingDefinitionWithoutOverwrite(String missing) throws Exception {
        WorkflowInstance active = activate();
        TransitionResult stored = runtime.executeTransition(command("submit", 0));
        String definitionId = missing.equals("missing") ? "missing" : DEFINITION.definitionId();
        long version = missing.equals("missing") ? 7 : 8;

        mvc.perform(post(BASE).contentType(MediaType.APPLICATION_JSON).content(createBody(definitionId, version)))
                .andExpect(status().isConflict()).andExpect(jsonPath("$.code").value("INSTANCE_ALREADY_EXISTS"));
        assertThat(runtime.loadInstance(active.instanceId())).isSameAs(stored.instance());
        assertThat(runtime.loadHistory(active.instanceId())).containsExactly(stored.record());
        verify(persistence, times(1)).createInstance(any());
        verify(persistence, never()).loadDefinition(definitionId, version);
    }

    @ParameterizedTest
    @ValueSource(strings = {"missing", "missing-version"})
    void missingInstanceAndDefinitionReturnsDefinitionNotFoundWithoutWriting(String missing) throws Exception {
        String definitionId = missing.equals("missing") ? "missing" : DEFINITION.definitionId();
        long version = missing.equals("missing") ? 7 : 8;
        mvc.perform(post(BASE).contentType(MediaType.APPLICATION_JSON).content(createBody(definitionId, version)))
                .andExpect(status().isNotFound()).andExpect(jsonPath("$.code").value("DEFINITION_NOT_FOUND"));
        assertError(() -> runtime.loadInstance("instance-1"), WorkflowErrorCode.INSTANCE_NOT_FOUND);
        verify(persistence, never()).createInstance(any());
    }

    @ParameterizedTest
    @EnumSource(value = WorkflowErrorCode.class, names = {"OPERATION_FAILURE", "COMMIT_OUTCOME_UNKNOWN"})
    void creationOutcomesDoNotRetryOrClaimRollbackForUnknownCommit(WorkflowErrorCode code) throws Exception {
        failWrite(code);
        mvc.perform(post(BASE).contentType(MediaType.APPLICATION_JSON).content(createBody(DEFINITION.definitionId(), 7)))
                .andExpect(status().isInternalServerError()).andExpect(jsonPath("$.code").value(code.name()))
                .andExpect(header().doesNotExist("Retry-After"));
        verify(persistence, times(1)).createInstance(any());
        if (code == WorkflowErrorCode.OPERATION_FAILURE) {
            assertError(() -> runtime.loadInstance("instance-1"), WorkflowErrorCode.INSTANCE_NOT_FOUND);
            assertError(() -> runtime.loadHistory("instance-1"), WorkflowErrorCode.INSTANCE_NOT_FOUND);
        } else {
            assertThat(runtime.loadInstance("instance-1").lifecycle()).isEqualTo(WorkflowLifecycle.NOT_STARTED);
            assertThat(runtime.loadHistory("instance-1")).isEmpty();
        }
    }

    @ParameterizedTest
    @EnumSource(value = WorkflowErrorCode.class, names = {"OPERATION_FAILURE", "COMMIT_OUTCOME_UNKNOWN"})
    void activationOutcomesPreserveVersionZeroAndNoHistoryWithoutRetry(WorkflowErrorCode code) throws Exception {
        WorkflowInstance initial = runtime.createInstance("instance-1", DEFINITION.definitionId(), 7, RESOURCE);
        failWrite(code);
        mvc.perform(post(BASE + "/instance-1/activate"))
                .andExpect(status().isInternalServerError()).andExpect(jsonPath("$.code").value(code.name()));
        verify(persistence, times(1)).commitActivation(any(), any());
        WorkflowInstance stored = runtime.loadInstance("instance-1");
        assertThat(stored.runtimeVersion()).isZero();
        assertThat(runtime.loadHistory("instance-1")).isEmpty();
        if (code == WorkflowErrorCode.OPERATION_FAILURE) assertThat(stored).isSameAs(initial);
        else assertThat(stored.lifecycle()).isEqualTo(WorkflowLifecycle.ACTIVE);
    }

    @ParameterizedTest
    @EnumSource(value = WorkflowErrorCode.class, names = {"OPERATION_FAILURE", "COMMIT_OUTCOME_UNKNOWN"})
    void transitionOutcomesKeepInstanceAndHistoryAtomicWithoutRetry(WorkflowErrorCode code) throws Exception {
        WorkflowInstance active = activate();
        failWrite(code);
        mvc.perform(post(BASE + "/instance-1/transitions").contentType(MediaType.APPLICATION_JSON).content(TRANSITION)
                        .requestAttr(WorkflowController.TRUSTED_ACTOR_ATTRIBUTE, ACTOR))
                .andExpect(status().isInternalServerError()).andExpect(jsonPath("$.code").value(code.name()));
        verify(persistence, times(1)).commitTransition(any());
        if (code == WorkflowErrorCode.OPERATION_FAILURE) {
            assertThat(runtime.loadInstance("instance-1")).isSameAs(active);
            assertThat(runtime.loadHistory("instance-1")).isEmpty();
        } else {
            WorkflowInstance stored = runtime.loadInstance("instance-1");
            assertThat(stored.currentState()).isEqualTo("review");
            assertThat(stored.runtimeVersion()).isEqualTo(1);
            assertThat(runtime.loadHistory("instance-1")).containsExactly(
                    new TransitionRecord("instance-1", "submit", "draft", "review", ACTOR, 1, stored.updatedAt()));
        }
    }

    private WorkflowInstance activate() {
        runtime.createInstance("instance-1", DEFINITION.definitionId(), 7, RESOURCE);
        return runtime.activateInstance("instance-1");
    }

    private void failWrite(WorkflowErrorCode code) {
        if (code == WorkflowErrorCode.OPERATION_FAILURE) persistence.failNextCommit();
        else persistence.loseNextCommitResponse();
    }

    private String createBody(String definitionId, long version) {
        return """
                {"instanceId":"instance-1","definitionId":"%s","definitionVersion":%d,
                 "resourceType":"document","resourceId":"document-1"}
                """.formatted(definitionId, version);
    }
}

package com.tricore.dxos.gateway.workflow.controller;

import com.tricore.dxos.core.workflow.ActorReference;
import com.tricore.dxos.core.workflow.ResourceReference;
import com.tricore.dxos.core.workflow.TransitionCommand;
import com.tricore.dxos.core.workflow.TransitionResult;
import com.tricore.dxos.core.workflow.WorkflowDefinition;
import com.tricore.dxos.core.workflow.WorkflowErrorCode;
import com.tricore.dxos.core.workflow.WorkflowException;
import com.tricore.dxos.core.workflow.WorkflowInstance;
import com.tricore.dxos.core.workflow.WorkflowRuntime;
import com.tricore.dxos.core.workflow.WorkflowTransition;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.Arguments;
import org.junit.jupiter.params.provider.EnumSource;
import org.junit.jupiter.params.provider.MethodSource;
import org.junit.jupiter.params.provider.ValueSource;
import org.springframework.context.annotation.Profile;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.web.bind.annotation.RestController;

import java.time.Instant;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Stream;

import static org.hamcrest.Matchers.containsString;
import static org.hamcrest.Matchers.not;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import static org.springframework.test.web.servlet.setup.MockMvcBuilders.standaloneSetup;

class WorkflowControllerTest {
    private static final String BASE = "/api/v1/workflow-instances";
    private static final String CREATE = """
            {"instanceId":"instance-1","definitionId":"publication","definitionVersion":7,
             "resourceType":"document","resourceId":"document-1"}
            """;
    private static final String TRANSITION = """
            {"transitionId":"submit","expectedVersion":0}
            """;
    private static final Instant NOW = Instant.parse("2026-10-07T00:00:00.123456789Z");
    private static final ActorReference ACTOR = new ActorReference("verified-subject");
    private static final ResourceReference RESOURCE = new ResourceReference("document", "document-1");
    private static final WorkflowDefinition DEFINITION = new WorkflowDefinition("publication", 7, "draft",
            Set.of("draft", "review", "published"),
            Set.of(new WorkflowTransition("submit", "draft", "review"),
                    new WorkflowTransition("publish", "review", "published")));
    private static final Map<WorkflowErrorCode, Integer> STATUSES = Map.of(
            WorkflowErrorCode.INSTANCE_ALREADY_EXISTS, 409,
            WorkflowErrorCode.VERSION_CONFLICT, 409,
            WorkflowErrorCode.DEFINITION_NOT_FOUND, 404,
            WorkflowErrorCode.INSTANCE_NOT_FOUND, 404,
            WorkflowErrorCode.INVALID_TRANSITION, 422,
            WorkflowErrorCode.TRANSITION_NOT_ALLOWED, 409,
            WorkflowErrorCode.INSTANCE_COMPLETED, 409,
            WorkflowErrorCode.OPERATION_FAILURE, 500,
            WorkflowErrorCode.COMMIT_OUTCOME_UNKNOWN, 500);

    private final WorkflowRuntime runtime = mock(WorkflowRuntime.class);
    private MockMvc mvc;

    // This registration exists only in tests, with no claim that requestAttr authenticates a caller.
    @RestController
    @Profile("workflow-http-tests")
    static class TestController extends WorkflowController {
        TestController(WorkflowRuntime runtime) {
            super(runtime);
        }
    }

    @BeforeEach
    void setUp() {
        mvc = standaloneSetup(new TestController(runtime))
                .setControllerAdvice(new WorkflowExceptionHandler()).build();
    }

    @Test
    void createsAnInstanceWithLocationAndExactSnapshotProjection() throws Exception {
        when(runtime.createInstance("instance-1", "publication", 7, RESOURCE)).thenReturn(initial());

        mvc.perform(post(BASE).contentType(MediaType.APPLICATION_JSON).content(CREATE))
                .andExpect(status().isCreated())
                .andExpect(header().string("Location", BASE + "/instance-1"))
                .andExpect(jsonPath("$.instanceId").value("instance-1"))
                .andExpect(jsonPath("$.definitionId").value("publication"))
                .andExpect(jsonPath("$.definitionVersion").value(7))
                .andExpect(jsonPath("$.resourceType").value("document"))
                .andExpect(jsonPath("$.resourceId").value("document-1"))
                .andExpect(jsonPath("$.currentState").value("draft"))
                .andExpect(jsonPath("$.runtimeVersion").value(0))
                .andExpect(jsonPath("$.lifecycle").value("NOT_STARTED"))
                .andExpect(jsonPath("$.createdAt").value(NOW.toString()))
                .andExpect(jsonPath("$.updatedAt").value(NOW.toString()));
        verify(runtime).createInstance("instance-1", "publication", 7, RESOURCE);
        verifyNoMoreInteractions(runtime);
    }

    @ParameterizedTest
    @ValueSource(strings = {"", "{}"})
    void activatesWithoutAcceptingStateOrChangingVersion(String body) throws Exception {
        when(runtime.activateInstance("instance-1")).thenReturn(initial().activate(DEFINITION, NOW));

        mvc.perform(post(BASE + "/instance-1/activate").contentType(MediaType.APPLICATION_JSON).content(body))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.lifecycle").value("ACTIVE"))
                .andExpect(jsonPath("$.runtimeVersion").value(0))
                .andExpect(jsonPath("$.updatedAt").value(NOW.toString()));
        verify(runtime).activateInstance("instance-1");
        verifyNoMoreInteractions(runtime);
    }

    @Test
    void transitionsUsingOnlyTheServerSuppliedActorAndPreservesRecordPrecision() throws Exception {
        TransitionResult result = initial().activate(DEFINITION, NOW).transition(DEFINITION,
                new TransitionCommand("instance-1", "submit", ACTOR, 0), NOW.plusNanos(1));
        when(runtime.executeTransition(any())).thenReturn(result);

        mvc.perform(post(BASE + "/instance-1/transitions").contentType(MediaType.APPLICATION_JSON)
                        .content(TRANSITION).requestAttr(WorkflowController.TRUSTED_ACTOR_ATTRIBUTE, ACTOR)
                        .header("X-User", "attacker").header("X-Role", "admin"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.instance.currentState").value("review"))
                .andExpect(jsonPath("$.instance.runtimeVersion").value(1))
                .andExpect(jsonPath("$.instance.definitionVersion").value(7))
                .andExpect(jsonPath("$.instance.updatedAt").value(result.record().occurredAt().toString()))
                .andExpect(jsonPath("$.record.actorId").value(ACTOR.actorId()))
                .andExpect(jsonPath("$.record.sourceState").value("draft"))
                .andExpect(jsonPath("$.record.targetState").value("review"))
                .andExpect(jsonPath("$.record.resultingRuntimeVersion").value(1))
                .andExpect(jsonPath("$.record.occurredAt").value(result.record().occurredAt().toString()))
                .andExpect(jsonPath("$.previousInstance").doesNotExist());
        verify(runtime).executeTransition(new TransitionCommand("instance-1", "submit", ACTOR, 0));
        verifyNoMoreInteractions(runtime);
    }

    @Test
    void readsAuthoritativeInstanceAndOrderedHistoryThroughRuntime() throws Exception {
        TransitionResult first = initial().activate(DEFINITION, NOW).transition(DEFINITION,
                new TransitionCommand("instance-1", "submit", ACTOR, 0), NOW);
        TransitionResult second = first.instance().transition(DEFINITION,
                new TransitionCommand("instance-1", "publish", ACTOR, 1), NOW);
        when(runtime.loadInstance("instance-1")).thenReturn(second.instance());
        when(runtime.loadHistory("instance-1")).thenReturn(List.of(first.record(), second.record()));

        mvc.perform(get(BASE + "/instance-1"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.lifecycle").value("COMPLETED"))
                .andExpect(jsonPath("$.runtimeVersion").value(2));
        mvc.perform(get(BASE + "/instance-1/history"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(2))
                .andExpect(jsonPath("$[0].transitionId").value("submit"))
                .andExpect(jsonPath("$[0].resultingRuntimeVersion").value(1))
                .andExpect(jsonPath("$[1].transitionId").value("publish"))
                .andExpect(jsonPath("$[1].resultingRuntimeVersion").value(2));
        verify(runtime).loadInstance("instance-1");
        verify(runtime).loadHistory("instance-1");
        verifyNoMoreInteractions(runtime);
    }

    @Test
    void returnsEmptyHistory() throws Exception {
        when(runtime.loadHistory("instance-1")).thenReturn(List.of());
        mvc.perform(get(BASE + "/instance-1/history"))
                .andExpect(status().isOk()).andExpect(content().json("[]"));
    }

    @ParameterizedTest
    @EnumSource(WorkflowErrorCode.class)
    void mapsEveryNormalizedErrorWithoutRetryingOrExposingDetails(WorkflowErrorCode code) throws Exception {
        when(runtime.createInstance(any(), any(), anyLong(), any())).thenThrow(new WorkflowException(code));

        mvc.perform(post(BASE).contentType(MediaType.APPLICATION_JSON).content(CREATE))
                .andExpect(status().is(STATUSES.get(code)))
                .andExpect(jsonPath("$.status").value(STATUSES.get(code)))
                .andExpect(jsonPath("$.code").value(code.name()))
                .andExpect(jsonPath("$.errors").isEmpty())
                .andExpect(jsonPath("$.stackTrace").doesNotExist())
                .andExpect(jsonPath("$.cause").doesNotExist());
        verify(runtime).createInstance("instance-1", "publication", 7, RESOURCE);
        verifyNoMoreInteractions(runtime);
    }

    @Test
    void hidesUnexpectedProviderAndServerClockFailures() throws Exception {
        when(runtime.activateInstance("instance-1"))
                .thenThrow(new IllegalArgumentException("SQL password=secret; server clock went backwards"));
        mvc.perform(post(BASE + "/instance-1/activate"))
                .andExpect(status().isInternalServerError())
                .andExpect(jsonPath("$.code").value("INTERNAL_ERROR"))
                .andExpect(content().string(not(containsString("secret"))))
                .andExpect(content().string(not(containsString("SQL"))));
        verify(runtime).activateInstance("instance-1");
        verifyNoMoreInteractions(runtime);
    }

    @Test
    void headersAndBearerStringsCannotSupplyTheReservedActorAttribute() throws Exception {
        mvc.perform(post(BASE + "/instance-1/transitions").contentType(MediaType.APPLICATION_JSON)
                        .content(TRANSITION).header("X-User", "attacker").header("X-Role", "admin")
                        .header("Authorization", "Bearer unverified").header(WorkflowController.TRUSTED_ACTOR_ATTRIBUTE, "attacker"))
                .andExpect(status().isUnauthorized())
                .andExpect(jsonPath("$.code").value("AUTHENTICATION_REQUIRED"));
        verifyNoInteractions(runtime);
    }

    @ParameterizedTest
    @MethodSource("invalidInputs")
    void rejectsInvalidInputBeforeCallingRuntime(String path, String body) throws Exception {
        mvc.perform(post(path).contentType(MediaType.APPLICATION_JSON).content(body)
                        .requestAttr(WorkflowController.TRUSTED_ACTOR_ATTRIBUTE, ACTOR))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.code").exists());
        verifyNoInteractions(runtime);
    }

    static Stream<Arguments> invalidInputs() {
        Stream<Arguments> creation = Stream.of(
                "{}", "null", CREATE.replace("\"instance-1\"", "\"\""),
                CREATE.replace("\"instance-1\"", "\"bad/id\""),
                CREATE.replace("\"publication\"", "\" \""),
                CREATE.replace("\"document\"", "\"\""),
                CREATE.replace("\"document-1\"", "null"))
                .map(body -> Arguments.of(BASE, body));
        Stream<Arguments> versions = Stream.of("null", "-1", "7.5", "\"7\"", "true", "{}", "9223372036854775808")
                .flatMap(version -> Stream.of(
                        Arguments.of(BASE, CREATE.replace("\"definitionVersion\":7", "\"definitionVersion\":" + version)),
                        Arguments.of(BASE + "/instance-1/transitions", TRANSITION.replace("\"expectedVersion\":0", "\"expectedVersion\":" + version))));
        Stream<Arguments> transitions = Stream.of("{}", "null", TRANSITION.replace("\"submit\"", "\"\""),
                "{\"transitionId\":\"submit\"}").map(body -> Arguments.of(BASE + "/instance-1/transitions", body));
        return Stream.of(creation, versions, transitions).flatMap(stream -> stream);
    }

    @ParameterizedTest
    @MethodSource("unknownFields")
    void rejectsUnknownControlFieldsForEveryWrite(String path, String body) throws Exception {
        mvc.perform(post(path).contentType(MediaType.APPLICATION_JSON).content(body)
                        .requestAttr(WorkflowController.TRUSTED_ACTOR_ATTRIBUTE, ACTOR))
                .andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("INVALID_BODY"));
        verifyNoInteractions(runtime);
    }

    static Stream<Arguments> unknownFields() {
        return Stream.of("actorId", "actorReference", "roles", "lifecycle", "timestamp", "targetState", "createdAt", "updatedAt")
                .flatMap(field -> Stream.of(
                        Arguments.of(BASE, CREATE.stripTrailing().replaceFirst("}$", ",\"" + field + "\":\"client\"}")),
                        Arguments.of(BASE + "/instance-1/activate", "{\"" + field + "\":\"client\"}"),
                        Arguments.of(BASE + "/instance-1/transitions", TRANSITION.stripTrailing().replaceFirst("}$", ",\"" + field + "\":\"client\"}"))));
    }

    @ParameterizedTest
    @ValueSource(strings = {"", "/instance-1/activate", "/instance-1/transitions"})
    void rejectsMalformedJsonWithoutExposingParserDetails(String suffix) throws Exception {
        mvc.perform(post(BASE + suffix).contentType(MediaType.APPLICATION_JSON).content("{broken")
                        .requestAttr(WorkflowController.TRUSTED_ACTOR_ATTRIBUTE, ACTOR))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.code").value("INVALID_BODY"))
                .andExpect(content().string(not(containsString("broken"))));
        verifyNoInteractions(runtime);
    }

    @ParameterizedTest
    @ValueSource(strings = {"", "/instance-1/transitions"})
    void requiresCreationAndTransitionBodies(String suffix) throws Exception {
        mvc.perform(post(BASE + suffix).contentType(MediaType.APPLICATION_JSON)
                        .requestAttr(WorkflowController.TRUSTED_ACTOR_ATTRIBUTE, ACTOR))
                .andExpect(status().isBadRequest());
        verifyNoInteractions(runtime);
    }

    @Test
    void rejectsInvalidPathIdentifiersBeforeRuntime() throws Exception {
        mvc.perform(get(BASE + "/{id}", "bad id")).andExpect(status().isBadRequest());
        verifyNoInteractions(runtime);
    }

    @Test
    void rejectsUnsupportedMediaTypeBeforeRuntime() throws Exception {
        mvc.perform(post(BASE).contentType(MediaType.TEXT_PLAIN).content(CREATE))
                .andExpect(status().isUnsupportedMediaType())
                .andExpect(jsonPath("$.code").value("UNSUPPORTED_MEDIA_TYPE"));
        verifyNoInteractions(runtime);
    }

    @Test
    void doesNotCoerceOrRoundLargeIntegerVersions() throws Exception {
        when(runtime.createInstance("instance-1", "publication", Long.MAX_VALUE, RESOURCE))
                .thenThrow(new WorkflowException(WorkflowErrorCode.DEFINITION_NOT_FOUND));
        mvc.perform(post(BASE).contentType(MediaType.APPLICATION_JSON)
                        .content(CREATE.replace("\"definitionVersion\":7", "\"definitionVersion\":" + Long.MAX_VALUE)))
                .andExpect(status().isNotFound());
        verify(runtime).createInstance("instance-1", "publication", Long.MAX_VALUE, RESOURCE);

        TransitionCommand command = new TransitionCommand("instance-1", "submit", ACTOR, Long.MAX_VALUE);
        when(runtime.executeTransition(command)).thenThrow(new WorkflowException(WorkflowErrorCode.VERSION_CONFLICT));
        mvc.perform(post(BASE + "/instance-1/transitions").contentType(MediaType.APPLICATION_JSON)
                        .content(TRANSITION.replace("\"expectedVersion\":0", "\"expectedVersion\":" + Long.MAX_VALUE))
                        .requestAttr(WorkflowController.TRUSTED_ACTOR_ATTRIBUTE, ACTOR))
                .andExpect(status().isConflict());
        verify(runtime).executeTransition(command);
        verifyNoMoreInteractions(runtime);
    }

    private WorkflowInstance initial() {
        return WorkflowInstance.notStarted("instance-1", DEFINITION, RESOURCE, NOW);
    }
}

package com.tricore.dxos.infrastructure.workflow;

import com.tricore.dxos.core.workflow.ActorReference;
import com.tricore.dxos.core.workflow.ResourceReference;
import com.tricore.dxos.core.workflow.TransitionCommand;
import com.tricore.dxos.core.workflow.TransitionRecord;
import com.tricore.dxos.core.workflow.TransitionResult;
import com.tricore.dxos.core.workflow.WorkflowDefinition;
import com.tricore.dxos.core.workflow.WorkflowErrorCode;
import com.tricore.dxos.core.workflow.WorkflowException;
import com.tricore.dxos.core.workflow.WorkflowInstance;
import com.tricore.dxos.core.workflow.WorkflowLifecycle;
import com.tricore.dxos.core.workflow.WorkflowPersistencePort;
import com.tricore.dxos.core.workflow.WorkflowTransition;
import org.springframework.stereotype.Component;
import org.springframework.beans.factory.annotation.Value;

import javax.sql.DataSource;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.Instant;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Objects;
import java.util.Set;

/** Owns its JDBC transactions: a Spring transaction must not defer this port's commit. */
@Component
public final class PostgresWorkflowPersistence implements WorkflowPersistencePort {
    private static final String INSTANCE_COLUMNS = """
            instance_id, definition_id, definition_version, resource_type, resource_id,
            current_state, runtime_version, lifecycle, created_at_seconds, created_at_nanos,
            updated_at_seconds, updated_at_nanos
            """;
    private final DataSource dataSource;
    private final WorkflowSchema schema;

    public PostgresWorkflowPersistence(DataSource dataSource,
                                       @Value("${dxos.workflow.schema}") String expectedSchema) {
        this.schema = new WorkflowSchema(expectedSchema);
        this.dataSource = schema.guard(Objects.requireNonNull(dataSource, "dataSource"));
    }

    @Override
    public WorkflowDefinition loadDefinition(String definitionId, long definitionVersion) {
        requireKey(definitionId, definitionVersion);
        return transaction(false, connection -> definition(connection, definitionId, definitionVersion));
    }

    /** Infrastructure-only import. A key is insert-only; identical imports are idempotent. */
    public WorkflowDefinition provisionDefinition(WorkflowDefinition definition) {
        Objects.requireNonNull(definition, "definition");
        WorkflowDefinition persisted = transaction(true, connection -> {
            int inserted = update(connection, """
                    INSERT INTO %s.workflow_definitions (definition_id, definition_version, initial_state)
                    VALUES (?, ?, ?) ON CONFLICT (definition_id, definition_version) DO NOTHING
                    """, definition.definitionId(), definition.definitionVersion(), definition.initialState());
            if (inserted == 0) {
                return definition(connection, definition.definitionId(), definition.definitionVersion());
            }
            for (String state : definition.states()) {
                update(connection, """
                        INSERT INTO %s.workflow_definition_states (definition_id, definition_version, state_id)
                        VALUES (?, ?, ?)
                        """, definition.definitionId(), definition.definitionVersion(), state);
            }
            for (WorkflowTransition transition : definition.transitions()) {
                update(connection, """
                        INSERT INTO %s.workflow_definition_transitions
                        (definition_id, definition_version, transition_id, source_state, target_state)
                        VALUES (?, ?, ?, ?, ?)
                        """, definition.definitionId(), definition.definitionVersion(), transition.transitionId(),
                        transition.sourceState(), transition.targetState());
            }
            return definition;
        });
        if (!definition.equals(persisted)) {
            throw new IllegalArgumentException("definition version must be immutable");
        }
        return persisted;
    }

    @Override
    public WorkflowInstance createInstance(WorkflowInstance initial) {
        Objects.requireNonNull(initial, "initial");
        return transaction(true, connection -> {
            try (PreparedStatement statement = prepare(connection,
                    "SELECT instance_id FROM %s.workflow_instances WHERE instance_id = ?", initial.instanceId());
                 ResultSet rows = statement.executeQuery()) {
                if (rows.next()) {
                    throw new WorkflowException(WorkflowErrorCode.INSTANCE_ALREADY_EXISTS);
                }
            }
            WorkflowDefinition definition = definition(connection, initial.definitionId(), initial.definitionVersion());
            WorkflowInstance canonical = WorkflowInstance.notStarted(
                    initial.instanceId(), definition, initial.resourceReference(), initial.createdAt());
            requireSnapshot(initial, canonical);
            int inserted = update(connection, "INSERT INTO %s.workflow_instances (" + INSTANCE_COLUMNS + """
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    ON CONFLICT (instance_id) DO NOTHING
                    """, initial.instanceId(), initial.definitionId(), initial.definitionVersion(),
                    initial.resourceReference().resourceType(), initial.resourceReference().resourceId(),
                    initial.currentState(), initial.runtimeVersion(), initial.lifecycle().name(),
                    initial.createdAt().getEpochSecond(), initial.createdAt().getNano(),
                    initial.updatedAt().getEpochSecond(), initial.updatedAt().getNano());
            if (inserted != 1) {
                throw new WorkflowException(WorkflowErrorCode.INSTANCE_ALREADY_EXISTS);
            }
            return canonical;
        });
    }

    @Override
    public WorkflowInstance commitActivation(WorkflowInstance expected, WorkflowInstance activated) {
        Objects.requireNonNull(expected, "expected");
        Objects.requireNonNull(activated, "activated");
        return transaction(true, connection -> {
            WorkflowInstance persisted = instance(connection, expected.instanceId(), true);
            if (persisted.runtimeVersion() != expected.runtimeVersion() || persisted.lifecycle() != expected.lifecycle()) {
                throw new WorkflowException(WorkflowErrorCode.VERSION_CONFLICT);
            }
            if (persisted.lifecycle() == WorkflowLifecycle.COMPLETED) {
                throw new WorkflowException(WorkflowErrorCode.INSTANCE_COMPLETED);
            }
            requireSnapshot(persisted, expected);
            if (persisted.lifecycle() != WorkflowLifecycle.NOT_STARTED
                    || activated.updatedAt().isBefore(expected.updatedAt())) {
                throw new WorkflowException(WorkflowErrorCode.TRANSITION_NOT_ALLOWED);
            }
            WorkflowDefinition definition = definition(connection, persisted.definitionId(), persisted.definitionVersion());
            WorkflowInstance canonical = persisted.activate(definition, activated.updatedAt());
            requireSnapshot(activated, canonical);
            updateInstance(connection, canonical);
            return canonical;
        });
    }

    @Override
    public WorkflowInstance loadInstance(String instanceId) {
        requireText(instanceId);
        return transaction(false, connection -> instance(connection, instanceId, false));
    }

    @Override
    public List<TransitionRecord> loadHistory(String instanceId) {
        requireText(instanceId);
        return transaction(false, connection -> {
            // REPEATABLE READ gives the existence check and history one database snapshot.
            try (PreparedStatement statement = prepare(connection,
                    "SELECT instance_id FROM %s.workflow_instances WHERE instance_id = ?", instanceId);
                 ResultSet rows = statement.executeQuery()) {
                if (!rows.next()) {
                    throw new WorkflowException(WorkflowErrorCode.INSTANCE_NOT_FOUND);
                }
            }
            List<TransitionRecord> history = new ArrayList<>();
            try (PreparedStatement statement = prepare(connection, """
                    SELECT instance_id, transition_id, source_state, target_state, actor_id,
                           resulting_runtime_version, occurred_at_seconds, occurred_at_nanos
                    FROM %s.workflow_transition_history WHERE instance_id = ? ORDER BY resulting_runtime_version
                    """, instanceId); ResultSet rows = statement.executeQuery()) {
                while (rows.next()) {
                    history.add(new TransitionRecord(rows.getString("instance_id"), rows.getString("transition_id"),
                            rows.getString("source_state"), rows.getString("target_state"),
                            new ActorReference(rows.getString("actor_id")), rows.getLong("resulting_runtime_version"),
                            instant(rows, "occurred_at")));
                }
            }
            return List.copyOf(history);
        });
    }

    @Override
    public TransitionResult commitTransition(TransitionResult transition) {
        Objects.requireNonNull(transition, "transition");
        return transaction(true, connection -> {
            WorkflowInstance persisted = instance(connection, transition.previousInstance().instanceId(), true);
            if (persisted.runtimeVersion() != transition.expectedVersion()) {
                throw new WorkflowException(WorkflowErrorCode.VERSION_CONFLICT);
            }
            if (persisted.lifecycle() == WorkflowLifecycle.COMPLETED) {
                throw new WorkflowException(WorkflowErrorCode.INSTANCE_COMPLETED);
            }
            requireSnapshot(persisted, transition.previousInstance());
            WorkflowDefinition definition = definition(connection, persisted.definitionId(), persisted.definitionVersion());
            TransitionRecord record = transition.record();
            TransitionResult canonical = persisted.transition(definition,
                    new TransitionCommand(persisted.instanceId(), record.transitionId(), record.actorReference(),
                            transition.expectedVersion()), record.occurredAt());
            requireSnapshot(transition.instance(), canonical.instance());
            if (!record.equals(canonical.record())) {
                throw new WorkflowException(WorkflowErrorCode.TRANSITION_NOT_ALLOWED);
            }
            updateInstance(connection, canonical.instance());
            if (update(connection, """
                    INSERT INTO %s.workflow_transition_history
                    (instance_id, resulting_runtime_version, transition_id, source_state, target_state,
                     actor_id, occurred_at_seconds, occurred_at_nanos) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                    """, record.instanceId(), record.resultingRuntimeVersion(), record.transitionId(),
                    record.sourceState(), record.targetState(), record.actorReference().actorId(),
                    record.occurredAt().getEpochSecond(), record.occurredAt().getNano()) != 1) {
                throw new SQLException();
            }
            return canonical;
        });
    }

    private WorkflowDefinition definition(Connection connection, String id, long version) throws SQLException {
        String initialState;
        try (PreparedStatement statement = prepare(connection, """
                SELECT initial_state FROM %s.workflow_definitions WHERE definition_id = ? AND definition_version = ?
                """, id, version); ResultSet rows = statement.executeQuery()) {
            if (!rows.next()) {
                throw new WorkflowException(WorkflowErrorCode.DEFINITION_NOT_FOUND);
            }
            initialState = rows.getString("initial_state");
        }
        Set<String> states = new HashSet<>();
        try (PreparedStatement statement = prepare(connection, """
                SELECT state_id FROM %s.workflow_definition_states WHERE definition_id = ? AND definition_version = ?
                """, id, version); ResultSet rows = statement.executeQuery()) {
            while (rows.next()) {
                states.add(rows.getString("state_id"));
            }
        }
        Set<WorkflowTransition> transitions = new HashSet<>();
        try (PreparedStatement statement = prepare(connection, """
                SELECT transition_id, source_state, target_state FROM %s.workflow_definition_transitions
                WHERE definition_id = ? AND definition_version = ?
                """, id, version); ResultSet rows = statement.executeQuery()) {
            while (rows.next()) {
                transitions.add(new WorkflowTransition(rows.getString("transition_id"),
                        rows.getString("source_state"), rows.getString("target_state")));
            }
        }
        return new WorkflowDefinition(id, version, initialState, states, transitions);
    }

    private WorkflowInstance instance(Connection connection, String id, boolean lock) throws SQLException {
        try (PreparedStatement statement = prepare(connection,
                "SELECT " + INSTANCE_COLUMNS + " FROM %s.workflow_instances WHERE instance_id = ?"
                        + (lock ? " FOR UPDATE" : ""), id); ResultSet rows = statement.executeQuery()) {
            if (!rows.next()) {
                throw new WorkflowException(WorkflowErrorCode.INSTANCE_NOT_FOUND);
            }
            WorkflowDefinition definition = definition(connection,
                    rows.getString("definition_id"), rows.getLong("definition_version"));
            return WorkflowInstance.restore(rows.getString("instance_id"), definition,
                    new ResourceReference(rows.getString("resource_type"), rows.getString("resource_id")),
                    rows.getString("current_state"), rows.getLong("runtime_version"),
                    WorkflowLifecycle.valueOf(rows.getString("lifecycle")),
                    instant(rows, "created_at"), instant(rows, "updated_at"));
        }
    }

    private void updateInstance(Connection connection, WorkflowInstance instance) throws SQLException {
        if (update(connection, """
                UPDATE %s.workflow_instances SET current_state = ?, runtime_version = ?, lifecycle = ?,
                    updated_at_seconds = ?, updated_at_nanos = ? WHERE instance_id = ?
                """, instance.currentState(), instance.runtimeVersion(), instance.lifecycle().name(),
                instance.updatedAt().getEpochSecond(), instance.updatedAt().getNano(), instance.instanceId()) != 1) {
            throw new SQLException();
        }
    }

    private static Instant instant(ResultSet rows, String prefix) throws SQLException {
        return Instant.ofEpochSecond(rows.getLong(prefix + "_seconds"), rows.getInt(prefix + "_nanos"));
    }

    private static void requireSnapshot(WorkflowInstance left, WorkflowInstance right) {
        if (!left.instanceId().equals(right.instanceId())
                || !left.definitionId().equals(right.definitionId())
                || left.definitionVersion() != right.definitionVersion()
                || !left.resourceReference().equals(right.resourceReference())
                || !left.currentState().equals(right.currentState())
                || left.runtimeVersion() != right.runtimeVersion()
                || left.lifecycle() != right.lifecycle()
                || !left.createdAt().equals(right.createdAt())
                || !left.updatedAt().equals(right.updatedAt())) {
            throw new WorkflowException(WorkflowErrorCode.TRANSITION_NOT_ALLOWED);
        }
    }

    private static void requireText(String text) {
        if (text == null || text.isBlank()) {
            throw new IllegalArgumentException("identifier must not be blank");
        }
    }

    private static void requireKey(String id, long version) {
        requireText(id);
        if (version < 0) {
            throw new IllegalArgumentException("definition version must not be negative");
        }
    }

    private PreparedStatement prepare(Connection connection, String sql, Object... values) throws SQLException {
        // Only the validated identifier is formatted; all data remains bound parameters.
        PreparedStatement statement = connection.prepareStatement(sql.formatted(schema.quoted()));
        try {
            for (int i = 0; i < values.length; i++) {
                statement.setObject(i + 1, values[i]);
            }
            return statement;
        } catch (SQLException | RuntimeException failure) {
            try {
                statement.close();
            } catch (SQLException ignored) {
                // Preserve the original failure; the transaction boundary handles rollback.
            }
            throw failure;
        }
    }

    private int update(Connection connection, String sql, Object... values) throws SQLException {
        try (PreparedStatement statement = prepare(connection, sql, values)) {
            return statement.executeUpdate();
        }
    }

    private <T> T transaction(boolean write, SqlWork<T> work) {
        Connection connection = null;
        boolean started = false;
        boolean committing = false;
        try {
            connection = dataSource.getConnection();
            if (!connection.getAutoCommit()) {
                throw new SQLException();
            }
            connection.setTransactionIsolation(write ? Connection.TRANSACTION_READ_COMMITTED
                    : Connection.TRANSACTION_REPEATABLE_READ);
            connection.setReadOnly(!write);
            connection.setAutoCommit(false);
            started = true;
            if (write) {
                try (var statement = connection.createStatement()) {
                    statement.execute("SET LOCAL synchronous_commit = on");
                    try (ResultSet settings = statement.executeQuery(
                            "SELECT current_setting('fsync'), current_setting('full_page_writes')")) {
                        if (!settings.next() || !"on".equals(settings.getString(1))
                                || !"on".equals(settings.getString(2))) {
                            throw new SQLException();
                        }
                    }
                }
            }
            T result = work.run(connection);
            committing = true;
            connection.commit();
            return result;
        } catch (SQLException | RuntimeException failure) {
            if (write && committing) {
                // A later successful rollback cannot disprove an earlier successful COMMIT.
                throw new WorkflowException(WorkflowErrorCode.COMMIT_OUTCOME_UNKNOWN);
            }
            if (started) {
                try {
                    connection.rollback();
                } catch (SQLException | RuntimeException rollbackFailure) {
                    throw new WorkflowException(write ? WorkflowErrorCode.COMMIT_OUTCOME_UNKNOWN
                            : WorkflowErrorCode.OPERATION_FAILURE);
                }
            }
            if (failure instanceof WorkflowException workflowFailure) {
                throw workflowFailure;
            }
            throw new WorkflowException(WorkflowErrorCode.OPERATION_FAILURE);
        } finally {
            if (connection != null) {
                try {
                    connection.close();
                } catch (SQLException | RuntimeException ignored) {
                    // Cleanup cannot change a confirmed durable commit or its classification.
                }
            }
        }
    }

    @FunctionalInterface
    private interface SqlWork<T> {
        T run(Connection connection) throws SQLException;
    }
}

package com.tricore.dxos.infrastructure.workflow;

import com.tricore.dxos.core.workflow.*;
import org.flywaydb.core.Flyway;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;
import org.junit.jupiter.params.provider.ValueSource;
import org.springframework.boot.test.context.runner.ApplicationContextRunner;
import org.springframework.jdbc.datasource.AbstractDataSource;
import org.springframework.jdbc.datasource.DriverManagerDataSource;

import javax.sql.DataSource;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Proxy;
import java.sql.Connection;
import java.sql.SQLException;
import java.time.Instant;
import java.util.List;
import java.util.Properties;
import java.util.Set;
import java.util.UUID;
import java.util.concurrent.Callable;
import java.util.concurrent.CyclicBarrier;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;

import static com.tricore.dxos.core.workflow.WorkflowErrorCode.*;
import static org.assertj.core.api.Assertions.*;

/** Every case migrates an isolated real PostgreSQL schema; no H2 or persistence fake. */
@EnabledIfEnvironmentVariable(named = "WORKFLOW_TEST_JDBC_URL", matches = ".+")
class PostgresWorkflowPersistenceIntegrationTest {
    private static final Instant NOW = Instant.parse("2026-10-13T01:02:03.123456789Z");
    private static final ResourceReference RESOURCE = new ResourceReference("document", "doc-1");
    private static final ActorReference ACTOR = new ActorReference("verified-actor");
    private DriverManagerDataSource admin;
    private DriverManagerDataSource database;
    private String schema;
    private PostgresWorkflowPersistence persistence;
    private WorkflowDefinition definition;

    @BeforeAll
    static void suppressDatabaseConnectionLogging() {
        ((ch.qos.logback.classic.Logger) org.slf4j.LoggerFactory.getLogger("org.flywaydb"))
                .setLevel(ch.qos.logback.classic.Level.OFF);
    }

    @BeforeEach
    void migrateRealDatabase() {
        schema = "workflow_test_" + UUID.randomUUID().toString().replace("-", "");
        admin = dataSource(false, null);
        database = dataSource(true, schema);
        String phase = "create-schema";
        try {
            sql(admin, "CREATE SCHEMA " + schema);
            phase = "V1-V2";
            WorkflowMigrations.configure(dataSource(false, schema), schema, "classpath:db/migration")
                    .locations("classpath:db/migration").loggers("slf4j").target("2").load().migrate();
            sql(dataSource(false, schema), """
                    INSERT INTO requests (id, title, description, request_type, status, created_at, updated_at)
                    VALUES ('00000000-0000-0000-0000-000000000025', 'kept', 'kept', 'test', 'NEW', now(), now())
                    """);
            phase = "V3-V4";
            WorkflowMigrations.configure(dataSource(false, schema), schema, "classpath:db/migration")
                    .locations("classpath:db/migration").loggers("slf4j").load().migrate();
            // A separately supplied runtime login gets only the adapter's required privileges.
            String runtimeRole;
            try (Connection connection = database.getConnection()) {
                runtimeRole = connection.getMetaData().getUserName().replace("\"", "\"\"");
            }
            var migrator = dataSource(false, schema);
            phase = "grant";
            sql(migrator, "GRANT USAGE ON SCHEMA " + schema + " TO \"" + runtimeRole + "\"");
            sql(migrator, "GRANT SELECT ON ALL TABLES IN SCHEMA " + schema + " TO \"" + runtimeRole + "\"");
            sql(migrator, "GRANT INSERT, UPDATE ON workflow_instances TO \"" + runtimeRole + "\"");
            sql(migrator, "GRANT INSERT ON workflow_transition_history TO \"" + runtimeRole + "\"");
            persistence = new PostgresWorkflowPersistence(database, schema);
            phase = "load-definition";
            definition = persistence.loadDefinition("document-review", 1);
        } catch (SQLException | RuntimeException failure) {
            Throwable rootCause = failure;
            while (rootCause.getCause() != null) rootCause = rootCause.getCause();
            String safeReason = rootCause.getMessage() != null && rootCause.getMessage().startsWith("Workflow ")
                    ? rootCause.getMessage() : rootCause.getClass().getSimpleName();
            throw new AssertionError("Real PostgreSQL fixture setup failed at " + phase + ": " + safeReason
                    + (rootCause instanceof SQLException sql ? " SQLSTATE=" + sql.getSQLState() : ""));
        }
    }

    @AfterEach
    void dropOnlyOwnedSchema() throws SQLException {
        if (admin != null && schema != null) {
            sql(admin, "DROP SCHEMA IF EXISTS " + schema + " CASCADE");
        }
    }

    @Test
    void migrationsUpgradeV1V2AndSeedTwoIndependentDefinitions() throws SQLException {
        assertThat(scalar(database, "SELECT count(*) FROM requests WHERE title = 'kept'")).isEqualTo(1);
        assertThat(scalar(database, "SELECT count(*) FROM flyway_schema_history WHERE success")).isEqualTo(4);
        WorkflowDefinition other = persistence.loadDefinition("incident-resolution", 1);
        assertThat(other).isNotEqualTo(definition);
        WorkflowInstance incident = WorkflowInstance.notStarted("incident", other,
                new ResourceReference("incident", "inc-1"), NOW);
        persistence.createInstance(incident);
        persistence.commitActivation(incident, incident.activate(other, NOW));
        persistence.commitTransition(persistence.loadInstance("incident").transition(other,
                new TransitionCommand("incident", "start", ACTOR, 0), NOW));
        assertThat(persistence.loadInstance("incident").currentState()).isEqualTo("IN_PROGRESS");
        assertThat(definition.initialState()).isEqualTo("DRAFT");
    }

    @Test
    void exactVersionsAndImmutableIdempotentProvisioning() {
        var importer = new PostgresWorkflowPersistence(dataSource(false, schema), schema);
        WorkflowDefinition version2 = new WorkflowDefinition("document-review", 2, "DRAFT",
                Set.of("DRAFT", "APPROVED"), Set.of(new WorkflowTransition("fast-approve", "DRAFT", "APPROVED")));
        importer.provisionDefinition(version2);
        importer.provisionDefinition(version2);
        assertThat(persistence.loadDefinition("document-review", 1)).isEqualTo(definition);
        assertThat(persistence.loadDefinition("document-review", 2)).isEqualTo(version2);
        WorkflowDefinition changed = new WorkflowDefinition("document-review", 2, "APPROVED",
                version2.states(), version2.transitions());
        assertThatThrownBy(() -> importer.provisionDefinition(changed)).isInstanceOf(IllegalArgumentException.class);
        assertThat(persistence.loadDefinition("document-review", 2)).isEqualTo(version2);
        expectCode(DEFINITION_NOT_FOUND, () -> persistence.loadDefinition("document-review", 3));
        expectCode(DEFINITION_NOT_FOUND, () -> persistence.loadDefinition("absent", 1));
    }

    @ParameterizedTest
    @ValueSource(strings = {
            "UPDATE workflow_definitions SET initial_state = 'APPROVED' WHERE definition_id = 'document-review'",
            "DELETE FROM workflow_definitions WHERE definition_id = 'document-review'",
            "UPDATE workflow_definition_states SET state_id = 'NEW' WHERE state_id = 'DRAFT'",
            "DELETE FROM workflow_definition_states WHERE state_id = 'DRAFT'",
            "UPDATE workflow_definition_transitions SET target_state = 'DRAFT' WHERE transition_id = 'approve'",
            "DELETE FROM workflow_definition_transitions WHERE transition_id = 'approve'",
            "INSERT INTO workflow_definition_states VALUES ('document-review', 1, 'LATE')",
            "INSERT INTO workflow_definition_transitions VALUES ('document-review', 1, 'late', 'DRAFT', 'APPROVED')",
            "TRUNCATE workflow_definitions CASCADE",
            "TRUNCATE workflow_definition_states CASCADE",
            "TRUNCATE workflow_definition_transitions"
    })
    void databaseSealsAllDefinitionContent(String mutation) {
        assertThatThrownBy(() -> sql(dataSource(false, schema), mutation)).isInstanceOf(SQLException.class);
        assertThat(persistence.loadDefinition("document-review", 1)).isEqualTo(definition);
    }

    @Test
    void initialStateMustExistAndProvisioningTransactionCannotBeSpoofed() throws SQLException {
        var migrator = dataSource(false, schema);
        assertThatThrownBy(() -> sql(migrator,
                "INSERT INTO workflow_definitions (definition_id, definition_version, initial_state) VALUES ('bad', 1, 'missing')"))
                .isInstanceOf(SQLException.class);
        try (Connection connection = migrator.getConnection()) {
            connection.setAutoCommit(false);
            try (var statement = connection.createStatement()) {
                statement.executeUpdate("""
                        INSERT INTO workflow_definitions
                        (definition_id, definition_version, initial_state, provisioning_transaction)
                        VALUES ('sealed', 0, 'ONLY', 0)
                        """);
                statement.executeUpdate("INSERT INTO workflow_definition_states VALUES ('sealed', 0, 'ONLY')");
            }
            connection.commit();
        }
        assertThatThrownBy(() -> sql(migrator, "INSERT INTO workflow_definition_states VALUES ('sealed', 0, 'LATE')"))
                .isInstanceOf(SQLException.class);
        assertThat(persistence.loadDefinition("sealed", 0).states()).containsExactly("ONLY");
    }

    @Test
    void createIsInsertOnlyAndActivationStaysVersionZeroWithoutHistory() {
        WorkflowInstance initial = create("one");
        expectCode(INSTANCE_ALREADY_EXISTS, () -> persistence.createInstance(initial));
        assertSnapshot(initial, persistence.loadInstance("one"));
        assertThat(persistence.loadHistory("one")).isEmpty();
        WorkflowInstance active = initial.activate(definition, NOW);
        assertSnapshot(active, persistence.commitActivation(initial, active));
        assertThat(persistence.loadInstance("one").runtimeVersion()).isZero();
        assertThat(persistence.loadHistory("one")).isEmpty();
        expectCode(VERSION_CONFLICT, () -> persistence.commitActivation(initial, active));
        expectCode(TRANSITION_NOT_ALLOWED, () -> persistence.commitActivation(active, active));
    }

    @Test
    void creationUsesAuthoritativeInitialStateAndDefinition() {
        WorkflowDefinition forged = new WorkflowDefinition(definition.definitionId(), 1, "IN_REVIEW",
                definition.states(), definition.transitions());
        expectCode(TRANSITION_NOT_ALLOWED, () -> persistence.createInstance(
                WorkflowInstance.notStarted("forged", forged, RESOURCE, NOW)));
        expectCode(INSTANCE_NOT_FOUND, () -> persistence.loadInstance("forged"));
        WorkflowInstance initial = WorkflowInstance.notStarted("not-initial", definition, RESOURCE, NOW);
        expectCode(TRANSITION_NOT_ALLOWED, () -> persistence.createInstance(initial.activate(definition, NOW)));
        WorkflowDefinition absent = new WorkflowDefinition("missing", 1, "ONLY", Set.of("ONLY"), Set.of());
        expectCode(DEFINITION_NOT_FOUND, () -> persistence.createInstance(
                WorkflowInstance.notStarted("missing", absent, RESOURCE, NOW)));
        expectCode(INSTANCE_NOT_FOUND, () -> persistence.loadHistory("missing"));
        create("exists");
        expectCode(INSTANCE_ALREADY_EXISTS, () -> persistence.createInstance(
                WorkflowInstance.notStarted("exists", absent, RESOURCE, NOW)));
    }

    @ParameterizedTest
    @CsvSource({
            "id, INSTANCE_NOT_FOUND", "definition, TRANSITION_NOT_ALLOWED", "definition-version, TRANSITION_NOT_ALLOWED",
            "resource-type, TRANSITION_NOT_ALLOWED", "resource-id, TRANSITION_NOT_ALLOWED",
            "state, TRANSITION_NOT_ALLOWED", "version, VERSION_CONFLICT",
            "created, TRANSITION_NOT_ALLOWED", "updated, TRANSITION_NOT_ALLOWED"
    })
    void transitionComparesFullPersistedSource(String field, WorkflowErrorCode error) {
        WorkflowInstance active = activate("source");
        WorkflowDefinition fakeDefinition = sourceDefinition(field);
        WorkflowInstance fake = WorkflowInstance.restore(field.equals("id") ? "missing" : active.instanceId(),
                fakeDefinition,
                new ResourceReference(field.equals("resource-type") ? "other" : RESOURCE.resourceType(),
                        field.equals("resource-id") ? "other" : RESOURCE.resourceId()),
                field.equals("state") ? "IN_REVIEW" : "DRAFT",
                field.equals("version") || field.equals("state") ? 1 : 0, WorkflowLifecycle.ACTIVE,
                field.equals("created") ? NOW.minusNanos(1) : NOW,
                field.equals("updated") ? NOW.plusNanos(1) : NOW);
        // Give both sides version 1 for the state case so the state check, rather than version, rejects it.
        if (field.equals("state")) {
            persistence.commitTransition(proposal(active, "submit", NOW));
            active = persistence.loadInstance("source");
            fake = WorkflowInstance.restore("source", fakeDefinition, RESOURCE, "DRAFT", 1,
                    WorkflowLifecycle.ACTIVE, NOW, NOW);
        }
        TransitionResult forged = proposal(fake, fakeDefinition, "submit", NOW.plusNanos(2));
        expectCode(error, () -> persistence.commitTransition(forged));
        assertSnapshot(active, persistence.loadInstance("source"));
    }

    private WorkflowDefinition sourceDefinition(String field) {
        String id = field.equals("definition") ? "other-definition" : definition.definitionId();
        long version = field.equals("definition-version") ? 2 : definition.definitionVersion();
        return new WorkflowDefinition(id, version, "DRAFT", definition.states(), definition.transitions());
    }

    @ParameterizedTest
    @ValueSource(strings = {"id", "definition", "definition-version", "resource-type", "resource-id", "state", "created"})
    void activationRejectsForgedSource(String field) {
        WorkflowInstance initial = create("activation");
        WorkflowDefinition fakeDefinition = sourceDefinition(field);
        if (field.equals("state")) {
            fakeDefinition = new WorkflowDefinition(definition.definitionId(), 1, "IN_REVIEW",
                    definition.states(), definition.transitions());
        }
        WorkflowInstance fake = WorkflowInstance.notStarted(field.equals("id") ? "missing" : initial.instanceId(),
                fakeDefinition, new ResourceReference(field.equals("resource-type") ? "other" : RESOURCE.resourceType(),
                        field.equals("resource-id") ? "other" : RESOURCE.resourceId()),
                field.equals("created") ? NOW.minusNanos(1) : NOW);
        WorkflowInstance activated = fake.activate(fakeDefinition, NOW);
        expectCode(field.equals("id") ? INSTANCE_NOT_FOUND : TRANSITION_NOT_ALLOWED,
                () -> persistence.commitActivation(fake, activated));
        assertSnapshot(initial, persistence.loadInstance("activation"));
    }

    @Test
    void activationChecksLifecycleVersionProposalAndBackwardsTime() {
        WorkflowInstance initial = create("activation");
        WorkflowInstance active = initial.activate(definition, NOW);
        expectCode(VERSION_CONFLICT, () -> persistence.commitActivation(active, active));
        WorkflowInstance newer = WorkflowInstance.restore("activation", definition, RESOURCE, "DRAFT", 1,
                WorkflowLifecycle.ACTIVE, NOW, NOW);
        expectCode(VERSION_CONFLICT, () -> persistence.commitActivation(newer, newer));
        WorkflowInstance wrongResource = WorkflowInstance.restore("activation", definition,
                new ResourceReference("other", "other"), "DRAFT", 0, WorkflowLifecycle.ACTIVE, NOW, NOW);
        expectCode(TRANSITION_NOT_ALLOWED, () -> persistence.commitActivation(initial, wrongResource));
        WorkflowInstance earlier = WorkflowInstance.restore("activation", definition, RESOURCE, "DRAFT", 0,
                WorkflowLifecycle.ACTIVE, NOW.minusNanos(1), NOW.minusNanos(1));
        expectCode(TRANSITION_NOT_ALLOWED, () -> persistence.commitActivation(initial, earlier));
        assertSnapshot(initial, persistence.loadInstance("activation"));
    }

    @Test
    void authoritativeDefinitionRejectsForgedTransitionTargetAndUnknownTransition() {
        WorkflowInstance active = activate("forged");
        WorkflowDefinition wrong = new WorkflowDefinition(definition.definitionId(), 1, "DRAFT",
                definition.states(), Set.of(new WorkflowTransition("submit", "DRAFT", "APPROVED")));
        expectCode(TRANSITION_NOT_ALLOWED, () -> persistence.commitTransition(proposal(active, wrong, "submit", NOW)));
        WorkflowDefinition invented = new WorkflowDefinition(definition.definitionId(), 1, "DRAFT",
                definition.states(), Set.of(new WorkflowTransition("invented", "DRAFT", "APPROVED")));
        expectCode(INVALID_TRANSITION, () -> persistence.commitTransition(proposal(active, invented, "invented", NOW)));
        assertSnapshot(active, persistence.loadInstance("forged"));
        assertThat(persistence.loadHistory("forged")).isEmpty();
    }

    @Test
    void historyIsImmutableOrderedContiguousAndTerminalReplayHasCorrectPrecedence() {
        WorkflowInstance active = activate("history");
        TransitionResult first = proposal(active, "submit", NOW);
        assertSnapshot(first.instance(), persistence.commitTransition(first).instance());
        expectCode(VERSION_CONFLICT, () -> persistence.commitTransition(first));
        TransitionResult second = proposal(persistence.loadInstance("history"), "approve", NOW);
        persistence.commitTransition(second);
        assertThat(persistence.loadInstance("history").lifecycle()).isEqualTo(WorkflowLifecycle.COMPLETED);
        List<TransitionRecord> history = persistence.loadHistory("history");
        assertThat(history).containsExactly(first.record(), second.record());
        assertThatThrownBy(() -> history.clear()).isInstanceOf(UnsupportedOperationException.class);
        expectCode(VERSION_CONFLICT, () -> persistence.commitTransition(second));
        WorkflowInstance completed = persistence.loadInstance("history");
        expectCode(INSTANCE_COMPLETED, () -> persistence.commitActivation(completed, completed));
    }

    @Test
    void sqlInjectionIdentifiersRemainData() {
        WorkflowInstance initial = create("'; DROP TABLE workflow_instances; --");
        assertSnapshot(initial, persistence.loadInstance(initial.instanceId()));
        assertThat(persistence.loadHistory(initial.instanceId())).isEmpty();
    }

    @ParameterizedTest
    @ValueSource(strings = {"-1000000000-01-01T00:00:00Z", "+1000000000-12-31T23:59:59.999999999Z",
            "1969-12-31T23:59:59.999999999Z", "2026-10-13T01:02:03.123456789Z"})
    void allJavaInstantSecondsAndNanosRoundTripExactly(String text) throws SQLException {
        Instant instant = Instant.parse(text);
        WorkflowInstance initial = WorkflowInstance.notStarted("precision", definition, RESOURCE, instant);
        persistence.createInstance(initial);
        WorkflowInstance active = persistence.commitActivation(initial, initial.activate(definition, instant));
        TransitionResult committed = persistence.commitTransition(proposal(active, "submit", instant));
        assertSnapshot(committed.instance(), persistence.loadInstance("precision"));
        assertThat(persistence.loadHistory("precision").getFirst().occurredAt()).isEqualTo(instant);
        assertThat(scalar(database, "SELECT updated_at_seconds FROM workflow_instances WHERE instance_id = 'precision'"))
                .isEqualTo(instant.getEpochSecond());
        assertThat(scalar(database, "SELECT updated_at_nanos FROM workflow_instances WHERE instance_id = 'precision'"))
                .isEqualTo(instant.getNano());
    }

    @Test
    void databaseRejectsOutOfRangeInstantAndNanos() throws SQLException {
        create("range");
        for (String mutation : List.of(
                "UPDATE workflow_instances SET created_at_seconds = -31557014167219201",
                "UPDATE workflow_instances SET updated_at_seconds = 31556889864403200",
                "UPDATE workflow_instances SET updated_at_nanos = 1000000000",
                "UPDATE workflow_instances SET created_at_nanos = -1")) {
            assertThatThrownBy(() -> sql(dataSource(false, schema), mutation)).isInstanceOf(SQLException.class);
        }
    }

    @ParameterizedTest
    @ValueSource(strings = {"create", "activate", "transition"})
    void twoIndependentConnectionsHaveExactlyOneWinner(String operation) throws Exception {
        var other = new PostgresWorkflowPersistence(dataSource(true, schema), schema);
        Callable<Object> left;
        Callable<Object> right;
        if (operation.equals("create")) {
            WorkflowInstance initial = WorkflowInstance.notStarted("race", definition, RESOURCE, NOW);
            left = () -> persistence.createInstance(initial);
            right = () -> other.createInstance(initial);
        } else if (operation.equals("activate")) {
            WorkflowInstance initial = create("race");
            WorkflowInstance active = initial.activate(definition, NOW);
            left = () -> persistence.commitActivation(initial, active);
            right = () -> other.commitActivation(initial, active);
        } else {
            TransitionResult proposal = proposal(activate("race"), "submit", NOW);
            left = () -> persistence.commitTransition(proposal);
            right = () -> other.commitTransition(proposal);
        }
        List<Object> results = race(left, right);
        WorkflowErrorCode loser = operation.equals("create") ? INSTANCE_ALREADY_EXISTS : VERSION_CONFLICT;
        assertThat(results.stream().filter(loser::equals)).hasSize(1);
        assertThat(results.stream().filter(result -> !(result instanceof WorkflowErrorCode))).hasSize(1);
        assertThat(persistence.loadInstance("race").runtimeVersion()).isEqualTo(operation.equals("transition") ? 1 : 0);
        assertThat(persistence.loadHistory("race")).hasSize(operation.equals("transition") ? 1 : 0);
    }

    @Test
    void historyInsertFailureRollsBackInstanceAndDoesNotRetry() throws SQLException {
        WorkflowInstance active = activate("rollback");
        rejectHistoryInsert();
        AtomicInteger connections = new AtomicInteger();
        var faulty = faultAdapter("count", connections);
        expectCode(OPERATION_FAILURE, () -> faulty.commitTransition(proposal(active, "submit", NOW)));
        assertThat(connections).hasValue(1);
        assertSnapshot(active, persistence.loadInstance("rollback"));
        assertThat(persistence.loadHistory("rollback")).isEmpty();
    }

    @ParameterizedTest
    @ValueSource(strings = {"commit-before", "commit-after"})
    void lostCommitResponseIsUnknownAndAtomicWithoutAutomaticRetry(String fault) {
        WorkflowInstance active = activate("unknown");
        TransitionResult transition = proposal(active, "submit", NOW);
        AtomicInteger connections = new AtomicInteger();
        expectCode(COMMIT_OUTCOME_UNKNOWN,
                () -> faultAdapter(fault, connections).commitTransition(transition));
        assertThat(connections).hasValue(1);
        if (fault.equals("commit-after")) {
            assertSnapshot(transition.instance(), persistence.loadInstance("unknown"));
            assertThat(persistence.loadHistory("unknown")).containsExactly(transition.record());
            expectCode(VERSION_CONFLICT, () -> persistence.commitTransition(transition));
        } else {
            assertSnapshot(active, persistence.loadInstance("unknown"));
            assertThat(persistence.loadHistory("unknown")).isEmpty();
        }
    }

    @ParameterizedTest
    @ValueSource(strings = {"create", "activate"})
    void lostCommitResponseForOtherWritesIsAlsoUnknown(String operation) {
        WorkflowInstance initial = WorkflowInstance.notStarted("unknown", definition, RESOURCE, NOW);
        var faulty = faultAdapter("commit-after", new AtomicInteger());
        if (operation.equals("create")) {
            expectCode(COMMIT_OUTCOME_UNKNOWN, () -> faulty.createInstance(initial));
            assertSnapshot(initial, persistence.loadInstance("unknown"));
            expectCode(INSTANCE_ALREADY_EXISTS, () -> persistence.createInstance(initial));
        } else {
            persistence.createInstance(initial);
            WorkflowInstance active = initial.activate(definition, NOW);
            expectCode(COMMIT_OUTCOME_UNKNOWN, () -> faulty.commitActivation(initial, active));
            assertSnapshot(active, persistence.loadInstance("unknown"));
            expectCode(VERSION_CONFLICT, () -> persistence.commitActivation(initial, active));
        }
        assertThat(persistence.loadHistory("unknown")).isEmpty();
    }

    @Test
    void failedRollbackCannotClaimOperationFailure() throws SQLException {
        WorkflowInstance active = activate("rollback");
        rejectHistoryInsert();
        expectCode(COMMIT_OUTCOME_UNKNOWN, () -> faultAdapter("rollback", new AtomicInteger())
                .commitTransition(proposal(active, "submit", NOW)));
        assertSnapshot(active, persistence.loadInstance("rollback"));
        assertThat(persistence.loadHistory("rollback")).isEmpty();
    }

    @Test
    void cleanupFailureDoesNotHideConfirmedDurableCommit() {
        WorkflowInstance initial = WorkflowInstance.notStarted("cleanup", definition, RESOURCE, NOW);
        assertSnapshot(initial, faultAdapter("close-after", new AtomicInteger()).createInstance(initial));
        assertSnapshot(initial, persistence.loadInstance("cleanup"));
    }

    @Test
    void ambientSpringTransactionCannotDeferPortCommit() {
        var manager = new org.springframework.jdbc.datasource.DataSourceTransactionManager(database);
        var outer = new org.springframework.transaction.support.TransactionTemplate(manager);
        outer.executeWithoutResult(status -> {
            create("independent");
            status.setRollbackOnly();
        });
        assertThat(persistence.loadInstance("independent").instanceId()).isEqualTo("independent");
    }

    @Test
    void springProvidesOneProductionPortAndDataSurvivesBackendRestart() {
        var runner = new ApplicationContextRunner()
                .withUserConfiguration(PostgresWorkflowPersistence.class, WorkflowPersistenceConfiguration.class)
                .withBean(DataSource.class, () -> database)
                .withPropertyValues("dxos.workflow.schema=" + schema);
        runner.run(context -> {
            assertThat(context).hasSingleBean(WorkflowPersistencePort.class).hasSingleBean(WorkflowRuntime.class);
            var runtime = context.getBean(WorkflowRuntime.class);
            runtime.createInstance("restart", "document-review", 1, RESOURCE);
            runtime.activateInstance("restart");
            runtime.executeTransition(new TransitionCommand("restart", "submit", ACTOR, 0));
        });
        runner.run(context -> {
            var runtime = context.getBean(WorkflowRuntime.class);
            assertThat(runtime.loadInstance("restart").runtimeVersion()).isEqualTo(1);
            assertThat(runtime.loadHistory("restart")).hasSize(1);
            assertThat(context).doesNotHaveBean(com.tricore.dxos.gateway.workflow.controller.WorkflowController.class);
        });
    }

    @Test
    void validatesStructuralArgumentsWithoutConnecting() {
        var adapter = faultAdapter("connect", new AtomicInteger());
        assertThatThrownBy(() -> adapter.loadDefinition(" ", 1)).isInstanceOf(IllegalArgumentException.class);
        assertThatThrownBy(() -> adapter.loadDefinition("valid", -1)).isInstanceOf(IllegalArgumentException.class);
        assertThatThrownBy(() -> adapter.loadInstance(null)).isInstanceOf(IllegalArgumentException.class);
        assertThatThrownBy(() -> adapter.loadHistory(" ")).isInstanceOf(IllegalArgumentException.class);
        assertThatThrownBy(() -> adapter.createInstance(null)).isInstanceOf(NullPointerException.class);
        expectCode(OPERATION_FAILURE, () -> adapter.loadDefinition("valid", 1));
        expectCode(OPERATION_FAILURE, () -> adapter.createInstance(
                WorkflowInstance.notStarted("failed", definition, RESOURCE, NOW)));
        expectCode(OPERATION_FAILURE, () -> faultAdapter("connect-runtime", new AtomicInteger())
                .loadInstance("valid"));
    }

    @Test
    void runtimeLoginCannotProvisionDeleteOrOwnWorkflowTables() throws SQLException {
        String runtimeUser = required("WORKFLOW_TEST_DB_USER");
        String migrationUser = System.getenv("WORKFLOW_TEST_MIGRATION_USER");
        org.junit.jupiter.api.Assumptions.assumeTrue(migrationUser != null && !runtimeUser.equals(migrationUser),
                "Supply a separate migration login to verify least-privilege runtime permissions");
        WorkflowInstance initial = create("permissions");
        for (String forbidden : List.of(
                "INSERT INTO workflow_definitions (definition_id, definition_version, initial_state) VALUES ('forbidden', 1, 'ONLY')",
                "INSERT INTO workflow_definition_states VALUES ('document-review', 1, 'LATE')",
                "DELETE FROM workflow_instances",
                "DELETE FROM workflow_transition_history",
                "DROP TABLE workflow_instances CASCADE")) {
            assertThatThrownBy(() -> sql(database, forbidden)).isInstanceOf(SQLException.class);
        }
        expectCode(OPERATION_FAILURE, () -> persistence.provisionDefinition(
                new WorkflowDefinition("forbidden", 1, "ONLY", Set.of("ONLY"), Set.of())));
        assertSnapshot(initial, persistence.loadInstance("permissions"));
    }

    private void rejectHistoryInsert() throws SQLException {
        var migrator = dataSource(false, schema);
        sql(migrator, """
                CREATE FUNCTION fail_history() RETURNS trigger LANGUAGE plpgsql AS $$
                BEGIN RAISE EXCEPTION 'private provider details'; END; $$
                """);
        sql(migrator, """
                CREATE TRIGGER fail_history BEFORE INSERT ON workflow_transition_history
                FOR EACH ROW EXECUTE FUNCTION fail_history()
                """);
    }

    private PostgresWorkflowPersistence faultAdapter(String fault, AtomicInteger connections) {
        return new PostgresWorkflowPersistence(new AbstractDataSource() {
            @Override
            public Connection getConnection() throws SQLException {
                connections.incrementAndGet();
                if (fault.equals("connect")) {
                    throw new SQLException("private credentials must never escape", "08001");
                }
                if (fault.equals("connect-runtime")) {
                    throw new IllegalArgumentException("private credentials must never escape");
                }
                Connection real = database.getConnection();
                return (Connection) Proxy.newProxyInstance(Connection.class.getClassLoader(),
                        new Class<?>[]{Connection.class}, (proxy, method, arguments) -> {
                            if (method.getName().equals("commit")) {
                                if (fault.equals("commit-before")) {
                                    throw new SQLException("lost connection before response", "08006");
                                }
                                if (fault.equals("commit-after")) {
                                    real.commit();
                                    throw new SQLException("lost response after durable commit", "08006");
                                }
                            }
                            if (method.getName().equals("rollback") && fault.equals("rollback")) {
                                throw new SQLException("rollback response unavailable", "08006");
                            }
                            if (method.getName().equals("close") && fault.equals("close-after")) {
                                real.close();
                                throw new SQLException("pool cleanup failure");
                            }
                            try {
                                return method.invoke(real, arguments);
                            } catch (InvocationTargetException failure) {
                                throw failure.getCause();
                            }
                        });
            }

            @Override
            public Connection getConnection(String username, String password) throws SQLException {
                return getConnection();
            }
        }, schema);
    }

    private WorkflowInstance create(String id) {
        return persistence.createInstance(WorkflowInstance.notStarted(id, definition, RESOURCE, NOW));
    }

    private WorkflowInstance activate(String id) {
        WorkflowInstance initial = create(id);
        return persistence.commitActivation(initial, initial.activate(definition, NOW));
    }

    private TransitionResult proposal(WorkflowInstance instance, String transition, Instant time) {
        return proposal(instance, definition, transition, time);
    }

    private TransitionResult proposal(WorkflowInstance instance, WorkflowDefinition exact, String transition, Instant time) {
        return instance.transition(exact,
                new TransitionCommand(instance.instanceId(), transition, ACTOR, instance.runtimeVersion()), time);
    }

    private static void assertSnapshot(WorkflowInstance expected, WorkflowInstance actual) {
        assertThat(actual).usingRecursiveComparison().isEqualTo(expected);
    }

    private static void expectCode(WorkflowErrorCode code, org.assertj.core.api.ThrowableAssert.ThrowingCallable operation) {
        assertThatThrownBy(operation).isInstanceOf(WorkflowException.class)
                .hasMessage(code.name()).hasNoCause();
    }

    private static List<Object> race(Callable<Object> left, Callable<Object> right) throws Exception {
        CyclicBarrier start = new CyclicBarrier(2);
        try (var workers = Executors.newFixedThreadPool(2)) {
            var first = workers.submit(() -> raced(start, left));
            var second = workers.submit(() -> raced(start, right));
            return List.of(first.get(15, TimeUnit.SECONDS), second.get(15, TimeUnit.SECONDS));
        }
    }

    private static Object raced(CyclicBarrier start, Callable<Object> operation) throws Exception {
        start.await(10, TimeUnit.SECONDS);
        try {
            return operation.call();
        } catch (WorkflowException failure) {
            return failure.code();
        }
    }

    private static DriverManagerDataSource dataSource(boolean runtime, String schema) {
        DriverManagerDataSource result = new DriverManagerDataSource();
        String url = required("WORKFLOW_TEST_JDBC_URL");
        if (!url.matches("jdbc:postgresql://(127\\.0\\.0\\.1|localhost|\\[::1\\]):[0-9]+/[A-Za-z0-9_]+")) {
            throw new IllegalArgumentException("Destructive integration tests require a local disposable database URL");
        }
        result.setUrl(url);
        String user = System.getenv(runtime ? "WORKFLOW_TEST_DB_USER" : "WORKFLOW_TEST_MIGRATION_USER");
        String password = System.getenv(runtime ? "WORKFLOW_TEST_DB_PASSWORD" : "WORKFLOW_TEST_MIGRATION_PASSWORD");
        result.setUsername(user == null ? required("WORKFLOW_TEST_DB_USER") : user);
        result.setPassword(password == null ? required("WORKFLOW_TEST_DB_PASSWORD") : password);
        if (schema != null) {
            Properties properties = new Properties();
            properties.setProperty("currentSchema", schema);
            result.setConnectionProperties(properties);
        }
        return result;
    }

    private static String required(String name) {
        String value = System.getenv(name);
        if (value == null || value.isBlank()) {
            throw new IllegalStateException("Missing test environment variable: " + name);
        }
        return value;
    }

    private static void sql(DataSource dataSource, String sql) throws SQLException {
        try (Connection connection = dataSource.getConnection(); var statement = connection.createStatement()) {
            statement.execute(sql);
        }
    }

    private static long scalar(DataSource dataSource, String sql) throws SQLException {
        try (Connection connection = dataSource.getConnection(); var statement = connection.createStatement();
             var rows = statement.executeQuery(sql)) {
            rows.next();
            return rows.getLong(1);
        }
    }
}

